Contents of file frontend/css/hive.css:

1 | /* ─────────────────────────────────────────────────────────────
2 |    IBM Hive — hive.css
3 |    IBM Carbon / w3 dark theme.
4 |    ───────────────────────────────────────────────────────────── */
5 | *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
6 | 
7 | :root {
8 |   /* IBM Carbon blue palette */
9 |   --ibm-blue-10:  #edf5ff;
10 |   --ibm-blue-40:  #78a9ff;
11 |   --ibm-blue-50:  #4589ff;
12 |   --ibm-blue-60:  #0f62fe;
13 |   --ibm-blue-70:  #0043ce;
14 | 
15 |   /* IBM Purple palette */
16 |   --ibm-purple-40: #be95ff;
17 |   --ibm-purple-50: #a56eff;
18 |   --ibm-purple-60: #8a3ffc;
19 | 
20 |   /* Accent aliases */
21 |   --accent-blue:     var(--ibm-blue-50);
22 |   --accent-blue-dark:var(--ibm-blue-60);
23 |   --accent-indigo:   #6c63ff;
24 |   --accent-violet:   #8b5cf6;
25 |   --accent-purple:   var(--ibm-purple-50);
26 |   --accent-magenta:  #d946ef;
27 |   --accent-gradient: linear-gradient(135deg, var(--ibm-blue-60) 0%, var(--ibm-purple-60) 100%);
28 | 
29 |   /* Back-compat aliases */
30 |   --ibm-blue:      var(--ibm-blue-50);
31 |   --ibm-blue-dark: var(--ibm-blue-60);
32 | 
33 |   /* IBM Carbon Gray 100 surfaces (w3 dark) */
34 |   --bg:         #161616;
35 |   --nav-bg:     #161616;
36 |   --sidebar-bg: #1c1c1c;
37 |   --surface:    #262626;
38 |   --surface-2:  #393939;
39 |   --border:     #525252;
40 |   --border-subtle: #3d3d3d;
41 |   --text:       #f4f4f4;
42 |   --text-secondary: #e0e0e0;   /* was #c6c6c6 — brighter */
43 |   --muted:      #a8a8a8;       /* was #8d8d8d — brighter, easier to read */
44 | 
45 |   /* Hex border */
46 |   --hex-border: rgba(255,255,255,0.85);
47 | 
48 |   /* Role / seniority color spectrum */
49 |   --c-exec:     #d946ef;
50 |   --c-director: #a855f7;
51 |   --c-manager:  #6c63ff;
52 |   --c-you:      var(--ibm-blue-50);
53 |   --c-peer:     #60a5fa;
54 |   --c-tech:     #a78bfa;
55 |   --c-csm:      #4338ca;
56 |   --c-sdr:      #7e22ce;
57 |   --c-partner:  #e879f9;
58 |   --c-other:    #525252;
59 |   --c-open:     var(--surface-2);
60 | 
61 |   /* Pipeline stage spectrum */
62 |   --stage-won:         #0f62fe;
63 |   --stage-negotiation: #6c63ff;
64 |   --stage-proposal:    #8a3ffc;
65 |   --stage-risk:        #d946ef;
66 |   --stage-prospect:    #525252;
67 | 
68 |   /* Market spectrum */
69 |   --mkt-enterprise: #0f62fe;
70 |   --mkt-strategic:  #a855f7;
71 |   --mkt-horizon:    #6c63ff;
72 |   --mkt-territory:  #d946ef;
73 | }
74 | 
75 | body {
76 |   font-family: "IBM Plex Sans", -apple-system, "Segoe UI", system-ui, sans-serif;
77 |   background: var(--bg);
78 |   color: var(--text);
79 |   min-height: 100vh;
80 |   display: flex;
81 |   flex-direction: column;
82 |   font-size: 15px;
83 |   line-height: 1.55;
84 | }
85 | 
86 | /* ── TOP NAV (IBM w3 style) ───────────────────────────────────── */
87 | .topnav {
88 |   background: #000000;
89 |   color: #fff;
90 |   display: flex;
91 |   align-items: center;
92 |   padding: 0;
93 |   height: 64px;
94 |   flex-shrink: 0;
95 |   border-bottom: 1px solid rgba(255,255,255,0.12);
96 |   gap: 0;
97 | }
98 | 
99 | .topnav-brand {
100 |   display: flex;
101 |   align-items: center;
102 |   gap: 5px;
103 |   font-size: 17px;
104 |   font-weight: 600;
105 |   letter-spacing: 0.16px;
106 |   padding: 0 24px;
107 |   height: 100%;
108 |   border-right: 1px solid rgba(255,255,255,0.12);
109 |   color: #fff;
110 |   flex-shrink: 0;
111 | }
112 | 
113 | .logo-img {
114 |   width: 32px;
115 |   height: 32px;
116 |   object-fit: contain;
117 |   display: block;
118 |   flex-shrink: 0;
119 | }
120 | 
121 | /* Nav link strip (mimic w3 Home / People / News / Apps tabs) */
122 | .topnav-links {
123 |   display: flex;
124 |   align-items: center;
125 |   height: 100%;
126 |   flex: 1;
127 | }
128 | 
129 | .topnav-link {
130 |   display: flex;
131 |   align-items: center;
132 |   height: 100%;
133 |   padding: 0 18px;
134 |   font-size: 14px;
135 |   color: #8d8d8d;
136 |   cursor: pointer;
137 |   border-bottom: 2px solid transparent;
138 |   white-space: nowrap;
139 |   transition: color 0.1s;
140 |   letter-spacing: 0.16px;
141 | }
142 | .topnav-link:hover { color: #fff; }
143 | .topnav-link.active { color: #fff; border-bottom-color: var(--ibm-blue-50); }
144 | 
145 | /* Search bar in top nav */
146 | .topnav-search {
147 |   display: flex;
148 |   align-items: center;
149 |   gap: 6px;
150 |   background: transparent;
151 |   border: none;
152 |   border-left: 1px solid rgba(255,255,255,0.12);
153 |   height: 100%;
154 |   padding: 0 14px;
155 |   flex: 0 1 280px;
156 | }
157 | .topnav-search input {
158 |   background: transparent;
159 |   border: none;
160 |   outline: none;
161 |   color: #c6c6c6;
162 |   font-size: 14px;
163 |   font-family: inherit;
164 |   width: 100%;
165 | }
166 | .topnav-search input::placeholder { color: #6f6f6f; }
167 | .topnav-search svg { flex-shrink: 0; }
168 | 
169 | .topnav-user {
170 |   display: flex;
171 |   align-items: center;
172 |   gap: 10px;
173 |   padding: 0 20px;
174 |   height: 100%;
175 |   font-size: 13px;
176 |   color: #c6c6c6;
177 |   border-left: 1px solid rgba(255,255,255,0.12);
178 |   flex-shrink: 0;
179 |   cursor: pointer;
180 | }
181 | 
182 | /* .avatar is kept for JS compatibility but hidden from nav */
183 | .avatar { display: none; }
184 | 
185 | /* ── LAYOUT ──────────────────────────────────────────────────── */
186 | .shell {
187 |   display: flex;
188 |   flex: 1;
189 |   overflow: hidden;
190 |   min-height: 0;
191 | }
192 | 
193 | /* ── SIDEBAR ─────────────────────────────────────────────────── */
194 | .sidebar {
195 |   width: 216px;
196 |   background: #0d0d0d;
197 |   display: flex;
198 |   flex-direction: column;
199 |   flex-shrink: 0;
200 |   border-right: 1px solid rgba(255,255,255,0.08);
201 |   overflow-y: auto;
202 | }
203 | 
204 | /* Section header label */
205 | .sb-section-label {
206 |   padding: 14px 18px 6px;
207 |   font-size: 10px;
208 |   font-weight: 600;
209 |   letter-spacing: 0.8px;
210 |   color: #4a4a4a;
211 |   text-transform: none;
212 |   border-bottom: 1px solid rgba(255,255,255,0.05);
213 | }
214 | 
215 | /* Flat sidebar item (non-expandable) */
216 | .sb-item {
217 |   display: flex;
218 |   align-items: center;
219 |   padding: 10px 18px;
220 |   font-size: 13px;
221 |   color: #a8a8a8;
222 |   cursor: pointer;
223 |   border-left: 2px solid transparent;
224 |   border-bottom: 1px solid rgba(255,255,255,0.04);
225 |   transition: color 0.1s;
226 | }
227 | .sb-item:hover { color: #e0e0e0; }
228 | .sb-item.active { color: #fff; border-left-color: var(--ibm-blue-50); }
229 | 
230 | /* Expandable group */
231 | .sb-group-header {
232 |   display: flex;
233 |   align-items: center;
234 |   justify-content: space-between;
235 |   padding: 10px 18px;
236 |   font-size: 13px;
237 |   color: #a8a8a8;
238 |   cursor: pointer;
239 |   border-bottom: 1px solid rgba(255,255,255,0.04);
240 |   transition: color 0.1s;
241 |   user-select: none;
242 | }
243 | .sb-group-header:hover { color: #e0e0e0; }
244 | .sb-caret { font-size: 14px; color: #666; transition: color 0.1s; }
245 | .sb-group-header:hover .sb-caret { color: #a8a8a8; }
246 | 
247 | .sb-group-body {
248 |   display: none;
249 |   flex-direction: column;
250 |   background: #0d0d0d;
251 |   border-bottom: 1px solid rgba(255,255,255,0.06);
252 | }
253 | .sb-group-body.open { display: flex; }
254 | 
255 | /* Search within group */
256 | .sb-search {
257 |   margin: 6px 12px 4px;
258 |   padding: 5px 8px;
259 |   font-size: 12px;
260 |   background: #141414;
261 |   border: 1px solid rgba(255,255,255,0.1);
262 |   color: #e0e0e0;
263 |   font-family: inherit;
264 |   outline: none;
265 |   border-radius: 0;
266 | }
267 | .sb-search::placeholder { color: #6f6f6f; }
268 | .sb-search:focus { border-color: var(--ibm-blue-50); }
269 | 
270 | /* Clear group button (org multi-select) */
271 | .sb-clear-group {
272 |   padding: 3px 18px 5px 24px;
273 |   font-size: 11px;
274 |   color: #525252;
275 |   cursor: pointer;
276 |   transition: color 0.1s;
277 |   letter-spacing: 0.16px;
278 | }
279 | .sb-clear-group:hover { color: var(--ibm-blue-40); }
280 | 
281 | /* Child item inside group */
282 | .sb-child {
283 |   padding: 8px 18px 8px 24px;
284 |   font-size: 13px;
285 |   color: #a8a8a8;
286 |   cursor: pointer;
287 |   border-left: 2px solid transparent;
288 |   transition: color 0.1s, background 0.1s;
289 | }
290 | .sb-child:hover { color: #e0e0e0; background: rgba(255,255,255,0.03); }
291 | .sb-child.active { color: #fff; border-left-color: var(--ibm-blue-50); background: rgba(69,137,255,0.07); }
292 | /* Multi-select: checkmark indicator */
293 | .sb-child.sb-multi.active::before {
294 |   content: '✓ ';
295 |   color: var(--ibm-blue-40);
296 |   font-size: 11px;
297 | }
298 | 
299 | /* Legacy nav-item (used in cell/seller view) */
300 | .nav-item {
301 |   display: flex;
302 |   align-items: center;
303 |   padding: 10px 18px;
304 |   cursor: pointer;
305 |   font-size: 13px;
306 |   color: #6f6f6f;
307 |   border-left: 2px solid transparent;
308 |   border-bottom: 1px solid rgba(255,255,255,0.04);
309 |   transition: color 0.1s;
310 | }
311 | .nav-item:hover { color: #c6c6c6; }
312 | .nav-item.active { color: #fff; border-left-color: var(--ibm-blue-50); }
313 | .nav-icon { display: none; }
314 | .sidebar-divider { display: none; }
315 | .sidebar-section { padding: 0; }
316 | .sidebar-label { display: none; }
317 | 
318 | /* ── MAIN ────────────────────────────────────────────────────── */
319 | .main { flex: 1; overflow: hidden; display: flex; flex-direction: column; min-height: 0; }
320 | 
321 | .view { display: none; flex-direction: column; flex: 1; overflow-y: auto; min-height: 0; }
322 | .view.active { display: flex; }
323 | /* Hive and org views manage their own overflow (SVG + zoom) */
324 | #view-org { overflow: hidden; }
325 | 
326 | /* ── PAGE HEADER ─────────────────────────────────────────────── */
327 | .page-header {
328 |   padding: 20px 24px 16px;
329 |   border-bottom: 1px solid var(--border-subtle);
330 |   background: var(--sidebar-bg);
331 |   flex-shrink: 0;
332 | }
333 | .page-title  {
334 |   font-size: 20px;
335 |   font-weight: 400;
336 |   letter-spacing: 0;
337 |   color: var(--text);
338 | }
339 | .page-sub    { font-size: 13px; color: var(--muted); margin-top: 3px; }
340 | 
341 | /* ── TAB BAR (IBM Carbon Tab style) ──────────────────────────── */
342 | .tab-bar {
343 |   display: flex;
344 |   padding: 0;
345 |   background: var(--sidebar-bg);
346 |   border-bottom: 1px solid var(--border-subtle);
347 |   flex-shrink: 0;
348 | }
349 | .tab {
350 |   padding: 12px 20px;
351 |   font-size: 14px;
352 |   cursor: pointer;
353 |   color: var(--muted);
354 |   border-bottom: 2px solid transparent;
355 |   white-space: nowrap;
356 |   letter-spacing: 0.16px;
357 |   transition: color 0.1s, border-color 0.1s;
358 | }
359 | .tab:hover { color: var(--text); }
360 | .tab.active {
361 |   color: var(--text);
362 |   border-bottom-color: var(--ibm-blue-50);
363 |   font-weight: 500;
364 | }
365 | 
366 | /* ── CONTENT AREA ────────────────────────────────────────────── */
367 | .content { padding: 20px 24px; overflow-y: auto; flex: 1; }
368 | 
369 | /* ── STAT CARDS ──────────────────────────────────────────────── */
370 | .stat-row { display: flex; gap: 1px; margin-bottom: 24px; flex-wrap: wrap; background: var(--border-subtle); border: 1px solid var(--border-subtle); border-radius: 0; overflow: hidden; }
371 | .stat-card {
372 |   background: var(--surface);
373 |   padding: 16px 20px;
374 |   flex: 1;
375 |   min-width: 120px;
376 |   border: none;
377 | }
378 | .stat-num   { font-size: 28px; font-weight: 300; color: var(--ibm-blue-40); letter-spacing: -0.5px; }
379 | .stat-label { font-size: 12px; color: var(--muted); margin-top: 4px; text-transform: uppercase; letter-spacing: 0.5px; }
380 | 
381 | /* ── TOOLBAR ─────────────────────────────────────────────────── */
382 | .toolbar { display: flex; align-items: center; gap: 8px; margin-bottom: 20px; flex-wrap: wrap; }
383 | .search-box {
384 |   flex: 1;
385 |   min-width: 160px;
386 |   max-width: 320px;
387 |   padding: 8px 12px;
388 |   border: 1px solid var(--border);
389 |   border-bottom-width: 2px;
390 |   border-bottom-color: var(--border);
391 |   border-radius: 0;
392 |   font-size: 14px;
393 |   background: var(--surface);
394 |   color: var(--text);
395 |   font-family: inherit;
396 |   transition: border-color 0.1s;
397 | }
398 | .search-box::placeholder { color: var(--muted); }
399 | .search-box:focus { outline: none; border-bottom-color: var(--ibm-blue-50); }
400 | 
401 | .sort-select {
402 |   padding: 8px 32px 8px 10px;
403 |   border: 1px solid var(--border);
404 |   border-bottom-width: 2px;
405 |   border-bottom-color: var(--border);
406 |   border-radius: 0;
407 |   font-size: 14px;
408 |   background: var(--surface);
409 |   color: var(--text);
410 |   font-family: inherit;
411 |   appearance: none;
412 |   cursor: pointer;
413 |   transition: border-color 0.1s;
414 | }
415 | .sort-select:focus { outline: none; border-bottom-color: var(--ibm-blue-50); }
416 | 
417 | /* ── ROLE LEGEND ─────────────────────────────────────────────── */
418 | .role-legend { display: flex; gap: 16px; flex-wrap: wrap; margin-bottom: 20px; }
419 | .rl-item { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--muted); }
420 | .rl-dot {
421 |   width: 10px;
422 |   height: 11px;
423 |   clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
424 |   flex-shrink: 0;
425 | }
426 | 
427 | /* ── HEX CELLS (hive grid) ───────────────────────────────────── */
428 | .hive-container {
429 |   display: flex;
430 |   flex-direction: column;
431 |   align-items: flex-start;
432 |   padding: 8px 0 40px;
433 | }
434 | .hex-row {
435 |   display: flex;
436 |   gap: 4px;
437 |   margin-bottom: -20px;
438 | }
439 | .hex-row:nth-child(even) { margin-left: 44px; }
440 | 
441 | .hex-wrap {
442 |   display: flex;
443 |   flex-direction: column;
444 |   align-items: center;
445 |   cursor: pointer;
446 | }
447 | 
448 | .hex {
449 |   position: relative;
450 |   width: 82px;
451 |   height: 90px;
452 |   clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
453 |   display: flex;
454 |   flex-direction: column;
455 |   align-items: center;
456 |   justify-content: center;
457 |   background: var(--accent-indigo);
458 |   transition: transform 0.15s, filter 0.15s;
459 |   text-align: center;
460 |   padding: 10px 6px;
461 | }
462 | .hex:hover { transform: scale(1.07); filter: brightness(1.2); }
463 | .hex.open  { background: var(--c-open); border: 1.5px dashed var(--border); }
464 | 
465 | /* Category marker (bottom-left of hex) */
466 | .hex.cat-sales::after,
467 | .hex.cat-tech::after,
468 | .hex.cat-support::after {
469 |   content: '';
470 |   position: absolute;
471 |   bottom: 8px;
472 |   left: 8px;
473 |   width: 7px;
474 |   height: 7px;
475 |   background: rgba(255,255,255,0.9);
476 | }
477 | .hex.cat-sales::after   { border-radius: 50%; }
478 | .hex.cat-tech::after    { transform: rotate(45deg); }
479 | .hex.cat-support::after { clip-path: polygon(0 0, 100% 0, 100% 100%); }
480 | 
481 | .hex-name {
482 |   font-size: 9px;
483 |   font-weight: 600;
484 |   color: #fff;
485 |   line-height: 1.25;
486 |   text-shadow: 0 1px 2px rgba(0,0,0,0.5);
487 |   max-width: 70px;
488 |   overflow: hidden;
489 |   text-overflow: ellipsis;
490 |   white-space: nowrap;
491 | }
492 | .hex-role {
493 |   font-size: 8px;
494 |   color: rgba(255,255,255,0.75);
495 |   text-shadow: 0 1px 2px rgba(0,0,0,0.4);
496 |   max-width: 70px;
497 |   overflow: hidden;
498 |   text-overflow: ellipsis;
499 |   white-space: nowrap;
500 |   margin-top: 2px;
501 | }
502 | .hex.open .hex-name { color: var(--muted); text-shadow: none; }
503 | 
504 | /* ── ORG TREE ────────────────────────────────────────────────── */
505 | .org-tree { display: flex; flex-direction: column; overflow-x: auto; padding-bottom: 16px; }
506 | .org-level { display: flex; justify-content: center; gap: 12px; padding: 10px 0; }
507 | .org-connector { display: flex; justify-content: center; }
508 | .org-connector-line { width: 1px; height: 16px; background: var(--border); }
509 | 
510 | .org-card {
511 |   background: var(--surface);
512 |   border: 1px solid var(--border-subtle);
513 |   border-left: 3px solid transparent;
514 |   padding: 12px 14px;
515 |   display: flex;
516 |   align-items: center;
517 |   gap: 10px;
518 |   min-width: 190px;
519 |   max-width: 220px;
520 |   cursor: pointer;
521 |   transition: border-color 0.15s, background 0.15s;
522 | }
523 | .org-card:hover { background: var(--surface-2); border-left-color: var(--ibm-blue-50); }
524 | .org-card.highlight { border-left-color: var(--ibm-purple-50); background: rgba(138, 63, 252, 0.08); }
525 | .org-card.you       { border-left-color: var(--ibm-blue-50); background: rgba(69, 137, 255, 0.08); }
526 | 
527 | /* Hex-shaped avatar in org cards */
528 | .org-avatar {
529 |   width: 36px;
530 |   height: 40px;
531 |   clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
532 |   display: flex;
533 |   align-items: center;
534 |   justify-content: center;
535 |   font-size: 13px;
536 |   font-weight: 700;
537 |   flex-shrink: 0;
538 |   color: #fff;
539 | }
540 | .org-info { flex: 1; min-width: 0; }
541 | .org-name  { font-size: 13px; font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
542 | .org-role  { font-size: 12px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }
543 | .org-badge {
544 |   font-size: 11px;
545 |   background: transparent;
546 |   border: 1px solid var(--border);
547 |   padding: 1px 6px;
548 |   color: var(--muted);
549 |   white-space: nowrap;
550 |   margin-top: 4px;
551 |   display: inline-block;
552 |   letter-spacing: 0.16px;
553 | }
554 | 
555 | /* ── NETWORK GRID ────────────────────────────────────────────── */
556 | .network-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 1px; background: var(--border-subtle); }
557 | .network-card {
558 |   background: var(--surface);
559 |   padding: 16px;
560 |   cursor: pointer;
561 |   transition: background 0.1s;
562 |   border-left: 3px solid transparent;
563 | }
564 | .network-card:hover { background: var(--surface-2); border-left-color: var(--ibm-blue-50); }
565 | 
566 | .nc-top { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
567 | 
568 | /* Hex-shaped avatar on network / connection cards */
569 | .nc-avatar {
570 |   width: 44px;
571 |   height: 50px;
572 |   clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
573 |   display: flex;
574 |   align-items: center;
575 |   justify-content: center;
576 |   font-size: 15px;
577 |   font-weight: 700;
578 |   color: #fff;
579 |   flex-shrink: 0;
580 | }
581 | .nc-name { font-size: 14px; font-weight: 500; letter-spacing: 0.16px; }
582 | .nc-role { font-size: 12px; color: var(--muted); margin-top: 1px; }
583 | .nc-tag  { display: inline-block; font-size: 11px; padding: 2px 8px; font-weight: 500; margin-top: 6px; letter-spacing: 0.32px; text-transform: uppercase; }
