89 |   const isOrgView = viewName === 'org';
90 | 
91 |   let html = '';
92 |   def.sections.forEach(section => {
93 |     if (section.label) {
94 |       html += `<div class="sb-section-label">${section.label}</div>`;
95 |     }
96 |     section.items.forEach(item => {
97 |       if (item.expandable && item.children) {
98 |         html += `
99 |           <div class="sb-group" data-group="${item.id}">
100 |             <div class="sb-group-header" data-toggle="${item.id}">
101 |               <span>${item.label}</span>
102 |               <span class="sb-caret">›</span>
103 |             </div>
104 |             <div class="sb-group-body" id="sbg-${item.id}">
105 |               <input class="sb-search" type="text" placeholder="Search…" data-group="${item.id}"/>
106 |               ${isOrgView ? `<div class="sb-clear-group" data-clear-group="${item.id}">Clear</div>` : ''}
107 |               ${item.children.map(c => `
108 |                 <div class="sb-child${isOrgView ? ' sb-multi' : ''}" data-filter="${item.id}" data-value="${c.id}">${c.label}</div>
109 |               `).join('')}
110 |             </div>
111 |           </div>
112 |         `;
113 |       } else {
114 |         html += `
115 |           <div class="sb-item${item.active ? ' active' : ''}" data-sb-item="${item.id}">${item.label}</div>
116 |         `;
117 |       }
118 |     });
119 |   });
120 | 
121 |   sidebar.innerHTML = html;
122 | 
123 |   // Wire expandable group toggles
124 |   sidebar.querySelectorAll('.sb-group-header').forEach(header => {
125 |     const id   = header.dataset.toggle;
126 |     const body = document.getElementById(`sbg-${id}`);
127 |     // Open by default in org view
128 |     if (isOrgView) { body.classList.add('open'); header.querySelector('.sb-caret').textContent = '⌄'; }
129 |     header.addEventListener('click', () => {
130 |       const open = body.classList.toggle('open');
131 |       header.querySelector('.sb-caret').textContent = open ? '⌄' : '›';
132 |     });
133 |   });
