137 |     input.addEventListener('input', e => {
138 |       const q = e.target.value.toLowerCase();
139 |       const group = e.target.dataset.group;
140 |       sidebar.querySelectorAll(`.sb-child[data-filter="${group}"]`).forEach(child => {
141 |         child.style.display = child.textContent.toLowerCase().includes(q) ? '' : 'none';
142 |       });
143 |     });
