8 | import { renderAccounts }  from './views/accounts.js';
9 | import { renderResources } from './views/resources.js';
10 | 
11 | // ── Boot: populate current user in nav ───────────────────────────
12 | async function boot() {
13 |   try {
14 |     const people = await getPeople();
15 |     const me = people.find(p => p.is_current_user);
16 |     if (me) {
17 |       document.getElementById('currentUserName').textContent = me.first_name + ' ' + me.last_name;
18 |     }
19 |   } catch (e) {
20 |     console.warn('Could not load user:', e.message);
21 |   }
22 | }
23 | 
24 | // ── Profile / account switcher dropdown ─────────────────────────
25 | function wireProfileDropdown() {
26 |   const userSection = document.getElementById('topnavUser');
27 |   const dropdown    = document.getElementById('userDropdown');
28 |   if (!userSection || !dropdown) return;
29 | 
30 |   userSection.addEventListener('click', e => {
31 |     e.stopPropagation();
32 |     dropdown.classList.toggle('open');
33 |   });
34 |   document.addEventListener('click', e => {
35 |     if (!userSection.contains(e.target)) dropdown.classList.remove('open');
36 |   });
37 | 
38 |   dropdown.querySelectorAll('.user-dropdown-item').forEach(item => {
39 |     item.addEventListener('click', e => {
40 |       e.stopPropagation();
41 |       dropdown.querySelectorAll('.user-dropdown-item').forEach(i => i.classList.remove('active'));
42 |       item.classList.add('active');
43 |       const nameEl = document.getElementById('currentUserName');
44 |       if (item.dataset.profile === 'sydney')       nameEl.textContent = 'Sydney Chin';
45 |       else if (item.dataset.profile === 'manager') nameEl.textContent = 'Chris Kennedy';
46 |       else if (item.dataset.profile === 'admin')   nameEl.textContent = 'Admin';
47 |       dropdown.classList.remove('open');
48 |     });
49 |   });
50 | }
51 | 
52 | // ── View registry ────────────────────────────────────────────────
53 | const VIEW_RENDERERS = {
54 |   org:       renderOrg,
55 |   cell:      renderSeller,
56 |   people:    renderPeople,
57 |   accounts:  renderAccounts,
58 |   resources: renderResources,
59 | };
60 | 
61 | const rendered = new Set();
62 | 
63 | async function activateView(viewName) {
64 |   // Update top nav
65 |   document.querySelectorAll('.topnav-link[data-view-link]').forEach(n => {
66 |     n.classList.toggle('active', n.dataset.viewLink === viewName);
67 |   });
68 | 
69 |   // Show the right view container
70 |   document.querySelectorAll('.main > .view').forEach(v => {
71 |     v.classList.toggle('active', v.id === `view-${viewName}`);
72 |   });
73 | 
74 |   // Render the view if not yet rendered
75 |   const container = document.getElementById(`view-${viewName}`);
76 |   if (!container) return;
77 | 
78 |   if (!rendered.has(viewName)) {
79 |     rendered.add(viewName);
80 |     try {
81 |       await VIEW_RENDERERS[viewName]?.(container);
82 |     } catch (err) {
83 |       container.innerHTML = `
84 |         <div class="page-header">
85 |           <div class="page-title">Error</div>
86 |           <div class="page-sub">${err.message}</div>
87 |         </div>
88 |         <div class="content" style="color:var(--muted);font-size:13px">
89 |           Make sure the server is running (<code>npm start</code>) and seeded (<code>npm run seed</code>).
90 |         </div>
91 |       `;
92 |     }
93 |   }
94 | }
95 | 
96 | // ── Top nav link clicks ──────────────────────────────────────────
97 | document.querySelectorAll('.topnav-link[data-view-link]').forEach(item => {
98 |   item.addEventListener('click', () => activateView(item.dataset.viewLink));
99 | });
