70 | // ── Structure: BTSS↔TSS pairing diagram ──────────────────────────
71 | function renderStructure(allPeople) {
72 |   const pane = document.getElementById('cell-tab-structure');
73 |   if (!pane) return;
74 | 
75 |   const me = allPeople.find(p => p.is_current_user) || allPeople[0];
76 | 
77 |   // Resolve team members by name (static team for Sydney)
78 |   const find = (fn, ln) => allPeople.find(p => p.first_name === fn && p.last_name === ln);
79 |   const chrisK  = find('Chris', 'Kennedy');
80 |   const robH    = find('Rob', 'Hanes');
81 |   const markH   = find('Mark', 'Hoffman');
82 |   const armada  = find('Armada', 'Veraepalli');
83 |   const rossH   = find('Ross', 'Holley');
84 |   const patrickM= find('Patrick', 'McBride');
85 | 
86 |   // Fallback to manager from data
87 |   const mgr = chrisK || allPeople.find(p => p.id === me?.manager_id);
88 | 
89 |   // BTSS column (left): Chris Kennedy (mgr), Sydney, Mark, Armada
90 |   const btssCol = [chrisK, me, markH, armada].filter(Boolean);
91 |   // TSS column (right): Rob Hanes (mgr), Ross, Patrick
92 |   const tssCol  = [robH, rossH, patrickM].filter(Boolean);
93 | 
94 |   // Pairings: [btss, tss]
95 |   const pairs = [
96 |     [markH, rossH],
97 |     [armada, patrickM],
98 |   ];
99 | 
100 |   // Node layout constants
101 |   const NODE_W = 140, NODE_H = 64, V_GAP = 20, H_GAP = 200;
102 |   const BTSS_X = 60, TSS_X = BTSS_X + NODE_W + H_GAP;
103 |   const START_Y = 120;
104 | 
105 |   // Compute Y positions for each person
106 |   const yPos = {};
107 |   btssCol.forEach((p, i) => { if (p) yPos[p.id] = START_Y + i * (NODE_H + V_GAP); });
108 |   tssCol.forEach((p, i)  => { if (p) yPos[p.id] = START_Y + i * (NODE_H + V_GAP); });
109 | 
110 |   const totalH = Math.max(btssCol.length, tssCol.length) * (NODE_H + V_GAP) + START_Y + 60;
111 |   const SVG_W  = TSS_X + NODE_W + 60;
112 | 
113 |   // Build SVG
