124 |       font-family="IBM Plex Sans, system-ui, sans-serif">Brand Technical Sales</text>
125 |     <text x="${TSS_X + NODE_W/2}" y="30" text-anchor="middle"
126 |       fill="#0ea5e9" font-size="11" font-weight="600" letter-spacing="1"
127 |       font-family="IBM Plex Sans, system-ui, sans-serif">TSS</text>
128 |     <text x="${TSS_X + NODE_W/2}" y="46" text-anchor="middle"
129 |       fill="#525252" font-size="10"
130 |       font-family="IBM Plex Sans, system-ui, sans-serif">Territory Sales</text>`;
131 | 
132 |   // Column divider
133 |   const midX = (BTSS_X + NODE_W + TSS_X) / 2;
134 |   svgHtml += `<line x1="${midX}" y1="60" x2="${midX}" y2="${totalH - 40}"
135 |     stroke="rgba(255,255,255,0.06)" stroke-width="1" stroke-dasharray="4,4"/>`;
136 | 
137 |   // Manager ↔ Manager reporting line (dashed)
138 |   if (chrisK && robH && yPos[chrisK.id] !== undefined && yPos[robH.id] !== undefined) {
139 |     const y1 = yPos[chrisK.id] + NODE_H / 2;
140 |     const y2 = yPos[robH.id]   + NODE_H / 2;
141 |     svgHtml += `<line
