147 |   }
148 | 
149 |   // Pairing lines (solid, colored, labeled)
150 |   pairs.forEach(([btss, tss], i) => {
151 |     if (!btss || !tss || yPos[btss.id] === undefined || yPos[tss.id] === undefined) return;
152 |     const y1 = yPos[btss.id] + NODE_H / 2;
153 |     const y2 = yPos[tss.id]  + NODE_H / 2;
154 |     const cx1 = BTSS_X + NODE_W;
155 |     const cx2 = TSS_X;
156 |     // Bezier curve for elegance
157 |     svgHtml += `<path
158 |       d="M ${cx1} ${y1} C ${midX} ${y1}, ${midX} ${y2}, ${cx2} ${y2}"
159 |       stroke="#0ea5e9" stroke-width="2" fill="none" opacity="0.7"/>
160 |     <circle cx="${midX}" cy="${(y1+y2)/2}" r="3" fill="#0ea5e9" opacity="0.7"/>
161 |     <text x="${midX + 6}" y="${(y1+y2)/2 + 4}" text-anchor="middle"
162 |       fill="#0ea5e9" font-size="9" opacity="0.8"
163 |       font-family="IBM Plex Sans, system-ui, sans-serif">paired</text>`;
164 |   });
165 | 
166 |   // Draw nodes
167 |   [...btssCol.map(p => ({p, x: BTSS_X})), ...tssCol.map(p => ({p, x: TSS_X}))].forEach(({p, x}) => {
168 |     if (!p || yPos[p.id] === undefined) return;
