179 |         <rect x="${x}" y="${y}" width="${NODE_W}" height="${NODE_H}" rx="6"
180 |           fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>
181 |         ${isMe_ ? `<rect x="${x-2}" y="${y-2}" width="${NODE_W+4}" height="${NODE_H+4}" rx="8"
182 |           fill="none" stroke="#4589ff" stroke-width="1" stroke-dasharray="3,3" opacity="0.5"/>` : ''}
