124 | // ── Build and render the full SVG map ─────────────────────────────
125 | function buildMap() {
126 |   const svg = document.getElementById('hmapSvg');
127 |   const stage = document.getElementById('hmapStage');
128 |   if (!svg || !stage) return;
129 | 
130 |   // --- Layout constants ---
131 |   const MARKET_R  = 64;   // market bubble radius
132 |   const ORG_R     = 44;   // org node radius
133 |   const TEAM_R    = 34;   // team node radius
134 |   const PERSON_R  = 26;   // person node radius
135 |   const PAD       = 40;
136 | 
137 |   // --- Group people by market → org → team ---
138 |   const markets = [...new Set(_all.map(p => p.market).filter(Boolean))];
139 |   const byMarket = {};
140 |   markets.forEach(m => { byMarket[m] = _all.filter(p => p.market === m); });
141 | 
142 |   // --- Position markets in a horizontal row, centered ---
143 |   const MARKET_STEP = 260;
144 |   const totalW = markets.length * MARKET_STEP;
145 | 
146 |   // Node positions stored for line drawing
147 |   const positions = {}; // key → {x,y}
148 | 
149 |   let nodes = ''; // SVG markup accumulator
150 |   let lines = ''; // connection lines (drawn under nodes)
151 | 
152 |   const marketY = 120;
153 | 
154 |   markets.forEach((mkt, mi) => {
155 |     const mx = PAD + mi * MARKET_STEP + MARKET_STEP / 2;
156 |     const my = marketY;
157 |     const mkey = `market:${mkt}`;
158 |     const color = MKT_COLOR[mkt] || '#525252';
159 |     const isMyMkt = _me?.market === mkt;
160 |     const isExpanded = _expanded.has(mkey);
161 |     const isSel = _sel?.type === 'market' && _sel.id === mkt;
162 | 
163 |     positions[mkey] = { x: mx, y: my };
164 | 
165 |     // Market bubble
166 |     nodes += marketNode(mx, my, MARKET_R, mkt, color, isMyMkt, isSel, isExpanded,
167 |       byMarket[mkt].length);
168 | 
169 |     if (!isExpanded) return;
170 | 
171 |     // --- Orgs within this market ---
172 |     const orgs = [...new Set(byMarket[mkt].map(p => p.comb).filter(Boolean))];
173 |     const orgStep = Math.max(180, MARKET_STEP / Math.max(orgs.length, 1));
174 |     const orgY = my + MARKET_R + 100;
175 |     const orgStartX = mx - ((orgs.length - 1) * orgStep) / 2;
176 | 
177 |     orgs.forEach((org, oi) => {
178 |       const ox = orgStartX + oi * orgStep;
179 |       const oy = orgY;
180 |       const okey = `org:${org}`;
181 |       const ocolor = ORG_COLOR[org] || '#525252';
182 |       const inOrg = byMarket[mkt].filter(p => p.comb === org);
183 |       const isMyOrg = _me?.comb === org;
184 |       const isOrgExp = _expanded.has(okey);
185 |       const isOrgSel = _sel?.type === 'org' && _sel.id === org;
186 | 
187 |       positions[okey] = { x: ox, y: oy };
188 | 
189 |       // Line: market → org
190 |       lines += connLine(mx, my + MARKET_R, ox, oy - ORG_R, color, 0.4);
191 | 
192 |       nodes += orgNode(ox, oy, ORG_R, org, ocolor, isMyOrg, isOrgSel, isOrgExp, inOrg.length);
193 | 
194 |       if (!isOrgExp) return;
195 | 
196 |       // --- Teams within this org ---
197 |       // A team = all people sharing the same manager_id within this org
198 |       const teamMap = {};
199 |       inOrg.forEach(p => {
200 |         const tid = teamId(p);
201 |         if (!teamMap[tid]) teamMap[tid] = [];
202 |         teamMap[tid].push(p);
203 |       });
204 |       // Also include managers themselves in "their own" team display
205 |       const teamKeys = Object.keys(teamMap).filter(k => k !== 'null:' + org);
206 | 
207 |       const teamStep = Math.max(160, orgStep);
208 |       const teamY = oy + ORG_R + 90;
209 |       const teamStartX = ox - ((teamKeys.length - 1) * teamStep) / 2;
210 | 
211 |       teamKeys.forEach((tk, ti) => {
212 |         const [mgrId, tcomb] = tk.split(':');
213 |         if (tcomb !== org) return;
214 |         const tx_ = teamStartX + ti * teamStep;
215 |         const ty_ = teamY;
216 |         const tkey = `team:${tk}`;
217 |         const members = teamMap[tk] || [];
218 |         const mgr = _all.find(p => p.id === parseInt(mgrId));
219 |         const label = mgr ? `${mgr.first_name} ${mgr.last_name}` : 'Team';
220 |         const isMyTeam = _me && teamId(_me) === tk;
221 |         const isTeamExp = _expanded.has(tkey);
222 |         const isTeamSel = _sel?.type === 'team' && _sel.id === tk;
223 | 
224 |         positions[tkey] = { x: tx_, y: ty_ };
225 | 
226 |         // Line: org → team
227 |         lines += connLine(ox, oy + ORG_R, tx_, ty_ - TEAM_R, ocolor, 0.35);
228 | 
229 |         nodes += teamNode(tx_, ty_, TEAM_R, tk, label, ocolor, isMyTeam, isTeamSel, isTeamExp, members.length);
230 | 
231 |         if (!isTeamExp) return;
232 | 
233 |         // --- People within this team ---
234 |         const allTeamMembers = [...members];
235 |         // Include the manager too if not already in members
236 |         if (mgr && !allTeamMembers.find(p => p.id === mgr.id)) {
237 |           allTeamMembers.unshift(mgr);
238 |         }
239 | 
240 |         const personStep = Math.max(70, teamStep / Math.max(allTeamMembers.length, 1));
241 |         const personY = ty_ + TEAM_R + 80;
242 |         const personStartX = tx_ - ((allTeamMembers.length - 1) * personStep) / 2;
243 | 
244 |         allTeamMembers.forEach((person, pi) => {
245 |           const px_ = personStartX + pi * personStep;
246 |           const py_ = personY;
247 |           const pkey = `person:${person.id}`;
248 |           const isMe_ = person.is_current_user;
249 |           const pSel  = _sel?.type === 'person' && _sel.id === person.id;
250 | 
251 |           positions[pkey] = { x: px_, y: py_ };
252 | 
253 |           // Line: team → person
254 |           lines += connLine(tx_, ty_ + TEAM_R, px_, py_ - PERSON_R, ocolor, 0.25);
255 | 
256 |           nodes += personNode(px_, py_, PERSON_R, person, isMe_, pSel);
257 |         });
258 |       });
259 |     });
260 |   });
261 | 
262 |   // Calculate total SVG dimensions from positions
263 |   let maxX = 800, maxY = 600;
264 |   Object.values(positions).forEach(({ x, y }) => {
265 |     if (x + 120 > maxX) maxX = x + 120;
266 |     if (y + 120 > maxY) maxY = y + 120;
267 |   });
268 |   _svgW = maxX + PAD;
269 |   _svgH = maxY + PAD;
270 | 
271 |   svg.setAttribute('width',   _svgW);
272 |   svg.setAttribute('height',  _svgH);
273 |   svg.setAttribute('viewBox', `0 0 ${_svgW} ${_svgH}`);
274 |   svg.innerHTML = `<g id="hmapLines">${lines}</g><g id="hmapNodes">${nodes}</g>`;
275 | 
276 |   // Wire all node clicks
277 |   svg.querySelectorAll('[data-node-key]').forEach(el => {
278 |     el.style.cursor = 'pointer';
279 |     el.addEventListener('click', e => {
280 |       e.stopPropagation();
281 |       handleNodeClick(el.dataset.nodeKey, el.dataset.nodeType, el.dataset.nodeId);
282 |     });
283 |   });
284 | 
285 |   applyTransform();
286 | }
