414 | function connLine(x1, y1, x2, y2, color, opacity = 0.3) {
415 |   return `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}"
416 |     stroke="${color}" stroke-width="1" opacity="${opacity}" pointer-events="none"/>`;
417 | }
