419 | function hexPts(cx, cy, r) {
420 |   return Array.from({ length: 6 }, (_, i) => {
421 |     const a = Math.PI / 3 * i - Math.PI / 6;
422 |     return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
423 |   }).join(' ');
424 | }
