// Hex geometry helpers
function hexPoints(cx, cy, r) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = (Math.PI / 3) * i - Math.PI / 6;
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(' ');
}

// ── View state ────────────────────────────────────────────────────
let _level    = 0;          // 0 = top, 1 = colony
let _colony   = null;       // active colony object
let _fn       = null;       // active function object
let _container = null;

// ── Entry ─────────────────────────────────────────────────────────
export async function renderOrg(container) {
  _container = container;
  _level = 0;
  _colony = null;
  _fn = null;

  container.innerHTML = `
    <div class="org-fn-shell">
      <div class="org-fn-topbar">
        <div class="org-fn-breadcrumb" id="orgFnBreadcrumb"></div>
        <div class="org-fn-tagline">How does IBM sell?</div>
      </div>
      <div class="org-fn-body" id="orgFnBody"></div>
    </div>
  `;

  renderLevel0();
}

// ── Level 0: four colonies ────────────────────────────────────────
function renderLevel0() {
  _level = 0;
  _colony = null;
  _fn = null;
  updateBreadcrumb();

  const body = document.getElementById('orgFnBody');
  if (!body) return;

  // SVG honeycomb — 2×2 grid of large hexes, offset rows
  const R = 90;          // hex radius
  const HW = R * Math.sqrt(3); // flat-to-flat width ≈ R * 1.732
  const HH = R * 2;
  const colGap = 8;
  const rowGap = 8;

  // Positions: col 0 and col 1, row 0 and row 1
  // Odd cols offset down by R * 1.5
  const cols = [0, 1];
  const rows = [0, 1];

  // We'll lay out in a 2×2 grid with pointy-top hexes:
  // col step = HW + colGap, row step = HH * 0.75 + rowGap (overlapping rows for hex tiling)
  const colStep = HW + colGap;
  const rowStep = HH * 0.75 + rowGap;

  const positions = COLONIES.map((col, i) => {
    const c = i % 2;
    const r = Math.floor(i / 2);
    const x = 80 + c * colStep + (r % 2 === 0 ? 0 : colStep / 2);
    const y = 80 + r * rowStep;
    return { col, x, y };
  });

  const svgW = 80 + 2 * colStep + R + 40;
  const svgH = 80 + 2 * rowStep + R + 40;

  let svgInner = '';
  positions.forEach(({ col, x, y }) => {
    const pts = hexPoints(x, y, R);
    const isYourColony = col.id === 'horizon'; // Horizon = Sydney's colony
    svgInner += `
      <g class="org-colony-hex" data-colony-id="${col.id}" style="cursor:pointer">
        ${isYourColony ? `<polygon points="${hexPoints(x, y, R + 9)}" fill="none" stroke="${col.color}" stroke-width="1.5" stroke-dasharray="5,4" opacity="0.45" pointer-events="none"/>` : ''}
        <polygon points="${pts}"
          fill="${isYourColony ? col.color + '22' : '#161616'}"
          stroke="${col.color}"
          stroke-width="${isYourColony ? 2 : 1.5}"
        />
        <text x="${x}" y="${y - 16}" text-anchor="middle" dominant-baseline="middle"
          fill="${col.color}" font-size="17" font-weight="600"
          font-family="IBM Plex Sans, system-ui, sans-serif" pointer-events="none">${col.label}</text>
        <text x="${x}" y="${y + 6}" text-anchor="middle" dominant-baseline="middle"
          fill="${col.color}99" font-size="11"
          font-family="IBM Plex Sans, system-ui, sans-serif" pointer-events="none">Colony</text>
        <text x="${x}" y="${y + 24}" text-anchor="middle" dominant-baseline="middle"
          fill="${col.color}66" font-size="10"
          font-family="IBM Plex Sans, system-ui, sans-serif" pointer-events="none">${col.sub}</text>
        ${isYourColony ? `
          <text x="${x}" y="${y - R - 14}" text-anchor="middle" dominant-baseline="middle"
            fill="${col.color}" font-size="10" font-weight="600" letter-spacing="0.5"
            font-family="IBM Plex Sans, system-ui, sans-serif" pointer-events="none">YOUR COLONY</text>` : ''}
      </g>`;
  });

  body.innerHTML = `
    <div class="org-fn-level0">
      <div class="org-fn-intro">
        <div class="org-fn-intro-title">IBM Sales Organization</div>
        <div class="org-fn-intro-sub">Select a colony to see the functions involved in selling and supporting accounts.</div>
      </div>
      <div class="org-fn-svg-wrap">
        <svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}"
          xmlns="http://www.w3.org/2000/svg" style="overflow:visible;display:block;margin:0 auto">
          ${svgInner}
        </svg>
      </div>
    </div>
  `;

  body.querySelectorAll('.org-colony-hex').forEach(el => {
    el.addEventListener('click', () => {
      const col = COLONIES.find(c => c.id === el.dataset.colonyId);
      if (col) renderLevel1(col);
    });
  });
}

// ── Level 1: functions within a colony ───────────────────────────
function renderLevel1(colony) {
  _level = 1;
  _colony = colony;
  _fn = null;
  updateBreadcrumb();

  const body = document.getElementById('orgFnBody');
  if (!body) return;

  const fns = colony.functions;
  const color = colony.color;

  // Hex grid layout for functions — wrap at 3 per row
  const R = 68;
  const colStep = R * Math.sqrt(3) + 6;
  const rowStep = R * 1.5 + 6;
  const PER_ROW = 3;

  const positions = fns.map((fn, i) => {
    const col = i % PER_ROW;
    const row = Math.floor(i / PER_ROW);
    const offsetX = row % 2 !== 0 ? colStep / 2 : 0;
    return { fn, x: 80 + col * colStep + offsetX, y: 80 + row * rowStep };
  });

  const maxX = Math.max(...positions.map(p => p.x)) + R + 60;
  const maxY = Math.max(...positions.map(p => p.y)) + R + 60;

  let svgInner = '';
  positions.forEach(({ fn, x, y }) => {
    const pts = hexPoints(x, y, R);
    const isYou = fn.youAreHere;
    svgInner += `
      <g class="org-fn-hex" data-fn-id="${fn.id}" style="cursor:pointer">
        ${isYou ? `<polygon points="${hexPoints(x, y, R + 8)}" fill="none" stroke="${color}" stroke-width="1.5" stroke-dasharray="4,3" opacity="0.4" pointer-events="none"/>` : ''}
        <polygon points="${pts}"
          fill="${isYou ? color + '20' : '#141414'}"
          stroke="${color}"
          stroke-width="${isYou ? 2 : 1.5}"
        />
        <text x="${x}" y="${y - 14}" text-anchor="middle" dominant-baseline="middle"
          fill="${color}" font-size="16" font-weight="700"
          font-family="IBM Plex Sans, system-ui, sans-serif" pointer-events="none">${fn.abbr}</text>
        <text x="${x}" y="${y + 6}" text-anchor="middle" dominant-baseline="middle"
          fill="${isYou ? '#e0e0e0' : '#888'}" font-size="10"
          font-family="IBM Plex Sans, system-ui, sans-serif" pointer-events="none"
          >${fn.label.length > 22 ? fn.label.slice(0, 22) + '…' : fn.label}</text>
        ${fn.members?.length ? `
          <text x="${x}" y="${y + 22}" text-anchor="middle" dominant-baseline="middle"
            fill="${color}88" font-size="9"
            font-family="IBM Plex Sans, system-ui, sans-serif" pointer-events="none">${fn.members.length} members</text>` : ''}
        ${isYou ? `
          <text x="${x}" y="${y - R - 12}" text-anchor="middle" dominant-baseline="middle"
            fill="${color}" font-size="9" font-weight="600" letter-spacing="0.5"
            font-family="IBM Plex Sans, system-ui, sans-serif" pointer-events="none">YOU ARE HERE</text>` : ''}
      </g>`;
  });

  body.innerHTML = `
    <div class="org-fn-level1">
      <div class="org-fn-colony-header">
        <div class="org-fn-colony-name" style="color:${color}">${colony.label} Colony</div>
        <div class="org-fn-colony-sub">${colony.sub} · Click a function to learn more</div>
      </div>
      <div class="org-fn-svg-wrap">
        <svg width="${maxX}" height="${maxY}" viewBox="0 0 ${maxX} ${maxY}"
          xmlns="http://www.w3.org/2000/svg" style="overflow:visible;display:block;margin:0 auto">
          ${svgInner}
        </svg>
      </div>
    </div>
  `;

  body.querySelectorAll('.org-fn-hex').forEach(el => {
    el.addEventListener('click', () => {
      const fn = colony.functions.find(f => f.id === el.dataset.fnId);
      if (fn) renderDetail(fn, colony);
    });
  });
}

// ── Level 2: function detail card ────────────────────────────────
function renderDetail(fn, colony) {
  _fn = fn;
  updateBreadcrumb();

  const body = document.getElementById('orgFnBody');
  if (!body) return;

  const color = colony.color;
  const membersHtml = fn.members?.length
    ? fn.members.map(m => {
        const isYou = m === 'Sydney Chin';
        return `<span class="org-fn-member${isYou ? ' org-fn-member-you' : ''}" style="${isYou ? `border-color:${color};color:${color}` : ''}">${m}${isYou ? ' ·&nbsp;You' : ''}</span>`;
      }).join('')
    : `<span class="org-fn-member-empty">Members vary by territory</span>`;

  const worksWithHtml = fn.worksWith?.length
    ? fn.worksWith.map(w => `<span class="org-fn-works-tag">${w}</span>`).join('')
    : '—';

  body.innerHTML = `
    <div class="org-fn-detail-wrap">
      <div class="org-fn-detail">
        <div class="org-fn-detail-head" style="border-left:4px solid ${color}">
          <div class="org-fn-detail-abbr" style="color:${color}">${fn.abbr}</div>
          <div class="org-fn-detail-label">${fn.label}</div>
        </div>

        <div class="org-fn-detail-section">
          <div class="org-fn-detail-section-title">What they do</div>
          <div class="org-fn-detail-text">${fn.purpose}</div>
        </div>

        <div class="org-fn-detail-section">
          <div class="org-fn-detail-section-title">Reports to</div>
          <div class="org-fn-detail-text">${fn.manager}</div>
        </div>

        <div class="org-fn-detail-section">
          <div class="org-fn-detail-section-title">Works closely with</div>
          <div class="org-fn-detail-tags">${worksWithHtml}</div>
        </div>

        ${fn.members !== undefined ? `
        <div class="org-fn-detail-section">
          <div class="org-fn-detail-section-title">Team members</div>
          <div class="org-fn-detail-members">${membersHtml}</div>
        </div>` : ''}

        <div class="org-fn-back-row">
          <button class="org-fn-back-btn" id="orgFnBackBtn">← Back to ${colony.label} Colony</button>
        </div>
      </div>
    </div>
  `;

  document.getElementById('orgFnBackBtn')?.addEventListener('click', () => renderLevel1(colony));
}

// ── Breadcrumb ────────────────────────────────────────────────────
function updateBreadcrumb() {
  const el = document.getElementById('orgFnBreadcrumb');
  if (!el) return;

  const crumbs = [{ label: 'IBM', action: () => renderLevel0() }];
  if (_colony) crumbs.push({ label: _colony.label + ' Colony', action: () => renderLevel1(_colony) });
  if (_fn)     crumbs.push({ label: _fn.abbr, action: null });

  el.innerHTML = crumbs.map((c, i) => {
    const sep = i > 0 ? `<span class="org-fn-bc-sep">›</span>` : '';
    const cls = c.action ? 'org-fn-bc-link' : 'org-fn-bc-active';
    return `${sep}<span class="${cls}">${c.label}</span>`;
  }).join('');

  el.querySelectorAll('.org-fn-bc-link').forEach((seg, i) => {
    seg.style.cursor = 'pointer';
    seg.addEventListener('click', crumbs[i].action);
  });
}

