/**
 * org.js — Organization tab
 *
 * Purpose: "How does IBM sell, and where does my role fit?"
 *
 * Navigation model:
 *   Level 0 — IBM (four colonies as hexagons)
 *   Level 1 — Colony (functions/roles within that colony)
 *   Level 2 — Function detail card (what, manager, works with, members)
 *
 * No individual people at levels 0–1.
 * Functions are static role definitions; some have member lists from the DB.
 */

// ── Static function definitions ───────────────────────────────────
// Each colony lists the major functions involved in selling/supporting accounts.
const COLONIES = [
  {
    id: 'enterprise',
    label: 'Enterprise',
    color: '#4589ff',
    sub: 'Large-account coverage',
    functions: [
      {
        id: 'bss-e', abbr: 'BSS', label: 'Brand Sales Specialist',
        purpose: 'Own quota and pipeline for a specific IBM brand (watsonx, Security, Automation). Engage customers from discovery through close.',
        manager: 'Colony VP',
        worksWith: ['BTSS', 'CSM', 'Partner Ecosystem'],
        members: [],
      },
      {
        id: 'bts-e', abbr: 'BTSS', label: 'Brand Technical Sales Specialist',
        purpose: 'Provide technical depth on IBM products. Run demos, POCs, and architecture workshops alongside the BSS.',
        manager: 'Colony VP',
