  border-top: 1px solid var(--border-subtle);
  padding-top: 10px;
  line-height: 1.5;
}
.nc-followup {
  font-size: 11px;
  color: var(--accent-magenta);
  font-weight: 600;
  margin-top: 6px;
  text-transform: uppercase;
  letter-spacing: 0.32px;
}

/* ── ACCOUNT HIVE ────────────────────────────────────────────── */
.accounts-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.acct-filter {
  font-size: 12px;
  padding: 5px 12px;
  border: 1px solid var(--border);
  background: var(--surface);
  cursor: pointer;
  color: var(--muted);
  transition: all 0.1s;
  letter-spacing: 0.32px;
  text-transform: uppercase;
  font-weight: 500;
  border-radius: 0;
}
.acct-filter:hover { background: var(--surface-2); color: var(--text); }
.acct-filter.active { background: var(--ibm-blue-60); color: #fff; border-color: var(--ibm-blue-60); }
.acct-legend { display: flex; align-items: center; gap: 16px; margin-left: auto; flex-wrap: wrap; }
.legend-item { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.32px; }
.legend-dot  { width: 10px; height: 10px; flex-shrink: 0; }

.acct-hex {
  width: 90px;
  height: 100px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform 0.15s, filter 0.15s, opacity 0.2s;
  padding: 10px 6px;
  text-align: center;
}
.acct-hex:hover { transform: scale(1.06); filter: brightness(1.2); }
.acct-name  { font-size: 9px; font-weight: 700; color: #fff; text-shadow: 0 1px 3px rgba(0,0,0,0.5); line-height: 1.2; max-width: 78px; overflow: hidden; text-overflow: ellipsis; }
.acct-val   { font-size: 8px; color: rgba(255,255,255,0.9); margin-top: 3px; text-shadow: 0 1px 2px rgba(0,0,0,0.4); font-weight: 600; }
.acct-stage { font-size: 8px; color: rgba(255,255,255,0.7); margin-top: 1px; }

/* Stage colors */
.col-won        { background: var(--stage-won); }
.col-negotiation{ background: var(--stage-negotiation); }
.col-proposal   { background: var(--stage-proposal); }
.col-risk       { background: var(--stage-risk); }
.col-prospect   { background: var(--stage-prospect); }

/* ── EXEC VIEW ───────────────────────────────────────────────── */
.exec-section { margin-bottom: 36px; }
.exec-title {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--muted);
}
.exec-badge {
  font-size: 11px;
  padding: 2px 8px;
  color: #fff;
  font-weight: 600;
  letter-spacing: 0.32px;
}

/* ── DETAIL PANEL (slide-over) ───────────────────────────────── */
.panel-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  z-index: 100;
  display: none;
  align-items: flex-start;
  justify-content: flex-end;
}
.panel-overlay.open { display: flex; }

.detail-panel {
  background: var(--surface);
  width: 352px;
  height: 100%;
  overflow-y: auto;
  box-shadow: -4px 0 32px rgba(0,0,0,0.6);
  display: flex;
  flex-direction: column;
  border-left: 1px solid var(--border-subtle);
}

.dp-header {
  padding: 20px 20px 16px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: flex-start;
  gap: 14px;
  background: var(--sidebar-bg);
}

/* Hex-shaped avatar in detail panel — all profile views are hive-shaped */
.dp-avatar {
  width: 56px;
  height: 63px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}

.dp-name   { font-size: 16px; font-weight: 400; letter-spacing: 0; color: var(--text); }
.dp-role   { font-size: 12px; color: var(--muted); margin-top: 3px; }
.dp-market {
  font-size: 11px;
  padding: 2px 8px;
  background: rgba(69,137,255,0.14);
  color: var(--ibm-blue-40);
  display: inline-block;
  margin-top: 6px;
  font-weight: 500;
  letter-spacing: 0.32px;
  text-transform: uppercase;
}
.dp-close {
  margin-left: auto;
  font-size: 18px;
  cursor: pointer;
  color: var(--muted);
  padding: 2px 6px;
  line-height: 1;
  transition: color 0.1s;
}
.dp-close:hover { color: var(--text); }

.dp-body { padding: 16px 20px; flex: 1; display: flex; flex-direction: column; gap: 20px; }
.dp-section { display: flex; flex-direction: column; gap: 8px; }
.dp-section-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
  font-weight: 600;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-subtle);
}
.dp-row { display: flex; align-items: flex-start; gap: 10px; font-size: 13px; }
.dp-label { color: var(--muted); min-width: 80px; font-size: 12px; flex-shrink: 0; letter-spacing: 0.16px; }
.dp-value { color: var(--text); font-weight: 400; }
.dp-link  { color: var(--ibm-blue-40); text-decoration: none; font-size: 13px; }
.dp-link:hover { text-decoration: underline; }

.dp-note-item {
  font-size: 13px;
  color: var(--text);
  line-height: 1.6;
  background: var(--surface-2);
  padding: 10px 12px;
  border-left: 3px solid var(--ibm-blue-60);
  margin-bottom: 6px;
}
.dp-note-date { font-size: 11px; color: var(--muted); margin-top: 4px; }

.dp-tag-row { display: flex; gap: 6px; flex-wrap: wrap; }
.dp-tag {
  font-size: 11px;
  padding: 3px 10px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  letter-spacing: 0.32px;
}

/* ── LOADING STATE ───────────────────────────────────────────── */
.loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px;
  color: var(--muted);
  font-size: 14px;
}


/* ── ROLE-CATEGORY LEGEND ────────────────────────────────────── */
.cat-legend {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
  margin-top: 20px;
  padding: 12px 16px;
  border-top: 1px solid var(--border-subtle);
  background: var(--surface);
}
.cat-legend-item { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 500; color: var(--muted); letter-spacing: 0.32px; text-transform: uppercase; }
.cat-legend-marker { width: 9px; height: 9px; background: rgba(255,255,255,0.85); flex-shrink: 0; }
.cat-legend-marker.cat-sales   { border-radius: 50%; }
.cat-legend-marker.cat-tech    { transform: rotate(45deg); }
.cat-legend-marker.cat-support { clip-path: polygon(0 0, 100% 0, 100% 100%); }

/* ── BUTTONS ─────────────────────────────────────────────────── */
.btn-primary {
  padding: 8px 16px;
  border: none;
  background: var(--ibm-blue-60);
  color: #fff;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
  letter-spacing: 0.16px;
  font-family: inherit;
  transition: background 0.1s;
  border-radius: 0;
}
.btn-primary:hover { background: var(--ibm-blue-70); }

.btn-secondary {
  padding: 8px 16px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text);
  font-size: 14px;
  cursor: pointer;
  letter-spacing: 0.16px;
  font-family: inherit;
  transition: background 0.1s;
  border-radius: 0;
}
.btn-secondary:hover { background: var(--surface-2); }

.btn-danger {
  padding: 8px 16px;
  border: 1px solid rgba(217,70,239,0.4);
  background: transparent;
  color: var(--accent-magenta);
  font-size: 14px;
  cursor: pointer;
  letter-spacing: 0.16px;
  font-family: inherit;
  border-radius: 0;
}
.btn-danger:hover { background: rgba(217,70,239,0.1); }

/* ── CONNECTIONS TOOLBAR / CRUD ─────────────────────────────── */
.nc-actions {
  display: flex;
  gap: 4px;
  margin-left: auto;
}
.nc-icon-btn {
  width: 26px; height: 26px;
  border: 1px solid var(--border-subtle);
  background: var(--surface);
  color: var(--muted);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  font-size: 12px;
  flex-shrink: 0;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
}
.nc-icon-btn:hover { background: var(--surface-2); color: var(--text); border-color: var(--ibm-blue-50); }
.nc-icon-btn.danger:hover { border-color: var(--accent-magenta); color: var(--accent-magenta); background: rgba(217,70,239,0.08); }

/* ── MODAL ───────────────────────────────────────────────────── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.65);
  z-index: 200;
  display: none;
  align-items: center;
  justify-content: center;
}
.modal-overlay.open { display: flex; }
.modal {
  background: var(--surface);
  border: 1px solid var(--border);
  width: 400px;
  max-width: calc(100vw - 32px);
  max-height: calc(100vh - 64px);
  overflow-y: auto;
  box-shadow: 0 16px 48px rgba(0,0,0,0.6);
  border-radius: 0;
}
.modal-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--sidebar-bg);
}
.modal-title { font-size: 16px; font-weight: 400; letter-spacing: 0; }
.modal-close { cursor: pointer; color: var(--muted); font-size: 16px; padding: 2px 6px; transition: color 0.1s; }
.modal-close:hover { color: var(--text); }
.modal-body { padding: 20px; display: flex; flex-direction: column; gap: 16px; }
.modal-body label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 12px;
  color: var(--muted);
  font-weight: 600;
  letter-spacing: 0.32px;
  text-transform: uppercase;
}
.modal-body input[type="text"],
.modal-body select,
.modal-body textarea {
  padding: 8px 10px;
  border: none;
  border-bottom: 2px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  resize: vertical;
  border-radius: 0;
  transition: border-color 0.1s;
}
.modal-body input[type="text"]:focus,
.modal-body select:focus,
.modal-body textarea:focus { outline: none; border-bottom-color: var(--ibm-blue-50); }
.modal-checkbox { flex-direction: row !important; align-items: center; gap: 8px !important; text-transform: none !important; letter-spacing: 0 !important; font-size: 13px !important; }
.modal-checkbox input { width: auto; accent-color: var(--ibm-blue-50); }
.modal-actions { display: flex; align-items: center; gap: 8px; margin-top: 4px; }

/* ── RESPONSIVE ──────────────────────────────────────────────── */
@media (max-width: 640px) {
  .sidebar { display: none; }
  .content { padding: 16px; }
  .detail-panel { width: 100vw; }
  .topnav-search { display: none; }
  .topnav-links { display: none; }
}

/* ─────────────────────────────────────────────────────────────
   COLONY HIVE VIEW — full-screen zoomable hexagon grid
   ───────────────────────────────────────────────────────────── */

/* Colony view fills the full flex area with its own layout */
.colony-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

/* Sticky toolbar at top of colony view */
.colony-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  height: 48px;
  flex-shrink: 0;
  background: var(--sidebar-bg);
  border-bottom: 1px solid var(--border-subtle);
  gap: 16px;
}
.colony-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.colony-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.16px;
}
.colony-subtitle {
  font-size: 12px;
  color: var(--muted);
}
.colony-toolbar-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}
.colony-zoom-btn {
  width: 32px;
  height: 32px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-secondary);
  font-size: 18px;
  font-family: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
  flex-shrink: 0;
}
.colony-zoom-btn:hover { background: var(--surface-2); color: #fff; }

/* The scrollable viewport — cursor:grab, overflow:hidden */
.colony-viewport {
  flex: 1;
  overflow: hidden;
  position: relative;
  cursor: grab;
  background: var(--bg);
}
.colony-viewport:active { cursor: grabbing; }

/* SVG colony hive — transforms applied by JS */
.colony-svg {
  position: absolute;
  top: 0;
  left: 0;
  transform-origin: 0 0;
  will-change: transform;
  overflow: visible;
  display: block;
}

/* SVG text labels — initially hidden, JS toggles opacity based on scale */
.colony-svg .hex-label-name,
.colony-svg .hex-label-role,
.colony-svg .colony-section-label {
  transition: opacity 0.2s;
  user-select: none;
}

/* Hover brightening on hex polygons — done via JS filter on parent SVG element */

/* ─────────────────────────────────────────────────────────────
   PROFILE / ACCOUNT SWITCHER DROPDOWN (name click)
   ───────────────────────────────────────────────────────────── */
.topnav-user {
  position: relative;
}
.user-dropdown {
  position: absolute;
  top: 100%;
  right: 0;
  background: #111111;
  border: 1px solid rgba(255,255,255,0.12);
  min-width: 220px;
  z-index: 500;
  display: none;
  flex-direction: column;
  box-shadow: 0 8px 32px rgba(0,0,0,0.7);
}
.user-dropdown.open { display: flex; }
.user-dropdown-header {
  padding: 10px 16px 8px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #525252;
  font-weight: 600;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.user-dropdown-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 16px;
  cursor: pointer;
  font-size: 13px;
  color: #8d8d8d;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  border-left: 2px solid transparent;
  transition: color 0.1s;
}
.user-dropdown-item:last-child { border-bottom: none; }
.user-dropdown-item:hover { color: #fff; }
.user-dropdown-item.active {
  color: #fff;
  border-left-color: rgba(255,255,255,0.5);
}
.user-dropdown-avatar {
  width: 22px;
  height: 25px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  background: #333333;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  font-weight: 700;
  color: #8d8d8d;
  flex-shrink: 0;
}
.user-dropdown-info { display: flex; flex-direction: column; gap: 2px; }
.user-dropdown-name { font-size: 13px; font-weight: 400; color: inherit; }
.user-dropdown-role { font-size: 11px; color: #525252; }

/* ── HIVE VIEW (The Hive tab) ─────────────────────────────────── */
.hive-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}
.hive-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  height: 44px;
  flex-shrink: 0;
  background: #000;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  gap: 16px;
}
.hive-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.hive-title {
  font-size: 13px;
  font-weight: 500;
  color: #c6c6c6;
}
.hive-subtitle {
  font-size: 11px;
  color: #3a3a3a;
}
.hive-toolbar-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ── RESOURCES EMPTY STATE ───────────────────────────────────── */
.resources-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 24px;
  text-align: center;
  color: var(--muted);
}
.resources-empty-icon {
  font-size: 40px;
  margin-bottom: 20px;
  color: #2a2a2a;
}
.resources-empty-title {
  font-size: 16px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: 8px;
}
.resources-empty-sub {
  font-size: 13px;
  color: var(--muted);
  max-width: 360px;
  line-height: 1.6;
}

/* ── ORG HIVE PAGE ───────────────────────────────────────────── */
.org-hive-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: #000;
}
.org-hive-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 44px;
  padding: 0 20px;
  background: #000;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  flex-shrink: 0;
  gap: 16px;
}
.org-hive-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.org-hive-title {
  font-size: 13px;
  font-weight: 500;
  color: #c6c6c6;
}
.org-hive-subtitle {
  font-size: 11px;
  color: #3a3a3a;
}
.org-hive-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Sort buttons in org toolbar */
.org-sort-btn {
  padding: 3px 10px;
  font-size: 11px;
  font-family: inherit;
  border: 1px solid rgba(255,255,255,0.12);
  background: transparent;
  color: #525252;
  cursor: pointer;
  letter-spacing: 0.16px;
  transition: color 0.1s, background 0.1s, border-color 0.1s;
  border-radius: 0;
}
.org-sort-btn:hover { color: #c6c6c6; border-color: rgba(255,255,255,0.25); }
.org-sort-btn.active {
  color: #fff;
  background: rgba(69,137,255,0.15);
  border-color: rgba(69,137,255,0.5);
}

/* Person hex names — hidden by default, shown on zoom via JS */
.org-hex-name {
  transition: opacity 0.15s;
  pointer-events: none;
  user-select: none;
}
.org-group-label {
  transition: opacity 0.15s;
  pointer-events: none;
  user-select: none;
}

/* Person hex hover effect */
.person-hex polygon:first-child {
  transition: filter 0.12s;
}
.person-hex:hover polygon:first-child {
  filter: brightness(1.3);
}

/* ── ORG COLONY / PERSON MODAL ──────────────────────────────── */
.org-modal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.7);
  z-index: 400;
  align-items: center;
  justify-content: center;
}
.org-modal-overlay.open { display: flex; }
.org-modal {
  background: #161616;
  border: 1px solid rgba(255,255,255,0.12);
  width: 460px;
  max-width: 90vw;
  max-height: 80vh;
  overflow-y: auto;
  padding: 0;
}
.org-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.org-modal-title {
  font-size: 16px;
  font-weight: 400;
  letter-spacing: 0.16px;
}
.org-modal-close {
  cursor: pointer;
  color: #525252;
  font-size: 16px;
  padding: 2px 6px;
  transition: color 0.1s;
}
.org-modal-close:hover { color: #fff; }
.org-modal-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.org-modal-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.org-modal-badge {
  display: inline-block;
  font-size: 11px;
  padding: 2px 10px;
  border: 1px solid;
  font-weight: 500;
  letter-spacing: 0.32px;
  text-transform: uppercase;
}
.org-modal-desc {
  font-size: 13px;
  line-height: 1.65;
  color: #c6c6c6;
}
.org-modal-section-title {
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.64px;
  color: #525252;
  margin-bottom: -4px;
}
.org-modal-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.org-modal-tag {
  font-size: 11px;
  padding: 3px 9px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  color: #a8a8a8;
  letter-spacing: 0.16px;
}
.org-modal-person-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px 16px;
}
.org-modal-field {
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 13px;
  color: #f4f4f4;
}
.org-modal-field-label {
  font-size: 11px;
  color: #525252;
  text-transform: uppercase;
  letter-spacing: 0.32px;
}

/* ── CELL / STRUCTURE HEX GRID ───────────────────────────────── */
.cell-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}
.cell-hex-grid {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  padding: 32px 24px;
}
.cell-hex-row {
  display: flex;
  gap: 3px;
  margin-bottom: -14px;
}
.cell-hex-row:nth-child(even) { margin-left: 57px; }
.cell-hex-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
}
.cell-hex-svg {
  display: block;
  overflow: visible;
}
.cell-hex-label {
  font-size: 10px;
  color: #a8a8a8;
  margin-top: 4px;
  text-align: center;
  max-width: 90px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cell-hex-label.you { color: #4d7bff; font-weight: 500; }

/* ── CONNECTIONS NETWORK ─────────────────────────────────────── */
.connections-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  padding: 24px;
  gap: 20px;
}

/* ── RESOURCES ───────────────────────────────────────────────── */
.res-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow-y: auto;
}
.res-header {
  padding: 24px 28px 16px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.res-header-title {
  font-size: 18px;
  font-weight: 300;
  letter-spacing: -0.2px;
  margin-bottom: 4px;
}
.res-header-sub {
  font-size: 12px;
  color: #525252;
}
.res-body {
  padding: 24px 28px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}
.res-section-title {
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.64px;
  color: #525252;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.res-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1px;
  background: rgba(255,255,255,0.06);
}
.res-card {
  background: #0d0d0d;
  padding: 16px 18px;
  cursor: pointer;
  transition: background 0.12s;
  border-left: 2px solid transparent;
}
.res-card:hover {
  background: #111;
  border-left-color: var(--ibm-blue-50);
}
.res-card-name {
  font-size: 13px;
  font-weight: 500;
  color: #f4f4f4;
  margin-bottom: 4px;
}
.res-card-desc {
  font-size: 12px;
  color: #525252;
  line-height: 1.55;
}
.res-card-link {
  font-size: 11px;
  color: var(--ibm-blue-40);
  margin-top: 8px;
  text-decoration: none;
}
.res-card-link:hover { text-decoration: underline; }
.res-team-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.res-team-table th {
  text-align: left;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.32px;
  color: #525252;
  padding: 0 12px 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.res-team-table td {
  padding: 10px 12px 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  color: #c6c6c6;
  vertical-align: middle;
}
.res-team-table tr:last-child td { border-bottom: none; }
.res-role-pill {
  display: inline-block;
  font-size: 10px;
  padding: 2px 7px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  color: #a8a8a8;
  letter-spacing: 0.16px;
  white-space: nowrap;
}
.res-product-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.res-product-pill {
  font-size: 12px;
  padding: 5px 12px;
  background: rgba(77,123,255,0.1);
  border: 1px solid rgba(77,123,255,0.2);
  color: #4d7bff;
  letter-spacing: 0.16px;
}

/* ── RESOURCES EXTENDED ──────────────────────────────────────── */
.res-section {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.res-section + .res-section {
  margin-top: 32px;
}

/* Motion cards */
.res-motion-card {
  display: flex;
  gap: 16px;
  padding: 16px 18px;
  background: #0d0d0d;
  border-left: 2px solid rgba(255,255,255,0.06);
  transition: border-color 0.12s;
}
.res-motion-card:hover { border-left-color: var(--ibm-blue-50); }
.res-motion-num {
  font-size: 22px;
  font-weight: 300;
  color: rgba(77,123,255,0.4);
  min-width: 24px;
  line-height: 1;
  padding-top: 2px;
  flex-shrink: 0;
}
.res-motion-content { flex: 1; min-width: 0; }
.res-motion-title {
  font-size: 13px;
  font-weight: 500;
  color: #f4f4f4;
  margin-bottom: 4px;
}
.res-motion-desc {
  font-size: 12px;
  color: #6f6f6f;
  margin-bottom: 10px;
  line-height: 1.55;
}
.res-motion-actions {
  margin: 0 0 10px 0;
  padding-left: 16px;
  color: #a8a8a8;
  font-size: 12px;
  line-height: 1.7;
}
.res-motion-tools {
  padding-top: 8px;
  border-top: 1px solid rgba(255,255,255,0.05);
}

/* GTM phase rows */
.res-phase {
  display: flex;
  gap: 20px;
  padding: 14px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.res-phase:last-child { border-bottom: none; }
.res-phase-num {
  font-size: 10px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: .5px;
  color: #4d7bff;
  min-width: 56px;
  padding-top: 2px;
  flex-shrink: 0;
}
.res-phase-title {
  font-size: 13px;
  font-weight: 500;
  color: #f4f4f4;
  margin-bottom: 6px;
}
.res-phase-bullets {
  margin: 0;
  padding-left: 16px;
  color: #525252;
  font-size: 12px;
  line-height: 1.75;
}
.res-phase-bullets em { color: #3d5afe; font-style: normal; }

/* ── PEOPLE DIRECTORY ────────────────────────────────────────── */
.people-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  flex-shrink: 0;
  flex-wrap: wrap;
  background: var(--sidebar-bg);
}

.people-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1px;
  background: rgba(255,255,255,0.05);
  flex: 1;
  overflow-y: auto;
  align-content: start;
}

.people-card {
  background: var(--surface);
  padding: 14px 16px;
  cursor: pointer;
  transition: background 0.1s;
  border-left: 2px solid transparent;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.people-card:hover { background: var(--surface-2); border-left-color: var(--ibm-blue-50); }
.people-card.people-card-me { border-left-color: rgba(77,123,255,0.6); background: rgba(15,33,77,0.3); }
.people-card.people-card-me:hover { background: rgba(15,33,77,0.5); }

.pc-top {
  display: flex;
  align-items: center;
  gap: 12px;
}
.pc-avatar-hex {
  flex-shrink: 0;
  display: block;
}
.pc-info { flex: 1; min-width: 0; }
.pc-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: 0.16px;
}
.pc-you {
  font-size: 10px;
  padding: 1px 6px;
  background: rgba(77,123,255,0.15);
  color: #4d7bff;
  font-weight: 600;
  letter-spacing: 0.32px;
  margin-left: 4px;
  vertical-align: middle;
}
.pc-role {
  font-size: 11px;
  color: var(--muted);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pc-colony {
  font-size: 10px;
  font-weight: 500;
  margin-top: 3px;
  letter-spacing: 0.16px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pc-meta {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.pc-badge {
  font-size: 10px;
  padding: 2px 7px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  color: #6f6f6f;
  letter-spacing: 0.16px;
  white-space: nowrap;
}
.pc-badge-market {
  background: rgba(69,137,255,0.08);
  border-color: rgba(69,137,255,0.2);
  color: #4d7bff;
}

/* ═══════════════════════════════════════════════════════════════
   ORG CONTEXT VIEW  — org-page, breadcrumb, nodes, detail panel
   ═══════════════════════════════════════════════════════════════ */

/* Page wrapper fills the view */
.org-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: var(--bg);
  overflow: hidden;
}

/* ── Top bar: breadcrumb + You Are Here ── */
.org-topbar {
  display: flex;
  align-items: stretch;
  gap: 0;
  flex-shrink: 0;
  border-bottom: 1px solid var(--border-subtle);
  background: #0d0d0d;
  min-height: 56px;
}

.org-breadcrumb {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 0 20px;
  font-size: 13px;
  flex: 1;
  flex-wrap: wrap;
}
.bc-segment {
  color: var(--text-secondary);
  transition: color 0.1s;
}
.bc-segment:hover { color: #fff; }
.bc-sep { color: #444; font-size: 12px; }
.bc-you {
  color: var(--ibm-blue-40);
  font-weight: 500;
  cursor: default;
}

.org-you-here {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 10px 20px;
  border-left: 1px solid var(--border-subtle);
  background: rgba(69,137,255,0.06);
  min-width: 240px;
  max-width: 320px;
  flex-shrink: 0;
}
.yah-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--ibm-blue-40);
  font-weight: 600;
  margin-bottom: 2px;
}
.yah-name {
  font-size: 15px;
  font-weight: 500;
  color: #fff;
  letter-spacing: 0.16px;
}
.yah-meta {
  font-size: 12px;
  color: var(--text-secondary);
  margin-top: 2px;
}
.yah-mgr {
  font-size: 11px;
  color: var(--muted);
  margin-top: 3px;
}
.yah-mgr strong { color: var(--text-secondary); font-weight: 500; }

/* ── Level navigator ── */
.org-level-nav {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 0 20px;
  height: 40px;
  background: #111;
  border-bottom: 1px solid var(--border-subtle);
  flex-shrink: 0;
}
.org-level-btn {
  padding: 6px 14px;
  font-size: 13px;
  font-family: inherit;
  background: transparent;
  border: none;
  color: var(--muted);
  cursor: pointer;
  letter-spacing: 0.16px;
  transition: color 0.1s;
  border-bottom: 2px solid transparent;
  height: 100%;
}
.org-level-btn:hover { color: var(--text); }
.org-level-btn.active { color: #fff; border-bottom-color: var(--ibm-blue-50); }
.org-level-sep { color: #333; font-size: 13px; padding: 0 2px; }

/* ── Active filter chips bar ── */
.org-filter-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 20px;
  background: rgba(69,137,255,0.05);
  border-bottom: 1px solid rgba(69,137,255,0.15);
  flex-shrink: 0;
  flex-wrap: wrap;
}
.org-chip-label {
  font-size: 11px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-right: 4px;
}
.org-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  padding: 3px 9px;
  background: rgba(69,137,255,0.12);
  border: 1px solid rgba(69,137,255,0.3);
  color: var(--ibm-blue-40);
  cursor: pointer;
  transition: background 0.1s;
  border-radius: 0;
}
.org-chip:hover { background: rgba(69,137,255,0.22); }
.org-chip-x { font-size: 14px; line-height: 1; color: rgba(120,169,255,0.6); }
.org-chip-clear {
  background: transparent;
  border-color: rgba(255,255,255,0.15);
  color: var(--muted);
  margin-left: 4px;
}
.org-chip-clear:hover { color: #fff; border-color: rgba(255,255,255,0.35); background: rgba(255,255,255,0.05); }

/* ── Body: grid + detail panel ── */
.org-body {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.org-grid-wrap {
  flex: 1;
  overflow-y: auto;
  padding: 20px 24px;
  min-height: 0;
}

/* ── Summary bar + legend ── */
.org-summary {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}
.org-summary-count {
  font-size: 13px;
  color: var(--muted);
}
.org-legend {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.org-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--muted);
}
.org-legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  flex-shrink: 0;
}

/* ── Section (colony / market / cell grouping) ── */
.org-section {
  margin-bottom: 28px;
}
.org-section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-subtle);
}
.org-section-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.org-section-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.16px;
}
.org-section-sub {
  font-size: 12px;
  color: var(--muted);
}
.org-section-you-badge {
  font-size: 10px;
  padding: 2px 7px;
  background: rgba(69,137,255,0.14);
  color: var(--ibm-blue-40);
  font-weight: 600;
  letter-spacing: 0.32px;
  margin-left: auto;
}

/* ── Node grid ── */
.org-node-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1px;
  background: var(--border-subtle);
}

/* ── Person node card ── */
.org-node {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: var(--surface);
  cursor: pointer;
  transition: background 0.1s;
  border-left: 3px solid transparent;
  outline: none;
  position: relative;
}
.org-node:hover { background: var(--surface-2); }
.org-node:focus-visible { outline: 2px solid var(--ibm-blue-50); outline-offset: -2px; }

/* Relationship-based left border */
.org-node-me          { border-left-color: var(--ibm-blue-50); background: rgba(13,31,76,0.5); }
.org-node-chain       { border-left-color: #6c63ff; background: rgba(30,26,60,0.4); }
.org-node-team        { border-left-color: #0ea5e9; background: rgba(14,32,48,0.4); }
.org-node-colleague   { border-left-color: transparent; }
.org-node-me:hover    { background: rgba(13,31,76,0.7); }
.org-node-chain:hover { background: rgba(30,26,60,0.6); }
.org-node-team:hover  { background: rgba(14,32,48,0.6); }

.org-node-selected {
  outline: 2px solid var(--ibm-blue-40) !important;
  outline-offset: -2px;
}

/* Hex avatar dot */
.org-node-hex {
  width: 36px;
  height: 40px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  flex-shrink: 0;
  position: relative;
  border: 1px solid transparent;
}
.org-node-hex-inner {
  position: absolute;
  inset: 0;
}

/* Node text content */
.org-node-body { flex: 1; min-width: 0; }
.org-node-name {
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: 0.16px;
}
.org-node-role {
  font-size: 12px;
  color: var(--text-secondary);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.org-node-meta {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 5px;
}
.org-node-badge {
  font-size: 10px;
  padding: 1px 6px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--muted);
  letter-spacing: 0.16px;
  white-space: nowrap;
}
.org-node-badge-chain {
  background: rgba(108,99,255,0.12);
  border-color: rgba(108,99,255,0.3);
  color: #a89fff;
}
.org-node-badge-team {
  background: rgba(14,165,233,0.12);
  border-color: rgba(14,165,233,0.3);
  color: #7dd3fc;
}

/* Arrow chevron */
.org-node-arrow {
  font-size: 16px;
  color: #444;
  flex-shrink: 0;
  transition: color 0.1s, transform 0.1s;
}
.org-node:hover .org-node-arrow { color: var(--text-secondary); transform: translateX(2px); }

/* "You" tag inline */
.org-you-tag {
  font-size: 10px;
  padding: 1px 6px;
  background: rgba(69,137,255,0.15);
  color: var(--ibm-blue-40);
  font-weight: 600;
  letter-spacing: 0.32px;
  margin-left: 5px;
  vertical-align: middle;
  white-space: nowrap;
}

/* Empty state */
.org-empty {
  padding: 40px 24px;
  color: var(--muted);
  font-size: 14px;
  text-align: center;
}
.org-empty a { color: var(--ibm-blue-40); }

/* ── Right-side detail panel ── */
.org-detail {
  width: 320px;
  flex-shrink: 0;
  background: #111;
  border-left: 1px solid var(--border-subtle);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  position: relative;
}
.org-detail-close {
  position: absolute;
  top: 12px;
  right: 14px;
  font-size: 16px;
  cursor: pointer;
  color: var(--muted);
  padding: 3px 6px;
  transition: color 0.1s;
  z-index: 1;
}
.org-detail-close:hover { color: var(--text); }
.org-detail-inner {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Detail panel header */
.odp-header {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding-bottom: 16px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border-subtle);
}
.odp-hex {
  width: 44px;
  height: 50px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  flex-shrink: 0;
  border: 2px solid transparent;
}
.odp-title { flex: 1; min-width: 0; padding-right: 24px; }
.odp-name {
  font-size: 17px;
  font-weight: 400;
  color: var(--text);
  letter-spacing: 0;
  line-height: 1.3;
}
.odp-role {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 3px;
}
.odp-rel {
  font-size: 11px;
  padding: 2px 8px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--muted);
  display: inline-block;
  margin-top: 6px;
  letter-spacing: 0.16px;
}

/* Detail panel sections */
.odp-sections { display: flex; flex-direction: column; gap: 16px; }
.odp-section { display: flex; flex-direction: column; gap: 6px; }
.odp-section-title {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
  font-weight: 600;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--border-subtle);
  margin-bottom: 2px;
}
.odp-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 13px;
}
.odp-label {
  color: var(--muted);
  min-width: 88px;
  font-size: 12px;
  flex-shrink: 0;
  padding-top: 1px;
}
.odp-value {
  color: var(--text);
  flex: 1;
  min-width: 0;
  word-break: break-word;
}
.odp-link {
  color: var(--ibm-blue-40);
  text-decoration: none;
  font-size: 13px;
}
.odp-link:hover { text-decoration: underline; }

/* Tags in detail panel */
.odp-tags { display: flex; flex-wrap: wrap; gap: 5px; }
.odp-tag {
  font-size: 11px;
  padding: 3px 9px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--text-secondary);
  letter-spacing: 0.16px;
}

/* Action buttons */
.odp-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--border-subtle);
}
.odp-btn-primary {
  padding: 9px 16px;
  background: var(--ibm-blue-60);
  color: #fff;
  border: none;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  letter-spacing: 0.16px;
  transition: background 0.1s;
  border-radius: 0;
  text-align: left;
}
.odp-btn-primary:hover { background: var(--ibm-blue-70); }
.odp-btn-secondary {
  padding: 9px 16px;
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  letter-spacing: 0.16px;
  transition: background 0.1s, color 0.1s;
  border-radius: 0;
  text-align: left;
}
.odp-btn-secondary:hover { background: var(--surface-2); color: var(--text); }

/* ═══════════════════════════════════════════════════════════════
   ORG FUNCTION MAP — role-centric honeycomb (org.js)
   ═══════════════════════════════════════════════════════════════ */

.org-fn-shell {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  background: var(--bg);
}

.org-fn-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 44px;
  flex-shrink: 0;
  background: #000;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  gap: 16px;
}

.org-fn-breadcrumb {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 13px;
  flex: 1;
  min-width: 0;
}
.org-fn-bc-link {
  color: var(--muted);
  transition: color 0.1s;
}
.org-fn-bc-link:hover { color: var(--text); }
.org-fn-bc-active {
  color: var(--text);
  font-weight: 500;
}
.org-fn-bc-sep {
  color: #3a3a3a;
  padding: 0 2px;
}

.org-fn-tagline {
  font-size: 11px;
  color: #3a3a3a;
  white-space: nowrap;
  flex-shrink: 0;
  letter-spacing: 0.32px;
}

.org-fn-body {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

/* ── Level 0: IBM colonies ───────────────────────────────────────── */
.org-fn-level0 {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 32px 24px 48px;
  gap: 24px;
}

.org-fn-intro {
  text-align: center;
}
.org-fn-intro-title {
  font-size: 18px;
  font-weight: 300;
  color: var(--text);
  letter-spacing: -0.2px;
  margin-bottom: 6px;
}
.org-fn-intro-sub {
  font-size: 13px;
  color: var(--muted);
}

.org-fn-svg-wrap {
  overflow-x: auto;
  max-width: 100%;
}

/* Hover brightening for colony and function hexes */
.org-colony-hex polygon:first-child,
.org-fn-hex polygon:first-child {
  transition: filter 0.12s;
}
.org-colony-hex:hover polygon:first-child,
.org-fn-hex:hover polygon:first-child {
  filter: brightness(1.35);
}

/* ── Level 1: colony functions ───────────────────────────────────── */
.org-fn-level1 {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 28px 24px 48px;
  gap: 20px;
}

.org-fn-colony-header {
  text-align: center;
}
.org-fn-colony-name {
  font-size: 20px;
  font-weight: 300;
  letter-spacing: -0.2px;
  margin-bottom: 4px;
}
.org-fn-colony-sub {
  font-size: 12px;
  color: var(--muted);
}

/* ── Level 2: function detail card ──────────────────────────────── */
.org-fn-detail-wrap {
  display: flex;
  justify-content: center;
  padding: 32px 24px 48px;
}

.org-fn-detail {
  width: 100%;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.org-fn-detail-head {
  padding: 16px 20px;
  background: var(--surface);
  border: 1px solid var(--border-subtle);
}
.org-fn-detail-abbr {
  font-size: 24px;
  font-weight: 600;
  letter-spacing: -0.5px;
  margin-bottom: 4px;
}
.org-fn-detail-label {
  font-size: 14px;
  color: var(--text-secondary);
  font-weight: 400;
}

.org-fn-detail-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.org-fn-detail-section-title {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
  font-weight: 600;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-subtle);
}
.org-fn-detail-text {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.65;
}

.org-fn-detail-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.org-fn-works-tag {
  font-size: 12px;
  padding: 4px 10px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  letter-spacing: 0.16px;
}

.org-fn-detail-members {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.org-fn-member {
  font-size: 13px;
  padding: 4px 12px;
  background: var(--surface);
  border: 1px solid var(--border-subtle);
  color: var(--muted);
}
.org-fn-member-you {
  font-weight: 500;
  border-style: solid;
}
.org-fn-member-empty {
  font-size: 13px;
  color: var(--muted);
  font-style: italic;
}

.org-fn-back-row {
  margin-top: 8px;
}
.org-fn-back-btn {
  background: transparent;
  border: 1px solid var(--border-subtle);
  color: var(--muted);
  font-size: 13px;
  font-family: inherit;
  padding: 7px 14px;
  cursor: pointer;
  letter-spacing: 0.16px;
  transition: color 0.1s, border-color 0.1s;
  border-radius: 0;
}
.org-fn-back-btn:hover { color: var(--text); border-color: var(--border); }

/* ═══════════════════════════════════════════════════════════════
   HIVE MAP — org.js zoomable organizational map (legacy styles kept for other refs)
   ═══════════════════════════════════════════════════════════════ */

.hmap-shell {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: #080808;
  overflow: hidden;
}

/* ── Top bar: breadcrumb + you-here + zoom controls ── */
.hmap-topbar {
  display: flex;
  align-items: center;
  gap: 0;
  height: 48px;
  flex-shrink: 0;
  background: #0a0a0a;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding: 0 16px;
}

.hmap-breadcrumb {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
}
.bc-root  { color: #525252; }
.bc-link  { color: var(--text-secondary); cursor: pointer; transition: color 0.1s; }
.bc-link:hover { color: #fff; }
.bc-sep   { color: #333; font-size: 11px; }
.bc-you   { color: var(--ibm-blue-40); font-weight: 500; }

.hmap-you-here {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  padding: 0 16px;
  border-left: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
}
.yah-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ibm-blue-50);
  flex-shrink: 0;
  box-shadow: 0 0 6px var(--ibm-blue-50);
}
.yah-text { color: var(--text-secondary); }
.yah-text strong { color: var(--text); font-weight: 500; }

.hmap-zoom-btns {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-left: 12px;
  border-left: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
}
.hmap-zbtn {
  width: 30px; height: 30px;
  border: 1px solid rgba(255,255,255,0.12);
  background: transparent;
  color: var(--text-secondary);
  font-size: 16px;
  font-family: inherit;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
}
.hmap-zbtn:hover { background: var(--surface-2); color: #fff; }
.hmap-zbtn-fit { font-size: 11px; width: auto; padding: 0 10px; }

/* ── Stage (the actual map canvas area) ── */
.hmap-stage {
  flex: 1;
  position: relative;
  overflow: hidden;
  cursor: default;
  min-height: 0;
  background: radial-gradient(ellipse at center, #0e0e0e 0%, #050505 100%);
}

.hmap-svg {
  position: absolute;
  top: 0;
  left: 0;
  transform-origin: 0 0;
  will-change: transform;
  overflow: visible;
}

/* ── Right detail panel ── */
.hmap-detail {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: 300px;
  background: #111;
  border-left: 1px solid rgba(255,255,255,0.08);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  z-index: 10;
  box-shadow: -8px 0 32px rgba(0,0,0,0.5);
}
.hmap-detail-close {
  position: absolute;
  top: 10px; right: 12px;
  background: none;
  border: none;
  color: var(--muted);
  font-size: 15px;
  cursor: pointer;
  padding: 4px 6px;
  transition: color 0.1s;
  z-index: 1;
}
.hmap-detail-close:hover { color: #fff; }

/* Detail panel body */
#hmapDetailBody { padding: 18px; }

.hdp-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding-right: 24px;
}
.hdp-hex {
  width: 40px; height: 46px;
  clip-path: polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%);
  flex-shrink: 0;
  border: 2px solid;
}
.hdp-circle {
  width: 40px; height: 40px;
  border-radius: 50%;
  flex-shrink: 0;
  border: 2px solid;
}
.hdp-name {
  font-size: 16px;
  font-weight: 400;
  color: var(--text);
  line-height: 1.3;
}
.hdp-role { font-size: 12px; color: var(--muted); margin-top: 3px; }

.hdp-sections {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.hdp-section { display: flex; flex-direction: column; gap: 3px; }
.hdp-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  font-weight: 600;
}
.hdp-val {
  font-size: 13px;
  color: var(--text);
  line-height: 1.5;
}
.hdp-link { color: var(--ibm-blue-40); text-decoration: none; font-size: 13px; }
.hdp-link:hover { text-decoration: underline; }
.hdp-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 2px; }
.hdp-tag {
  font-size: 11px;
  padding: 2px 8px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--text-secondary);
}
.you-tag {
  font-size: 10px; padding: 1px 6px;
  background: rgba(69,137,255,0.15); color: var(--ibm-blue-40);
  font-weight: 600; letter-spacing: 0.32px;
  margin-left: 5px; vertical-align: middle;
}

/* ═══════════════════════════════════════════════════════════════
   CELL VIEW — BTSS↔TSS pairing diagram
   ═══════════════════════════════════════════════════════════════ */

.cell-structure-wrap {
  flex: 1;
  padding: 24px 32px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.cell-structure-header {
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding-bottom: 14px;
}
.cell-header-breadcrumb {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  margin-bottom: 6px;
}
.cell-bc { color: var(--muted); }
.cell-bc-sep { color: #333; }
.cell-bc-active { color: var(--text); font-weight: 500; }
.cell-header-sub { font-size: 12px; color: #525252; }

.cell-diagram-wrap {
  overflow-x: auto;
  padding-bottom: 8px;
}

.cell-legend {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
  font-size: 12px;
  color: var(--muted);
  padding: 10px 0;
  border-top: 1px solid rgba(255,255,255,0.06);
}
.cell-leg-item { display: flex; align-items: center; gap: 7px; }
.cell-leg-line {
  display: inline-block;
  width: 28px; height: 2px;
  flex-shrink: 0;
}
.cell-leg-solid  { background: #0ea5e9; }
.cell-leg-dashed { background: none; border-top: 2px dashed #6c63ff; }
.cell-leg-dot {
  width: 10px; height: 10px;
  border-radius: 2px; flex-shrink: 0;
}

.cell-products {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cell-products-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  font-weight: 600;
}
.cell-products-list { display: flex; gap: 6px; flex-wrap: wrap; }
.cell-product-tag {
  font-size: 12px;
  padding: 4px 12px;
  background: rgba(77,123,255,0.08);
  border: 1px solid rgba(77,123,255,0.2);
  color: var(--ibm-blue-40);
}

.cell-pairs-table { }
.cell-pairs-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  font-weight: 600;
  margin-bottom: 10px;
}
.cell-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.cell-table th {
  text-align: left;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.32px;
  color: var(--muted);
  padding: 0 12px 8px 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.cell-table td {
  padding: 9px 12px 9px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  color: var(--text-secondary);
  vertical-align: middle;
}
.cell-table tr:last-child td { border-bottom: none; }

/* ═══════════════════════════════════════════════════════════════
   MY HIVE — personal collections
   ═══════════════════════════════════════════════════════════════ */

.mh-page {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.mh-sidebar {
  width: 220px;
  flex-shrink: 0;
  background: #0d0d0d;
  border-right: 1px solid rgba(255,255,255,0.07);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}
.mh-sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 16px 10px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.mh-sidebar-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.16px;
}
.mh-new-btn {
  font-size: 11px;
  padding: 4px 10px;
  border: 1px solid rgba(255,255,255,0.15);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-family: inherit;
  transition: color 0.1s, border-color 0.1s;
  border-radius: 0;
}
.mh-new-btn:hover { color: #fff; border-color: rgba(255,255,255,0.35); }

.mh-col-list { display: flex; flex-direction: column; }
.mh-col-item {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 16px;
  cursor: pointer;
  font-size: 13px;
  color: var(--muted);
  border-left: 2px solid transparent;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  transition: color 0.1s, background 0.1s;
}
.mh-col-item:hover { color: var(--text); background: rgba(255,255,255,0.03); }
.mh-col-item.active { color: var(--text); border-left-color: var(--ibm-blue-50); background: rgba(69,137,255,0.06); }
.mh-col-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
.mh-col-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mh-col-count { font-size: 11px; color: #444; flex-shrink: 0; }

.mh-main {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  background: var(--bg);
}

.mh-empty {
  padding: 48px 32px;
  color: var(--muted);
  font-size: 14px;
  text-align: center;
}

.mh-col-detail { padding: 24px 28px; }
.mh-col-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.mh-col-header-name { font-size: 18px; font-weight: 400; letter-spacing: -0.2px; }
.mh-col-header-desc { font-size: 13px; color: var(--muted); margin-top: 4px; }
.mh-add-btn {
  padding: 8px 14px;
  background: var(--ibm-blue-60);
  color: #fff;
  border: none;
  font-size: 12px;
  font-family: inherit;
  cursor: pointer;
  flex-shrink: 0;
  white-space: nowrap;
  transition: background 0.1s;
  border-radius: 0;
}
.mh-add-btn:hover { background: var(--ibm-blue-70); }

.mh-member-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1px;
  background: rgba(255,255,255,0.05);
  margin-bottom: 20px;
}
.mh-member-card {
  background: var(--surface);
  padding: 12px 14px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.mh-mc-hex {
  width: 32px; height: 36px;
  clip-path: polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%);
  flex-shrink: 0;
  border: 2px solid;
}
.mh-mc-body { flex: 1; min-width: 0; }
.mh-mc-name { font-size: 13px; font-weight: 500; color: var(--text); }
.mh-mc-role { font-size: 11px; color: var(--muted); margin-top: 2px; }
.mh-mc-meta { font-size: 10px; color: #444; margin-top: 3px; }
.mh-mc-remove {
  background: none; border: none; color: #444; cursor: pointer;
  font-size: 13px; padding: 3px 5px; flex-shrink: 0;
  transition: color 0.1s;
}
.mh-mc-remove:hover { color: var(--accent-magenta); }

.mh-add-panel {
  border: 1px solid rgba(255,255,255,0.1);
  background: #111;
  padding: 12px;
  margin-top: 12px;
}
.mh-add-search {
  width: 100%;
  padding: 8px 10px;
  background: var(--surface-2);
  border: none;
  border-bottom: 2px solid var(--border);
  color: var(--text);
  font-size: 13px;
  font-family: inherit;
  outline: none;
  margin-bottom: 8px;
  transition: border-color 0.1s;
  border-radius: 0;
}
.mh-add-search:focus { border-bottom-color: var(--ibm-blue-50); }
.mh-add-results { display: flex; flex-direction: column; max-height: 240px; overflow-y: auto; }
.mh-add-result {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  cursor: pointer;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  transition: background 0.1s;
}
.mh-add-result:hover { background: var(--surface); }
.mh-ar-name { font-size: 13px; color: var(--text); flex: 1; }
.mh-ar-role { font-size: 11px; color: var(--muted); }
.mh-ar-add  { font-size: 11px; color: var(--ibm-blue-40); font-weight: 600; flex-shrink: 0; }

