// ─────────────────────────────────────────────────────────────────
// Hex geometry  (flat-top hexagons)
// ─────────────────────────────────────────────────────────────────
// We use flat-top hexes so horizontal rows tile seamlessly.
// For flat-top: vertex angle = 0°, 60°, 120° …
// col step = R * sqrt(3),  row step = R * 1.5, odd rows offset by R*sqrt(3)/2

const R   = 52;                        // hex circumradius
const CS  = R * Math.sqrt(3);          // column step  ≈ 90
const RS  = R * 1.5;                   // row step     ≈ 78
const GAP = 3;                         // gap between hexes

function hexPts(cx, cy) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = (Math.PI / 3) * i;       // flat-top: start at 0°
    return `${(cx + R * Math.cos(a)).toFixed(1)},${(cy + R * Math.sin(a)).toFixed(1)}`;
  }).join(' ');
}

// ─────────────────────────────────────────────────────────────────
// View state
// ─────────────────────────────────────────────────────────────────
let _expandedSegments = new Set();   // segment ids that are expanded to show functions
let _expandedFunctions = new Set();  // function ids that are expanded to show members
let _selectedId = null;              // id of currently selected node (any type)
let _container  = null;

// ─────────────────────────────────────────────────────────────────
// Entry
// ─────────────────────────────────────────────────────────────────
export async function renderOrg(container) {
  _container = container;
  _expandedSegments  = new Set();
  _expandedFunctions = new Set();
  _selectedId = null;

  // Auto-expand the user's segment and function
  _expandedSegments.add('horizon');
  _expandedFunctions.add('btss-h');

  container.innerHTML = `
    <div class="ohive-shell">
      <div class="ohive-topbar">
        <div class="ohive-title">IBM Client Segments</div>
        <div class="ohive-sub">Select a segment to explore roles and functions</div>
      </div>
      <div class="ohive-body">
        <div class="ohive-canvas" id="ohiveCanvas"></div>
        <div class="ohive-panel" id="ohivePanel" style="display:none">
          <div class="ohive-panel-close" id="ohivePanelClose">✕</div>
          <div id="ohivePanelBody"></div>
        </div>
      </div>
    </div>
  `;

  document.getElementById('ohivePanelClose')?.addEventListener('click', () => {
    _selectedId = null;
    document.getElementById('ohivePanel').style.display = 'none';
    redraw();
  });

  redraw();
}

// ─────────────────────────────────────────────────────────────────
// Build node list from current expand state
// ─────────────────────────────────────────────────────────────────

/*
 * Layout strategy:
 * We place nodes row by row, each row centered horizontally.
 * Row 0: IBM root (1 hex)
 * Row 1: four segment hexes, tightly tiled
 * For each expanded segment → a row of its function hexes
 * For each expanded function → a row of its member hexes
 *
 * Rows are separated by RS (row step). Hex centers within a row
 * are spaced CS apart (column step). Every other row is offset by CS/2.
 *
 * We return { nodes, svgW, svgH } where nodes = [{id,label,sub,type,cx,cy,selected,youAreHere,data}]
 */
function buildLayout() {
  const nodes = [];
  const rowGroups = []; // [{ids, parentId}] — groups of node IDs per row segment

  // ── Row 0: root IBM node ──
  rowGroups.push({ ids: ['root'], parent: null, type: 'root' });

  // ── Row 1: all four segments ──
  rowGroups.push({ ids: SEGMENTS.map(s => s.id), parent: 'root', type: 'segment' });

  // ── Rows 2+: expanded content ──
  // We interleave: after each segment row entry, if that segment is expanded, inject its function row.
  // Then for each function if expanded, inject its member row.
  // But we want them in a sensible visual order:
  // All functions of expanded segments appear in their own rows, beneath that segment's position.
  // This can get complex; simplest approach: one row per "expansion group" in order.

  // We'll do a depth-first expansion:
  // segments → if expanded → functions → if expanded → members
  // Each expansion is its own row.

  for (const seg of SEGMENTS) {
    if (!_expandedSegments.has(seg.id)) continue;
    rowGroups.push({ ids: seg.functions.map(f => f.id), parent: seg.id, type: 'function', segId: seg.id });

    for (const fn of seg.functions) {
      if (!_expandedFunctions.has(fn.id) || !fn.members?.length) continue;
      rowGroups.push({ ids: fn.members.map((_, i) => `${fn.id}:m${i}`), parent: fn.id, type: 'member', fnId: fn.id });
    }
  }

  // ── Assign positions ──
  // The SVG is wide enough to fit the widest row, all centered.
  // We'll compute cx for each node after collecting all rows.

  const rowData = rowGroups.map(rg => {
    const count = rg.ids.length;
    const totalW = count * CS + (count - 1) * GAP;
    return { ...rg, count, totalW };
  });

  // svgW = max totalW + 2*R + padding
  const maxW = Math.max(...rowData.map(r => r.totalW));
  const SVG_PAD_X = R + 40;
  const SVG_PAD_Y = R + 30;
  const svgW = maxW + SVG_PAD_X * 2;

  // Assign cy (center Y) for each row
  let cy = SVG_PAD_Y + R;
  const rowCYs = rowData.map((r, i) => {
    const thisCY = cy;
    cy += RS + GAP;
    return thisCY;
  });

  // Assign cx for each node within each row (centered)
  rowData.forEach((rg, ri) => {
    const rowCY  = rowCYs[ri];
    const startX = svgW / 2 - rg.totalW / 2 + CS / 2;

    rg.ids.forEach((nid, ni) => {
      const cx = startX + ni * (CS + GAP);

      // Resolve node data
      let label = '', sub = '', type = rg.type, data = null, youAreHere = false;

      if (type === 'root') {
        label = 'IBM'; sub = 'Client Segments';
      } else if (type === 'segment') {
        const seg = SEGMENTS.find(s => s.id === nid);
        label = seg.label; sub = seg.clients; data = seg;
        youAreHere = seg.youAreHere || false;
      } else if (type === 'function') {
        const seg = SEGMENTS.find(s => s.id === rg.segId);
        const fn  = seg?.functions.find(f => f.id === nid);
        label = fn.abbr; sub = fn.label; data = fn;
        youAreHere = fn.youAreHere || false;
      } else if (type === 'member') {
        const seg = SEGMENTS.find(s => s.functions.some(f => f.id === rg.fnId));
        const fn  = seg?.functions.find(f => f.id === rg.fnId);
        const idx = parseInt(nid.split(':m')[1]);
        const m   = fn?.members[idx];
        label = m?.name?.split(' ')[0] || '?';
        sub   = m?.name?.split(' ').slice(1).join(' ') || '';
        data  = { ...m, fullName: m?.name };
        youAreHere = m?.isYou || false;
      }

      const isSelected = _selectedId === nid;
      const isExpanded = type === 'segment'  ? _expandedSegments.has(nid)
                       : type === 'function' ? _expandedFunctions.has(nid)
                       : false;

      nodes.push({ id: nid, label, sub, type, cx, cy: rowCY, isSelected, youAreHere, isExpanded, data, rowGroup: rg });
    });
  });

  const svgH = cy + R + SVG_PAD_Y;
  return { nodes, svgW, svgH };
}

// ─────────────────────────────────────────────────────────────────
// Draw
// ─────────────────────────────────────────────────────────────────
function redraw() {
  const canvas = document.getElementById('ohiveCanvas');
  if (!canvas) return;

  const { nodes, svgW, svgH } = buildLayout();

  // Build connector lines: each node connects to its parent row
  // We'll draw a line from each node to the centroid of its parent group
  let lines = '';
  // Map id→{cx,cy}
  const pos = {};
  nodes.forEach(n => { pos[n.id] = { cx: n.cx, cy: n.cy }; });

  nodes.forEach(n => {
    if (!n.rowGroup.parent) return;
    const pPos = pos[n.rowGroup.parent];
    if (!pPos) return;
    lines += `<line x1="${n.cx.toFixed(1)}" y1="${(n.cy - R).toFixed(1)}"
      x2="${pPos.cx.toFixed(1)}" y2="${(pPos.cy + R).toFixed(1)}"
      stroke="rgba(255,255,255,0.08)" stroke-width="1" pointer-events="none"/>`;
  });

  // Draw hexes
  let hexes = '';
  nodes.forEach(n => {
    const pts = hexPts(n.cx, n.cy);
    const isRoot    = n.type === 'root';
    const isSel     = n.isSelected;
    const isYou     = n.youAreHere;
    const isExpanded = n.isExpanded;

    // Color scheme: white/gray/IBM-blue only
    const strokeColor = isSel ? '#4589ff' : isYou ? '#4589ff' : 'rgba(255,255,255,0.25)';
    const strokeW     = isSel || isYou ? 1.5 : 1;
    const fillColor   = isSel ? 'rgba(69,137,255,0.14)' : isRoot ? 'rgba(255,255,255,0.05)' : '#111111';

    // "you are here" outer ring
    const youRing = isYou && !isSel ? `<polygon points="${hexPts_r(n.cx, n.cy, R + 7)}"
      fill="none" stroke="rgba(69,137,255,0.35)" stroke-width="1" stroke-dasharray="4,3" pointer-events="none"/>` : '';

    // Label lines
    const labelColor = isSel ? '#4589ff' : isYou ? '#4589ff' : '#f4f4f4';
    const subColor   = isSel ? 'rgba(69,137,255,0.8)' : 'rgba(255,255,255,0.35)';
    const labelY     = n.sub ? n.cy - 8 : n.cy + 4;

    const labelEl  = `<text x="${n.cx.toFixed(1)}" y="${labelY.toFixed(1)}" text-anchor="middle"
      fill="${labelColor}" font-size="${isRoot ? 13 : 12}" font-weight="${isRoot || isSel ? 600 : 400}"
      font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none">${n.label}</text>`;

    const subEl = n.sub ? `<text x="${n.cx.toFixed(1)}" y="${(n.cy + 10).toFixed(1)}" text-anchor="middle"
      fill="${subColor}" font-size="8"
      font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none"
      >${n.sub.length > 16 ? n.sub.slice(0,15)+'…' : n.sub}</text>` : '';

    // expand indicator
    const canExpand = (n.type === 'segment' && !n.isExpanded) || (n.type === 'function' && n.data?.members?.length && !n.isExpanded);
    const expandDot = canExpand ? `<circle cx="${n.cx.toFixed(1)}" cy="${(n.cy + R - 10).toFixed(1)}" r="3"
      fill="rgba(255,255,255,0.2)" pointer-events="none"/>` : '';

    hexes += `
      <g class="ohive-node" data-node-id="${n.id}" data-node-type="${n.type}" style="cursor:pointer">
        ${youRing}
        <polygon points="${pts}" fill="${fillColor}" stroke="${strokeColor}" stroke-width="${strokeW}"/>
        ${labelEl}${subEl}${expandDot}
      </g>`;
  });

  canvas.innerHTML = `
    <svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}"
      xmlns="http://www.w3.org/2000/svg" style="display:block;overflow:visible">
      <g id="ohiveLines">${lines}</g>
      <g id="ohiveNodes">${hexes}</g>
    </svg>`;

  // Wire clicks
  canvas.querySelectorAll('.ohive-node').forEach(el => {
    el.addEventListener('click', e => {
      e.stopPropagation();
      handleClick(el.dataset.nodeId, el.dataset.nodeType);
    });
  });
}

// Hex points with custom radius
function hexPts_r(cx, cy, r) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = (Math.PI / 3) * i;
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(' ');
}

// ─────────────────────────────────────────────────────────────────
// Interaction
// ─────────────────────────────────────────────────────────────────
function handleClick(id, type) {
  if (type === 'root') {
    // Collapse everything
    _expandedSegments.clear();
    _expandedFunctions.clear();
    _selectedId = null;
    hidePanel();
    redraw();
    return;
  }

  // Toggle expand
  if (type === 'segment') {
    if (_expandedSegments.has(id)) {
      _expandedSegments.delete(id);
      // collapse any functions under this segment
      const seg = SEGMENTS.find(s => s.id === id);
      seg?.functions.forEach(f => _expandedFunctions.delete(f.id));
    } else {
      _expandedSegments.add(id);
    }
  }

  if (type === 'function') {
    const seg = SEGMENTS.find(s => s.functions.some(f => f.id === id));
    const fn  = seg?.functions.find(f => f.id === id);
    if (fn?.members?.length) {
      if (_expandedFunctions.has(id)) _expandedFunctions.delete(id);
      else _expandedFunctions.add(id);
    }
  }

  // Select and show panel
  _selectedId = id;
  redraw();
  showPanel(id, type);
}

// ─────────────────────────────────────────────────────────────────
// Detail panel
// ─────────────────────────────────────────────────────────────────
function showPanel(id, type) {
  const panel = document.getElementById('ohivePanel');
  const body  = document.getElementById('ohivePanelBody');
  if (!panel || !body) return;

  let html = '';

  if (type === 'root') {
    hidePanel(); return;
  }

  if (type === 'segment') {
    const seg = SEGMENTS.find(s => s.id === id);
    if (!seg) return;
    html = `
      <div class="ohp-title">${seg.label}</div>
      <div class="ohp-meta">${seg.clients}</div>
      <div class="ohp-desc">${seg.desc}</div>
      <div class="ohp-section-title">Functions in this segment</div>
      <div class="ohp-tags">${seg.functions.map(f => `<span class="ohp-tag">${f.abbr}</span>`).join('')}</div>`;
  }

  if (type === 'function') {
    const seg = SEGMENTS.find(s => s.functions.some(f => f.id === id));
    const fn  = seg?.functions.find(f => f.id === id);
    if (!fn) return;
    const worksWith = fn.worksWith?.map(w => `<span class="ohp-tag">${w}</span>`).join('') || '—';
    const members   = fn.members?.length
      ? fn.members.map(m => `<div class="ohp-member${m.isYou ? ' ohp-member-you' : ''}">${m.name}<span>${m.role}</span></div>`).join('')
      : '';
    html = `
      <div class="ohp-title">${fn.abbr}</div>
      <div class="ohp-meta">${fn.label}</div>
      <div class="ohp-desc">${fn.purpose}</div>
      <div class="ohp-section-title">Works with</div>
      <div class="ohp-tags">${worksWith}</div>
      ${members ? `<div class="ohp-section-title">Team</div><div class="ohp-members">${members}</div>` : ''}`;
  }

  if (type === 'member') {
    // Find the member data
    let memberData = null, fnData = null;
    for (const seg of SEGMENTS) {
      for (const fn of seg.functions) {
        if (!fn.members) continue;
        fn.members.forEach((m, i) => {
          if (`${fn.id}:m${i}` === id) { memberData = m; fnData = fn; }
        });
      }
    }
    if (!memberData) return;
    html = `
      <div class="ohp-title">${memberData.name}${memberData.isYou ? ' <span class="ohp-you-tag">You</span>' : ''}</div>
      <div class="ohp-meta">${memberData.role}</div>
      <div class="ohp-desc">${fnData.abbr} — ${fnData.label}</div>`;
  }

  body.innerHTML = html;
  panel.style.display = 'flex';
}

function hidePanel() {
  const panel = document.getElementById('ohivePanel');
  if (panel) panel.style.display = 'none';
}

