          <div class="org-fn-detail-members">${membersHtml}</div>
        </div>` : ''}

        <div class="org-fn-back-row">
          <button class="org-fn-back-btn" id="orgFnBackBtn">← Back to ${colony.label} Colony</button>
        </div>
      </div>
    </div>
  `;

  document.getElementById('orgFnBackBtn')?.addEventListener('click', () => renderLevel1(colony));
}

// ── Breadcrumb ────────────────────────────────────────────────────
function updateBreadcrumb() {
  const el = document.getElementById('orgFnBreadcrumb');
  if (!el) return;

  const crumbs = [{ label: 'IBM', action: () => renderLevel0() }];
  if (_colony) crumbs.push({ label: _colony.label + ' Colony', action: () => renderLevel1(_colony) });
  if (_fn)     crumbs.push({ label: _fn.abbr, action: null });

  el.innerHTML = crumbs.map((c, i) => {
    const sep = i > 0 ? `<span class="org-fn-bc-sep">›</span>` : '';
    const cls = c.action ? 'org-fn-bc-link' : 'org-fn-bc-active';
    return `${sep}<span class="${cls}">${c.label}</span>`;
  }).join('');

  el.querySelectorAll('.org-fn-bc-link').forEach((seg, i) => {
    seg.style.cursor = 'pointer';
    seg.addEventListener('click', crumbs[i].action);
  });
}

