// Hex geometry  (flat-top)
// col step = R * sqrt(3),  row step = R * 1.5
// ─────────────────────────────────────────────────────────────────
const R   = 52;
const CS  = R * Math.sqrt(3);
const RS  = R * 1.5;
const GAP = 3;

function hexPts(cx, cy, r = R) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = (Math.PI / 3) * i;
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(' ');
}

