// ─────────────────────────────────────────────────────────────────
// Layout
// ─────────────────────────────────────────────────────────────────
function buildLayout() {
  const rowGroups = [];

  rowGroups.push({ ids: ['root'],                      parent: null,  type: 'root' });
  rowGroups.push({ ids: SEGMENTS.map(s => s.id),       parent: 'root', type: 'segment' });

  for (const seg of SEGMENTS) {
    if (!_expandedSegments.has(seg.id)) continue;
    rowGroups.push({ ids: seg.functions.map(f => f.id), parent: seg.id, type: 'function', segId: seg.id });
  }

  // Compute SVG width from widest row
  const rowData = rowGroups.map(rg => {
    const count  = rg.ids.length;
    const totalW = count * CS + (count - 1) * GAP;
    return { ...rg, count, totalW };
  });
  const maxW     = Math.max(...rowData.map(r => r.totalW));
  const PAD_X    = R + 40;
  const PAD_Y    = R + 30;
  const svgW     = maxW + PAD_X * 2;

  // Assign row Y positions
  let cy = PAD_Y + R;
  const rowCYs = rowData.map(() => { const v = cy; cy += RS + GAP; return v; });

  const nodes = [];
  const pos   = {};   // id → {cx, cy}

  rowData.forEach((rg, ri) => {
    const rowCY  = rowCYs[ri];
    const startX = svgW / 2 - rg.totalW / 2 + CS / 2;

    rg.ids.forEach((nid, ni) => {
      const cx = startX + ni * (CS + GAP);

      let label = '', sub = '', data = null, youAreHere = false;

      if (rg.type === 'root') {
        label = 'IBM'; sub = 'Sales Hive';
      } else if (rg.type === 'segment') {
        const seg = SEGMENTS.find(s => s.id === nid);
        label = seg.label; sub = seg.sub; data = seg;
        youAreHere = seg.youAreHere || false;
      } else if (rg.type === 'function') {
        const seg = SEGMENTS.find(s => s.id === rg.segId);
        const fn  = seg?.functions.find(f => f.id === nid);
        label = fn.abbr; sub = fn.label; data = fn;
        youAreHere = fn.youAreHere || false;
      }

      const isSelected = _selectedId === nid;
      const isExpanded = rg.type === 'segment' ? _expandedSegments.has(nid) : false;

      const node = { id: nid, label, sub, type: rg.type, cx, cy: rowCY,
                     isSelected, youAreHere, isExpanded, data, rowGroup: rg };
      nodes.push(node);
      pos[nid] = { cx, cy: rowCY };
    });
  });

  const svgH = cy + R + PAD_Y;
  return { nodes, svgW, svgH, pos };
}

// ─────────────────────────────────────────────────────────────────
// Draw
// ─────────────────────────────────────────────────────────────────
function redraw() {
  const canvas = document.getElementById('ohiveCanvas');
  if (!canvas) return;

  const { nodes, svgW, svgH, pos } = buildLayout();

  // Connector lines
  let lines = '';
  nodes.forEach(n => {
    if (!n.rowGroup.parent) return;
    const p = pos[n.rowGroup.parent];
    if (!p) return;
    lines += `<line
      x1="${n.cx.toFixed(1)}" y1="${(n.cy - R).toFixed(1)}"
      x2="${p.cx.toFixed(1)}"  y2="${(p.cy + R).toFixed(1)}"
      stroke="rgba(255,255,255,0.07)" stroke-width="1" pointer-events="none"/>`;
  });

  // Hex nodes
  let hexes = '';
  nodes.forEach(n => {
    const isSel  = n.isSelected;
    const isYou  = n.youAreHere;
    const isRoot = n.type === 'root';

    const stroke = isSel ? '#4589ff' : isYou ? '#4589ff' : 'rgba(255,255,255,0.22)';
    const sw     = isSel || isYou ? 1.5 : 1;
    const fill   = isSel ? 'rgba(69,137,255,0.13)' : isRoot ? 'rgba(255,255,255,0.04)' : '#0f0f0f';

    const youRing = isYou && !isSel
      ? `<polygon points="${hexPts(n.cx, n.cy, R + 7)}"
          fill="none" stroke="rgba(69,137,255,0.3)" stroke-width="1"
          stroke-dasharray="4,3" pointer-events="none"/>` : '';

    const labelColor = isSel || isYou ? '#4589ff' : '#e0e0e0';
    const subColor   = isSel ? 'rgba(69,137,255,0.75)' : 'rgba(255,255,255,0.28)';
    const labelY     = n.sub ? n.cy - 9 : n.cy + 4;

    const labelEl = `<text x="${n.cx.toFixed(1)}" y="${labelY.toFixed(1)}" text-anchor="middle"
      fill="${labelColor}" font-size="${isRoot ? 13 : 12}" font-weight="${isSel || isRoot ? 600 : 400}"
      font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none">${n.label}</text>`;

    const subEl = n.sub
      ? `<text x="${n.cx.toFixed(1)}" y="${(n.cy + 9).toFixed(1)}" text-anchor="middle"
          fill="${subColor}" font-size="8"
          font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none"
          >${n.sub.length > 16 ? n.sub.slice(0, 15) + '…' : n.sub}</text>` : '';

    // Small dot if can expand
    const canExpand = n.type === 'segment' && !n.isExpanded;
    const expandDot = canExpand
      ? `<circle cx="${n.cx.toFixed(1)}" cy="${(n.cy + R - 11).toFixed(1)}" r="3"
          fill="rgba(255,255,255,0.18)" pointer-events="none"/>` : '';

    hexes += `
      <g class="ohive-node" data-node-id="${n.id}" data-node-type="${n.type}" style="cursor:pointer">
        ${youRing}
        <polygon points="${hexPts(n.cx, n.cy)}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>
        ${labelEl}${subEl}${expandDot}
      </g>`;
  });

  canvas.innerHTML = `
    <svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}"
      xmlns="http://www.w3.org/2000/svg" style="display:block;overflow:visible">
      <g>${lines}</g>
      <g>${hexes}</g>
    </svg>`;

  canvas.querySelectorAll('.ohive-node').forEach(el => {
    el.addEventListener('click', e => {
      e.stopPropagation();
      handleClick(el.dataset.nodeId, el.dataset.nodeType);
    });
  });
}

// ─────────────────────────────────────────────────────────────────
// Interaction
// ─────────────────────────────────────────────────────────────────
function handleClick(id, type) {
  if (type === 'root') {
    _expandedSegments.clear();
    _selectedId = null;
    document.getElementById('ohivePanel').style.display = 'none';
    redraw();
    return;
  }

  if (type === 'segment') {
    if (_expandedSegments.has(id)) {
      _expandedSegments.delete(id);
    } else {
      _expandedSegments.add(id);
    }
  }

  _selectedId = id;
  redraw();
  showPanel(id, type);
}

// ─────────────────────────────────────────────────────────────────
// Detail panel — role context only, no people
// ─────────────────────────────────────────────────────────────────
function showPanel(id, type) {
  const panel = document.getElementById('ohivePanel');
  const body  = document.getElementById('ohivePanelBody');
  if (!panel || !body) return;

  let html = '';

  if (type === 'segment') {
    const seg = SEGMENTS.find(s => s.id === id);
    if (!seg) return;
    const fns = seg.functions.map(f =>
      `<div class="ohp-fn-row">
        <span class="ohp-fn-abbr">${f.abbr}</span>
        <span class="ohp-fn-label">${f.label}</span>
      </div>`
    ).join('');
    html = `
      <div class="ohp-title">${seg.label}</div>
      <div class="ohp-meta">${seg.sub}</div>
      <div class="ohp-desc">${seg.desc}</div>
      <div class="ohp-section-title">Roles in this segment</div>
      <div class="ohp-fn-list">${fns}</div>`;
  }

  if (type === 'function') {
    const seg = SEGMENTS.find(s => s.functions.some(f => f.id === id));
    const fn  = seg?.functions.find(f => f.id === id);
    if (!fn) return;

    const ww = fn.worksWith?.map(w => `<span class="ohp-tag">${w}</span>`).join('') || '—';

    html = `
      <div class="ohp-title">${fn.abbr}</div>
      <div class="ohp-meta">${fn.label}</div>

      <div class="ohp-section-title">What they do</div>
      <div class="ohp-desc">${fn.purpose}</div>

      <div class="ohp-section-title">Works with</div>
      <div class="ohp-tags">${ww}</div>

      <div class="ohp-section-title">Reports through</div>
      <div class="ohp-detail-row">${fn.reportsThrough}</div>

      <div class="ohp-section-title">Owns accounts?</div>
      <div class="ohp-detail-row ${fn.ownsAccounts ? 'ohp-yes' : 'ohp-no'}">${fn.ownsAccounts ? 'Yes — carries quota' : 'No — supports quota'}</div>

      <div class="ohp-section-title">Sales motion</div>
      <div class="ohp-detail-row ohp-motion">${fn.salesMotion}</div>`;
  }

  body.innerHTML = html;
  panel.style.display = 'flex';
}

