  flex-direction: column;
  overflow-y: auto;
}
.mh-sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 16px 10px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.mh-sidebar-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.16px;
}
.mh-new-btn {
  font-size: 11px;
  padding: 4px 10px;
  border: 1px solid rgba(255,255,255,0.15);
