210 | // ─────────────────────────────────────────────────────────────────
211 | // Hex geometry  (flat-top)
212 | // col step = R * sqrt(3),  row step = R * 1.5
213 | // ─────────────────────────────────────────────────────────────────
214 | const R   = 52;
215 | const CS  = R * Math.sqrt(3);
216 | const RS  = R * 1.5;
217 | const GAP = 3;
218 | 
219 | function hexPts(cx, cy, r = R) {
220 |   return Array.from({ length: 6 }, (_, i) => {
221 |     const a = (Math.PI / 3) * i;
222 |     return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
223 |   }).join(' ');
224 | }
225 | 
226 | // ─────────────────────────────────────────────────────────────────
227 | // View state
228 | // ─────────────────────────────────────────────────────────────────
229 | let _expandedSegments  = new Set();
230 | let _expandedFunctions = new Set();
231 | let _selectedId        = null;
232 | 
233 | // ─────────────────────────────────────────────────────────────────
234 | // Entry
235 | // ─────────────────────────────────────────────────────────────────
236 | export async function renderOrg(container) {
237 |   _expandedSegments  = new Set();
238 |   _expandedFunctions = new Set();
239 |   _selectedId        = null;
240 | 
241 |   // Auto-expand the user's segment
242 |   _expandedSegments.add('horizon');
243 | 
244 |   container.innerHTML = `
245 |     <div class="ohive-shell">
246 |       <div class="ohive-topbar">
247 |         <div class="ohive-title">IBM Sales Hive</div>
248 |         <div class="ohive-sub">Where does my role fit in IBM?</div>
249 |       </div>
250 |       <div class="ohive-body">
251 |         <div class="ohive-canvas" id="ohiveCanvas"></div>
252 |         <div class="ohive-panel" id="ohivePanel" style="display:none">
253 |           <div class="ohive-panel-close" id="ohivePanelClose">✕</div>
254 |           <div id="ohivePanelBody"></div>
255 |         </div>
256 |       </div>
257 |     </div>
258 |   `;
259 | 
260 |   document.getElementById('ohivePanelClose')?.addEventListener('click', () => {
261 |     _selectedId = null;
262 |     document.getElementById('ohivePanel').style.display = 'none';
263 |     redraw();
264 |   });
265 | 
266 |   redraw();
267 | }
268 | 
269 | // ─────────────────────────────────────────────────────────────────
270 | // Layout
271 | // ─────────────────────────────────────────────────────────────────
272 | function buildLayout() {
273 |   const rowGroups = [];
274 | 
275 |   rowGroups.push({ ids: ['root'],                      parent: null,  type: 'root' });
276 |   rowGroups.push({ ids: SEGMENTS.map(s => s.id),       parent: 'root', type: 'segment' });
277 | 
278 |   for (const seg of SEGMENTS) {
279 |     if (!_expandedSegments.has(seg.id)) continue;
280 |     rowGroups.push({ ids: seg.functions.map(f => f.id), parent: seg.id, type: 'function', segId: seg.id });
281 |   }
282 | 
283 |   // Compute SVG width from widest row
284 |   const rowData = rowGroups.map(rg => {
285 |     const count  = rg.ids.length;
286 |     const totalW = count * CS + (count - 1) * GAP;
287 |     return { ...rg, count, totalW };
288 |   });
289 |   const maxW     = Math.max(...rowData.map(r => r.totalW));
290 |   const PAD_X    = R + 40;
291 |   const PAD_Y    = R + 30;
292 |   const svgW     = maxW + PAD_X * 2;
293 | 
294 |   // Assign row Y positions
295 |   let cy = PAD_Y + R;
296 |   const rowCYs = rowData.map(() => { const v = cy; cy += RS + GAP; return v; });
297 | 
298 |   const nodes = [];
299 |   const pos   = {};   // id → {cx, cy}
300 | 
301 |   rowData.forEach((rg, ri) => {
302 |     const rowCY  = rowCYs[ri];
303 |     const startX = svgW / 2 - rg.totalW / 2 + CS / 2;
304 | 
305 |     rg.ids.forEach((nid, ni) => {
306 |       const cx = startX + ni * (CS + GAP);
307 | 
308 |       let label = '', sub = '', data = null, youAreHere = false;
309 | 
310 |       if (rg.type === 'root') {
311 |         label = 'IBM'; sub = 'Sales Hive';
312 |       } else if (rg.type === 'segment') {
313 |         const seg = SEGMENTS.find(s => s.id === nid);
314 |         label = seg.label; sub = seg.sub; data = seg;
315 |         youAreHere = seg.youAreHere || false;
316 |       } else if (rg.type === 'function') {
317 |         const seg = SEGMENTS.find(s => s.id === rg.segId);
318 |         const fn  = seg?.functions.find(f => f.id === nid);
319 |         label = fn.abbr; sub = fn.label; data = fn;
320 |         youAreHere = fn.youAreHere || false;
321 |       }
322 | 
323 |       const isSelected = _selectedId === nid;
324 |       const isExpanded = rg.type === 'segment' ? _expandedSegments.has(nid) : false;
325 | 
326 |       const node = { id: nid, label, sub, type: rg.type, cx, cy: rowCY,
327 |                      isSelected, youAreHere, isExpanded, data, rowGroup: rg };
328 |       nodes.push(node);
329 |       pos[nid] = { cx, cy: rowCY };
330 |     });
331 |   });
332 | 
333 |   const svgH = cy + R + PAD_Y;
334 |   return { nodes, svgW, svgH, pos };
335 | }
