337 | // ─────────────────────────────────────────────────────────────────
338 | // Draw
339 | // ─────────────────────────────────────────────────────────────────
340 | function redraw() {
341 |   const canvas = document.getElementById('ohiveCanvas');
342 |   if (!canvas) return;
343 | 
344 |   const { nodes, svgW, svgH, pos } = buildLayout();
345 | 
346 |   // Connector lines
347 |   let lines = '';
348 |   nodes.forEach(n => {
349 |     if (!n.rowGroup.parent) return;
350 |     const p = pos[n.rowGroup.parent];
351 |     if (!p) return;
352 |     lines += `<line
353 |       x1="${n.cx.toFixed(1)}" y1="${(n.cy - R).toFixed(1)}"
354 |       x2="${p.cx.toFixed(1)}"  y2="${(p.cy + R).toFixed(1)}"
355 |       stroke="rgba(255,255,255,0.07)" stroke-width="1" pointer-events="none"/>`;
356 |   });
357 | 
358 |   // Hex nodes
359 |   let hexes = '';
360 |   nodes.forEach(n => {
361 |     const isSel  = n.isSelected;
362 |     const isYou  = n.youAreHere;
363 |     const isRoot = n.type === 'root';
364 | 
365 |     const stroke = isSel ? '#4589ff' : isYou ? '#4589ff' : 'rgba(255,255,255,0.22)';
366 |     const sw     = isSel || isYou ? 1.5 : 1;
367 |     const fill   = isSel ? 'rgba(69,137,255,0.13)' : isRoot ? 'rgba(255,255,255,0.04)' : '#0f0f0f';
368 | 
369 |     const youRing = isYou && !isSel
370 |       ? `<polygon points="${hexPts(n.cx, n.cy, R + 7)}"
371 |           fill="none" stroke="rgba(69,137,255,0.3)" stroke-width="1"
372 |           stroke-dasharray="4,3" pointer-events="none"/>` : '';
373 | 
374 |     const labelColor = isSel || isYou ? '#4589ff' : '#e0e0e0';
375 |     const subColor   = isSel ? 'rgba(69,137,255,0.75)' : 'rgba(255,255,255,0.28)';
376 |     const labelY     = n.sub ? n.cy - 9 : n.cy + 4;
377 | 
378 |     const labelEl = `<text x="${n.cx.toFixed(1)}" y="${labelY.toFixed(1)}" text-anchor="middle"
379 |       fill="${labelColor}" font-size="${isRoot ? 13 : 12}" font-weight="${isSel || isRoot ? 600 : 400}"
380 |       font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none">${n.label}</text>`;
381 | 
382 |     const subEl = n.sub
383 |       ? `<text x="${n.cx.toFixed(1)}" y="${(n.cy + 9).toFixed(1)}" text-anchor="middle"
384 |           fill="${subColor}" font-size="8"
385 |           font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none"
386 |           >${n.sub.length > 16 ? n.sub.slice(0, 15) + '…' : n.sub}</text>` : '';
387 | 
388 |     // Small dot if can expand
389 |     const canExpand = n.type === 'segment' && !n.isExpanded;
390 |     const expandDot = canExpand
391 |       ? `<circle cx="${n.cx.toFixed(1)}" cy="${(n.cy + R - 11).toFixed(1)}" r="3"
392 |           fill="rgba(255,255,255,0.18)" pointer-events="none"/>` : '';
393 | 
394 |     hexes += `
395 |       <g class="ohive-node" data-node-id="${n.id}" data-node-type="${n.type}" style="cursor:pointer">
396 |         ${youRing}
397 |         <polygon points="${hexPts(n.cx, n.cy)}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>
398 |         ${labelEl}${subEl}${expandDot}
399 |       </g>`;
400 |   });
401 | 
402 |   canvas.innerHTML = `
403 |     <svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}"
404 |       xmlns="http://www.w3.org/2000/svg" style="display:block;overflow:visible">
405 |       <g>${lines}</g>
406 |       <g>${hexes}</g>
407 |     </svg>`;
408 | 
409 |   canvas.querySelectorAll('.ohive-node').forEach(el => {
410 |     el.addEventListener('click', e => {
411 |       e.stopPropagation();
412 |       handleClick(el.dataset.nodeId, el.dataset.nodeType);
413 |     });
414 |   });
415 | }
