// ─────────────────────────────────────────────────────────────────
// Hex geometry  (flat-top)
// col step = R * sqrt(3),  row step = R * 1.5
// ─────────────────────────────────────────────────────────────────
const R   = 52;
const CS  = R * Math.sqrt(3);
const RS  = R * 1.5;
const GAP = 3;

function hexPts(cx, cy, r = R) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = (Math.PI / 3) * i;
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(' ');
}

// ─────────────────────────────────────────────────────────────────
// View state
// ─────────────────────────────────────────────────────────────────
let _expandedSegments  = new Set();
let _expandedFunctions = new Set();
let _selectedId        = null;

// ─────────────────────────────────────────────────────────────────
// Entry
// ─────────────────────────────────────────────────────────────────
export async function renderOrg(container) {
  _expandedSegments  = new Set();
  _expandedFunctions = new Set();
  _selectedId        = null;

  // Auto-expand the user's segment (BTSS in Select Territory)
  _expandedSegments.add('territory');

  container.innerHTML = `
    <div class="ohive-shell">
      <div class="ohive-body">
        <div class="ohive-canvas" id="ohiveCanvas"></div>
        <div class="ohive-panel" id="ohivePanel" style="display:none">
          <div class="ohive-panel-close" id="ohivePanelClose">✕</div>
          <div id="ohivePanelBody"></div>
        </div>
      </div>
    </div>
  `;

  document.getElementById('ohivePanelClose')?.addEventListener('click', () => {
    _selectedId = null;
    document.getElementById('ohivePanel').style.display = 'none';
    redraw();
  });

  redraw();
}

// ─────────────────────────────────────────────────────────────────
// Layout
//
// Structure:
//   Row 0: IBM root (1 hex)
//   Row 1: 4 segment hexes in a line (lines connect to IBM)
//   For each expanded segment: a PACKED HEX GRID of its roles
//     — rows of COLS_PER_ROW, offset every other row (real honeycomb)
//     — NO lines between roles; the cluster communicates membership
//
// Lines only: IBM → segments (structural hierarchy).
// Roles inside a segment are PEERS — no lines between them.
// ─────────────────────────────────────────────────────────────────

const COLS_PER_ROW = 4;   // roles per row in the cluster grid

function buildLayout() {
  const nodes = [];
  const pos   = {};
  const lines_data = [];   // [{x1,y1,x2,y2}] — only IBM→segment

  const PAD_X  = R + 48;
  const PAD_Y  = R + 36;
  const SEG_ROW_STEP = RS + 8;   // vertical gap between segment and role cluster

  // ── Row 0: IBM root ──────────────────────────────────────────
  // We'll figure out the total width once we know the widest thing,
  // so first collect all node positions relative to their row center X,
  // then shift everything to center in the SVG.

  // First pass: compute relative X for segments
  const segCount  = SEGMENTS.length;
  const segTotalW = segCount * CS + (segCount - 1) * GAP;

  // For each expanded segment, compute how wide its role cluster is
  const clusterWidths = {};
  SEGMENTS.forEach(seg => {
    if (!_expandedSegments.has(seg.id)) return;
    const n = seg.functions.length;
    const cols = Math.min(n, COLS_PER_ROW);
    clusterWidths[seg.id] = cols * CS + (cols - 1) * GAP;
  });

  // SVG width = max of (segTotalW, any cluster width) + padding
  const maxW  = Math.max(segTotalW, ...Object.values(clusterWidths), 0);
  const svgW  = maxW + PAD_X * 2;
  const svgCX = svgW / 2;   // center X for everything

  // ── Place root ───────────────────────────────────────────────
  let curY = PAD_Y + R;
  const rootCX = svgCX;

  nodes.push({ id: 'root', label: 'IBM', sub: 'Sales Hive',
    type: 'root', cx: rootCX, cy: curY,
    isSelected: _selectedId === 'root', youAreHere: false,
    isExpanded: false, data: null });
  pos['root'] = { cx: rootCX, cy: curY };

  curY += RS + GAP;

  // ── Place segments ───────────────────────────────────────────
  const segStartX = svgCX - segTotalW / 2 + CS / 2;
  SEGMENTS.forEach((seg, si) => {
    const cx = segStartX + si * (CS + GAP);
    const cy = curY;
    nodes.push({ id: seg.id, label: seg.label, sub: seg.sub,
      type: 'segment', cx, cy,
      isSelected: _selectedId === seg.id,
      youAreHere: seg.youAreHere || false,
      isExpanded: _expandedSegments.has(seg.id),
      data: seg });
    pos[seg.id] = { cx, cy };
    // IBM → segment line
    lines_data.push({ x1: rootCX, y1: pos['root'].cy + R, x2: cx, y2: cy - R });
  });

  curY += RS + GAP;

  // ── Place role clusters for expanded segments ────────────────
  SEGMENTS.forEach(seg => {
    if (!_expandedSegments.has(seg.id)) return;

    const fns  = seg.functions;
    const cols = Math.min(fns.length, COLS_PER_ROW);

    // Compute rows needed
    const rows = Math.ceil(fns.length / cols);

    // Cluster total width (widest row)
    const clusterW = cols * CS + (cols - 1) * GAP;
    const clusterStartX = svgCX - clusterW / 2 + CS / 2;

    fns.forEach((fn, fi) => {
      const col = fi % cols;
      const row = Math.floor(fi / cols);
      // Offset every other row by CS/2 for tight honeycomb packing
      const offsetX = (row % 2 === 1) ? CS / 2 : 0;
      const cx = clusterStartX + col * (CS + GAP) + offsetX;
      const cy = curY + row * (RS + GAP);

      nodes.push({ id: fn.id, label: fn.abbr, sub: fn.label,
        type: 'function', cx, cy,
        isSelected: _selectedId === fn.id,
        youAreHere: fn.youAreHere || false,
        isExpanded: false, data: fn,
        segId: seg.id });
      pos[fn.id] = { cx, cy };
      // No lines from segment to roles — cluster shape communicates membership
    });

    curY += rows * (RS + GAP) + GAP;
  });

  const svgH = curY + R + PAD_Y;
  return { nodes, svgW, svgH, lines_data };
}

// ─────────────────────────────────────────────────────────────────
// Draw
// ─────────────────────────────────────────────────────────────────
function redraw() {
  const canvas = document.getElementById('ohiveCanvas');
  if (!canvas) return;

  const { nodes, svgW, svgH, lines_data } = buildLayout();

  // Structural lines — IBM → segments only
  let lines = lines_data.map(l =>
    `<line x1="${l.x1.toFixed(1)}" y1="${l.y1.toFixed(1)}"
      x2="${l.x2.toFixed(1)}" y2="${l.y2.toFixed(1)}"
      stroke="rgba(255,255,255,0.10)" stroke-width="1" pointer-events="none"/>`
  ).join('');

  // Hex nodes
  // Purple (#a855f7) = you are here   |   IBM blue (#4589ff) = selected
  let hexes = '';
  nodes.forEach(n => {
    const isSel  = n.isSelected;
    const isYou  = n.youAreHere;
    const isRoot = n.type === 'root';
    const isFn   = n.type === 'function';

    const stroke = isSel ? '#4589ff' : isYou ? '#a855f7' : 'rgba(255,255,255,0.22)';
    const sw     = isSel || isYou ? 1.5 : 1;
    const fill   = isSel ? 'rgba(69,137,255,0.13)'
                 : isYou ? 'rgba(168,85,247,0.10)'
                 : isRoot ? 'rgba(255,255,255,0.04)'
                 : '#0f0f0f';

    const youRing = isYou && !isSel
      ? `<polygon points="${hexPts(n.cx, n.cy, R + 7)}"
          fill="none" stroke="rgba(168,85,247,0.35)" stroke-width="1"
          stroke-dasharray="4,3" pointer-events="none"/>` : '';

    const labelColor = isSel ? '#4589ff' : isYou ? '#a855f7' : '#e0e0e0';
    const subColor   = isSel ? 'rgba(69,137,255,0.75)'
                     : isYou ? 'rgba(168,85,247,0.65)'
                     : 'rgba(255,255,255,0.28)';
    const labelY     = n.sub ? n.cy - 9 : n.cy + 4;

    const labelEl = `<text x="${n.cx.toFixed(1)}" y="${labelY.toFixed(1)}" text-anchor="middle"
      fill="${labelColor}" font-size="${isRoot ? 13 : 12}" font-weight="${isSel || isRoot ? 600 : 400}"
      font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none">${n.label}</text>`;

    // Sub-label: truncate to fit hex width (~R*1.6 ≈ 83px @ 8px font)
    const subTrunc = n.sub?.length > 14 ? n.sub.slice(0, 13) + '…' : n.sub;
    const subEl = n.sub
      ? `<text x="${n.cx.toFixed(1)}" y="${(n.cy + 9).toFixed(1)}" text-anchor="middle"
          fill="${subColor}" font-size="${isFn ? 7.5 : 8}"
          font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none"
          >${subTrunc}</text>` : '';

    // Expand indicator: small dot bottom of segment hexes that aren't expanded
    const canExpand = n.type === 'segment' && !n.isExpanded;
    const expandDot = canExpand
      ? `<circle cx="${n.cx.toFixed(1)}" cy="${(n.cy + R - 11).toFixed(1)}" r="2.5"
          fill="rgba(255,255,255,0.18)" pointer-events="none"/>` : '';

    hexes += `
      <g class="ohive-node" data-node-id="${n.id}" data-node-type="${n.type}"
         ${n.segId ? `data-seg-id="${n.segId}"` : ''} style="cursor:pointer">
        ${youRing}
        <polygon points="${hexPts(n.cx, n.cy)}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>
        ${labelEl}${subEl}${expandDot}
      </g>`;
  });

  canvas.innerHTML = `
    <svg width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}"
      xmlns="http://www.w3.org/2000/svg" style="display:block;overflow:visible">
      <g>${lines}</g>
      <g>${hexes}</g>
    </svg>`;

  canvas.querySelectorAll('.ohive-node').forEach(el => {
    el.addEventListener('click', e => {
      e.stopPropagation();
      handleClick(el.dataset.nodeId, el.dataset.nodeType);
    });
  });
}

// ─────────────────────────────────────────────────────────────────
// Interaction
// ─────────────────────────────────────────────────────────────────
function handleClick(id, type) {
  if (type === 'root') {
    _expandedSegments.clear();
    _selectedId = null;
    document.getElementById('ohivePanel').style.display = 'none';
    redraw();
    return;
  }

  if (type === 'segment') {
    if (_expandedSegments.has(id)) {
      _expandedSegments.delete(id);
    } else {
      _expandedSegments.add(id);
    }
  }

  _selectedId = id;
  redraw();
  showPanel(id, type);
}

// ─────────────────────────────────────────────────────────────────
// Detail panel — role context only, no people
// ─────────────────────────────────────────────────────────────────
function showPanel(id, type) {
  const panel = document.getElementById('ohivePanel');
  const body  = document.getElementById('ohivePanelBody');
  if (!panel || !body) return;

  let html = '';

  if (type === 'segment') {
    const seg = SEGMENTS.find(s => s.id === id);
    if (!seg) return;
    const fns = seg.functions.map(f =>
      `<div class="ohp-fn-row">
        <span class="ohp-fn-abbr">${f.abbr}</span>
        <span class="ohp-fn-label">${f.label}</span>
      </div>`
    ).join('');
    html = `
      <div class="ohp-title">${seg.label}</div>
      <div class="ohp-meta">${seg.sub}</div>
      <div class="ohp-desc">${seg.desc}</div>
      <div class="ohp-section-title">Roles in this segment</div>
      <div class="ohp-fn-list">${fns}</div>`;
  }

  if (type === 'function') {
    const seg = SEGMENTS.find(s => s.functions.some(f => f.id === id));
    const fn  = seg?.functions.find(f => f.id === id);
    if (!fn) return;

    const ww = fn.worksWith?.map(w => `<span class="ohp-tag">${w}</span>`).join('') || '—';

    html = `
      <div class="ohp-title">${fn.abbr}</div>
      <div class="ohp-meta">${fn.label}</div>

      <div class="ohp-section-title">What they do</div>
      <div class="ohp-desc">${fn.purpose}</div>

      <div class="ohp-section-title">Works with</div>
      <div class="ohp-tags">${ww}</div>

      <div class="ohp-section-title">Reports through</div>
      <div class="ohp-detail-row">${fn.reportsThrough}</div>

      <div class="ohp-section-title">Owns accounts?</div>
      <div class="ohp-detail-row ${fn.ownsAccounts ? 'ohp-yes' : 'ohp-no'}">${fn.ownsAccounts ? 'Yes — carries quota' : 'No — supports quota'}</div>

      <div class="ohp-section-title">Sales motion</div>
      <div class="ohp-detail-row ohp-motion">${fn.salesMotion}</div>

      ${fn.products ? `<div class="ohp-section-title">Products covered</div>
      <div class="ohp-detail-row">${fn.products}</div>` : ''}`;
  }

  body.innerHTML = html;
  panel.style.display = 'flex';
}

