  padding: 12px;
  margin-top: 12px;
}
.mh-add-search {
  width: 100%;
  padding: 8px 10px;
  background: var(--surface-2);
  border: none;
  border-bottom: 2px solid var(--border);
  color: var(--text);
  font-size: 13px;
  font-family: inherit;
  outline: none;
  margin-bottom: 8px;
  transition: border-color 0.1s;
  border-radius: 0;
