}
.cell-table th {
  text-align: left;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.32px;
  color: var(--muted);
  padding: 0 12px 8px 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.cell-table td {
  padding: 9px 12px 9px 0;
