   ═══════════════════════════════════════════════════════════════ */

.cell-structure-wrap {
  flex: 1;
  padding: 24px 32px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.cell-structure-header {
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding-bottom: 14px;
}
.cell-header-breadcrumb {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  margin-bottom: 6px;
