}
.cell-leg-solid  { background: #0ea5e9; }
.cell-leg-dashed { background: none; border-top: 2px dashed #6c63ff; }
.cell-leg-dot {
  width: 10px; height: 10px;
  border-radius: 2px; flex-shrink: 0;
}

.cell-products {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cell-products-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  font-weight: 600;
}
.cell-products-list { display: flex; gap: 6px; flex-wrap: wrap; }
.cell-product-tag {
  font-size: 12px;
  padding: 4px 12px;
  background: rgba(77,123,255,0.08);
  border: 1px solid rgba(77,123,255,0.2);
  color: var(--ibm-blue-40);
}

.cell-pairs-table { }
.cell-pairs-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  font-weight: 600;
  margin-bottom: 10px;
}
.cell-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.cell-table th {
  text-align: left;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.32px;
