.cell-table td {
  padding: 9px 12px 9px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  color: var(--text-secondary);
  vertical-align: middle;
}
.cell-table tr:last-child td { border-bottom: none; }

