/**
 * seller.js — My Team view
 *
 * Answers one question: "Who do I work with and how does our team operate?"
 *
 * Team: Infrastructure · Select Territory
 *   BTSS Manager: Chris Kennedy
 *   BTSS: Sydney Chin (you), Mark Hoffman, Armada Veraepalli
 *   TSS Manager: Rob Hanes
 *   TSS: Ross Holley, Patrick McBride
 *   Pairs: Mark ↔ Ross  |  Armada ↔ Patrick
 *   Sydney: unassigned / intern (no formal TSS pair shown)
 */
import { getPeople } from '../api.js';
import { openPerson } from '../panel.js';

// ── Static team config ────────────────────────────────────────────
const PRODUCTS = ['IBM PowerVS', 'IBM FlashSystem', 'IBM Fusion', 'IBM z16', 'IBM LinuxONE'];
const COVERAGE = 'Select Territory · National · C&D (Channels & Distribution)';

const TEAM_DETAIL = {
  // role-level extra info keyed by "First Last"
  'Sydney Chin':        { role: 'Brand Technical Sales Specialist', manager: 'Chris Kennedy', pair: null,             products: ['PowerVS','FlashSystem','Fusion'], territory: 'C&D', responsibilities: 'Technical sales, demos, POCs, solution validation' },
  'Mark Hoffman':       { role: 'Brand Technical Sales Specialist', manager: 'Chris Kennedy', pair: 'Ross Holley',    products: ['PowerVS','FlashSystem'],          territory: 'C&D', responsibilities: 'Technical sales, demos, POCs, solution validation' },
  'Armada Veraepalli':  { role: 'Brand Technical Sales Specialist', manager: 'Chris Kennedy', pair: 'Patrick McBride',products: ['Fusion','z16'],                   territory: 'C&D', responsibilities: 'Technical sales, demos, POCs, solution validation' },
  'Ross Holley':        { role: 'Territory Sales Specialist',       manager: 'Rob Hanes',     pair: 'Mark Hoffman',  products: null,                               territory: 'National', responsibilities: 'Territory pipeline, prospecting, commercial close' },
  'Patrick McBride':    { role: 'Territory Sales Specialist',       manager: 'Rob Hanes',     pair: 'Armada Veraepalli', products: null,                            territory: 'National', responsibilities: 'Territory pipeline, prospecting, commercial close' },
  'Chris Kennedy':      { role: 'BTSS Manager',                     manager: null,             pair: null,             products: null,                               territory: 'National', responsibilities: 'Team leadership, BTSS alignment, escalation support' },
  'Rob Hanes':          { role: 'TSS Manager',                      manager: null,             pair: null,             products: null,                               territory: 'National', responsibilities: 'Team leadership, TSS quota ownership, territory strategy' },
};

export async function renderSeller(container) {
  const allPeople = await getPeople();

  const find = (fn, ln) => allPeople.find(p => p.first_name === fn && p.last_name === ln);
  const chrisK   = find('Chris',   'Kennedy');
  const robH     = find('Rob',     'Hanes');
  const sydneyC  = allPeople.find(p => p.is_current_user) || find('Sydney', 'Chin');
  const markH    = find('Mark',    'Hoffman');
  const armada   = find('Armada',  'Veraepalli');
  const rossH    = find('Ross',    'Holley');
  const patrickM = find('Patrick', 'McBride');

  // ── SVG layout ──────────────────────────────────────────────────
  // Three rows (top to bottom):
  //   Row A: Managers  — Chris Kennedy (left), Rob Hanes (right)
  //   Row B: BTSS members (left column): Sydney, Mark, Armada
  //   Row C: TSS members (right column): Ross, Patrick  (vertically aligned with their pair)
  //
  // Pairing lines connect Mark↔Ross and Armada↔Patrick horizontally.
  // Manager reporting lines connect downward from managers to their teams.

  const NW = 148, NH = 60;   // node width / height
  const MGRCOL_L = 80;       // left column X (BTSS / Chris)
  const MGRCOL_R = 420;      // right column X (TSS / Rob)
  const MGR_Y    = 60;       // managers row Y
  const MBR_Y    = 196;      // members start Y
  const V_STEP   = 88;       // vertical step between members
  const SVG_W    = MGRCOL_R + NW + 80;
  const BTSSx    = MGRCOL_L;
  const TSSx     = MGRCOL_R;

  // Y positions for pairs (Mark↔Ross at same Y, Armada↔Patrick at same Y)
  const yMark   = MBR_Y;
  const yArmada = MBR_Y + V_STEP;
  const ySydney = MBR_Y + V_STEP * 2;

  const yRoss    = yMark;
  const yPatrick = yArmada;

  const SVG_H = ySydney + NH + 80;

  let svgLines = '';
  let svgNodes = '';

  const midX = (BTSSx + NW + TSSx) / 2;  // midpoint between the two columns

  // ── Vertical divider ────────────────────────────────────────────
  svgLines += `<line x1="${midX}" y1="${MGR_Y}" x2="${midX}" y2="${SVG_H - 40}"
    stroke="rgba(255,255,255,0.05)" stroke-width="1" stroke-dasharray="4,6"/>`;

  // ── Manager → member reporting lines (soft dashed, vertical) ────
  const mgrReportLine = (mx, my, memberYs) => memberYs.map(my2 =>
    `<line x1="${mx + NW/2}" y1="${my + NH}" x2="${mx + NW/2}" y2="${my2}"
      stroke="rgba(255,255,255,0.12)" stroke-width="1" stroke-dasharray="4,4"/>`
  ).join('');

  svgLines += mgrReportLine(BTSSx, MGR_Y, [yMark, yArmada, ySydney]);
  svgLines += mgrReportLine(TSSx,  MGR_Y, [yRoss, yPatrick]);

  // ── Pairing lines ────────────────────────────────────────────────
  const pairLine = (y1, y2) => {
    const x1 = BTSSx + NW, x2 = TSSx;
    return `<path d="M ${x1} ${y1 + NH/2} C ${midX} ${y1 + NH/2}, ${midX} ${y2 + NH/2}, ${x2} ${y2 + NH/2}"
      stroke="#4589ff" stroke-width="1.5" fill="none" opacity="0.6"/>
    <circle cx="${midX}" cy="${(y1 + y2)/2 + NH/2}" r="3" fill="#4589ff" opacity="0.5"/>`;
  };
  svgLines += pairLine(yMark,   yRoss);
  svgLines += pairLine(yArmada, yPatrick);

  // ── Draw a node ──────────────────────────────────────────────────
  const drawNode = (person, x, y, isManager = false) => {
    if (!person) return '';
    const isMe = person.is_current_user;
    const name = `${person.first_name} ${person.last_name}`;
    const detail = TEAM_DETAIL[name] || {};
    const roleLabel = detail.role || person.role || '—';

    const borderColor = isMe ? '#4589ff' : isManager ? '#a855f7' : (x === BTSSx ? '#4589ff' : '#0ea5e9');
    const textColor   = isMe ? '#78a9ff' : '#e0e0e0';

    return `
      <g class="mt-node" data-person-id="${person.id}" style="cursor:pointer">
        <rect x="${x}" y="${y}" width="${NW}" height="${NH}" rx="4"
          fill="#1c1c1c" stroke="${borderColor}" stroke-width="${isMe ? 2 : 1}"/>
        ${isMe ? `<rect x="${x-3}" y="${y-3}" width="${NW+6}" height="${NH+6}" rx="7"
          fill="none" stroke="#4589ff" stroke-width="1" stroke-dasharray="3,3" opacity="0.4"/>` : ''}
        <text x="${x + NW/2}" y="${y + 22}" text-anchor="middle"
          fill="${textColor}" font-size="13" font-weight="500"
          font-family="IBM Plex Sans, system-ui, sans-serif">${name}</text>
        <text x="${x + NW/2}" y="${y + 40}" text-anchor="middle"
          fill="${borderColor}" font-size="10" opacity="0.85"
          font-family="IBM Plex Sans, system-ui, sans-serif">${isManager ? roleLabel : (x === BTSSx ? 'BTSS' : 'TSS')}</text>
        ${isMe ? `<text x="${x + NW/2}" y="${y + 54}" text-anchor="middle"
          fill="#4589ff" font-size="9" opacity="0.7"
          font-family="IBM Plex Sans, system-ui, sans-serif">you</text>` : ''}
      </g>`;
  };

  // Managers
  svgNodes += drawNode(chrisK,   BTSSx, MGR_Y, true);
  svgNodes += drawNode(robH,     TSSx,  MGR_Y, true);
  // BTSS members
  svgNodes += drawNode(markH,    BTSSx, yMark);
  svgNodes += drawNode(armada,   BTSSx, yArmada);
  svgNodes += drawNode(sydneyC,  BTSSx, ySydney);
  // TSS members
  svgNodes += drawNode(rossH,    TSSx,  yRoss);
  svgNodes += drawNode(patrickM, TSSx,  yPatrick);

  // Column headings
  const colHead = (x, label, sub, color) =>
    `<text x="${x + NW/2}" y="${MGR_Y - 28}" text-anchor="middle"
      fill="${color}" font-size="12" font-weight="600"
      font-family="IBM Plex Sans, system-ui, sans-serif">${label}</text>
    <text x="${x + NW/2}" y="${MGR_Y - 13}" text-anchor="middle"
      fill="#525252" font-size="10"
      font-family="IBM Plex Sans, system-ui, sans-serif">${sub}</text>`;

  svgNodes += colHead(BTSSx, 'BTSS', 'Brand Technical Sales', '#a855f7');
  svgNodes += colHead(TSSx,  'TSS',  'Territory Sales', '#0ea5e9');

  const svgHtml = `
    <svg width="${SVG_W}" height="${SVG_H}" viewBox="0 0 ${SVG_W} ${SVG_H}"
      xmlns="http://www.w3.org/2000/svg" style="display:block;overflow:visible">
      <g>${svgLines}</g>
      <g>${svgNodes}</g>
    </svg>`;

  // ── Render page ──────────────────────────────────────────────────
  container.innerHTML = `
    <div class="mt-page">

      <div class="mt-header">
        <div class="mt-header-left">
          <div class="mt-title">My Team</div>
          <div class="mt-subtitle">Infrastructure · Select Territory</div>
        </div>
        <div class="mt-header-meta">
          <div class="mt-meta-block">
            <div class="mt-meta-label">Products supported</div>
            <div class="mt-meta-tags">
              ${PRODUCTS.map(p => `<span class="mt-tag">${p}</span>`).join('')}
            </div>
          </div>
          <div class="mt-meta-block">
            <div class="mt-meta-label">Coverage model</div>
            <div class="mt-meta-value">${COVERAGE}</div>
          </div>
        </div>
      </div>

      <div class="mt-diagram">
        <div class="mt-diagram-inner">
          ${svgHtml}
        </div>
        <div class="mt-legend">
          <span class="mt-leg"><span class="mt-leg-line mt-leg-pair"></span>BTSS ↔ TSS pair</span>
          <span class="mt-leg"><span class="mt-leg-line mt-leg-report"></span>Reports to manager</span>
          <span class="mt-leg"><span class="mt-leg-dot" style="background:#4589ff"></span>You</span>
        </div>
      </div>

    </div>
  `;

  // Wire clicks → detail panel
  container.querySelectorAll('.mt-node').forEach(el => {
    el.addEventListener('click', () => openPerson(el.dataset.personId));
  });
}

