// ─────────────────────────────────────────────────────────────────
// Hex geometry  (flat-top)
// col step  = R * sqrt(3)
// row step  = R * 2  (full diameter — ensures no vertical overlap even on offset rows)
// ─────────────────────────────────────────────────────────────────
const R   = 72;
const CS  = R * Math.sqrt(3);   // ≈ 124.7 — horizontal center-to-center
const RS  = R * 2;              // 144    — vertical center-to-center (no overlap)
const GAP = 48;                 // extra spacing between cells — wide enough so hexes don't touch

function hexPts(cx, cy, r = R) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = (Math.PI / 3) * i;
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(' ');
}

// ─────────────────────────────────────────────────────────────────
// View state
// ─────────────────────────────────────────────────────────────────
let _expandedSegments  = new Set();
let _expandedFunctions = new Set();
let _selectedId        = null;

// ─────────────────────────────────────────────────────────────────
// Entry
// ─────────────────────────────────────────────────────────────────
export async function renderOrg(container) {
  _expandedSegments  = new Set();
  _expandedFunctions = new Set();
  _selectedId        = null;

  // Load with IBM + segments only — user expands segments to reveal roles
  container.innerHTML = `
    <div class="ohive-shell">
      <div class="ohive-body">
        <div class="ohive-canvas" id="ohiveCanvas"></div>
      </div>
    </div>
  `;

  redraw();
}

// ─────────────────────────────────────────────────────────────────
// Layout
//
// Structure:
//   Row 0: IBM root (1 hex)
//   Row 1: 4 segment hexes in a line (lines connect to IBM)
//   For each expanded segment: a PACKED HEX GRID of its roles
//     — rows of COLS_PER_ROW, offset every other row (real honeycomb)
//     — NO lines between roles; the cluster communicates membership
//
// Lines only: IBM → segments (structural hierarchy).
// Roles inside a segment are PEERS — no lines between them.
// ─────────────────────────────────────────────────────────────────

const COLS_PER_ROW = 4;   // roles per row in the cluster grid

function buildLayout() {
  const nodes = [];
  const pos   = {};
  const lines_data = [];   // [{x1,y1,x2,y2, type:'root-seg'|'seg-role'}]

  const PAD_X  = R + 48;
  const PAD_Y  = R + 36;
  const SEG_ROW_STEP = RS + 8;   // vertical gap between segment and role cluster

  // ── Row 0: IBM root ──────────────────────────────────────────
  // We'll figure out the total width once we know the widest thing,
  // so first collect all node positions relative to their row center X,
  // then shift everything to center in the SVG.

  // First pass: compute relative X for segments
  const segCount  = SEGMENTS.length;
  const segTotalW = segCount * CS + (segCount - 1) * GAP;

  // For each expanded segment, compute how wide its role cluster is
  const clusterWidths = {};
  SEGMENTS.forEach(seg => {
    if (!_expandedSegments.has(seg.id)) return;
    const n = seg.functions.length;
    const cols = Math.min(n, COLS_PER_ROW);
    clusterWidths[seg.id] = cols * CS + (cols - 1) * GAP;
  });

  // SVG width = max of (segTotalW, any cluster width) + padding
  const maxW  = Math.max(segTotalW, ...Object.values(clusterWidths), 0);
  const svgW  = maxW + PAD_X * 2;
  const svgCX = svgW / 2;   // center X for everything

  // ── Place root ───────────────────────────────────────────────
  let curY = PAD_Y + R;
  const rootCX = svgCX;

  nodes.push({ id: 'root', label: 'IBM', sub: 'Sales Hive',
    type: 'root', cx: rootCX, cy: curY,
    isSelected: _selectedId === 'root', youAreHere: false,
    isExpanded: false, data: null });
  pos['root'] = { cx: rootCX, cy: curY };

  curY += RS + GAP;

  // ── Place segments ───────────────────────────────────────────
  const segStartX = svgCX - segTotalW / 2 + CS / 2;
  SEGMENTS.forEach((seg, si) => {
    const cx = segStartX + si * (CS + GAP);
    const cy = curY;
    nodes.push({ id: seg.id, label: seg.label, sub: seg.sub,
      type: 'segment', cx, cy,
      isSelected: _selectedId === seg.id,
      youAreHere: seg.youAreHere || false,
      isExpanded: _expandedSegments.has(seg.id),
      data: seg });
    pos[seg.id] = { cx, cy };
    // IBM → segment thin connector
    lines_data.push({ x1: rootCX, y1: pos['root'].cy + R, x2: cx, y2: cy - R, kind: 'root-seg' });
  });

  curY += RS + GAP;

  // ── Place role clusters for expanded segments ────────────────
  SEGMENTS.forEach(seg => {
    if (!_expandedSegments.has(seg.id)) return;

    const fns  = seg.functions;
    const cols = Math.min(fns.length, COLS_PER_ROW);

    // Compute rows needed
    const rows = Math.ceil(fns.length / cols);

    // Cluster total width (widest row)
    const clusterW = cols * CS + (cols - 1) * GAP;
    const clusterStartX = svgCX - clusterW / 2 + CS / 2;

    fns.forEach((fn, fi) => {
      const col = fi % cols;
      const row = Math.floor(fi / cols);
      // Offset every other row by CS/2 for tight honeycomb packing
      const offsetX = (row % 2 === 1) ? CS / 2 : 0;
      const cx = clusterStartX + col * (CS + GAP) + offsetX;
      const cy = curY + row * (RS + GAP);

      nodes.push({ id: fn.id, label: fn.abbr, sub: fn.label,
        type: 'function', cx, cy,
        isSelected: _selectedId === fn.id,
        youAreHere: fn.youAreHere || false,
        isExpanded: false, data: fn,
        segId: seg.id });
      pos[fn.id] = { cx, cy };
      // Segment → role line (shows membership, not hierarchy)
      const segPos = pos[seg.id];
      if (segPos) {
        lines_data.push({ x1: segPos.cx, y1: segPos.cy + R, x2: cx, y2: cy - R, kind: 'seg-role' });
      }
    });

    curY += rows * (RS + GAP) + GAP;
  });

  const svgH = curY + R + PAD_Y;
  return { nodes, svgW, svgH, lines_data };
}

// ─────────────────────────────────────────────────────────────────
// Draw
// ─────────────────────────────────────────────────────────────────
function redraw() {
  const canvas = document.getElementById('ohiveCanvas');
  if (!canvas) return;

  const { nodes, svgW, svgH, lines_data } = buildLayout();

  // Lines: root→segment thin & subtle; segment→role slightly visible
  let lines = lines_data.map(l => {
    const isRootSeg = l.kind === 'root-seg';
    return `<line x1="${l.x1.toFixed(1)}" y1="${l.y1.toFixed(1)}"
      x2="${l.x2.toFixed(1)}" y2="${l.y2.toFixed(1)}"
      stroke="rgba(255,255,255,${isRootSeg ? '0.18' : '0.12'})"
      stroke-width="1"
      stroke-linecap="round" pointer-events="none"/>`;
  }).join('');

  // Hex nodes
  // Cells: gray fill (#2a2a2a). Background: black.
  // Selected/youAreHere: outline color change ONLY — no fill tint.
  let hexes = '';
  nodes.forEach(n => {
    const isSel  = n.isSelected;
    const isYou  = n.youAreHere;
    const isRoot = n.type === 'root';
    const isFn   = n.type === 'function';
    const isSeg  = n.type === 'segment';

    // Outline: blue if selected, purple if you-are-here, white otherwise
    const stroke = isSel ? '#4589ff' : isYou ? '#a855f7' : 'rgba(255,255,255,0.55)';
    const sw     = isSel || isYou ? 2.5 : 1.5;
    // All hexes: gray fill. No fill tint for state.
    const fill = '#2a2a2a';

    const youRing = isYou && !isSel
      ? `<polygon points="${hexPts(n.cx, n.cy, R + 8)}"
          fill="none" stroke="rgba(168,85,247,0.35)" stroke-width="1.5"
          stroke-dasharray="5,3" pointer-events="none"/>` : '';

    const labelColor = isSel ? '#4589ff' : isYou ? '#c084fc' : '#ffffff';
    const subColor   = isSel ? 'rgba(69,137,255,0.75)'
                     : isYou ? 'rgba(192,132,252,0.70)'
                     : 'rgba(255,255,255,0.42)';

    const labelFontSize = isRoot ? 16 : isFn ? 14 : 13;
    const labelFontWeight = isSel || isRoot ? 700 : 500;

    // Multi-line label: split on spaces, render with tspan per word if needed
    const labelLines = wrapText(n.label, isRoot ? 10 : 8);  // chars per line
    const lineH = labelFontSize + 3;
    const labelBlockH = labelLines.length * lineH;
    // If there's a sub-label, shift label block up
    const labelBaseY = n.sub
      ? n.cy - labelBlockH / 2 - 6
      : n.cy - labelBlockH / 2 + labelFontSize * 0.35;

    const labelEl = labelLines.map((line, i) =>
      `<text x="${n.cx.toFixed(1)}" y="${(labelBaseY + i * lineH).toFixed(1)}" text-anchor="middle"
        fill="${labelColor}" font-size="${labelFontSize}" font-weight="${labelFontWeight}"
        font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none">${line}</text>`
    ).join('');

    const subLines = n.sub ? wrapText(n.sub, 11) : [];
    const subBaseY = labelBaseY + labelLines.length * lineH + 3;
    const subEl = subLines.map((line, i) =>
      `<text x="${n.cx.toFixed(1)}" y="${(subBaseY + i * 13).toFixed(1)}" text-anchor="middle"
        fill="${subColor}" font-size="10"
        font-family="IBM Plex Sans,system-ui,sans-serif" pointer-events="none">${line}</text>`
    ).join('');

    const canExpand = isSeg && !n.isExpanded;
    const expandDot = canExpand
      ? `<circle cx="${n.cx.toFixed(1)}" cy="${(n.cy + R - 14).toFixed(1)}" r="3"
          fill="rgba(255,255,255,0.28)" pointer-events="none"/>` : '';

    hexes += `
      <g class="ohive-node" data-node-id="${n.id}" data-node-type="${n.type}"
         ${n.segId ? `data-seg-id="${n.segId}"` : ''} style="cursor:pointer">
        ${youRing}
        <polygon points="${hexPts(n.cx, n.cy)}" fill="${fill}" stroke="${stroke}" stroke-width="${sw}"/>
        ${labelEl}${subEl}${expandDot}
      </g>`;
  });

  // Tooltip is rendered as an HTML div below the SVG, not inside it,
  // so it never overlaps the hive.
  canvas.innerHTML = `
    <div style="position:relative;display:inline-block">
      <svg id="ohiveSvg" width="${svgW}" height="${svgH}" viewBox="0 0 ${svgW} ${svgH}"
        xmlns="http://www.w3.org/2000/svg" style="display:block;overflow:visible">
        <g>${lines}</g>
        <g>${hexes}</g>
      </svg>
      <div id="ohiveTooltip" style="display:none;position:absolute;pointer-events:none;
        z-index:10;background:#111;border:1px solid rgba(255,255,255,0.15);
        font-family:'IBM Plex Sans',system-ui,sans-serif;font-size:12px;color:#e0e0e0;
        padding:14px 16px;line-height:1.6;box-sizing:border-box;width:260px;
        max-height:460px;overflow-y:auto;"></div>
    </div>`;

  // Dismiss tooltip on SVG background click
  canvas.querySelector('#ohiveSvg')?.addEventListener('click', () => hideTooltip());

  canvas.querySelectorAll('.ohive-node').forEach(el => {
    el.addEventListener('click', e => {
      e.stopPropagation();
      handleClick(el.dataset.nodeId, el.dataset.nodeType, e.shiftKey);
    });
  });
}

// ─────────────────────────────────────────────────────────────────
// Text wrap utility
// Splits a string into lines of at most `maxChars` characters,
// breaking on spaces.
// ─────────────────────────────────────────────────────────────────
function wrapText(text, maxChars) {
  if (!text) return [];
  const words = text.split(' ');
  const lines = [];
  let current = '';
  for (const word of words) {
    if (!current) { current = word; continue; }
    if ((current + ' ' + word).length <= maxChars) {
      current += ' ' + word;
    } else {
      lines.push(current);
      current = word;
    }
  }
  if (current) lines.push(current);
  return lines;
}

// ─────────────────────────────────────────────────────────────────
// Interaction
// ─────────────────────────────────────────────────────────────────
function handleClick(id, type, shiftKey = false) {
  if (type === 'root') {
    _expandedSegments.clear();
    _selectedId = null;
    hideTooltip();
    redraw();
    return;
  }

  if (type === 'segment') {
    if (_expandedSegments.has(id)) {
      _expandedSegments.delete(id);
      hideTooltip();
      _selectedId = null;
      redraw();
      return;
    } else {
      if (!shiftKey) _expandedSegments.clear();
      _expandedSegments.add(id);
    }
  }

  _selectedId = id;
  redraw();                   // redraw first so node positions are current
  showTooltip(id, type);
}

// ─────────────────────────────────────────────────────────────────
// Inline SVG tooltip — floats next to the clicked hex, never moves hive
// ─────────────────────────────────────────────────────────────────
const TT_W = 260;   // tooltip width px

function buildTooltipHTML(id, type) {
  if (type === 'segment') {
    const seg = SEGMENTS.find(s => s.id === id);
    if (!seg) return null;
    const rows = seg.functions.map(f =>
      `<div style="display:flex;gap:10px;padding:4px 0;border-bottom:1px solid rgba(255,255,255,0.07)">
        <span style="color:#78a9ff;font-weight:600;min-width:46px">${f.abbr}</span>
        <span style="color:#a8a8a8">${f.label}</span>
       </div>`
    ).join('');
    return `<div style="color:#fff;font-size:13px;font-weight:600;margin-bottom:4px">${seg.label}</div>
      <div style="color:#78a9ff;font-size:11px;margin-bottom:8px">${seg.sub}</div>
      <div style="color:#c6c6c6;font-size:11px;line-height:1.5;margin-bottom:10px">${seg.desc}</div>
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#525252;margin-bottom:6px">Roles</div>
      ${rows}`;
  }

  if (type === 'function') {
    const seg = SEGMENTS.find(s => s.functions.some(f => f.id === id));
    const fn  = seg?.functions.find(f => f.id === id);
    if (!fn) return null;
    const ww = fn.worksWith?.map(w =>
      `<span style="display:inline-block;padding:2px 8px;border:1px solid rgba(255,255,255,0.18);
        color:#a8a8a8;font-size:10px;margin:2px">${w}</span>`
    ).join('') || '—';
    return `<div style="color:#fff;font-size:14px;font-weight:600;margin-bottom:2px">${fn.abbr}</div>
      <div style="color:#78a9ff;font-size:11px;margin-bottom:8px">${fn.label}</div>
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#525252;margin-bottom:4px">What they do</div>
      <div style="color:#c6c6c6;font-size:11px;line-height:1.55;margin-bottom:10px">${fn.purpose}</div>
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#525252;margin-bottom:6px">Works with</div>
      <div style="margin-bottom:10px">${ww}</div>
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#525252;margin-bottom:4px">Owns accounts?</div>
      <div style="color:${fn.ownsAccounts ? '#78a9ff' : '#6f6f6f'};font-size:11px;margin-bottom:10px">${fn.ownsAccounts ? 'Yes — carries quota' : 'No — supports quota'}</div>
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#525252;margin-bottom:4px">Sales motion</div>
      <div style="color:#a8a8a8;font-size:11px;font-style:italic;margin-bottom:${fn.products ? '10px' : '0'}">${fn.salesMotion}</div>
      ${fn.products ? `<div style="font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#525252;margin-bottom:4px">Products</div>
        <div style="color:#c6c6c6;font-size:11px">${fn.products}</div>` : ''}`;
  }
  return null;
}

function showTooltip(id, type) {
  // Find node position from the re-rendered SVG
  const nodeEl = document.querySelector(`.ohive-node[data-node-id="${id}"]`);
  if (!nodeEl) return;

  const ttGroup  = document.getElementById('ohiveTooltip');
  const ttBg     = document.getElementById('ohiveTooltipBg');
  const ttFO     = document.getElementById('ohiveTooltipFO');
  const ttDiv    = document.getElementById('ohiveTooltipContent');
  if (!ttGroup || !ttBg || !ttFO || !ttDiv) return;

  const html = buildTooltipHTML(id, type);
  if (!html) return;

  ttDiv.innerHTML = html;

  // Measure height after content injection
  const estLines = (html.match(/<div/g) || []).length;
  const ttH = Math.min(Math.max(estLines * 22 + 28, 120), 460);

  // Get SVG node position from its polygon points to find center
  const poly = nodeEl.querySelector('polygon');
  const pts  = poly?.getAttribute('points')?.split(' ').map(p => p.split(',').map(Number));
  if (!pts?.length) return;
  const ncx = pts.reduce((s, p) => s + p[0], 0) / pts.length;
  const ncy = pts.reduce((s, p) => s + p[1], 0) / pts.length;

  // Get the SVG dimensions to keep tooltip inside
  const svg = document.getElementById('ohiveSvg');
  const svgW = parseFloat(svg?.getAttribute('width') || '1200');

  // Place tooltip to the right of the hex, flip left if near right edge
  let tx = ncx + R + 16;
  if (tx + TT_W > svgW - 20) tx = ncx - R - TT_W - 16;
  const ty = ncy - ttH / 2;

  ttBg.setAttribute('x', tx);
  ttBg.setAttribute('y', ty);
  ttBg.setAttribute('width', TT_W);
  ttBg.setAttribute('height', ttH);

  ttFO.setAttribute('x', tx);
  ttFO.setAttribute('y', ty);
  ttFO.setAttribute('width', TT_W);
  ttFO.setAttribute('height', ttH);

  ttGroup.style.display = '';
}

function hideTooltip() {
  const tt = document.getElementById('ohiveTooltip');
  if (tt) tt.style.display = 'none';
  _selectedId = null;
  redraw();
}

