/* ═══════════════════════════════════════════════════════════════
   MY TEAM PAGE — seller.js
   ═══════════════════════════════════════════════════════════════ */

.mt-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  background: #000;
}

/* Header: title + meta info */
.mt-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 32px;
  padding: 28px 36px 24px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
  flex-wrap: wrap;
}
.mt-header-left { flex-shrink: 0; }
.mt-title {
  font-size: 22px;
  font-weight: 300;
  color: #f4f4f4;
  letter-spacing: -0.2px;
  margin-bottom: 4px;
}
.mt-subtitle { font-size: 13px; color: #525252; }

.mt-header-meta {
  display: flex;
  gap: 40px;
  flex-wrap: wrap;
  align-items: flex-start;
}
.mt-meta-block { display: flex; flex-direction: column; gap: 6px; }
.mt-meta-label {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.8px;
  color: #525252;
}
.mt-meta-tags { display: flex; gap: 6px; flex-wrap: wrap; }
.mt-tag {
  font-size: 11px;
  padding: 2px 10px;
  border: 1px solid rgba(255,255,255,0.12);
  color: #a8a8a8;
  background: rgba(255,255,255,0.03);
  letter-spacing: 0.16px;
}
.mt-meta-value { font-size: 12px; color: #8d8d8d; }

/* Diagram area */
.mt-diagram {
  padding: 40px 36px 32px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  flex: 1;
}
.mt-diagram-inner { overflow-x: auto; }

/* Legend */
.mt-legend {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}
.mt-leg {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: #525252;
}
.mt-leg-line {
  display: inline-block;
  width: 28px;
  height: 2px;
  flex-shrink: 0;
}
.mt-leg-pair   { background: #4589ff; opacity: 0.7; }
.mt-leg-report { background: rgba(255,255,255,0.18); }
.mt-leg-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
}

