  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cell-hex-label.you { color: #4d7bff; font-weight: 500; }

/* ── CONNECTIONS NETWORK ─────────────────────────────────────── */
.connections-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  padding: 24px;
  gap: 20px;
}

