279 | // ─────────────────────────────────────────────────────────────────
280 | // Layout builder
281 | // ─────────────────────────────────────────────────────────────────
282 | const COLS_PER_ROW = 4;
283 | 
284 | function buildLayout() {
285 |   const nodes = [];
286 |   const pos   = {};
287 | 
288 |   const PAD_X = R + 40;
289 |   const PAD_Y = R + 48;
290 | 
291 |   const segCount  = SEGMENTS.length;
292 |   const segTotalW = segCount * (CS + GAP) - GAP;
293 | 
294 |   // Cluster widths for expanded segments
295 |   const clusterWidths = {};
296 |   SEGMENTS.forEach(seg => {
297 |     if (!_expandedSegments.has(seg.id)) return;
298 |     const n    = seg.functions.length;
299 |     const cols = Math.min(n, COLS_PER_ROW);
300 |     clusterWidths[seg.id] = cols * (CS + GAP) - GAP;
301 |   });
302 | 
303 |   const maxW  = Math.max(segTotalW, ...Object.values(clusterWidths), 0);
304 |   const svgW  = maxW + PAD_X * 2;
305 |   const svgCX = svgW / 2;
306 | 
307 |   // Root
308 |   let curY = PAD_Y + R;
309 |   nodes.push({
310 |     id: 'root', label: 'IBM', sub: 'Sales',
311 |     type: 'root', cx: svgCX, cy: curY,
312 |     isSelected: _selectedId === 'root',
313 |     youAreHere: false, data: null,
314 |   });
315 |   pos['root'] = { cx: svgCX, cy: curY };
316 |   curY += RS + GAP + 24;
317 | 
318 |   // Segments
319 |   const segStartX = svgCX - segTotalW / 2 + CS / 2;
320 |   SEGMENTS.forEach((seg, si) => {
321 |     const cx = segStartX + si * (CS + GAP);
322 |     const cy = curY;
323 |     nodes.push({
324 |       id: seg.id, label: seg.label, sub: seg.sub,
325 |       type: 'segment', cx, cy,
326 |       isSelected: _selectedId === seg.id,
327 |       youAreHere: seg.youAreHere || false,
328 |       isExpanded: _expandedSegments.has(seg.id),
329 |       data: seg,
330 |     });
331 |     pos[seg.id] = { cx, cy };
332 |   });
333 |   curY += RS + GAP + 24;
334 | 
335 |   // Role clusters (no lines — grouping communicated by proximity)
336 |   SEGMENTS.forEach(seg => {
