338 | 
339 |     const fns  = seg.functions;
340 |     const cols = Math.min(fns.length, COLS_PER_ROW);
341 |     const rows = Math.ceil(fns.length / cols);
342 |     const clusterW    = cols * (CS + GAP) - GAP;
343 |     const clusterStartX = svgCX - clusterW / 2 + CS / 2;
344 | 
345 |     fns.forEach((fn, fi) => {
346 |       const col     = fi % cols;
347 |       const row     = Math.floor(fi / cols);
348 |       const offsetX = (row % 2 === 1) ? (CS + GAP) / 2 : 0;
349 |       const cx      = clusterStartX + col * (CS + GAP) + offsetX;
350 |       const cy      = curY + row * (RS + GAP);
351 | 
352 |       nodes.push({
353 |         id: fn.id, label: fn.abbr, sub: fn.label,
354 |         type: 'function', cx, cy,
355 |         isSelected: _selectedId === fn.id,
356 |         youAreHere: fn.youAreHere || false,
