434 |     const isRel  = related.has(n.id);
435 |     const isYou  = n.youAreHere;
436 | 
437 |     // Dimming: if there's a selection and this node is neither selected nor related
438 |     // (but never dim root or segment headers)
439 |     const isDimmed = hasSelection && !isSel && !isRel && isFn;
440 | 
441 |     // Stroke: selected = IBM blue, you-are-here = IBM blue (same — keep white text only)
442 |     // related = brighter white outline
443 |     const stroke = isSel
444 |       ? '#4589ff'
445 |       : isRel
446 |         ? 'rgba(255,255,255,0.80)'
447 |         : isYou
448 |           ? '#4589ff'
449 |           : 'rgba(255,255,255,0.45)';
450 |     const sw = isSel || isYou ? 2.5 : isRel ? 2 : 1.5;
451 | 
452 |     // Fill: gray. Dimmed nodes get darker.
