  nodes.push({
    id: 'root', label: 'IBM', sub: 'Sales',
    type: 'root', cx: svgCX, cy: curY,
    isSelected: _selectedId === 'root',
    youAreHere: false, data: null,
  });
  pos['root'] = { cx: svgCX, cy: curY };
  curY += RS + GAP + 24;

