.hmap-detail-close {
  position: absolute;
  top: 10px; right: 12px;
  background: none;
  border: none;
  color: var(--muted);
  font-size: 15px;
  cursor: pointer;
  padding: 4px 6px;
  transition: color 0.1s;
  z-index: 1;
}
.hmap-detail-close:hover { color: #fff; }

/* Detail panel body */
#hmapDetailBody { padding: 18px; }

.hdp-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding-right: 24px;
}
.hdp-hex {
  width: 40px; height: 46px;
  clip-path: polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%);
  flex-shrink: 0;
  border: 2px solid;
}
.hdp-circle {
  width: 40px; height: 40px;
  border-radius: 50%;
  flex-shrink: 0;
  border: 2px solid;
}
.hdp-name {
  font-size: 16px;
  font-weight: 400;
  color: var(--text);
  line-height: 1.3;
}
.hdp-role { font-size: 12px; color: var(--muted); margin-top: 3px; }

.hdp-sections {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.hdp-section { display: flex; flex-direction: column; gap: 3px; }
.hdp-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  font-weight: 600;
}
.hdp-val {
  font-size: 13px;
  color: var(--text);
  line-height: 1.5;
}
.hdp-link { color: var(--ibm-blue-40); text-decoration: none; font-size: 13px; }
.hdp-link:hover { text-decoration: underline; }
.hdp-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 2px; }
.hdp-tag {
  font-size: 11px;
  padding: 2px 8px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
