  font-size: 12px;
  padding: 3px 9px;
  background: rgba(69,137,255,0.12);
  border: 1px solid rgba(69,137,255,0.3);
  color: var(--ibm-blue-40);
  cursor: pointer;
  transition: background 0.1s;
  border-radius: 0;
}
.org-chip:hover { background: rgba(69,137,255,0.22); }
.org-chip-x { font-size: 14px; line-height: 1; color: rgba(120,169,255,0.6); }
.org-chip-clear {
  background: transparent;
  border-color: rgba(255,255,255,0.15);
  color: var(--muted);
  margin-left: 4px;
}
.org-chip-clear:hover { color: #fff; border-color: rgba(255,255,255,0.35); background: rgba(255,255,255,0.05); }

/* ── Body: grid + detail panel ── */
.org-body {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.org-grid-wrap {
  flex: 1;
  overflow-y: auto;
  padding: 20px 24px;
  min-height: 0;
}

/* ── Summary bar + legend ── */
.org-summary {
  display: flex;
  align-items: center;
  gap: 20px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}
.org-summary-count {
  font-size: 13px;
  color: var(--muted);
}
.org-legend {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.org-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--muted);
}
.org-legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  flex-shrink: 0;
}

/* ── Section (colony / market / cell grouping) ── */
.org-section {
  margin-bottom: 28px;
}
.org-section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-subtle);
}
.org-section-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.org-section-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.16px;
}
.org-section-sub {
  font-size: 12px;
  color: var(--muted);
}
.org-section-you-badge {
  font-size: 10px;
  padding: 2px 7px;
  background: rgba(69,137,255,0.14);
  color: var(--ibm-blue-40);
  font-weight: 600;
  letter-spacing: 0.32px;
  margin-left: auto;
}

/* ── Node grid ── */
.org-node-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1px;
  background: var(--border-subtle);
}

/* ── Person node card ── */
.org-node {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: var(--surface);
  cursor: pointer;
  transition: background 0.1s;
  border-left: 3px solid transparent;
  outline: none;
  position: relative;
}
.org-node:hover { background: var(--surface-2); }
.org-node:focus-visible { outline: 2px solid var(--ibm-blue-50); outline-offset: -2px; }

/* Relationship-based left border */
.org-node-me          { border-left-color: var(--ibm-blue-50); background: rgba(13,31,76,0.5); }
.org-node-chain       { border-left-color: #6c63ff; background: rgba(30,26,60,0.4); }
.org-node-team        { border-left-color: #0ea5e9; background: rgba(14,32,48,0.4); }
.org-node-colleague   { border-left-color: transparent; }
.org-node-me:hover    { background: rgba(13,31,76,0.7); }
.org-node-chain:hover { background: rgba(30,26,60,0.6); }
.org-node-team:hover  { background: rgba(14,32,48,0.6); }

.org-node-selected {
  outline: 2px solid var(--ibm-blue-40) !important;
  outline-offset: -2px;
}

/* Hex avatar dot */
.org-node-hex {
  width: 36px;
  height: 40px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  flex-shrink: 0;
  position: relative;
  border: 1px solid transparent;
}
.org-node-hex-inner {
  position: absolute;
  inset: 0;
}

/* Node text content */
.org-node-body { flex: 1; min-width: 0; }
.org-node-name {
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: 0.16px;
}
.org-node-role {
  font-size: 12px;
  color: var(--text-secondary);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.org-node-meta {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 5px;
}
.org-node-badge {
  font-size: 10px;
  padding: 1px 6px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--muted);
  letter-spacing: 0.16px;
  white-space: nowrap;
}
.org-node-badge-chain {
  background: rgba(108,99,255,0.12);
  border-color: rgba(108,99,255,0.3);
  color: #a89fff;
}
.org-node-badge-team {
  background: rgba(14,165,233,0.12);
  border-color: rgba(14,165,233,0.3);
  color: #7dd3fc;
}

/* Arrow chevron */
.org-node-arrow {
  font-size: 16px;
  color: #444;
  flex-shrink: 0;
  transition: color 0.1s, transform 0.1s;
}
.org-node:hover .org-node-arrow { color: var(--text-secondary); transform: translateX(2px); }

/* "You" tag inline */
.org-you-tag {
  font-size: 10px;
  padding: 1px 6px;
  background: rgba(69,137,255,0.15);
  color: var(--ibm-blue-40);
  font-weight: 600;
  letter-spacing: 0.32px;
  margin-left: 5px;
  vertical-align: middle;
  white-space: nowrap;
}

/* Empty state */
.org-empty {
  padding: 40px 24px;
  color: var(--muted);
  font-size: 14px;
  text-align: center;
}
.org-empty a { color: var(--ibm-blue-40); }

/* ── Right-side detail panel ── */
.org-detail {
  width: 320px;
  flex-shrink: 0;
  background: #111;
  border-left: 1px solid var(--border-subtle);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  position: relative;
}
.org-detail-close {
  position: absolute;
  top: 12px;
  right: 14px;
  font-size: 16px;
  cursor: pointer;
  color: var(--muted);
  padding: 3px 6px;
  transition: color 0.1s;
  z-index: 1;
}
.org-detail-close:hover { color: var(--text); }
.org-detail-inner {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Detail panel header */
.odp-header {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding-bottom: 16px;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--border-subtle);
}
.odp-hex {
  width: 44px;
  height: 50px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  flex-shrink: 0;
  border: 2px solid transparent;
}
.odp-title { flex: 1; min-width: 0; padding-right: 24px; }
.odp-name {
  font-size: 17px;
  font-weight: 400;
  color: var(--text);
  letter-spacing: 0;
  line-height: 1.3;
}
.odp-role {
  font-size: 13px;
  color: var(--text-secondary);
  margin-top: 3px;
}
.odp-rel {
  font-size: 11px;
  padding: 2px 8px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--muted);
  display: inline-block;
  margin-top: 6px;
  letter-spacing: 0.16px;
}

/* Detail panel sections */
.odp-sections { display: flex; flex-direction: column; gap: 16px; }
.odp-section { display: flex; flex-direction: column; gap: 6px; }
.odp-section-title {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
  font-weight: 600;
  padding-bottom: 5px;
  border-bottom: 1px solid var(--border-subtle);
  margin-bottom: 2px;
}
.odp-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 13px;
}
.odp-label {
  color: var(--muted);
  min-width: 88px;
  font-size: 12px;
  flex-shrink: 0;
  padding-top: 1px;
}
.odp-value {
  color: var(--text);
  flex: 1;
  min-width: 0;
  word-break: break-word;
}
.odp-link {
  color: var(--ibm-blue-40);
  text-decoration: none;
  font-size: 13px;
}
.odp-link:hover { text-decoration: underline; }

/* Tags in detail panel */
.odp-tags { display: flex; flex-wrap: wrap; gap: 5px; }
.odp-tag {
  font-size: 11px;
  padding: 3px 9px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--text-secondary);
  letter-spacing: 0.16px;
}

/* Action buttons */
.odp-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--border-subtle);
}
.odp-btn-primary {
  padding: 9px 16px;
  background: var(--ibm-blue-60);
  color: #fff;
  border: none;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  letter-spacing: 0.16px;
  transition: background 0.1s;
  border-radius: 0;
  text-align: left;
}
.odp-btn-primary:hover { background: var(--ibm-blue-70); }
.odp-btn-secondary {
  padding: 9px 16px;
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  letter-spacing: 0.16px;
  transition: background 0.1s, color 0.1s;
  border-radius: 0;
  text-align: left;
}
.odp-btn-secondary:hover { background: var(--surface-2); color: var(--text); }


/* ═══════════════════════════════════════════════════════════════
   MY TEAM PAGE — seller.js
   ═══════════════════════════════════════════════════════════════ */

.mt-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  background: #000;
}

/* Header: title + meta info */
.mt-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 32px;
  padding: 28px 36px 24px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
  flex-wrap: wrap;
}
.mt-header-left { flex-shrink: 0; }
.mt-title {
  font-size: 22px;
  font-weight: 300;
  color: #f4f4f4;
  letter-spacing: -0.2px;
  margin-bottom: 4px;
}
.mt-subtitle { font-size: 13px; color: #525252; }

.mt-header-meta {
  display: flex;
  gap: 40px;
  flex-wrap: wrap;
  align-items: flex-start;
}
.mt-meta-block { display: flex; flex-direction: column; gap: 6px; }
.mt-meta-label {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.8px;
  color: #525252;
}
.mt-meta-tags { display: flex; gap: 6px; flex-wrap: wrap; }
.mt-tag {
  font-size: 11px;
  padding: 2px 10px;
  border: 1px solid rgba(255,255,255,0.12);
  color: #a8a8a8;
  background: rgba(255,255,255,0.03);
  letter-spacing: 0.16px;
}
.mt-meta-value { font-size: 12px; color: #8d8d8d; }

/* Diagram area */
.mt-diagram {
  padding: 40px 36px 32px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  flex: 1;
}
.mt-diagram-inner { overflow-x: auto; }

/* Legend */
.mt-legend {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
}
.mt-leg {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: #525252;
}
.mt-leg-line {
  display: inline-block;
  width: 28px;
  height: 2px;
  flex-shrink: 0;
}
.mt-leg-pair   { background: #4589ff; opacity: 0.7; }
.mt-leg-report { background: rgba(255,255,255,0.18); }
.mt-leg-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
}


/* ═══════════════════════════════════════════════════════════════
   ORGANIZATION TAB — org.js (ohive)
   Two-column: scrollable hive left, permanent detail panel right
   ═══════════════════════════════════════════════════════════════ */

/* Outer layout: hive area + detail panel side by side */
.ohive-layout {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  background: #000;
}

/* Left: scrollable hive canvas */
.ohive-hive-area {
  flex: 1;
  min-width: 0;
  overflow: auto;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 32px 80px;
}

.ohive-canvas {
  display: inline-block;
}

/* Right: permanent detail panel */
.ohive-detail-panel {
  width: 300px;
  flex-shrink: 0;
  background: #0d0d0d;
  border-left: 1px solid rgba(255,255,255,0.07);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

/* Empty state */
.ohive-detail-empty {
  flex: 1;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 32px 24px;
}
.ohive-detail-hint {
  font-size: 12px;
  color: #3a3a3a;
  text-align: center;
  line-height: 1.6;
}
.ohive-detail-welcome {
  padding: 8px 0;
}
.ohive-detail-welcome-title {
  font-size: 15px;
  font-weight: 500;
  color: #f4f4f4;
  margin-bottom: 12px;
  letter-spacing: 0.16px;
}
.ohive-detail-welcome-body {
  font-size: 12px;
  color: #6f6f6f;
  line-height: 1.7;
  margin-bottom: 16px;
}
.ohive-detail-welcome-tip {
  font-size: 11px;
  color: #a855f7;
  opacity: 0.7;
}

/* Detail content */
.odp-content {
  padding: 24px 20px 40px;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.odp-type-badge {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.8px;
  color: #525252;
  margin-bottom: 8px;
}
.odp-title {
  font-size: 20px;
  font-weight: 300;
  color: #f4f4f4;
  letter-spacing: -0.2px;
  margin-bottom: 4px;
  line-height: 1.2;
}
.odp-sub {
  font-size: 12px;
  color: #525252;
  margin-bottom: 16px;
}
.odp-you-badge {
  display: inline-block;
  font-size: 10px;
  padding: 2px 8px;
  background: rgba(69,137,255,0.12);
  color: #4589ff;
  font-weight: 500;
  letter-spacing: 0.32px;
  margin-bottom: 12px;
}
.odp-desc {
  font-size: 13px;
  color: #a8a8a8;
  line-height: 1.65;
  margin-bottom: 20px;
  border-top: 1px solid rgba(255,255,255,0.06);
  padding-top: 16px;
}
.odp-section-title {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.8px;
  color: #525252;
  margin-bottom: 8px;
}
.odp-role-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 20px;
}
.odp-role-row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 5px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}
.odp-role-abbr {
  font-size: 12px;
  font-weight: 600;
  color: #78a9ff;
  min-width: 44px;
  flex-shrink: 0;
}
.odp-role-label { font-size: 12px; color: #8d8d8d; }
.odp-hint {
  font-size: 11px;
  color: #3a3a3a;
  font-style: italic;
  margin-top: 8px;
}
.odp-works-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-bottom: 6px;
}
.odp-works-tag {
  font-size: 11px;
  padding: 3px 9px;
  border: 1px solid rgba(255,255,255,0.15);
  color: #c6c6c6;
  letter-spacing: 0.16px;
}
.odp-works-hint {
  font-size: 11px;
  color: #3a3a3a;
  font-style: italic;
  margin-bottom: 16px;
}
.odp-field {
  margin-bottom: 14px;
  border-top: 1px solid rgba(255,255,255,0.05);
  padding-top: 12px;
}
.odp-field-label {
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.8px;
  color: #525252;
  margin-bottom: 4px;
}
.odp-field-value {
  font-size: 12px;
  color: #a8a8a8;
  line-height: 1.55;
}

/* Hex hover brightening */
.ohive-node polygon {
  transition: filter 0.12s;
}
.ohive-node:hover polygon { filter: brightness(1.35); }

/* ═══════════════════════════════════════════════════════════════
   HIVE MAP — legacy styles (kept for other refs)
   ═══════════════════════════════════════════════════════════════ */

.hmap-shell {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: #080808;
  overflow: hidden;
}

/* ── Top bar: breadcrumb + you-here + zoom controls ── */
.hmap-topbar {
  display: flex;
  align-items: center;
  gap: 0;
  height: 48px;
  flex-shrink: 0;
  background: #0a0a0a;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding: 0 16px;
}

.hmap-breadcrumb {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
}
.bc-root  { color: #525252; }
.bc-link  { color: var(--text-secondary); cursor: pointer; transition: color 0.1s; }
.bc-link:hover { color: #fff; }
.bc-sep   { color: #333; font-size: 11px; }
.bc-you   { color: var(--ibm-blue-40); font-weight: 500; }

.hmap-you-here {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  padding: 0 16px;
  border-left: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
}
.yah-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ibm-blue-50);
  flex-shrink: 0;
  box-shadow: 0 0 6px var(--ibm-blue-50);
}
.yah-text { color: var(--text-secondary); }
.yah-text strong { color: var(--text); font-weight: 500; }

.hmap-zoom-btns {
  display: flex;
  align-items: center;
  gap: 4px;
  padding-left: 12px;
  border-left: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
}
.hmap-zbtn {
  width: 30px; height: 30px;
  border: 1px solid rgba(255,255,255,0.12);
  background: transparent;
  color: var(--text-secondary);
  font-size: 16px;
  font-family: inherit;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
}
.hmap-zbtn:hover { background: var(--surface-2); color: #fff; }
.hmap-zbtn-fit { font-size: 11px; width: auto; padding: 0 10px; }

/* ── Stage (the actual map canvas area) ── */
.hmap-stage {
  flex: 1;
  position: relative;
  overflow: hidden;
  cursor: default;
  min-height: 0;
  background: radial-gradient(ellipse at center, #0e0e0e 0%, #050505 100%);
}

.hmap-svg {
  position: absolute;
  top: 0;
  left: 0;
  transform-origin: 0 0;
  will-change: transform;
  overflow: visible;
}

/* ── Right detail panel ── */
.hmap-detail {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: 300px;
  background: #111;
  border-left: 1px solid rgba(255,255,255,0.08);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  z-index: 10;
  box-shadow: -8px 0 32px rgba(0,0,0,0.5);
}
.hmap-detail-close {
  position: absolute;
  top: 10px; right: 12px;
  background: none;
  border: none;
  color: var(--muted);
  font-size: 15px;
  cursor: pointer;
  padding: 4px 6px;
  transition: color 0.1s;
  z-index: 1;
}
.hmap-detail-close:hover { color: #fff; }

/* Detail panel body */
#hmapDetailBody { padding: 18px; }

.hdp-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding-right: 24px;
}
.hdp-hex {
  width: 40px; height: 46px;
  clip-path: polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%);
  flex-shrink: 0;
  border: 2px solid;
}
.hdp-circle {
  width: 40px; height: 40px;
  border-radius: 50%;
  flex-shrink: 0;
