}
.hive-subtitle {
  font-size: 11px;
  color: #3a3a3a;
}
.hive-toolbar-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ── RESOURCES EMPTY STATE ───────────────────────────────────── */
.resources-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
