}
.org-modal-desc {
  font-size: 13px;
  line-height: 1.65;
  color: #c6c6c6;
}
.org-modal-section-title {
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.64px;
  color: #525252;
