Contents of file frontend/js/views/seller.js:

1 | /**
2 |  * seller.js — My Team view
3 |  *
4 |  * Answers one question: "Who do I work with and how does our team operate?"
5 |  *
6 |  * Team: Infrastructure · Select Territory
7 |  *   BTSS Manager: Chris Kennedy
8 |  *   BTSS: Sydney Chin (you), Mark Hoffman, Armada Veraepalli
9 |  *   TSS Manager: Rob Hanes
10 |  *   TSS: Ross Holley, Patrick McBride
11 |  *   Pairs: Mark ↔ Ross  |  Armada ↔ Patrick
12 |  *   Sydney: unassigned / intern (no formal TSS pair shown)
13 |  */
14 | import { getPeople } from '../api.js';
15 | import { openPerson } from '../panel.js';
16 | 
17 | // ── Static team config ────────────────────────────────────────────
18 | const PRODUCTS = ['IBM PowerVS', 'IBM FlashSystem', 'IBM Fusion', 'IBM z16', 'IBM LinuxONE'];
19 | const COVERAGE = 'Select Territory · National · C&D (Channels & Distribution)';
20 | 
21 | const TEAM_DETAIL = {
22 |   // role-level extra info keyed by "First Last"
23 |   'Sydney Chin':        { role: 'Brand Technical Sales Specialist', manager: 'Chris Kennedy', pair: null,             products: ['PowerVS','FlashSystem','Fusion'], territory: 'C&D', responsibilities: 'Technical sales, demos, POCs, solution validation' },
24 |   'Mark Hoffman':       { role: 'Brand Technical Sales Specialist', manager: 'Chris Kennedy', pair: 'Ross Holley',    products: ['PowerVS','FlashSystem'],          territory: 'C&D', responsibilities: 'Technical sales, demos, POCs, solution validation' },
25 |   'Armada Veraepalli':  { role: 'Brand Technical Sales Specialist', manager: 'Chris Kennedy', pair: 'Patrick McBride',products: ['Fusion','z16'],                   territory: 'C&D', responsibilities: 'Technical sales, demos, POCs, solution validation' },
26 |   'Ross Holley':        { role: 'Territory Sales Specialist',       manager: 'Rob Hanes',     pair: 'Mark Hoffman',  products: null,                               territory: 'National', responsibilities: 'Territory pipeline, prospecting, commercial close' },
27 |   'Patrick McBride':    { role: 'Territory Sales Specialist',       manager: 'Rob Hanes',     pair: 'Armada Veraepalli', products: null,                            territory: 'National', responsibilities: 'Territory pipeline, prospecting, commercial close' },
28 |   'Chris Kennedy':      { role: 'BTSS Manager',                     manager: null,             pair: null,             products: null,                               territory: 'National', responsibilities: 'Team leadership, BTSS alignment, escalation support' },
29 |   'Rob Hanes':          { role: 'TSS Manager',                      manager: null,             pair: null,             products: null,                               territory: 'National', responsibilities: 'Team leadership, TSS quota ownership, territory strategy' },
30 | };
31 | 
32 | export async function renderSeller(container) {
33 |   const allPeople = await getPeople();
34 | 
35 |   const find = (fn, ln) => allPeople.find(p => p.first_name === fn && p.last_name === ln);
36 |   const chrisK   = find('Chris',   'Kennedy');
37 |   const robH     = find('Rob',     'Hanes');
38 |   const sydneyC  = allPeople.find(p => p.is_current_user) || find('Sydney', 'Chin');
39 |   const markH    = find('Mark',    'Hoffman');
40 |   const armada   = find('Armada',  'Veraepalli');
41 |   const rossH    = find('Ross',    'Holley');
42 |   const patrickM = find('Patrick', 'McBride');
43 | 
44 |   // ── SVG layout ──────────────────────────────────────────────────
45 |   // Three rows (top to bottom):
46 |   //   Row A: Managers  — Chris Kennedy (left), Rob Hanes (right)
47 |   //   Row B: BTSS members (left column): Sydney, Mark, Armada
48 |   //   Row C: TSS members (right column): Ross, Patrick  (vertically aligned with their pair)
49 |   //
50 |   // Pairing lines connect Mark↔Ross and Armada↔Patrick horizontally.
51 |   // Manager reporting lines connect downward from managers to their teams.
52 | 
53 |   const NW = 148, NH = 60;   // node width / height
54 |   const MGRCOL_L = 80;       // left column X (BTSS / Chris)
55 |   const MGRCOL_R = 420;      // right column X (TSS / Rob)
56 |   const MGR_Y    = 60;       // managers row Y
57 |   const MBR_Y    = 196;      // members start Y
58 |   const V_STEP   = 88;       // vertical step between members
59 |   const SVG_W    = MGRCOL_R + NW + 80;
60 |   const BTSSx    = MGRCOL_L;
61 |   const TSSx     = MGRCOL_R;
62 | 
63 |   // Y positions for pairs (Mark↔Ross at same Y, Armada↔Patrick at same Y)
64 |   const yMark   = MBR_Y;
65 |   const yArmada = MBR_Y + V_STEP;
66 |   const ySydney = MBR_Y + V_STEP * 2;
67 | 
68 |   const yRoss    = yMark;
69 |   const yPatrick = yArmada;
70 | 
71 |   const SVG_H = ySydney + NH + 80;
72 | 
73 |   let svgLines = '';
74 |   let svgNodes = '';
75 | 
76 |   const midX = (BTSSx + NW + TSSx) / 2;  // midpoint between the two columns
77 | 
78 |   // ── Vertical divider ────────────────────────────────────────────
79 |   svgLines += `<line x1="${midX}" y1="${MGR_Y}" x2="${midX}" y2="${SVG_H - 40}"
80 |     stroke="rgba(255,255,255,0.05)" stroke-width="1" stroke-dasharray="4,6"/>`;
81 | 
82 |   // ── Manager → member reporting lines (soft dashed, vertical) ────
83 |   const mgrReportLine = (mx, my, memberYs) => memberYs.map(my2 =>
84 |     `<line x1="${mx + NW/2}" y1="${my + NH}" x2="${mx + NW/2}" y2="${my2}"
85 |       stroke="rgba(255,255,255,0.12)" stroke-width="1" stroke-dasharray="4,4"/>`
86 |   ).join('');
87 | 
88 |   svgLines += mgrReportLine(BTSSx, MGR_Y, [yMark, yArmada, ySydney]);
89 |   svgLines += mgrReportLine(TSSx,  MGR_Y, [yRoss, yPatrick]);
90 | 
91 |   // ── Pairing lines ────────────────────────────────────────────────
92 |   const pairLine = (y1, y2) => {
93 |     const x1 = BTSSx + NW, x2 = TSSx;
