+  const relationship    = document.getElementById('dpRelationship')?.value || '';
+  const whyKnow         = document.getElementById('dpWhyKnow')?.value.trim() || '';
+  const lastInteraction = document.getElementById('dpLastInteraction')?.value || '';
+  const followUp        = document.getElementById('dpFollowUp')?.value || '';
+  const notes           = document.getElementById('dpNotes')?.value.trim() || '';
+
+  _store.details[String(pid)] = { expertise, relationship, whyKnow, lastInteraction, followUp, notes };
+  saveStore(_store);
+
+  // Flash save confirmation
+  const btn = document.getElementById('nwDpSave');
+  if (btn) { btn.textContent = 'Saved'; setTimeout(() => { if (btn) btn.textContent = 'Save'; }, 1400); }
+
+  // Re-render cards so expertise tags update
+  renderCenter();
+}
+
+// ── Group CRUD ────────────────────────────────────────────────────
+function createGroup() {
+  const name = prompt('Group name:');
+  if (!name?.trim()) return;
+  const g = { id: uid(), name: name.trim() };
+  _store.groups.push(g);
+  _store.members[g.id] = [];
+  saveStore(_store);
+  _selectedGid = g.id;
+  _selectedPid = null;
+  render();
+}
+
+function renameGroup(gid) {
+  const g = _store.groups.find(x => x.id === gid);
+  if (!g) return;
+  const name = prompt('New name:', g.name);
+  if (!name?.trim()) return;
+  g.name = name.trim();
+  saveStore(_store);
+  render();
+}
+
+function deleteGroup(gid) {
+  if (!confirm('Delete this group? People are not removed from IBM Hive.')) return;
+  _store.groups = _store.groups.filter(g => g.id !== gid);
+  delete _store.members[gid];
+  saveStore(_store);
+  if (_selectedGid === gid) {
+    _selectedGid = _store.groups[0]?.id || null;
+    _selectedPid = null;
+  }
+  render();
+}
+
+// ── Add / remove person ───────────────────────────────────────────
+function openAddPerson() {
+  const panel = document.getElementById('nwDetail');
+  if (!panel) return;
+
+  const group    = _store.groups.find(g => g.id === _selectedGid);
+  if (!group) return;
+  const existIds = new Set((_store.members[_selectedGid] || []).map(String));
+  const available = _allPeople.filter(p => !existIds.has(String(p.id)));
+
+  panel.innerHTML = `
+    <div class="nw-dp-content">
+      <div class="nw-dp-add-title">Add to "${escHtml(group.name)}"</div>
+      <input class="nw-dp-input" id="nwAddSearch" type="text" placeholder="Search by name or role…" style="margin-bottom:12px"/>
+      <div class="nw-add-list" id="nwAddList"></div>
+      <button class="nw-dp-close-btn" id="nwAddCancel">Cancel</button>
+    </div>`;
+
+  const listEl = document.getElementById('nwAddList');
+  const searchEl = document.getElementById('nwAddSearch');
+
+  function renderAddList(q) {
+    const results = available.filter(p => {
+      const name = `${p.first_name} ${p.last_name}`.toLowerCase();
+      return !q || name.includes(q.toLowerCase()) || (p.role || '').toLowerCase().includes(q.toLowerCase());
+    });
+    listEl.innerHTML = results.slice(0, 20).map(p => `
+      <div class="nw-add-item" data-pid="${p.id}">
+        <div class="nw-add-initials" style="background:${p.color || '#2a2a2a'}">${p.first_name?.[0] || ''}${p.last_name?.[0] || ''}</div>
+        <div class="nw-add-info">
+          <div class="nw-add-name">${escHtml(p.first_name + ' ' + p.last_name)}</div>
+          <div class="nw-add-role">${escHtml(p.role || '—')}</div>
+        </div>
+        <button class="nw-add-btn-sm">Add</button>
+      </div>`).join('');
+
+    listEl.querySelectorAll('.nw-add-item').forEach(el => {
+      el.querySelector('.nw-add-btn-sm').addEventListener('click', () => {
+        addPerson(el.dataset.pid);
+      });
+    });
+  }
+
+  searchEl.addEventListener('input', e => renderAddList(e.target.value));
+  document.getElementById('nwAddCancel')?.addEventListener('click', () => {
+    _selectedPid = null;
+    renderDetail(null);
+  });
+
+  renderAddList('');
+}
+
+function addPerson(pid) {
+  if (!_selectedGid) return;
+  const members = _store.members[_selectedGid] || [];
+  if (!members.includes(String(pid))) {
+    members.push(String(pid));
+    _store.members[_selectedGid] = members;
+    saveStore(_store);
+  }
+  _selectedPid = String(pid);
+  render();
+  renderDetail(_selectedPid);
+}
+
+function removePerson(pid, gid) {
+  _store.members[gid] = (_store.members[gid] || []).filter(id => String(id) !== String(pid));
+  saveStore(_store);
+  if (_selectedPid === String(pid)) {
+    _selectedPid = null;
+    const panel = document.getElementById('nwDetail');
+    if (panel) panel.innerHTML = `<div class="nw-detail-empty">Select a person to view details</div>`;
+  }
+  renderSidebar();
+  renderCenter();
+}
+
+// ── Util ──────────────────────────────────────────────────────────
+function escHtml(str) {
+  return String(str ?? '')
+    .replace(/&/g, '&amp;')
+    .replace(/</g, '&lt;')
+    .replace(/>/g, '&gt;')
+    .replace(/"/g, '&quot;');
+}

