+  _container   = container;
+  _selectedGid = null;
+  _selectedPid = null;
+  _searchQ     = '';
+
+  _allPeople = await getPeople();
+  _store     = seedDefaults(loadStore(), _allPeople);
+
+  if (_store.groups.length > 0) _selectedGid = _store.groups[0].id;
+
   container.innerHTML = `
-    <div style="display:flex;flex-direction:column;flex:1;min-height:0;background:#000">
-      <div style="padding:32px 40px 20px;border-bottom:1px solid rgba(255,255,255,0.07);flex-shrink:0">
-        <div style="font-size:22px;font-weight:300;color:#f4f4f4;letter-spacing:-0.2px;margin-bottom:6px">Network</div>
-        <div style="font-size:13px;color:#525252">Your personal IBM network — track relationships, expertise, and follow-ups.</div>
+    <div class="nw-page">
+      <div class="nw-sidebar">
+        <div class="nw-sidebar-header">
+          <span class="nw-sidebar-title">Groups</span>
+          <button class="nw-new-group-btn" id="nwNewGroup">+ New</button>
+        </div>
+        <div class="nw-group-list" id="nwGroupList"></div>
       </div>
-      <div style="flex:1;display:flex;align-items:center;justify-content:center;color:#2a2a2a;font-size:14px">
-        Coming soon
+      <div class="nw-center">
+        <div class="nw-center-toolbar" id="nwCenterToolbar"></div>
+        <div class="nw-cards-area" id="nwCardsArea"></div>
       </div>
+      <div class="nw-detail" id="nwDetail">
+        <div class="nw-detail-empty">Select a person to view details</div>
+      </div>
     </div>
   `;
+
+  document.getElementById('nwNewGroup').addEventListener('click', () => createGroup());
+
+  render();
 }
+
+// ── Top-level render ──────────────────────────────────────────────
+function render() {
+  renderSidebar();
+  renderCenter();
+  // detail panel only re-renders if a person is selected
+  if (_selectedPid) renderDetail(_selectedPid);
+}
+
+// ── Sidebar ───────────────────────────────────────────────────────
+function renderSidebar() {
+  const list = document.getElementById('nwGroupList');
+  if (!list) return;
+
+  if (_store.groups.length === 0) {
+    list.innerHTML = `<div class="nw-group-empty">No groups yet.<br>Create one above.</div>`;
+    return;
+  }
+
+  list.innerHTML = _store.groups.map(g => {
+    const count = (_store.members[g.id] || []).length;
+    const active = g.id === _selectedGid;
+    return `
+      <div class="nw-group-item${active ? ' active' : ''}" data-gid="${g.id}">
+        <span class="nw-group-name">${escHtml(g.name)}</span>
+        <span class="nw-group-count">${count}</span>
+        <span class="nw-group-actions">
+          <span class="nw-group-action" data-action="rename" data-gid="${g.id}" title="Rename">✎</span>
+          <span class="nw-group-action" data-action="delete" data-gid="${g.id}" title="Delete">✕</span>
+        </span>
+      </div>`;
+  }).join('');
+
+  list.querySelectorAll('.nw-group-item').forEach(el => {
+    el.addEventListener('click', e => {
+      if (e.target.closest('.nw-group-actions')) return;
+      _selectedGid = el.dataset.gid;
+      _selectedPid = null;
+      render();
+    });
+  });
+
+  list.querySelectorAll('.nw-group-action').forEach(el => {
+    el.addEventListener('click', e => {
+      e.stopPropagation();
+      const { action, gid } = el.dataset;
+      if (action === 'rename') renameGroup(gid);
+      if (action === 'delete') deleteGroup(gid);
+    });
+  });
+}
+
+// ── Center (cards) ────────────────────────────────────────────────
+function renderCenter() {
+  const toolbar = document.getElementById('nwCenterToolbar');
+  const area    = document.getElementById('nwCardsArea');
+  if (!toolbar || !area) return;
+
+  const group = _store.groups.find(g => g.id === _selectedGid);
+
+  if (!group) {
+    toolbar.innerHTML = '';
+    area.innerHTML = `<div class="nw-no-group">Create or select a group to get started.</div>`;
+    return;
+  }
+
+  // Toolbar: group title + search + add person
+  toolbar.innerHTML = `
+    <div class="nw-center-title">${escHtml(group.name)}</div>
+    <div class="nw-center-controls">
+      <input class="nw-search" id="nwSearch" type="text" placeholder="Search people…" value="${escHtml(_searchQ)}"/>
+      <button class="nw-add-btn" id="nwAddPerson">+ Add person</button>
+    </div>
+  `;
+
+  document.getElementById('nwSearch')?.addEventListener('input', e => {
+    _searchQ = e.target.value;
+    renderCenter();
+  });
+  document.getElementById('nwAddPerson')?.addEventListener('click', () => openAddPerson());
+
+  // Cards
+  const memberIds = _store.members[group.id] || [];
+  const members   = memberIds
+    .map(id => _allPeople.find(p => String(p.id) === String(id)))
+    .filter(Boolean);
+
+  const filtered = _searchQ
+    ? members.filter(p => {
+        const q = _searchQ.toLowerCase();
+        const name = `${p.first_name} ${p.last_name}`.toLowerCase();
+        const det = _store.details[String(p.id)] || {};
+        return name.includes(q) || (det.expertise || '').toLowerCase().includes(q);
+      })
+    : members;
+
+  if (filtered.length === 0) {
+    area.innerHTML = `<div class="nw-no-group">${
+      memberIds.length === 0
+        ? 'No people in this group yet. Click "+ Add person" to begin.'
+        : 'No people match your search.'
+    }</div>`;
+    return;
+  }
+
+  // Arrange cards in honeycomb rows: rows of 4, every even row offset
+  const COLS = 4;
+  const rows = [];
+  for (let i = 0; i < filtered.length; i += COLS) {
+    rows.push(filtered.slice(i, i + COLS));
+  }
+
+  area.innerHTML = `
+    <div class="nw-hive-grid">
+      ${rows.map((row, ri) => `
+        <div class="nw-hive-row${ri % 2 === 1 ? ' nw-hive-row-offset' : ''}">
+          ${row.map(p => cardHTML(p, group.id)).join('')}
+        </div>`
+      ).join('')}
+    </div>`;
+
+  area.querySelectorAll('.nw-card').forEach(el => {
+    el.addEventListener('click', () => {
+      _selectedPid = el.dataset.pid;
+      renderSidebar();  // keep group list in sync
+      renderCenter();   // re-render to update active state
+      renderDetail(_selectedPid);
+    });
+  });
+
+  area.querySelectorAll('.nw-card-remove').forEach(el => {
+    el.addEventListener('click', e => {
+      e.stopPropagation();
+      removePerson(el.dataset.pid, el.dataset.gid);
+    });
+  });
+}
+
+function cardHTML(p, gid) {
+  const det     = _store.details[String(p.id)] || {};
+  const name    = `${p.first_name} ${p.last_name}`;
+  const isActive = String(p.id) === String(_selectedPid);
+  const initials = `${p.first_name?.[0] || ''}${p.last_name?.[0] || ''}`;
+  const expertise = det.expertise ? det.expertise.split(',').map(e => e.trim()).slice(0, 2) : [];
+
+  return `
+    <div class="nw-card${isActive ? ' active' : ''}" data-pid="${p.id}">
+      <button class="nw-card-remove" data-pid="${p.id}" data-gid="${gid}" title="Remove from group">✕</button>
+      <div class="nw-card-avatar" style="background:${p.color || '#2a2a2a'}">${initials}</div>
+      <div class="nw-card-name">${escHtml(name)}</div>
+      <div class="nw-card-role">${escHtml(p.role || '—')}</div>
+      ${expertise.length ? `<div class="nw-card-tags">${expertise.map(e => `<span class="nw-card-tag">${escHtml(e)}</span>`).join('')}</div>` : ''}
+    </div>`;
+}
+
+// ── Detail panel ──────────────────────────────────────────────────
+function renderDetail(pid) {
+  const panel = document.getElementById('nwDetail');
+  if (!panel) return;
+
+  if (!pid) {
+    panel.innerHTML = `<div class="nw-detail-empty">Select a person to view details</div>`;
+    return;
+  }
+
+  const p   = _allPeople.find(x => String(x.id) === String(pid));
+  if (!p) return;
+
+  const det  = _store.details[String(pid)] || {};
+  const name = `${p.first_name} ${p.last_name}`;
+
+  const REL_TYPES = ['Mentor', 'Technical Expert', 'Manager', 'Counterpart', 'Partner', 'Peer', 'Client', 'Other'];
+
+  panel.innerHTML = `
+    <div class="nw-dp-content">
+      <div class="nw-dp-header">
+        <div class="nw-dp-avatar" style="background:${p.color || '#2a2a2a'}">${p.first_name?.[0] || ''}${p.last_name?.[0] || ''}</div>
+        <div class="nw-dp-identity">
+          <div class="nw-dp-name">${escHtml(name)}</div>
+          <div class="nw-dp-role">${escHtml(p.role || '—')}</div>
+          ${p.market ? `<div class="nw-dp-market">${escHtml(p.market)}</div>` : ''}
+        </div>
+        <button class="nw-dp-close" id="nwDpClose">✕</button>
+      </div>
+
+      <div class="nw-dp-body">
+
+        ${p.email ? `
+        <div class="nw-dp-field">
+          <div class="nw-dp-label">Email</div>
+          <a href="mailto:${escHtml(p.email)}" class="nw-dp-link">${escHtml(p.email)}</a>
+        </div>` : ''}
+
+        ${p.location ? `
+        <div class="nw-dp-field">
+          <div class="nw-dp-label">Location</div>
+          <div class="nw-dp-value">${escHtml(p.location)}</div>
+        </div>` : ''}
+
+        <div class="nw-dp-field">
+          <div class="nw-dp-label">Expertise</div>
+          <input class="nw-dp-input" id="dpExpertise" type="text"
+            placeholder="e.g. PowerVS, Storage, z/OS"
+            value="${escHtml(det.expertise || '')}"/>
+        </div>
+
+        <div class="nw-dp-field">
+          <div class="nw-dp-label">Relationship</div>
+          <select class="nw-dp-select" id="dpRelationship">
+            <option value="">— select —</option>
+            ${REL_TYPES.map(r => `<option value="${r}"${det.relationship === r ? ' selected' : ''}>${r}</option>`).join('')}
+          </select>
+        </div>
+
+        <div class="nw-dp-field">
+          <div class="nw-dp-label">Why I know them</div>
+          <input class="nw-dp-input" id="dpWhyKnow" type="text"
+            placeholder="Context for the relationship…"
+            value="${escHtml(det.whyKnow || '')}"/>
+        </div>
+
+        <div class="nw-dp-field">
+          <div class="nw-dp-label">Last interaction</div>
+          <input class="nw-dp-input" id="dpLastInteraction" type="date"
+            value="${escHtml(det.lastInteraction || '')}"/>
+        </div>
+
+        <div class="nw-dp-field">
+          <div class="nw-dp-label">Follow-up date</div>
+          <input class="nw-dp-input" id="dpFollowUp" type="date"
+            value="${escHtml(det.followUp || '')}"/>
+        </div>
+
+        <div class="nw-dp-field">
+          <div class="nw-dp-label">Notes</div>
+          <textarea class="nw-dp-textarea" id="dpNotes" rows="4"
+            placeholder="Notes about this person…">${escHtml(det.notes || '')}</textarea>
+        </div>
+
+        <button class="nw-dp-save" id="nwDpSave">Save</button>
+
+      </div>
+    </div>
+  `;
+
+  document.getElementById('nwDpClose')?.addEventListener('click', () => {
+    _selectedPid = null;
+    renderCenter();
+    panel.innerHTML = `<div class="nw-detail-empty">Select a person to view details</div>`;
+  });
+
+  document.getElementById('nwDpSave')?.addEventListener('click', () => {
+    savePerson(pid);
+  });
+}
+
+function savePerson(pid) {
+  const expertise       = document.getElementById('dpExpertise')?.value.trim() || '';
+  const relationship    = document.getElementById('dpRelationship')?.value || '';
+  const whyKnow         = document.getElementById('dpWhyKnow')?.value.trim() || '';
+  const lastInteraction = document.getElementById('dpLastInteraction')?.value || '';
+  const followUp        = document.getElementById('dpFollowUp')?.value || '';
+  const notes           = document.getElementById('dpNotes')?.value.trim() || '';
+
+  _store.details[String(pid)] = { expertise, relationship, whyKnow, lastInteraction, followUp, notes };
+  saveStore(_store);
+
+  // Flash save confirmation
+  const btn = document.getElementById('nwDpSave');
+  if (btn) { btn.textContent = 'Saved'; setTimeout(() => { if (btn) btn.textContent = 'Save'; }, 1400); }
+
+  // Re-render cards so expertise tags update
+  renderCenter();
+}
+
+// ── Group CRUD ────────────────────────────────────────────────────
+function createGroup() {
+  const name = prompt('Group name:');
+  if (!name?.trim()) return;
+  const g = { id: uid(), name: name.trim() };
+  _store.groups.push(g);
+  _store.members[g.id] = [];
+  saveStore(_store);
+  _selectedGid = g.id;
+  _selectedPid = null;
+  render();
+}
+
+function renameGroup(gid) {
+  const g = _store.groups.find(x => x.id === gid);
+  if (!g) return;
+  const name = prompt('New name:', g.name);
+  if (!name?.trim()) return;
+  g.name = name.trim();
+  saveStore(_store);
+  render();
+}
+
+function deleteGroup(gid) {
+  if (!confirm('Delete this group? People are not removed from IBM Hive.')) return;
+  _store.groups = _store.groups.filter(g => g.id !== gid);
+  delete _store.members[gid];
+  saveStore(_store);
+  if (_selectedGid === gid) {
+    _selectedGid = _store.groups[0]?.id || null;
+    _selectedPid = null;
+  }
+  render();
+}
+
+// ── Add / remove person ───────────────────────────────────────────
+function openAddPerson() {
+  const panel = document.getElementById('nwDetail');
+  if (!panel) return;
+
+  const group    = _store.groups.find(g => g.id === _selectedGid);
+  if (!group) return;
+  const existIds = new Set((_store.members[_selectedGid] || []).map(String));
+  const available = _allPeople.filter(p => !existIds.has(String(p.id)));
+
+  panel.innerHTML = `
+    <div class="nw-dp-content">
+      <div class="nw-dp-add-title">Add to "${escHtml(group.name)}"</div>
+      <input class="nw-dp-input" id="nwAddSearch" type="text" placeholder="Search by name or role…" style="margin-bottom:12px"/>
+      <div class="nw-add-list" id="nwAddList"></div>
+      <button class="nw-dp-close-btn" id="nwAddCancel">Cancel</button>
+    </div>`;
+
+  const listEl = document.getElementById('nwAddList');
+  const searchEl = document.getElementById('nwAddSearch');
+
+  function renderAddList(q) {
+    const results = available.filter(p => {
+      const name = `${p.first_name} ${p.last_name}`.toLowerCase();
+      return !q || name.includes(q.toLowerCase()) || (p.role || '').toLowerCase().includes(q.toLowerCase());
+    });
+    listEl.innerHTML = results.slice(0, 20).map(p => `
+      <div class="nw-add-item" data-pid="${p.id}">
+        <div class="nw-add-initials" style="background:${p.color || '#2a2a2a'}">${p.first_name?.[0] || ''}${p.last_name?.[0] || ''}</div>
+        <div class="nw-add-info">
+          <div class="nw-add-name">${escHtml(p.first_name + ' ' + p.last_name)}</div>
+          <div class="nw-add-role">${escHtml(p.role || '—')}</div>
+        </div>
+        <button class="nw-add-btn-sm">Add</button>
+      </div>`).join('');
+
+    listEl.querySelectorAll('.nw-add-item').forEach(el => {
+      el.querySelector('.nw-add-btn-sm').addEventListener('click', () => {
+        addPerson(el.dataset.pid);
+      });
+    });
+  }
+
+  searchEl.addEventListener('input', e => renderAddList(e.target.value));
+  document.getElementById('nwAddCancel')?.addEventListener('click', () => {
+    _selectedPid = null;
+    renderDetail(null);
+  });
+
+  renderAddList('');
+}
+
+function addPerson(pid) {
+  if (!_selectedGid) return;
+  const members = _store.members[_selectedGid] || [];
+  if (!members.includes(String(pid))) {
+    members.push(String(pid));
+    _store.members[_selectedGid] = members;
+    saveStore(_store);
+  }
+  _selectedPid = String(pid);
+  render();
+  renderDetail(_selectedPid);
+}
+
+function removePerson(pid, gid) {
+  _store.members[gid] = (_store.members[gid] || []).filter(id => String(id) !== String(pid));
+  saveStore(_store);
+  if (_selectedPid === String(pid)) {
+    _selectedPid = null;
+    const panel = document.getElementById('nwDetail');
+    if (panel) panel.innerHTML = `<div class="nw-detail-empty">Select a person to view details</div>`;
+  }
+  renderSidebar();
+  renderCenter();
+}
+
+// ── Util ──────────────────────────────────────────────────────────
+function escHtml(str) {
+  return String(str ?? '')
+    .replace(/&/g, '&amp;')
+    .replace(/</g, '&lt;')
+    .replace(/>/g, '&gt;')
+    .replace(/"/g, '&quot;');
+}

