/* ═══════════════════════════════════════════════════════════════
   NETWORK TAB — network.js
   Three columns: groups sidebar | honeycomb cards | detail panel
   ═══════════════════════════════════════════════════════════════ */

.nw-page {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  background: #000;
}

/* ── Left: groups sidebar ── */
.nw-sidebar {
  width: 200px;
  flex-shrink: 0;
  background: #0d0d0d;
  border-right: 1px solid rgba(255,255,255,0.07);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.nw-sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 16px 12px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  flex-shrink: 0;
}
.nw-sidebar-title {
  font-size: 11px;
  font-weight: 500;
  color: #525252;
}
.nw-new-group-btn {
  font-size: 11px;
  padding: 3px 8px;
  background: transparent;
  border: 1px solid rgba(255,255,255,0.12);
  color: #8d8d8d;
  cursor: pointer;
  font-family: inherit;
  border-radius: 0;
  transition: color 0.1s, border-color 0.1s;
}
.nw-new-group-btn:hover { color: #fff; border-color: rgba(255,255,255,0.3); }

.nw-group-list { flex: 1; overflow-y: auto; }
.nw-group-empty {
  padding: 20px 16px;
  font-size: 12px;
  color: #3a3a3a;
  line-height: 1.6;
}
.nw-group-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 9px 14px;
  font-size: 13px;
  color: #6f6f6f;
  cursor: pointer;
  border-left: 2px solid transparent;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  transition: color 0.1s;
}
.nw-group-item:hover { color: #c6c6c6; }
.nw-group-item.active { color: #fff; border-left-color: #4589ff; }
.nw-group-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.nw-group-count {
  font-size: 10px;
  color: #3a3a3a;
  flex-shrink: 0;
}
.nw-group-actions {
  display: none;
  gap: 4px;
  flex-shrink: 0;
}
.nw-group-item:hover .nw-group-actions { display: flex; }
.nw-group-item.active .nw-group-actions { display: flex; }
.nw-group-action {
  font-size: 11px;
  color: #525252;
  padding: 1px 3px;
  cursor: pointer;
  transition: color 0.1s;
}
.nw-group-action:hover { color: #fff; }

/* ── Center: cards ── */
.nw-center {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.nw-center-toolbar {
  padding: 16px 20px 12px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.nw-center-title {
  font-size: 16px;
  font-weight: 300;
  color: #f4f4f4;
  flex-shrink: 0;
  margin-right: 8px;
}
.nw-center-controls {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
}
.nw-search {
  flex: 1;
  max-width: 240px;
  padding: 6px 10px;
  background: #111;
  border: 1px solid rgba(255,255,255,0.1);
  border-bottom-width: 2px;
  border-bottom-color: rgba(255,255,255,0.1);
  color: #e0e0e0;
  font-size: 13px;
  font-family: inherit;
  border-radius: 0;
  outline: none;
  transition: border-color 0.1s;
}
.nw-search:focus { border-bottom-color: #4589ff; }
.nw-search::placeholder { color: #3a3a3a; }
.nw-add-btn {
  padding: 6px 14px;
  background: transparent;
  border: 1px solid rgba(255,255,255,0.18);
  color: #a8a8a8;
  font-size: 12px;
  font-family: inherit;
  cursor: pointer;
  border-radius: 0;
  transition: color 0.1s, border-color 0.1s;
  flex-shrink: 0;
}
.nw-add-btn:hover { color: #fff; border-color: #4589ff; }

.nw-cards-area {
  flex: 1;
  overflow-y: auto;
  padding: 24px 20px 40px;
}
.nw-no-group {
  padding: 48px 24px;
  font-size: 13px;
  color: #3a3a3a;
  text-align: center;
  line-height: 1.6;
}

/* Honeycomb grid */
.nw-hive-grid {
  display: flex;
  flex-direction: column;
  gap: 0;
}
.nw-hive-row {
  display: flex;
  gap: 12px;
  margin-bottom: -8px;
}
.nw-hive-row-offset { margin-left: 90px; }

/* Individual card — hex-shaped via clip-path */
.nw-card {
  position: relative;
  width: 148px;
  height: 148px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  background: #1c1c1c;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.12s;
  padding: 16px 12px;
  text-align: center;
}
.nw-card:hover { background: #242424; }
.nw-card.active { background: #0d1f3c; outline: 2px solid #4589ff; outline-offset: -2px; }

.nw-card-remove {
  position: absolute;
  top: 28px;
  right: 36px;
  background: transparent;
  border: none;
