+  overflow-y: auto;
+  display: flex;
+  flex-direction: column;
+}
+.nw-detail-empty {
+  flex: 1;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  padding: 32px 20px;
+  font-size: 12px;
+  color: #3a3a3a;
+  text-align: center;
+  line-height: 1.6;
+}
+
+/* Person detail */
+.nw-dp-content { padding: 20px 18px 40px; }
+.nw-dp-header {
+  display: flex;
+  align-items: flex-start;
+  gap: 12px;
+  margin-bottom: 20px;
+  padding-bottom: 16px;
+  border-bottom: 1px solid rgba(255,255,255,0.06);
+}
+.nw-dp-avatar {
+  width: 40px;
+  height: 40px;
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 14px;
+  font-weight: 700;
+  color: #fff;
+  flex-shrink: 0;
+}
+.nw-dp-identity { flex: 1; min-width: 0; }
+.nw-dp-name { font-size: 15px; font-weight: 400; color: #f4f4f4; margin-bottom: 2px; }
+.nw-dp-role { font-size: 11px; color: #525252; }
+.nw-dp-market { font-size: 10px; color: #3a3a3a; margin-top: 2px; }
+.nw-dp-close {
+  background: transparent;
+  border: none;
+  color: #525252;
+  font-size: 14px;
+  cursor: pointer;
+  padding: 2px 4px;
+  flex-shrink: 0;
+  transition: color 0.1s;
+  line-height: 1;
+}
+.nw-dp-close:hover { color: #fff; }
+
+.nw-dp-body { display: flex; flex-direction: column; gap: 12px; }
+.nw-dp-field { display: flex; flex-direction: column; gap: 4px; }
+.nw-dp-label { font-size: 10px; color: #3a3a3a; font-weight: 400; }
+.nw-dp-value { font-size: 12px; color: #a8a8a8; line-height: 1.5; }
+.nw-dp-link  { font-size: 12px; color: #4589ff; text-decoration: none; }
+.nw-dp-link:hover { text-decoration: underline; }
+.nw-dp-input {
+  padding: 6px 8px;
+  background: #111;
+  border: none;
+  border-bottom: 1px solid rgba(255,255,255,0.1);
+  color: #e0e0e0;
+  font-size: 12px;
+  font-family: inherit;
+  outline: none;
+  transition: border-color 0.1s;
+}
+.nw-dp-input:focus { border-bottom-color: #4589ff; }
+.nw-dp-select {
+  padding: 6px 8px;
+  background: #111;
+  border: none;
+  border-bottom: 1px solid rgba(255,255,255,0.1);
+  color: #e0e0e0;
+  font-size: 12px;
+  font-family: inherit;
+  outline: none;
+  cursor: pointer;
+  appearance: none;
+  transition: border-color 0.1s;
+}
+.nw-dp-select:focus { border-bottom-color: #4589ff; }
+.nw-dp-textarea {
+  padding: 6px 8px;
+  background: #111;
+  border: 1px solid rgba(255,255,255,0.08);
+  color: #e0e0e0;
+  font-size: 12px;
+  font-family: inherit;
+  outline: none;
+  resize: vertical;
+  line-height: 1.55;
+  transition: border-color 0.1s;
+}
+.nw-dp-textarea:focus { border-color: #4589ff; }
+.nw-dp-save {
+  margin-top: 8px;
+  padding: 8px 16px;
+  background: #4589ff;
+  color: #fff;
+  border: none;
+  font-size: 13px;
+  font-family: inherit;
+  cursor: pointer;
+  border-radius: 0;
+  transition: background 0.1s;
+  align-self: flex-start;
+}
+.nw-dp-save:hover { background: #0f62fe; }
+
+/* Add person panel */
+.nw-dp-add-title {
+  font-size: 14px;
+  font-weight: 400;
+  color: #f4f4f4;
+  margin-bottom: 14px;
+}
+.nw-add-list {
+  display: flex;
+  flex-direction: column;
+  gap: 2px;
+  max-height: 380px;
+  overflow-y: auto;
+  margin-bottom: 12px;
+}
+.nw-add-item {
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  padding: 8px 6px;
+  border-bottom: 1px solid rgba(255,255,255,0.04);
+}
+.nw-add-initials {
+  width: 28px;
+  height: 28px;
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  font-size: 11px;
+  font-weight: 700;
+  color: #fff;
+  flex-shrink: 0;
+}
+.nw-add-info { flex: 1; min-width: 0; }
+.nw-add-name { font-size: 12px; color: #e0e0e0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
+.nw-add-role { font-size: 10px; color: #525252; }
+.nw-add-btn-sm {
+  padding: 3px 10px;
+  background: transparent;
+  border: 1px solid rgba(255,255,255,0.14);
+  color: #8d8d8d;
+  font-size: 11px;
+  font-family: inherit;
+  cursor: pointer;
+  border-radius: 0;
+  flex-shrink: 0;
+  transition: color 0.1s, border-color 0.1s;
+}
+.nw-add-btn-sm:hover { color: #fff; border-color: #4589ff; }
+.nw-dp-close-btn {
+  padding: 6px 14px;
+  background: transparent;
+  border: 1px solid rgba(255,255,255,0.1);
+  color: #6f6f6f;
+  font-size: 12px;
+  font-family: inherit;
+  cursor: pointer;
+  border-radius: 0;
+  transition: color 0.1s;
+}
+.nw-dp-close-btn:hover { color: #fff; }
