24 | function wireProfileDropdown() {
25 |   const userSection = document.getElementById('topnavUser');
26 |   const dropdown    = document.getElementById('userDropdown');
27 |   if (!userSection || !dropdown) return;
28 | 
29 |   userSection.addEventListener('click', e => {
30 |     e.stopPropagation();
31 |     dropdown.classList.toggle('open');
32 |   });
33 |   document.addEventListener('click', e => {
34 |     if (!userSection.contains(e.target)) dropdown.classList.remove('open');
35 |   });
36 | 
37 |   dropdown.querySelectorAll('.user-dropdown-item').forEach(item => {
38 |     item.addEventListener('click', e => {
39 |       e.stopPropagation();
40 |       dropdown.querySelectorAll('.user-dropdown-item').forEach(i => i.classList.remove('active'));
41 |       item.classList.add('active');
42 |       const nameEl = document.getElementById('currentUserName');
43 |       if (item.dataset.profile === 'sydney')       nameEl.textContent = 'Sydney Chin';
44 |       else if (item.dataset.profile === 'manager') nameEl.textContent = 'Chris Kennedy';
45 |       else if (item.dataset.profile === 'admin')   nameEl.textContent = 'Admin';
46 |       dropdown.classList.remove('open');
47 |     });
48 |   });
49 | }
