52 | const VIEW_RENDERERS = {
53 |   org:     renderOrg,
54 |   cell:    renderSeller,
55 |   people:  renderPeople,
56 |   network: renderNetwork,
57 | };
58 | 
59 | const rendered = new Set();
60 | 
61 | async function activateView(viewName) {
62 |   // Update top nav
63 |   document.querySelectorAll('.topnav-link[data-view-link]').forEach(n => {
64 |     n.classList.toggle('active', n.dataset.viewLink === viewName);
65 |   });
66 | 
67 |   // Show the right view container
68 |   document.querySelectorAll('.main > .view').forEach(v => {
69 |     v.classList.toggle('active', v.id === `view-${viewName}`);
70 |   });
71 | 
72 |   // Render the view if not yet rendered
73 |   const container = document.getElementById(`view-${viewName}`);
74 |   if (!container) return;
75 | 
76 |   if (!rendered.has(viewName)) {
77 |     rendered.add(viewName);
78 |     try {
79 |       await VIEW_RENDERERS[viewName]?.(container);
80 |     } catch (err) {
81 |       container.innerHTML = `
