84 |           <div class="page-sub">${err.message}</div>
85 |         </div>
86 |         <div class="content" style="color:var(--muted);font-size:13px">
87 |           Make sure the server is running (<code>npm start</code>) and seeded (<code>npm run seed</code>).
88 |         </div>
89 |       `;
90 |     }
91 |   }
92 | }
93 | 
94 | // ── Top nav link clicks ──────────────────────────────────────────
95 | document.querySelectorAll('.topnav-link[data-view-link]').forEach(item => {
96 |   item.addEventListener('click', () => activateView(item.dataset.viewLink));
97 | });
98 | 
