385 | // ─────────────────────────────────────────────────────────────────
386 | function getRelationshipSets(selectedId) {
387 |   if (!selectedId || selectedId === 'root') return { selected: new Set(), related: new Set() };
388 | 
389 |   // Find the selected function
390 |   let selFn = null;
391 |   for (const seg of SEGMENTS) {
392 |     const fn = seg.functions.find(f => f.id === selectedId);
393 |     if (fn) { selFn = fn; break; }
394 |   }
395 |   if (!selFn) return { selected: new Set([selectedId]), related: new Set() };
396 | 
397 |   const worksWithAbbrs = new Set((selFn.worksWith || []).map(w => w.toLowerCase()));
398 | 
399 |   // Find all role nodes whose abbr is in worksWith
400 |   const related = new Set();
401 |   for (const seg of SEGMENTS) {
402 |     for (const fn of seg.functions) {
403 |       if (worksWithAbbrs.has(fn.abbr.toLowerCase())) {
404 |         related.add(fn.id);
