413 | // Text wrap — break on spaces, max maxChars per line
414 | // ─────────────────────────────────────────────────────────────────
415 | function wrapText(text, maxChars) {
416 |   if (!text) return [];
417 |   const words = text.split(' ');
418 |   const lines = [];
419 |   let cur = '';
420 |   for (const w of words) {
421 |     if (!cur) { cur = w; continue; }
422 |     if ((cur + ' ' + w).length <= maxChars) { cur += ' ' + w; }
423 |     else { lines.push(cur); cur = w; }
424 |   }
425 |   if (cur) lines.push(cur);
426 |   return lines;
427 | }
