    };
    if (isNew) {
      _contacts.push(updated);
    } else {
      const idx = _contacts.findIndex(c => c.id === contact.id);
      if (idx !== -1) _contacts[idx] = updated;
    }
    saveContacts(_contacts);
    close();
  });

  // Focus name field
  setTimeout(() => document.getElementById('nwmName')?.focus(), 60);
}

