/**
 * network.js — Network tab
 *
 * Purpose: "Who do I know?"
 * Three-column layout:
 *   Left   — group list + create/rename/delete
 *   Center — honeycomb cards for people in selected group
 *   Right  — selected person detail + relationship fields
 *
 * Data stored in localStorage under 'ibm_hive_network'.
 */
import { getPeople } from '../api.js';

// ── Persistence helpers ───────────────────────────────────────────
const STORE_KEY = 'ibm_hive_network';

function loadStore() {
  try {
    const raw = localStorage.getItem(STORE_KEY);
    if (raw) return JSON.parse(raw);
  } catch {}
  return { groups: [], members: {}, details: {} };
  // groups: [{id, name}]
  // members: { groupId: [personId, ...] }
  // details: { personId: { relationship, whyKnow, lastInteraction, followUp, notes, expertise } }
}

function saveStore(store) {
  localStorage.setItem(STORE_KEY, JSON.stringify(store));
}

function seedDefaults(store, allPeople) {
  if (store.groups.length > 0) return store;

  // Seed with example groups and the team members already known
  const find = (fn, ln) => allPeople.find(p => p.first_name === fn && p.last_name === ln);
  const markH    = find('Mark',    'Hoffman');
  const rossH    = find('Ross',    'Holley');
  const patrickM = find('Patrick', 'McBride');

  const g1 = { id: uid(), name: 'PowerVS Experts' };
  const g2 = { id: uid(), name: 'My Team' };
  store.groups = [g1, g2];

  const pvIds = [markH, rossH, patrickM].filter(Boolean).map(p => String(p.id));
  store.members[g1.id] = pvIds;

  const teamNames = ['Chris Kennedy','Rob Hanes','Mark Hoffman','Armada Veraepalli','Sydney Chin','Ross Holley','Patrick McBride'];
  store.members[g2.id] = allPeople
    .filter(p => teamNames.includes(`${p.first_name} ${p.last_name}`))
    .map(p => String(p.id));

  // Seed details for Ross
  if (rossH) {
    store.details[String(rossH.id)] = {
      relationship: 'Counterpart',
      expertise: 'PowerVS, Infrastructure',
      whyKnow: 'Supports infrastructure opportunities',
      notes: 'Strong PowerVS resource.',
      lastInteraction: '',
      followUp: '',
    };
  }
  if (markH) {
    store.details[String(markH.id)] = {
      relationship: 'Counterpart',
      expertise: 'PowerVS, FlashSystem',
      whyKnow: 'BTSS paired with Ross Holley',
      notes: '',
      lastInteraction: '',
      followUp: '',
    };
  }

  saveStore(store);
  return store;
}

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

// ── Module state ──────────────────────────────────────────────────
let _store       = null;
let _allPeople   = [];
let _selectedGid = null;
let _selectedPid = null;
let _searchQ     = '';
let _container   = null;

// ── Entry ─────────────────────────────────────────────────────────
export async function renderNetwork(container) {
  _container   = container;
  _selectedGid = null;
  _selectedPid = null;
  _searchQ     = '';

  _allPeople = await getPeople();
  _store     = seedDefaults(loadStore(), _allPeople);

  if (_store.groups.length > 0) _selectedGid = _store.groups[0].id;

  container.innerHTML = `
    <div class="nw-page">
      <div class="nw-sidebar">
        <div class="nw-sidebar-header">
          <span class="nw-sidebar-title">Groups</span>
          <button class="nw-new-group-btn" id="nwNewGroup">+ New</button>
        </div>
        <div class="nw-group-list" id="nwGroupList"></div>
      </div>
      <div class="nw-center">
        <div class="nw-center-toolbar" id="nwCenterToolbar"></div>
        <div class="nw-cards-area" id="nwCardsArea"></div>
      </div>
      <div class="nw-detail" id="nwDetail">
        <div class="nw-detail-empty">Select a person to view details</div>
      </div>
    </div>
  `;

  document.getElementById('nwNewGroup').addEventListener('click', () => createGroup());

  render();
}

// ── Top-level render ──────────────────────────────────────────────
function render() {
  renderSidebar();
  renderCenter();
  // detail panel only re-renders if a person is selected
  if (_selectedPid) renderDetail(_selectedPid);
}

// ── Sidebar ───────────────────────────────────────────────────────
function renderSidebar() {
  const list = document.getElementById('nwGroupList');
  if (!list) return;

  if (_store.groups.length === 0) {
    list.innerHTML = `<div class="nw-group-empty">No groups yet.<br>Create one above.</div>`;
    return;
  }

  list.innerHTML = _store.groups.map(g => {
    const count = (_store.members[g.id] || []).length;
    const active = g.id === _selectedGid;
    return `
      <div class="nw-group-item${active ? ' active' : ''}" data-gid="${g.id}">
        <span class="nw-group-name">${escHtml(g.name)}</span>
        <span class="nw-group-count">${count}</span>
        <span class="nw-group-actions">
          <span class="nw-group-action" data-action="rename" data-gid="${g.id}" title="Rename">✎</span>
          <span class="nw-group-action" data-action="delete" data-gid="${g.id}" title="Delete">✕</span>
        </span>
      </div>`;
  }).join('');

  list.querySelectorAll('.nw-group-item').forEach(el => {
    el.addEventListener('click', e => {
      if (e.target.closest('.nw-group-actions')) return;
      _selectedGid = el.dataset.gid;
      _selectedPid = null;
      render();
    });
  });

  list.querySelectorAll('.nw-group-action').forEach(el => {
    el.addEventListener('click', e => {
      e.stopPropagation();
      const { action, gid } = el.dataset;
      if (action === 'rename') renameGroup(gid);
      if (action === 'delete') deleteGroup(gid);
    });
  });
}

// ── Center (cards) ────────────────────────────────────────────────
function renderCenter() {
  const toolbar = document.getElementById('nwCenterToolbar');
  const area    = document.getElementById('nwCardsArea');
  if (!toolbar || !area) return;

  const group = _store.groups.find(g => g.id === _selectedGid);

  if (!group) {
    toolbar.innerHTML = '';
    area.innerHTML = `<div class="nw-no-group">Create or select a group to get started.</div>`;
    return;
  }

  // Toolbar: group title + search + add person
  toolbar.innerHTML = `
    <div class="nw-center-title">${escHtml(group.name)}</div>
    <div class="nw-center-controls">
      <input class="nw-search" id="nwSearch" type="text" placeholder="Search people…" value="${escHtml(_searchQ)}"/>
      <button class="nw-add-btn" id="nwAddPerson">+ Add person</button>
    </div>
  `;

  document.getElementById('nwSearch')?.addEventListener('input', e => {
    _searchQ = e.target.value;
    renderCenter();
  });
  document.getElementById('nwAddPerson')?.addEventListener('click', () => openAddPerson());

  // Cards
  const memberIds = _store.members[group.id] || [];
  const members   = memberIds
    .map(id => _allPeople.find(p => String(p.id) === String(id)))
    .filter(Boolean);

  const filtered = _searchQ
    ? members.filter(p => {
        const q = _searchQ.toLowerCase();
        const name = `${p.first_name} ${p.last_name}`.toLowerCase();
        const det = _store.details[String(p.id)] || {};
        return name.includes(q) || (det.expertise || '').toLowerCase().includes(q);
      })
    : members;

  if (filtered.length === 0) {
    area.innerHTML = `<div class="nw-no-group">${
      memberIds.length === 0
        ? 'No people in this group yet. Click "+ Add person" to begin.'
        : 'No people match your search.'
    }</div>`;
    return;
  }

  // Arrange cards in honeycomb rows: rows of 4, every even row offset
  const COLS = 4;
  const rows = [];
  for (let i = 0; i < filtered.length; i += COLS) {
    rows.push(filtered.slice(i, i + COLS));
  }

  area.innerHTML = `
    <div class="nw-hive-grid">
      ${rows.map((row, ri) => `
        <div class="nw-hive-row${ri % 2 === 1 ? ' nw-hive-row-offset' : ''}">
          ${row.map(p => cardHTML(p, group.id)).join('')}
        </div>`
      ).join('')}
    </div>`;

  area.querySelectorAll('.nw-card').forEach(el => {
    el.addEventListener('click', () => {
      _selectedPid = el.dataset.pid;
      renderSidebar();  // keep group list in sync
      renderCenter();   // re-render to update active state
      renderDetail(_selectedPid);
    });
  });

  area.querySelectorAll('.nw-card-remove').forEach(el => {
    el.addEventListener('click', e => {
      e.stopPropagation();
      removePerson(el.dataset.pid, el.dataset.gid);
    });
  });
}

function cardHTML(p, gid) {
  const det     = _store.details[String(p.id)] || {};
  const name    = `${p.first_name} ${p.last_name}`;
  const isActive = String(p.id) === String(_selectedPid);
  const initials = `${p.first_name?.[0] || ''}${p.last_name?.[0] || ''}`;
  const expertise = det.expertise ? det.expertise.split(',').map(e => e.trim()).slice(0, 2) : [];

