/* ── ORG HIVE PAGE ───────────────────────────────────────────── */
.org-hive-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: #000;
}
.org-hive-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 44px;
  padding: 0 20px;
  background: #000;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  flex-shrink: 0;
  gap: 16px;
}
.org-hive-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.org-hive-title {
  font-size: 13px;
  font-weight: 500;
  color: #c6c6c6;
}
.org-hive-subtitle {
  font-size: 11px;
  color: #3a3a3a;
}
.org-hive-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Sort buttons in org toolbar */
.org-sort-btn {
  padding: 3px 10px;
  font-size: 11px;
  font-family: inherit;
  border: 1px solid rgba(255,255,255,0.12);
  background: transparent;
  color: #525252;
  cursor: pointer;
  letter-spacing: 0.16px;
  transition: color 0.1s, background 0.1s, border-color 0.1s;
  border-radius: 0;
}
.org-sort-btn:hover { color: #c6c6c6; border-color: rgba(255,255,255,0.25); }
.org-sort-btn.active {
  color: #fff;
  background: rgba(69,137,255,0.15);
  border-color: rgba(69,137,255,0.5);
}

/* Person hex names — hidden by default, shown on zoom via JS */
.org-hex-name {
  transition: opacity 0.15s;
  pointer-events: none;
  user-select: none;
}
.org-group-label {
  transition: opacity 0.15s;
  pointer-events: none;
  user-select: none;
}

/* Person hex hover effect */
.person-hex polygon:first-child {
  transition: filter 0.12s;
}
.person-hex:hover polygon:first-child {
