}

/* ── ORG COLONY / PERSON MODAL ──────────────────────────────── */
.org-modal-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.7);
  z-index: 400;
  align-items: center;
  justify-content: center;
}
.org-modal-overlay.open { display: flex; }
.org-modal {
  background: #161616;
  border: 1px solid rgba(255,255,255,0.12);
  width: 460px;
  max-width: 90vw;
  max-height: 80vh;
  overflow-y: auto;
  padding: 0;
}
.org-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
