  color: #a8a8a8;
  letter-spacing: 0.16px;
  white-space: nowrap;
}
.res-product-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.res-product-pill {
  font-size: 12px;
  padding: 5px 12px;
  background: rgba(77,123,255,0.1);
