}
.mt-dp-label {
  font-size: 10px;
  color: #3a3a3a;
  font-weight: 400;
}
.mt-dp-value {
  font-size: 12px;
  color: #a8a8a8;
  line-height: 1.5;
}


/* ═══════════════════════════════════════════════════════════════
   ORGANIZATION TAB — org.js (ohive)
