/* Detail content */
.odp-content {
  padding: 24px 20px 40px;
  display: flex;
  flex-direction: column;
  gap: 0;
}
.odp-type-badge {
  font-size: 11px;
  font-weight: 400;
  color: #525252;
  margin-bottom: 8px;
}
.odp-title {
  font-size: 20px;
  font-weight: 300;
  color: #f4f4f4;
  letter-spacing: -0.2px;
  margin-bottom: 4px;
  line-height: 1.2;
}
.odp-sub {
  font-size: 12px;
  color: #525252;
  margin-bottom: 16px;
}
.odp-you-badge {
