}
.odp-works-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-bottom: 6px;
}
.odp-works-tag {
  font-size: 11px;
  padding: 3px 9px;
  border: 1px solid rgba(255,255,255,0.15);
