  border-radius: 0;
}
.mh-add-btn:hover { background: var(--ibm-blue-70); }

.mh-member-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1px;
  background: rgba(255,255,255,0.05);
  margin-bottom: 20px;
}
.mh-member-card {
  background: var(--surface);
  padding: 12px 14px;
  display: flex;
  align-items: center;
  gap: 12px;
}
.mh-mc-hex {
  width: 32px; height: 36px;
  clip-path: polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%);
  flex-shrink: 0;
  border: 2px solid;
}
.mh-mc-body { flex: 1; min-width: 0; }
.mh-mc-name { font-size: 13px; font-weight: 500; color: var(--text); }
.mh-mc-role { font-size: 11px; color: var(--muted); margin-top: 2px; }
.mh-mc-meta { font-size: 10px; color: #444; margin-top: 3px; }
.mh-mc-remove {
  background: none; border: none; color: #444; cursor: pointer;
  font-size: 13px; padding: 3px 5px; flex-shrink: 0;
  transition: color 0.1s;
}
.mh-mc-remove:hover { color: var(--accent-magenta); }

.mh-add-panel {
  border: 1px solid rgba(255,255,255,0.1);
  background: #111;
  padding: 12px;
  margin-top: 12px;
}
.mh-add-search {
  width: 100%;
  padding: 8px 10px;
  background: var(--surface-2);
  border: none;
  border-bottom: 2px solid var(--border);
  color: var(--text);
  font-size: 13px;
  font-family: inherit;
  outline: none;
  margin-bottom: 8px;
  transition: border-color 0.1s;
  border-radius: 0;
}
.mh-add-search:focus { border-bottom-color: var(--ibm-blue-50); }
.mh-add-results { display: flex; flex-direction: column; max-height: 240px; overflow-y: auto; }
.mh-add-result {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  cursor: pointer;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  transition: background 0.1s;
}
.mh-add-result:hover { background: var(--surface); }
.mh-ar-name { font-size: 13px; color: var(--text); flex: 1; }
.mh-ar-role { font-size: 11px; color: var(--muted); }
.mh-ar-add  { font-size: 11px; color: var(--ibm-blue-40); font-weight: 600; flex-shrink: 0; }

/* ═══════════════════════════════════════════════════════════════
   NETWORK TAB — network.js
   Full SVG honeycomb: you at center, contacts as hex nodes
   ═══════════════════════════════════════════════════════════════ */

.nw-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow: hidden;
  background: #000;
}

/* Toolbar strip */
.nw-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 52px;
  flex-shrink: 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  background: #0d0d0d;
}
.nw-toolbar-title {
  font-size: 13px;
  font-weight: 400;
  color: #525252;
  letter-spacing: 0.16px;
}
.nw-add-btn {
  padding: 6px 16px;
  background: transparent;
  border: 1px solid rgba(255,255,255,0.18);
  color: #a8a8a8;
  font-size: 12px;
  font-family: inherit;
  cursor: pointer;
  border-radius: 0;
  transition: color 0.1s, border-color 0.1s;
}
.nw-add-btn:hover { color: #fff; border-color: #4589ff; }

/* Scrollable SVG canvas */
.nw-canvas-wrap {
  flex: 1;
  overflow: auto;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 40px 80px;
}

/* ── Modal overlay ── */
.nw-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
}
.nw-modal {
  background: #161616;
  border: 1px solid rgba(255,255,255,0.12);
  width: 420px;
  max-width: calc(100vw - 40px);
  max-height: calc(100vh - 80px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.nw-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px 14px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
}
.nw-modal-title {
  font-size: 15px;
  font-weight: 400;
  color: #f4f4f4;
}
.nw-modal-close {
  background: transparent;
  border: none;
  color: #525252;
  font-size: 14px;
  cursor: pointer;
  padding: 2px 4px;
  line-height: 1;
  transition: color 0.1s;
}
.nw-modal-close:hover { color: #fff; }
.nw-modal-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  overflow-y: auto;
  flex: 1;
}
.nw-modal-label {
  display: flex;
  flex-direction: column;
  gap: 5px;
  font-size: 11px;
  color: #525252;
  font-weight: 400;
}
.nw-modal-input {
  padding: 7px 10px;
  background: #0d0d0d;
  border: none;
  border-bottom: 1px solid rgba(255,255,255,0.12);
  color: #e0e0e0;
  font-size: 13px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.1s;
  border-radius: 0;
}
.nw-modal-input:focus { border-bottom-color: #4589ff; }
.nw-modal-select {
  padding: 7px 10px;
  background: #0d0d0d;
  border: none;
  border-bottom: 1px solid rgba(255,255,255,0.12);
  color: #e0e0e0;
  font-size: 13px;
  font-family: inherit;
  outline: none;
  appearance: none;
  cursor: pointer;
  transition: border-color 0.1s;
  border-radius: 0;
}
.nw-modal-select:focus { border-bottom-color: #4589ff; }
.nw-modal-textarea {
  padding: 7px 10px;
  background: #0d0d0d;
  border: 1px solid rgba(255,255,255,0.08);
  color: #e0e0e0;
  font-size: 13px;
  font-family: inherit;
  outline: none;
  resize: vertical;
  line-height: 1.55;
  transition: border-color 0.1s;
  border-radius: 0;
}
.nw-modal-textarea:focus { border-color: #4589ff; }
.nw-modal-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 20px;
  border-top: 1px solid rgba(255,255,255,0.07);
  flex-shrink: 0;
}
.nw-modal-save {
  padding: 8px 20px;
  background: #4589ff;
  color: #fff;
  border: none;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  border-radius: 0;
  transition: background 0.1s;
}
.nw-modal-save:hover { background: #0f62fe; }
.nw-modal-cancel {
  padding: 8px 14px;
  background: transparent;
  border: 1px solid rgba(255,255,255,0.12);
  color: #8d8d8d;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  border-radius: 0;
  transition: color 0.1s;
}
.nw-modal-cancel:hover { color: #fff; }
.nw-modal-delete {
  padding: 8px 14px;
  background: transparent;
  border: 1px solid rgba(255,80,80,0.3);
  color: #ff6b6b;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
}
.nw-modal-delete:hover { background: rgba(255,80,80,0.1); }

