const COLS = 7, HEX_R = 32, COL_STEP = Math.sqrt(3)*HEX_R, ROW_STEP = HEX_R*1.5, LABEL_H = HEX_R*1.2, PAD = COL_STEP*0.8;
const COLONY_ORDER = ['Data & AI Colony','Automation Colony','Sustainability Colony','Security Colony','Infrastructure Colony','Hybrid Cloud Colony'];
const byColony = {};
