4 | import { getPerson, getAccount, getNotes, addNote } from './api.js';
5 | 
6 | const overlay = document.getElementById('panelOverlay');
7 | const dpClose  = document.getElementById('dpClose');
8 | 
9 | let _currentEntityType = null;
10 | let _currentEntityId   = null;
11 | 
12 | // ── Close ──────────────────────────────────────────────────────
13 | dpClose.addEventListener('click', close);
14 | overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
15 | 
16 | export function close() {
17 |   overlay.classList.remove('open');
18 |   _currentEntityType = null;
19 |   _currentEntityId   = null;
20 | }
