22 | // ── Open person panel ──────────────────────────────────────────
23 | export async function openPerson(id) {
24 |   overlay.classList.add('open');
25 |   renderLoading();
26 | 
27 |   const p = await getPerson(id);
28 |   _currentEntityType = 'person';
29 |   _currentEntityId   = id;
30 | 
31 |   setHeader(p.initials, p.color, p.first_name + ' ' + p.last_name, p.role, p.market + ' Market');
32 | 
33 |   setContact(p.email, p.slack, p.location);
34 | 
35 |   // Relationship tags
36 |   const conn = p.connection;
37 |   const tagMap = { close_ally:'Close Ally', partner:'Partner', cross_brand:'Cross-brand', client:'Client', peer:'Peer' };
38 |   const tags = conn ? [tagMap[conn.relationship]] : [];
39 |   if (p.role_type === 'exec')     tags.push('Executive');
40 |   if (p.role_type === 'director') tags.push('Director');
41 |   if (p.role_type === 'manager')  tags.push('Manager');
42 |   if (p.is_current_user)          tags.push('You');
43 | 
44 |   setTags(tags);
45 |   document.getElementById('dpMet').textContent = conn?.how_we_met || '—';
46 | 
47 |   const notes = await getNotes('person', id);
48 |   renderNotes(notes);
49 |   wireNoteForm();
50 | }
