71 | async function renderHierarchy(me, people) {
72 |   const container = document.getElementById('seller-tab-hier');
73 | 
74 |   // Build levels: chain up from current user to root
75 |   const byId = {};
76 |   people.forEach(p => { byId[p.id] = p; });
77 | 
78 |   const chain = [me];
79 |   let cur = me;
80 |   while (cur.manager_id && byId[cur.manager_id]) {
81 |     cur = byId[cur.manager_id];
82 |     chain.unshift(cur);
83 |   }
84 | 
85 |   // Direct peers (same manager)
86 |   const peers = people.filter(p =>
87 |     p.manager_id === me.manager_id && !p.is_current_user
88 |   );
89 | 
90 |   const legend = `
91 |     <div class="role-legend">
92 |       <div class="rl-item"><div class="rl-dot" style="background:var(--c-exec)"></div>VP / Exec</div>
93 |       <div class="rl-item"><div class="rl-dot" style="background:var(--c-director)"></div>Director</div>
94 |       <div class="rl-item"><div class="rl-dot" style="background:var(--c-manager)"></div>Manager</div>
95 |       <div class="rl-item"><div class="rl-dot" style="background:var(--c-you)"></div>You</div>
96 |       <div class="rl-item"><div class="rl-dot" style="background:var(--c-peer)"></div>Peer</div>
97 |     </div>
98 |   `;
