103 |       ${orgCard(p, '')}
104 |     </div>
105 |     <div class="org-connector"><div class="org-connector-line"></div></div>
106 |   `).join('');
107 | 
108 |   // Render my manager (last in chain before me)
109 |   const manager = chain.length > 1 ? chain[chain.length - 2] : null;
110 | 
111 |   // Peer row including "you"
112 |   const peerRow = `
113 |     <div class="org-level" style="gap:12px">
114 |       ${peers.slice(0, 2).map(p => orgCard(p, 'peer')).join('')}
115 |       ${orgCard(me, 'you')}
116 |       ${peers.slice(2).map(p => orgCard(p, 'peer')).join('')}
117 |     </div>
118 |   `;
