120 |   container.innerHTML = legend + `
121 |     <div class="org-tree">
122 |       ${chainHtml}
123 |       <div class="org-level">${orgCard(chain[chain.length - (chain.length > 1 ? 2 : 1)], 'highlight')}</div>
124 |       <div class="org-connector"><div class="org-connector-line"></div></div>
125 |       ${peerRow}
126 |     </div>
127 |   `;
