135 | async function renderCell(me, people) {
136 |   const container = document.getElementById('seller-tab-cell');
137 | 
138 |   const cellMembers = people.filter(p =>
139 |     p.manager_id === me.manager_id || p.id === me.manager_id
140 |   );
141 | 
142 |   const legend = `
143 |     <div class="role-legend">
144 |       <div class="rl-item"><div class="rl-dot" style="background:var(--c-manager)"></div>Manager</div>
145 |       <div class="rl-item"><div class="rl-dot" style="background:var(--c-you)"></div>You</div>
146 |       <div class="rl-item"><div class="rl-dot" style="background:var(--c-peer)"></div>Peer AE</div>
147 |       <div class="rl-item"><div class="rl-dot" style="background:var(--c-tech)"></div>Technical</div>
148 |     </div>
149 |   `;
150 | 
151 |   // Build rows: manager on top, then grid of peers
152 |   const manager = people.find(p => p.id === me.manager_id);
153 |   const others  = cellMembers.filter(p => p.id !== me.manager_id);
154 |   const withMe  = [me, ...others];
155 | 
156 |   // Chunk into rows of 3
157 |   const rows = [];
158 |   if (manager) rows.push([manager]);
159 |   for (let i = 0; i < withMe.length; i += 3) {
160 |     rows.push(withMe.slice(i, i + 3));
161 |   }
162 | 
163 |   const hexRows = rows.map(row => `
164 |     <div class="hex-row">
165 |       ${row.map(p => `
166 |         <div class="hex-wrap" data-person-id="${p.id}">
167 |           <div class="hex ${ROLE_CATEGORY[p.role_type] || ''}" style="background:${p.is_current_user ? 'var(--c-you)' : ROLE_COLORS[p.role_type] || 'var(--c-other)'}">
168 |             <div class="hex-name">${p.first_name} ${p.last_name.charAt(0)}.</div>
169 |             <div class="hex-role">${p.role_type.toUpperCase()}</div>
170 |           </div>
171 |         </div>
172 |       `).join('')}
173 |     </div>
174 |   `).join('');
175 | 
176 |   const catLegend = `
177 |     <div class="cat-legend">
178 |       <div class="cat-legend-item"><div class="cat-legend-marker cat-sales"></div>Sales Roles</div>
179 |       <div class="cat-legend-item"><div class="cat-legend-marker cat-tech"></div>Technical Roles</div>
180 |       <div class="cat-legend-item"><div class="cat-legend-marker cat-support"></div>Ecosystem Roles</div>
181 |     </div>
182 |   `;
183 | 
184 |   container.innerHTML = legend + `<div class="hive-container">${hexRows}</div>` + catLegend;
185 | 
186 |   container.querySelectorAll('[data-person-id]').forEach(el => {
187 |     el.addEventListener('click', () => openPerson(el.dataset.personId));
188 |   });
189 | }
