1 | /**
2 |  * network.js — Connections view (personal CRM), full create/edit/delete
3 |  */
4 | import { getNetwork, getPeople, addConnection, updateConnection, deleteConnection } from '../api.js';
5 | import { openPerson } from '../panel.js';
6 | 
7 | const TAG_LABELS = {
8 |   close_ally:  'Close Ally',
9 |   partner:     'Partner',
10 |   cross_brand: 'Cross-brand',
11 |   client:      'Client',
12 |   peer:        'Peer',
13 | };
14 | 
15 | const TAG_CLASSES = {
16 |   close_ally:  'tag-close',
17 |   partner:     'tag-partner',
18 |   cross_brand: 'tag-cross',
19 |   client:      'tag-client',
20 |   peer:        'tag-peer',
21 | };
22 | 
23 | let connections = [];
24 | let allPeople   = [];
25 | let editingId   = null; // null = create mode, otherwise connection id being edited
26 | 
27 | // ── Modal elements (shared markup lives in public/index.html) ─────
28 | const modalOverlay  = document.getElementById('modalOverlay');
29 | const modalTitle    = document.getElementById('modalTitle');
30 | const modalClose    = document.getElementById('modalClose');
31 | const cfForm        = document.getElementById('connectionForm');
32 | const cfPersonRow   = document.getElementById('cfPersonRow');
33 | const cfPerson      = document.getElementById('cfPerson');
34 | const cfRelationship= document.getElementById('cfRelationship');
35 | const cfHowWeMet    = document.getElementById('cfHowWeMet');
36 | const cfNotes       = document.getElementById('cfNotes');
37 | const cfFollowup    = document.getElementById('cfFollowup');
38 | const cfDelete      = document.getElementById('cfDelete');
39 | const cfCancel      = document.getElementById('cfCancel');
40 | 
41 | export async function renderNetwork(container) {
42 |   container.innerHTML = `
43 |     <div class="page-header">
44 |       <div class="page-title">Connections</div>
45 |       <div class="page-sub">Personal connections within IBM — relationships, context, open notes</div>
46 |     </div>
47 |     <div class="content">
48 |       <div id="network-stats" class="stat-row"></div>
49 |       <div class="toolbar">
50 |         <input class="search-box" id="networkSearch" type="text" placeholder="Search connections…"/>
51 |         <select class="sort-select" id="networkFilter">
52 |           <option value="">All Relationships</option>
53 |           <option value="close_ally">Close Ally</option>
54 |           <option value="partner">Partner</option>
55 |           <option value="cross_brand">Cross-brand</option>
56 |           <option value="client">Client</option>
57 |           <option value="peer">Peer</option>
58 |         </select>
59 |         <div style="flex:1"></div>
60 |         <button class="btn-primary" id="addConnectionBtn">+ Add Connection</button>
61 |       </div>
62 |       <div id="network-grid" class="network-grid"><div class="loading">Loading…</div></div>
63 |     </div>
64 |   `;
65 | 
66 |   [connections, allPeople] = await Promise.all([getNetwork(), getPeople()]);
67 |   renderStats(connections);
68 | 
69 |   function redraw() {
70 |     const search = document.getElementById('networkSearch')?.value.toLowerCase() || '';
71 |     const filter = document.getElementById('networkFilter')?.value || '';
72 |     const filtered = connections.filter(c => {
73 |       const name = (c.first_name + ' ' + c.last_name).toLowerCase();
74 |       const matchSearch = !search || name.includes(search) || c.role.toLowerCase().includes(search);
75 |       const matchFilter = !filter || c.relationship === filter;
76 |       return matchSearch && matchFilter;
77 |     });
78 |     renderCards(filtered);
79 |   }
80 | 
81 |   document.getElementById('networkSearch')?.addEventListener('input', redraw);
82 |   document.getElementById('networkFilter')?.addEventListener('change', redraw);
83 |   document.getElementById('addConnectionBtn')?.addEventListener('click', () => openModal('create'));
84 | 
85 |   redraw();
86 |   wireModal();
87 | }
88 | 
89 | function renderStats(list) {
90 |   const total     = list.length;
91 |   const allies    = list.filter(c => c.relationship === 'close_ally').length;
92 |   const crossBrand= list.filter(c => c.relationship === 'cross_brand').length;
93 |   const followup  = list.filter(c => c.needs_followup).length;
94 | 
95 |   document.getElementById('network-stats').innerHTML = `
96 |     <div class="stat-card"><div class="stat-num">${total}</div><div class="stat-label">Connections</div></div>
97 |     <div class="stat-card"><div class="stat-num">${allies}</div><div class="stat-label">Close Allies</div></div>
98 |     <div class="stat-card"><div class="stat-num">${crossBrand}</div><div class="stat-label">Cross-Brand</div></div>
99 |     <div class="stat-card"><div class="stat-num" style="color:var(--accent-magenta)">${followup}</div><div class="stat-label">Need Follow-up</div></div>
100 |   `;
101 | }
102 | 
103 | function renderCards(list) {
104 |   const grid = document.getElementById('network-grid');
105 |   if (!grid) return;
106 | 
107 |   if (!list.length) {
108 |     grid.innerHTML = '<div class="loading">No connections match.</div>';
109 |     return;
110 |   }
111 | 
112 |   grid.innerHTML = list.map(c => `
113 |     <div class="network-card" data-person-id="${c.person_id}">
114 |       <div class="nc-top">
115 |         <div class="nc-avatar" style="background:${c.color}">${c.initials}</div>
116 |         <div>
117 |           <div class="nc-name">${c.first_name} ${c.last_name}</div>
118 |           <div class="nc-role">${c.role}</div>
119 |         </div>
120 |         <div class="nc-actions">
121 |           <div class="nc-icon-btn" data-edit-id="${c.id}" title="Edit">✎</div>
122 |           <div class="nc-icon-btn danger" data-delete-id="${c.id}" title="Delete">🗑</div>
123 |         </div>
124 |       </div>
125 |       <span class="nc-tag ${TAG_CLASSES[c.relationship] || ''}">${TAG_LABELS[c.relationship] || c.relationship}</span>
126 |       ${c.needs_followup ? '<div class="nc-followup">⚠ Follow-up needed</div>' : ''}
127 |       ${c.notes ? `<div class="nc-note">${c.notes}</div>` : ''}
128 |     </div>
129 |   `).join('');
130 | 
131 |   grid.querySelectorAll('.network-card').forEach(el => {
132 |     el.addEventListener('click', () => openPerson(el.dataset.personId));
133 |   });
134 |   grid.querySelectorAll('[data-edit-id]').forEach(el => {
135 |     el.addEventListener('click', e => {
136 |       e.stopPropagation();
137 |       const conn = connections.find(c => String(c.id) === el.dataset.editId);
138 |       if (conn) openModal('edit', conn);
139 |     });
140 |   });
141 |   grid.querySelectorAll('[data-delete-id]').forEach(el => {
142 |     el.addEventListener('click', async e => {
143 |       e.stopPropagation();
144 |       const conn = connections.find(c => String(c.id) === el.dataset.deleteId);
145 |       if (!conn) return;
146 |       if (!confirm(`Remove ${conn.first_name} ${conn.last_name} from your connections?`)) return;
147 |       await deleteConnection(conn.id);
148 |       connections = await getNetwork();
149 |       renderStats(connections);
150 |       renderCards(connections);
151 |     });
152 |   });
153 | }
154 | 
155 | // ── Modal (create / edit) ──────────────────────────────────────────
156 | function openModal(mode, conn) {
157 |   editingId = mode === 'edit' ? conn.id : null;
158 |   modalTitle.textContent = mode === 'edit' ? 'Edit Connection' : 'Add Connection';
159 |   cfDelete.style.display = mode === 'edit' ? 'inline-block' : 'none';
160 | 
161 |   if (mode === 'create') {
162 |     const connectedIds = new Set(connections.map(c => String(c.person_id)));
163 |     const candidates = allPeople.filter(p => !p.is_current_user && !connectedIds.has(String(p.id)));
164 |     cfPerson.innerHTML = candidates
165 |       .map(p => `<option value="${p.id}">${p.first_name} ${p.last_name} — ${p.role}</option>`)
166 |       .join('');
167 |     cfPersonRow.style.display = '';
168 |     cfRelationship.value = 'peer';
169 |     cfHowWeMet.value = '';
170 |     cfNotes.value = '';
171 |     cfFollowup.checked = false;
172 |   } else {
173 |     cfPersonRow.style.display = 'none';
174 |     cfRelationship.value = conn.relationship;
175 |     cfHowWeMet.value = conn.how_we_met || '';
176 |     cfNotes.value = conn.notes || '';
177 |     cfFollowup.checked = !!conn.needs_followup;
178 |   }
179 | 
180 |   modalOverlay.classList.add('open');
181 | }
182 | 
183 | function closeModal() {
184 |   modalOverlay.classList.remove('open');
185 |   editingId = null;
186 | }
187 | 
188 | function wireModal() {
189 |   modalClose.onclick  = closeModal;
190 |   cfCancel.onclick    = closeModal;
191 |   modalOverlay.onclick = e => { if (e.target === modalOverlay) closeModal(); };
192 | 
193 |   cfDelete.onclick = async () => {
194 |     if (!editingId) return;
195 |     const conn = connections.find(c => c.id === editingId);
196 |     if (!confirm(`Remove ${conn?.first_name || 'this person'} from your connections?`)) return;
197 |     await deleteConnection(editingId);
198 |     closeModal();
199 |     connections = await getNetwork();
200 |     renderStats(connections);
201 |     renderCards(connections);
202 |   };
203 | 
204 |   cfForm.onsubmit = async e => {
205 |     e.preventDefault();
206 |     const body = {
207 |       relationship: cfRelationship.value,
208 |       how_we_met: cfHowWeMet.value.trim() || null,
209 |       notes: cfNotes.value.trim() || null,
210 |       needs_followup: cfFollowup.checked,
211 |     };
212 | 
213 |     if (editingId) {
214 |       await updateConnection(editingId, body);
215 |     } else {
216 |       if (!cfPerson.value) return;
217 |       await addConnection({ person_id: cfPerson.value, ...body });
218 |     }
219 | 
220 |     closeModal();
221 |     connections = await getNetwork();
222 |     renderStats(connections);
223 |     renderCards(connections);
224 |   };
225 | }
