17 | export async function renderAccounts(container) {
18 |   container.innerHTML = `
19 |     <div class="page-header">
20 |       <div class="page-title">Account Hive</div>
21 |       <div class="page-sub">All your accounts in one comb — color coded by pipeline stage</div>
22 |     </div>
23 |     <div class="content">
24 |       <div id="acct-stats" class="stat-row"></div>
25 |       <div class="accounts-toolbar">
26 |         <button class="acct-filter active" data-stage="">All</button>
