28 |         <div class="acct-legend">
29 |           ${Object.entries(STAGE_COLORS).map(([stage, color]) => `
30 |             <div class="legend-item">
31 |               <div class="legend-dot" style="background:${color}"></div>${stage}
32 |             </div>
33 |           `).join('')}
34 |         </div>
