37 |         <div class="loading">Loading…</div>
38 |       </div>
39 |     </div>
40 |   `;
41 | 
42 |   const accounts = await getAccounts();
43 |   renderStats(accounts);
44 | 
45 |   let activeStage = '';
46 | 
47 |   function redraw() {
48 |     renderHive(accounts, activeStage);
49 |   }
50 | 
51 |   container.querySelectorAll('.acct-filter').forEach(btn => {
52 |     btn.addEventListener('click', () => {
53 |       container.querySelectorAll('.acct-filter').forEach(b => b.classList.remove('active'));
54 |       btn.classList.add('active');
55 |       activeStage = btn.dataset.stage;
56 |       redraw();
57 |     });
58 |   });
59 | 
60 |   redraw();
