63 | function renderStats(accounts) {
64 |   const el = document.getElementById('acct-stats');
65 |   if (!el) return;
66 | 
67 |   const total     = accounts.length;
68 |   const closedWon = accounts.filter(a => a.stage === 'Closed Won').reduce((s,a) => s + (a.value_usd||0), 0);
69 |   const pipeline  = accounts.filter(a => ['Negotiation','Proposal'].includes(a.stage)).reduce((s,a) => s + (a.value_usd||0), 0);
70 |   const atRisk    = accounts.filter(a => a.stage === 'At Risk').reduce((s,a) => s + (a.value_usd||0), 0);
71 | 
72 |   el.innerHTML = `
73 |     <div class="stat-card"><div class="stat-num">${total}</div><div class="stat-label">Accounts</div></div>
74 |     <div class="stat-card"><div class="stat-num" style="color:var(--stage-won)">${fmt(closedWon)}</div><div class="stat-label">Closed Won</div></div>
75 |     <div class="stat-card"><div class="stat-num" style="color:var(--accent-blue)">${fmt(pipeline)}</div><div class="stat-label">Active Pipeline</div></div>
