    insertPerson.run({ first_name:'Omar', last_name:'Diaz', initials:'OD', role:'Sales Development Rep', role_type:'sdr', market_id:mkt['Territory'], comb_id:combMap['Automation Colony'], manager_id:sofia, email:'omar.diaz@ibm.com', slack:'@omar.d', location:'New York, NY', color:'#7e22ce', is_current_user:0, joined_date:'2023-02-01' });
    const omar = lastId();

    insertPerson.run({ first_name:'Carlos', last_name:'Vega', initials:'CV', role:'Automation CSM', role_type:'csm', market_id:mkt['Horizon'], comb_id:combMap['Automation Colony'], manager_id:sofia, email:'carlos.vega@ibm.com', slack:'@carlos.v', location:'Miami, FL', color:'#4338ca', is_current_user:0, joined_date:'2020-02-01' });

