  'Hybrid Cloud Colony':   '#ee5396',
};

const COLONY_ORDER = [
  'Data & AI Colony',
  'Automation Colony',
  'Sustainability Colony',
  'Security Colony',
  'Infrastructure Colony',
  'Hybrid Cloud Colony',
];

const ROLE_ORDER = { exec: 0, director: 1, manager: 2, ae: 3, tse: 4, csm: 5, sdr: 6, partner: 7, other: 8 };

export async function renderColony(container) {
  container.innerHTML = `
    <div class="colony-page">
      <div class="colony-toolbar">
        <div class="colony-toolbar-left">
          <span class="colony-title">IBM Hive</span>
          <span class="colony-subtitle">All Colonies · ${0} people</span>
        </div>
        <div class="colony-toolbar-controls">
          <select class="sort-select" id="colonySort">
            <option value="colony">Group by Colony</option>
            <option value="role">Sort by Role</option>
            <option value="name">Sort by Name</option>
          </select>
          <button class="colony-zoom-btn" id="colonyZoomIn"  title="Zoom in">+</button>
          <button class="colony-zoom-btn" id="colonyZoomOut" title="Zoom out">−</button>
          <button class="colony-zoom-btn" id="colonyZoomReset" title="Reset zoom" style="font-size:11px;letter-spacing:0.5px">FIT</button>
        </div>
      </div>
      <div class="colony-viewport" id="colonyViewport">
        <div class="colony-canvas" id="colonyCanvas">
          <div class="loading">Loading…</div>
        </div>
      </div>
    </div>
  `;

  const people = await getPeople();

  // Update subtitle count
  container.querySelector('.colony-subtitle').textContent =
    `All Colonies · ${people.length} people`;

  let sortMode = 'colony';

  function redraw() {
    renderGrid(people, sortMode);
    wireZoom();
  }

  document.getElementById('colonySort')?.addEventListener('change', e => {
    sortMode = e.target.value;
    redraw();
  });

  redraw();
}

function renderGrid(people, sortMode) {
  const canvas = document.getElementById('colonyCanvas');
  if (!canvas) return;

  let sorted = [...people];

  if (sortMode === 'name') {
    sorted.sort((a, b) => (a.first_name + a.last_name).localeCompare(b.first_name + b.last_name));
  } else if (sortMode === 'role') {
    sorted.sort((a, b) => (ROLE_ORDER[a.role_type] ?? 9) - (ROLE_ORDER[b.role_type] ?? 9));
  }
  // 'colony' default — group by comb

  if (sortMode === 'colony') {
    // Group into colony clusters
    const byColony = {};
    COLONY_ORDER.forEach(c => { byColony[c] = []; });
    sorted.forEach(p => {
      const key = p.comb || 'Other';
      if (!byColony[key]) byColony[key] = [];
      byColony[key].push(p);
    });

    let html = '<div class="colony-grid">';
    COLONY_ORDER.forEach(colonyName => {
      const members = byColony[colonyName] || [];
      if (!members.length) return;
      const color = COLONY_COLORS[colonyName] || '#525252';
      html += renderColonyCluster(colonyName, members, color);
    });
    html += '</div>';
    canvas.innerHTML = html;
  } else {
    // Flat grid — all people in a single hive
    const ROW = 8;
    const rows = [];
    for (let i = 0; i < sorted.length; i += ROW) {
      rows.push(sorted.slice(i, i + ROW));
    }
    let html = '<div class="colony-flat-grid">';
    rows.forEach((row, ri) => {
      html += `<div class="chex-row${ri % 2 === 1 ? ' chex-row-offset' : ''}">`;
      row.forEach(p => { html += hexCell(p); });
      html += '</div>';
    });
    html += '</div>';
    canvas.innerHTML = html;
  }

  // Wire clicks
  canvas.querySelectorAll('[data-person-id]').forEach(el => {
    el.addEventListener('click', () => openPerson(el.dataset.personId));
  });
}

function renderColonyCluster(name, members, color) {
  // Sort members: exec first, then by role order
  const sorted = [...members].sort((a, b) =>
    (ROLE_ORDER[a.role_type] ?? 9) - (ROLE_ORDER[b.role_type] ?? 9)
  );

  // Pack into rows of 6 for a tight hex cluster
  const ROW = 6;
  const rows = [];
  for (let i = 0; i < sorted.length; i += ROW) {
    rows.push(sorted.slice(i, i + ROW));
  }

  let hexHtml = '';
  rows.forEach((row, ri) => {
    hexHtml += `<div class="chex-row${ri % 2 === 1 ? ' chex-row-offset' : ''}">`;
    row.forEach(p => { hexHtml += hexCell(p, color); });
    hexHtml += '</div>';
  });

  return `
    <div class="colony-cluster" style="--colony-color:${color}">
      <div class="colony-cluster-label">
        <span class="colony-cluster-dot" style="background:${color}"></span>
        ${name}
        <span class="colony-cluster-count">${members.length}</span>
      </div>
      <div class="colony-cluster-hex">${hexHtml}</div>
    </div>
  `;
}

function hexCell(p, clusterColor) {
  // Color: current user → blue, exec → colony/exec color, else person color
  let bg = p.color || '#525252';
  if (p.is_current_user) bg = '#4589ff';
  else if (clusterColor && p.role_type === 'exec') bg = clusterColor;

  const isYou = p.is_current_user ? ' chex-you' : '';
  const name = p.first_name + ' ' + p.last_name;
  // Shorten name if very long
  const displayName = name.length > 14
    ? p.first_name + ' ' + p.last_name.charAt(0) + '.'
    : name;

  return `
    <div class="chex-wrap${isYou}" data-person-id="${p.id}" title="${name} — ${p.role}">
      <div class="chex" style="background:${bg}">
        <span class="chex-name">${displayName}</span>
      </div>
    </div>
  `;
}

// ── Zoom / Pan ─────────────────────────────────────────────────
function wireZoom() {
  const viewport = document.getElementById('colonyViewport');
  const canvas   = document.getElementById('colonyCanvas');
  if (!viewport || !canvas) return;

  let scale = 1;
  let tx = 0, ty = 0;
  let dragging = false, sx = 0, sy = 0, stx = 0, sty = 0;

  function applyTransform() {
    canvas.style.transform = `translate(${tx}px, ${ty}px) scale(${scale})`;
  }

  // Zoom buttons
  document.getElementById('colonyZoomIn')?.addEventListener('click', () => {
    scale = Math.min(scale * 1.3, 4);
    applyTransform();
  });
  document.getElementById('colonyZoomOut')?.addEventListener('click', () => {
    scale = Math.max(scale / 1.3, 0.25);
    applyTransform();
  });
  document.getElementById('colonyZoomReset')?.addEventListener('click', () => {
    scale = 1; tx = 0; ty = 0;
    applyTransform();
  });

  // Scroll-to-zoom
  viewport.addEventListener('wheel', e => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    const newScale = Math.min(Math.max(scale * delta, 0.25), 4);

    // Zoom toward cursor
    const rect = viewport.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;
    tx = mx - (mx - tx) * (newScale / scale);
    ty = my - (my - ty) * (newScale / scale);
    scale = newScale;
    applyTransform();
  }, { passive: false });

  // Drag to pan
  viewport.addEventListener('mousedown', e => {
    if (e.button !== 0) return;
    dragging = true;
    sx = e.clientX; sy = e.clientY;
    stx = tx; sty = ty;
    viewport.style.cursor = 'grabbing';
  });
  window.addEventListener('mousemove', e => {
    if (!dragging) return;
    tx = stx + (e.clientX - sx);
    ty = sty + (e.clientY - sy);
    applyTransform();
  });
  window.addEventListener('mouseup', () => {
    dragging = false;
    if (viewport) viewport.style.cursor = 'grab';
  });

  // Touch pan
  let lt = null;
  viewport.addEventListener('touchstart', e => {
    if (e.touches.length === 1) {
      lt = { x: e.touches[0].clientX, y: e.touches[0].clientY, tx, ty };
    }
  }, { passive: true });
  viewport.addEventListener('touchmove', e => {
    if (!lt || e.touches.length !== 1) return;
    tx = lt.tx + (e.touches[0].clientX - lt.x);
    ty = lt.ty + (e.touches[0].clientY - lt.y);
    applyTransform();
  }, { passive: true });
  viewport.addEventListener('touchend', () => { lt = null; });
}

