/**
 * app.js — boot, navigation, and view orchestration
 */
import { getPeople }      from './api.js';
import { renderColony }   from './views/colony.js';
import { renderSeller }   from './views/seller.js';
import { renderNetwork }  from './views/network.js';
import { renderAccounts } from './views/accounts.js';

// ── Boot: populate current user in nav ────────────────────────
async function boot() {
  try {
    const people = await getPeople();
    const me = people.find(p => p.is_current_user);
    if (me) {
      document.getElementById('currentUserName').textContent = me.first_name + ' ' + me.last_name;
      // Avatar shows no initials — just the hex shape
      document.getElementById('currentUserAvatar').textContent = '';
    }
  } catch (e) {
    console.warn('Could not load user from API:', e.message);
  }
}

// ── Profile / account switcher dropdown ──────────────────────
function wireProfileDropdown() {
  const userSection = document.getElementById('topnavUser');
  const dropdown    = document.getElementById('userDropdown');
  const avatar      = document.getElementById('currentUserAvatar');

  if (!userSection || !dropdown) return;

  // Toggle on avatar or name click
  function toggleDropdown(e) {
    e.stopPropagation();
    dropdown.classList.toggle('open');
  }
  avatar.addEventListener('click', toggleDropdown);
  document.getElementById('currentUserName')?.addEventListener('click', toggleDropdown);

  // Close on outside click
  document.addEventListener('click', e => {
    if (!userSection.contains(e.target)) {
      dropdown.classList.remove('open');
    }
  });

  // Profile switcher items
  dropdown.querySelectorAll('.user-dropdown-item').forEach(item => {
    item.addEventListener('click', e => {
      e.stopPropagation();
      dropdown.querySelectorAll('.user-dropdown-item').forEach(i => i.classList.remove('active'));
      item.classList.add('active');

      const profile = item.dataset.profile;
      const nameEl  = document.getElementById('currentUserName');

      if (profile === 'sydney') {
        nameEl.textContent = 'Sydney Chin';
        document.getElementById('currentUserAvatar').style.background = 'var(--accent-gradient)';
      } else if (profile === 'manager') {
        nameEl.textContent = 'Chris Kennedy';
        document.getElementById('currentUserAvatar').style.background = '#6c63ff';
      } else if (profile === 'admin') {
        nameEl.textContent = 'Admin';
        document.getElementById('currentUserAvatar').style.background = '#da1e28';
      }

      dropdown.classList.remove('open');
    });
  });
}

// ── View registry ─────────────────────────────────────────────
const VIEW_RENDERERS = {
  colony:   renderColony,
  seller:   renderSeller,
  network:  renderNetwork,
  accounts: renderAccounts,
};

const rendered = new Set();

async function activateView(viewName) {
  // Update sidebar
  document.querySelectorAll('.nav-item').forEach(n => {
    n.classList.toggle('active', n.dataset.view === viewName);
  });

  // Update top nav links
  document.querySelectorAll('.topnav-link[data-view-link]').forEach(n => {
    n.classList.toggle('active', n.dataset.viewLink === viewName);
  });

  // Show the right view container
  document.querySelectorAll('.main > .view').forEach(v => {
    v.classList.toggle('active', v.id === `view-${viewName}`);
  });

  // Render the view if not already rendered
  const container = document.getElementById(`view-${viewName}`);
  if (!container) return;

  if (!rendered.has(viewName)) {
    rendered.add(viewName);
    try {
      await VIEW_RENDERERS[viewName]?.(container);
    } catch (err) {
      container.innerHTML = `
        <div class="page-header">
          <div class="page-title">Error</div>
          <div class="page-sub">Could not load view: ${err.message}</div>
        </div>
        <div class="content" style="color:var(--muted);font-size:13px">
          Make sure the server is running (<code>npm start</code>) and the database is seeded (<code>npm run seed</code>).
        </div>
      `;
    }
  }
}

// ── Sidebar nav clicks ────────────────────────────────────────
document.querySelectorAll('.nav-item').forEach(item => {
  item.addEventListener('click', () => activateView(item.dataset.view));
});

// ── Top nav link clicks ───────────────────────────────────────
document.querySelectorAll('.topnav-link[data-view-link]').forEach(item => {
  item.addEventListener('click', () => activateView(item.dataset.viewLink));
});

// ── Init ──────────────────────────────────────────────────────
boot();
wireProfileDropdown();
activateView('colony');

