.colony-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.colony-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.16px;
}
.colony-subtitle {
  font-size: 12px;
  color: var(--muted);
}
.colony-toolbar-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}
.colony-zoom-btn {
  width: 32px;
  height: 32px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-secondary);
  font-size: 18px;
  font-family: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
  flex-shrink: 0;
}
.colony-zoom-btn:hover { background: var(--surface-2); color: #fff; }

/* The scrollable viewport — cursor:grab, overflow:hidden */
.colony-viewport {
  flex: 1;
  overflow: hidden;
  position: relative;
  cursor: grab;
  background: var(--bg);
}
.colony-viewport:active { cursor: grabbing; }

/* The transformable canvas inside the viewport */
.colony-canvas {
  position: absolute;
  top: 0;
  left: 0;
  transform-origin: top left;
  padding: 32px 24px 80px;
  will-change: transform;
}

/* Grid that arranges colony clusters side by side */
.colony-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 40px 48px;
  align-items: flex-start;
}

/* Flat grid mode */
.colony-flat-grid {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding-bottom: 40px;
}

/* ── Colony cluster block ─────────────────────────────────── */
