/* ─────────────────────────────────────────────────────────────
   IBM Hive — hive.css
   IBM Carbon / w3 dark theme.
   ───────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* IBM Carbon blue palette */
  --ibm-blue-10:  #edf5ff;
  --ibm-blue-40:  #78a9ff;
  --ibm-blue-50:  #4589ff;
  --ibm-blue-60:  #0f62fe;
  --ibm-blue-70:  #0043ce;

  /* IBM Purple palette */
  --ibm-purple-40: #be95ff;
  --ibm-purple-50: #a56eff;
  --ibm-purple-60: #8a3ffc;

  /* Accent aliases */
  --accent-blue:     var(--ibm-blue-50);
  --accent-blue-dark:var(--ibm-blue-60);
  --accent-indigo:   #6c63ff;
  --accent-violet:   #8b5cf6;
  --accent-purple:   var(--ibm-purple-50);
  --accent-magenta:  #d946ef;
  --accent-gradient: linear-gradient(135deg, var(--ibm-blue-60) 0%, var(--ibm-purple-60) 100%);

  /* Back-compat aliases */
  --ibm-blue:      var(--ibm-blue-50);
  --ibm-blue-dark: var(--ibm-blue-60);

  /* IBM Carbon Gray 100 surfaces (w3 dark) */
  --bg:         #161616;
  --nav-bg:     #161616;
  --sidebar-bg: #1c1c1c;
  --surface:    #262626;
  --surface-2:  #393939;
  --border:     #525252;
  --border-subtle: #393939;
  --text:       #f4f4f4;
  --text-secondary: #c6c6c6;
  --muted:      #8d8d8d;

  /* Hex border */
  --hex-border: rgba(255,255,255,0.85);

  /* Role / seniority color spectrum */
  --c-exec:     #d946ef;
  --c-director: #a855f7;
  --c-manager:  #6c63ff;
  --c-you:      var(--ibm-blue-50);
  --c-peer:     #60a5fa;
  --c-tech:     #a78bfa;
  --c-csm:      #4338ca;
  --c-sdr:      #7e22ce;
  --c-partner:  #e879f9;
  --c-other:    #525252;
  --c-open:     var(--surface-2);

  /* Pipeline stage spectrum */
  --stage-won:         #0f62fe;
  --stage-negotiation: #6c63ff;
  --stage-proposal:    #8a3ffc;
  --stage-risk:        #d946ef;
  --stage-prospect:    #525252;

  /* Market spectrum */
  --mkt-enterprise: #0f62fe;
  --mkt-strategic:  #a855f7;
  --mkt-horizon:    #6c63ff;
  --mkt-territory:  #d946ef;
}

body {
  font-family: "IBM Plex Sans", -apple-system, "Segoe UI", system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-size: 14px;
  line-height: 1.5;
}

/* ── TOP NAV (IBM w3 style) ───────────────────────────────────── */
.topnav {
  background: #000000;
  color: #fff;
  display: flex;
  align-items: center;
  padding: 0;
  height: 64px;
  flex-shrink: 0;
  border-bottom: 1px solid rgba(255,255,255,0.12);
  gap: 0;
}

.topnav-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.16px;
  padding: 0 20px;
  height: 100%;
  border-right: 1px solid rgba(255,255,255,0.12);
  color: #fff;
  flex-shrink: 0;
}

.logo-img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  display: block;
  flex-shrink: 0;
}

/* Nav link strip (mimic w3 Home / People / News / Apps tabs) */
.topnav-links {
  display: flex;
  align-items: center;
  height: 100%;
  flex: 1;
}

.topnav-link {
  display: flex;
  align-items: center;
  height: 100%;
  padding: 0 18px;
  font-size: 14px;
  color: #8d8d8d;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  white-space: nowrap;
  transition: color 0.1s;
  letter-spacing: 0.16px;
}
.topnav-link:hover { color: #fff; }
.topnav-link.active { color: #fff; border-bottom-color: rgba(255,255,255,0.5); }

/* Search bar in top nav */
.topnav-search {
  display: flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: none;
  border-left: 1px solid rgba(255,255,255,0.12);
  height: 100%;
  padding: 0 14px;
  flex: 0 1 280px;
}
.topnav-search input {
  background: transparent;
  border: none;
  outline: none;
  color: #c6c6c6;
  font-size: 14px;
  font-family: inherit;
  width: 100%;
}
.topnav-search input::placeholder { color: #6f6f6f; }
.topnav-search svg { flex-shrink: 0; }

.topnav-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 20px;
  height: 100%;
  font-size: 13px;
  color: #c6c6c6;
  border-left: 1px solid rgba(255,255,255,0.12);
  flex-shrink: 0;
  cursor: pointer;
}

/* .avatar is kept for JS compatibility but hidden from nav */
.avatar { display: none; }

/* ── LAYOUT ──────────────────────────────────────────────────── */
.shell {
  display: flex;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

/* ── SIDEBAR ─────────────────────────────────────────────────── */
.sidebar {
  width: 192px;
  background: #111111;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  border-right: 1px solid rgba(255,255,255,0.1);
}
.sidebar-section { padding: 0; }
.sidebar-label { display: none; }
.nav-item {
  display: flex;
  align-items: center;
  padding: 13px 20px;
  cursor: pointer;
  font-size: 13px;
  color: #8d8d8d;
  border-left: 2px solid transparent;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  transition: color 0.1s;
  letter-spacing: 0.16px;
}
.nav-item:hover { color: #fff; }
.nav-item.active {
  background: transparent;
  color: #fff;
  border-left-color: rgba(255,255,255,0.5);
}
.nav-icon { display: none; }
.sidebar-divider { display: none; }

/* ── MAIN ────────────────────────────────────────────────────── */
.main { flex: 1; overflow: hidden; display: flex; flex-direction: column; min-height: 0; }

.view { display: none; flex-direction: column; flex: 1; overflow-y: auto; min-height: 0; }
.view.active { display: flex; }
/* Colony view manages its own overflow — prevent double-scroll */
#view-colony { overflow: hidden; }

/* ── PAGE HEADER ─────────────────────────────────────────────── */
.page-header {
  padding: 20px 24px 16px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--sidebar-bg);
  flex-shrink: 0;
}
.page-title  {
  font-size: 20px;
  font-weight: 400;
  letter-spacing: 0;
  color: var(--text);
}
.page-sub    { font-size: 13px; color: var(--muted); margin-top: 3px; }

/* ── TAB BAR (IBM Carbon Tab style) ──────────────────────────── */
.tab-bar {
  display: flex;
  padding: 0;
  background: var(--sidebar-bg);
  border-bottom: 1px solid var(--border-subtle);
  flex-shrink: 0;
}
.tab {
  padding: 12px 20px;
  font-size: 14px;
  cursor: pointer;
  color: var(--muted);
  border-bottom: 2px solid transparent;
  white-space: nowrap;
  letter-spacing: 0.16px;
  transition: color 0.1s, border-color 0.1s;
}
.tab:hover { color: var(--text); }
.tab.active {
  color: var(--text);
  border-bottom-color: var(--ibm-blue-50);
  font-weight: 500;
}

/* ── CONTENT AREA ────────────────────────────────────────────── */
.content { padding: 20px 24px; overflow-y: auto; flex: 1; }

/* ── STAT CARDS ──────────────────────────────────────────────── */
.stat-row { display: flex; gap: 1px; margin-bottom: 24px; flex-wrap: wrap; background: var(--border-subtle); border: 1px solid var(--border-subtle); border-radius: 0; overflow: hidden; }
.stat-card {
  background: var(--surface);
  padding: 16px 20px;
  flex: 1;
  min-width: 120px;
  border: none;
}
.stat-num   { font-size: 28px; font-weight: 300; color: var(--ibm-blue-40); letter-spacing: -0.5px; }
.stat-label { font-size: 12px; color: var(--muted); margin-top: 4px; text-transform: uppercase; letter-spacing: 0.5px; }

/* ── TOOLBAR ─────────────────────────────────────────────────── */
.toolbar { display: flex; align-items: center; gap: 8px; margin-bottom: 20px; flex-wrap: wrap; }
.search-box {
  flex: 1;
  min-width: 160px;
  max-width: 320px;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-bottom-color: var(--border);
  border-radius: 0;
  font-size: 14px;
  background: var(--surface);
  color: var(--text);
  font-family: inherit;
  transition: border-color 0.1s;
}
.search-box::placeholder { color: var(--muted); }
.search-box:focus { outline: none; border-bottom-color: var(--ibm-blue-50); }

.sort-select {
  padding: 8px 32px 8px 10px;
  border: 1px solid var(--border);
  border-bottom-width: 2px;
  border-bottom-color: var(--border);
  border-radius: 0;
  font-size: 14px;
  background: var(--surface);
  color: var(--text);
  font-family: inherit;
  appearance: none;
  cursor: pointer;
  transition: border-color 0.1s;
}
.sort-select:focus { outline: none; border-bottom-color: var(--ibm-blue-50); }

/* ── ROLE LEGEND ─────────────────────────────────────────────── */
.role-legend { display: flex; gap: 16px; flex-wrap: wrap; margin-bottom: 20px; }
.rl-item { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--muted); }
.rl-dot {
  width: 10px;
  height: 11px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  flex-shrink: 0;
}

/* ── HEX CELLS (hive grid) ───────────────────────────────────── */
.hive-container {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 8px 0 40px;
}
.hex-row {
  display: flex;
  gap: 4px;
  margin-bottom: -20px;
}
.hex-row:nth-child(even) { margin-left: 44px; }

.hex-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
}

.hex {
  position: relative;
  width: 82px;
  height: 90px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: var(--accent-indigo);
  transition: transform 0.15s, filter 0.15s;
  text-align: center;
  padding: 10px 6px;
}
.hex:hover { transform: scale(1.07); filter: brightness(1.2); }
.hex.open  { background: var(--c-open); border: 1.5px dashed var(--border); }

/* Category marker (bottom-left of hex) */
.hex.cat-sales::after,
.hex.cat-tech::after,
.hex.cat-support::after {
  content: '';
  position: absolute;
  bottom: 8px;
  left: 8px;
  width: 7px;
  height: 7px;
  background: rgba(255,255,255,0.9);
}
.hex.cat-sales::after   { border-radius: 50%; }
.hex.cat-tech::after    { transform: rotate(45deg); }
.hex.cat-support::after { clip-path: polygon(0 0, 100% 0, 100% 100%); }

.hex-name {
  font-size: 9px;
  font-weight: 600;
  color: #fff;
  line-height: 1.25;
  text-shadow: 0 1px 2px rgba(0,0,0,0.5);
  max-width: 70px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.hex-role {
  font-size: 8px;
  color: rgba(255,255,255,0.75);
  text-shadow: 0 1px 2px rgba(0,0,0,0.4);
  max-width: 70px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-top: 2px;
}
.hex.open .hex-name { color: var(--muted); text-shadow: none; }

/* ── ORG TREE ────────────────────────────────────────────────── */
.org-tree { display: flex; flex-direction: column; overflow-x: auto; padding-bottom: 16px; }
.org-level { display: flex; justify-content: center; gap: 12px; padding: 10px 0; }
.org-connector { display: flex; justify-content: center; }
.org-connector-line { width: 1px; height: 16px; background: var(--border); }

.org-card {
  background: var(--surface);
  border: 1px solid var(--border-subtle);
  border-left: 3px solid transparent;
  padding: 12px 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 190px;
  max-width: 220px;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
.org-card:hover { background: var(--surface-2); border-left-color: var(--ibm-blue-50); }
.org-card.highlight { border-left-color: var(--ibm-purple-50); background: rgba(138, 63, 252, 0.08); }
.org-card.you       { border-left-color: var(--ibm-blue-50); background: rgba(69, 137, 255, 0.08); }

/* Hex-shaped avatar in org cards */
.org-avatar {
  width: 36px;
  height: 40px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
  flex-shrink: 0;
  color: #fff;
}
.org-info { flex: 1; min-width: 0; }
.org-name  { font-size: 13px; font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.org-role  { font-size: 12px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }
.org-badge {
  font-size: 11px;
  background: transparent;
  border: 1px solid var(--border);
  padding: 1px 6px;
  color: var(--muted);
  white-space: nowrap;
  margin-top: 4px;
  display: inline-block;
  letter-spacing: 0.16px;
}

/* ── NETWORK GRID ────────────────────────────────────────────── */
.network-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 1px; background: var(--border-subtle); }
.network-card {
  background: var(--surface);
  padding: 16px;
  cursor: pointer;
  transition: background 0.1s;
  border-left: 3px solid transparent;
}
.network-card:hover { background: var(--surface-2); border-left-color: var(--ibm-blue-50); }

.nc-top { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }

/* Hex-shaped avatar on network / connection cards */
.nc-avatar {
  width: 44px;
  height: 50px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.nc-name { font-size: 14px; font-weight: 500; letter-spacing: 0.16px; }
.nc-role { font-size: 12px; color: var(--muted); margin-top: 1px; }
.nc-tag  { display: inline-block; font-size: 11px; padding: 2px 8px; font-weight: 500; margin-top: 6px; letter-spacing: 0.32px; text-transform: uppercase; }
.tag-close   { background: rgba(69,137,255,0.16);  color: var(--ibm-blue-40); }
.tag-partner { background: rgba(165,110,255,0.18);  color: var(--ibm-purple-40); }
.tag-cross   { background: rgba(217,70,239,0.16);   color: #f0abfc; }
.tag-client  { background: rgba(108,99,255,0.18);   color: #bcb6ff; }
.tag-peer    { background: rgba(96,165,250,0.16);   color: #bfdbfe; }
.nc-note {
  font-size: 12px;
  color: var(--muted);
  margin-top: 10px;
  border-top: 1px solid var(--border-subtle);
  padding-top: 10px;
  line-height: 1.5;
}
.nc-followup {
  font-size: 11px;
  color: var(--accent-magenta);
  font-weight: 600;
  margin-top: 6px;
  text-transform: uppercase;
  letter-spacing: 0.32px;
}

/* ── ACCOUNT HIVE ────────────────────────────────────────────── */
.accounts-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.acct-filter {
  font-size: 12px;
  padding: 5px 12px;
  border: 1px solid var(--border);
  background: var(--surface);
  cursor: pointer;
  color: var(--muted);
  transition: all 0.1s;
  letter-spacing: 0.32px;
  text-transform: uppercase;
  font-weight: 500;
  border-radius: 0;
}
.acct-filter:hover { background: var(--surface-2); color: var(--text); }
.acct-filter.active { background: var(--ibm-blue-60); color: #fff; border-color: var(--ibm-blue-60); }
.acct-legend { display: flex; align-items: center; gap: 16px; margin-left: auto; flex-wrap: wrap; }
.legend-item { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.32px; }
.legend-dot  { width: 10px; height: 10px; flex-shrink: 0; }

.acct-hex {
  width: 90px;
  height: 100px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform 0.15s, filter 0.15s, opacity 0.2s;
  padding: 10px 6px;
  text-align: center;
}
.acct-hex:hover { transform: scale(1.06); filter: brightness(1.2); }
.acct-name  { font-size: 9px; font-weight: 700; color: #fff; text-shadow: 0 1px 3px rgba(0,0,0,0.5); line-height: 1.2; max-width: 78px; overflow: hidden; text-overflow: ellipsis; }
.acct-val   { font-size: 8px; color: rgba(255,255,255,0.9); margin-top: 3px; text-shadow: 0 1px 2px rgba(0,0,0,0.4); font-weight: 600; }
.acct-stage { font-size: 8px; color: rgba(255,255,255,0.7); margin-top: 1px; }

/* Stage colors */
.col-won        { background: var(--stage-won); }
.col-negotiation{ background: var(--stage-negotiation); }
.col-proposal   { background: var(--stage-proposal); }
.col-risk       { background: var(--stage-risk); }
.col-prospect   { background: var(--stage-prospect); }

/* ── EXEC VIEW ───────────────────────────────────────────────── */
.exec-section { margin-bottom: 36px; }
.exec-title {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--muted);
}
.exec-badge {
  font-size: 11px;
  padding: 2px 8px;
  color: #fff;
  font-weight: 600;
  letter-spacing: 0.32px;
}

/* ── DETAIL PANEL (slide-over) ───────────────────────────────── */
.panel-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  z-index: 100;
  display: none;
  align-items: flex-start;
  justify-content: flex-end;
}
.panel-overlay.open { display: flex; }

.detail-panel {
  background: var(--surface);
  width: 352px;
  height: 100%;
  overflow-y: auto;
  box-shadow: -4px 0 32px rgba(0,0,0,0.6);
  display: flex;
  flex-direction: column;
  border-left: 1px solid var(--border-subtle);
}

.dp-header {
  padding: 20px 20px 16px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: flex-start;
  gap: 14px;
  background: var(--sidebar-bg);
}

/* Hex-shaped avatar in detail panel — all profile views are hive-shaped */
.dp-avatar {
  width: 56px;
  height: 63px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}

.dp-name   { font-size: 16px; font-weight: 400; letter-spacing: 0; color: var(--text); }
.dp-role   { font-size: 12px; color: var(--muted); margin-top: 3px; }
.dp-market {
  font-size: 11px;
  padding: 2px 8px;
  background: rgba(69,137,255,0.14);
  color: var(--ibm-blue-40);
  display: inline-block;
  margin-top: 6px;
  font-weight: 500;
  letter-spacing: 0.32px;
  text-transform: uppercase;
}
.dp-close {
  margin-left: auto;
  font-size: 18px;
  cursor: pointer;
  color: var(--muted);
  padding: 2px 6px;
  line-height: 1;
  transition: color 0.1s;
}
.dp-close:hover { color: var(--text); }

.dp-body { padding: 16px 20px; flex: 1; display: flex; flex-direction: column; gap: 20px; }
.dp-section { display: flex; flex-direction: column; gap: 8px; }
.dp-section-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
  font-weight: 600;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-subtle);
}
.dp-row { display: flex; align-items: flex-start; gap: 10px; font-size: 13px; }
.dp-label { color: var(--muted); min-width: 80px; font-size: 12px; flex-shrink: 0; letter-spacing: 0.16px; }
.dp-value { color: var(--text); font-weight: 400; }
.dp-link  { color: var(--ibm-blue-40); text-decoration: none; font-size: 13px; }
.dp-link:hover { text-decoration: underline; }

.dp-note-item {
  font-size: 13px;
  color: var(--text);
  line-height: 1.6;
  background: var(--surface-2);
  padding: 10px 12px;
  border-left: 3px solid var(--ibm-blue-60);
  margin-bottom: 6px;
}
.dp-note-date { font-size: 11px; color: var(--muted); margin-top: 4px; }

.dp-tag-row { display: flex; gap: 6px; flex-wrap: wrap; }
.dp-tag {
  font-size: 11px;
  padding: 3px 10px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  letter-spacing: 0.32px;
}

/* ── LOADING STATE ───────────────────────────────────────────── */
.loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px;
  color: var(--muted);
  font-size: 14px;
}

/* ── FOOTER ──────────────────────────────────────────────────── */
.app-footer {
  flex-shrink: 0;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #000;
  border-top: 1px solid var(--border-subtle);
  color: var(--muted);
  font-size: 12px;
  letter-spacing: 0.32px;
}
.app-footer strong { color: var(--text-secondary); font-weight: 500; }

/* ── ROLE-CATEGORY LEGEND ────────────────────────────────────── */
.cat-legend {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
  margin-top: 20px;
  padding: 12px 16px;
  border-top: 1px solid var(--border-subtle);
  background: var(--surface);
}
.cat-legend-item { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 500; color: var(--muted); letter-spacing: 0.32px; text-transform: uppercase; }
.cat-legend-marker { width: 9px; height: 9px; background: rgba(255,255,255,0.85); flex-shrink: 0; }
.cat-legend-marker.cat-sales   { border-radius: 50%; }
.cat-legend-marker.cat-tech    { transform: rotate(45deg); }
.cat-legend-marker.cat-support { clip-path: polygon(0 0, 100% 0, 100% 100%); }

/* ── BUTTONS ─────────────────────────────────────────────────── */
.btn-primary {
  padding: 8px 16px;
  border: none;
  background: var(--ibm-blue-60);
  color: #fff;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
  letter-spacing: 0.16px;
  font-family: inherit;
  transition: background 0.1s;
  border-radius: 0;
}
.btn-primary:hover { background: var(--ibm-blue-70); }

.btn-secondary {
  padding: 8px 16px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text);
  font-size: 14px;
  cursor: pointer;
  letter-spacing: 0.16px;
  font-family: inherit;
  transition: background 0.1s;
  border-radius: 0;
}
.btn-secondary:hover { background: var(--surface-2); }

.btn-danger {
  padding: 8px 16px;
  border: 1px solid rgba(217,70,239,0.4);
  background: transparent;
  color: var(--accent-magenta);
  font-size: 14px;
  cursor: pointer;
  letter-spacing: 0.16px;
  font-family: inherit;
  border-radius: 0;
}
.btn-danger:hover { background: rgba(217,70,239,0.1); }

/* ── CONNECTIONS TOOLBAR / CRUD ─────────────────────────────── */
.nc-actions {
  display: flex;
  gap: 4px;
  margin-left: auto;
}
.nc-icon-btn {
  width: 26px; height: 26px;
  border: 1px solid var(--border-subtle);
  background: var(--surface);
  color: var(--muted);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  font-size: 12px;
  flex-shrink: 0;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
}
.nc-icon-btn:hover { background: var(--surface-2); color: var(--text); border-color: var(--ibm-blue-50); }
.nc-icon-btn.danger:hover { border-color: var(--accent-magenta); color: var(--accent-magenta); background: rgba(217,70,239,0.08); }

/* ── MODAL ───────────────────────────────────────────────────── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.65);
  z-index: 200;
  display: none;
  align-items: center;
  justify-content: center;
}
.modal-overlay.open { display: flex; }
.modal {
  background: var(--surface);
  border: 1px solid var(--border);
  width: 400px;
  max-width: calc(100vw - 32px);
  max-height: calc(100vh - 64px);
  overflow-y: auto;
  box-shadow: 0 16px 48px rgba(0,0,0,0.6);
  border-radius: 0;
}
.modal-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--sidebar-bg);
}
.modal-title { font-size: 16px; font-weight: 400; letter-spacing: 0; }
.modal-close { cursor: pointer; color: var(--muted); font-size: 16px; padding: 2px 6px; transition: color 0.1s; }
.modal-close:hover { color: var(--text); }
.modal-body { padding: 20px; display: flex; flex-direction: column; gap: 16px; }
.modal-body label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 12px;
  color: var(--muted);
  font-weight: 600;
  letter-spacing: 0.32px;
  text-transform: uppercase;
}
.modal-body input[type="text"],
.modal-body select,
.modal-body textarea {
  padding: 8px 10px;
  border: none;
  border-bottom: 2px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  resize: vertical;
  border-radius: 0;
