      nameText.setAttribute('fill', isYou ? '#fff' : 'rgba(255,255,255,0.85)');
      nameText.setAttribute('font-size', '8');
      nameText.setAttribute('font-weight', '500');
      nameText.setAttribute('font-family', 'IBM Plex Sans, system-ui, sans-serif');
