/* ─────────────────────────────────────────────────────────────
   COLONY HIVE VIEW — full-screen zoomable hexagon grid
   ───────────────────────────────────────────────────────────── */

/* Colony view fills the full flex area with its own layout */
.colony-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

/* Sticky toolbar at top of colony view */
.colony-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  height: 48px;
  flex-shrink: 0;
  background: var(--sidebar-bg);
  border-bottom: 1px solid var(--border-subtle);
  gap: 16px;
}
.colony-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.colony-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.16px;
}
.colony-subtitle {
  font-size: 12px;
  color: var(--muted);
}
.colony-toolbar-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}
.colony-zoom-btn {
  width: 32px;
  height: 32px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-secondary);
  font-size: 18px;
  font-family: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
  flex-shrink: 0;
}
.colony-zoom-btn:hover { background: var(--surface-2); color: #fff; }

/* The scrollable viewport — cursor:grab, overflow:hidden */
.colony-viewport {
  flex: 1;
  overflow: hidden;
  position: relative;
  cursor: grab;
  background: var(--bg);
}
.colony-viewport:active { cursor: grabbing; }

/* The transformable canvas inside the viewport */
.colony-canvas {
  position: absolute;
  top: 0;
  left: 0;
  transform-origin: top left;
  padding: 32px 24px 80px;
  will-change: transform;
}

/* Grid that arranges colony clusters side by side */
.colony-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 40px 48px;
  align-items: flex-start;
}

/* Flat grid mode */
.colony-flat-grid {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding-bottom: 40px;
}

/* ── Colony cluster block ─────────────────────────────────── */
.colony-cluster {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.colony-cluster-label {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #6f6f6f;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(255,255,255,0.14);
  white-space: nowrap;
}
.colony-cluster-dot {
  width: 9px;
  height: 10px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  background: #3d3d3d;
