}

/* ── Hex cell rows ────────────────────────────────────────── */
.chex-row {
  display: flex;
  gap: 3px;
  margin-bottom: -22px;
}
.chex-row-offset {
  margin-left: 42px;
}
/* last row in a cluster shouldn't pull up with negative margin */
.colony-cluster-hex .chex-row:last-child,
.colony-flat-grid .chex-row:last-child {
  margin-bottom: 0;
}

/* ── Single hexagon cell ──────────────────────────────────── */
.chex-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  /* Stacked cells share a thin white outline — achieved via outline on hover 
     and a subtle inner stroke via box-shadow on the clip */
  position: relative;
}
/* You-highlight: thin white ring around your hex */
.chex-wrap.chex-you .chex {
  outline: 1px solid rgba(255,255,255,0.6);
  outline-offset: 2px;
}

.chex {
  width: 76px;
  height: 84px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2a2a2a;
  transition: transform 0.14s, filter 0.14s;
  text-align: center;
  padding: 8px 5px;
  position: relative;
}
.chex::before {
  content: '';
  position: absolute;
  inset: 0;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  background: rgba(255,255,255,0.12);
  pointer-events: none;
  opacity: 0;
