Contents of file frontend/js/app.js:

1 | /**
2 |  * app.js — boot, navigation, and view orchestration
3 |  */
4 | import { getPeople }      from './api.js';
5 | import { renderColony }   from './views/colony.js';
6 | import { renderSeller }   from './views/seller.js';
7 | import { renderNetwork }  from './views/network.js';
8 | import { renderAccounts } from './views/accounts.js';
9 | 
10 | // ── Boot: populate current user in nav ────────────────────────
11 | async function boot() {
12 |   try {
13 |     const people = await getPeople();
14 |     const me = people.find(p => p.is_current_user);
15 |     if (me) {
16 |       document.getElementById('currentUserName').textContent = me.first_name + ' ' + me.last_name;
17 |     }
18 |   } catch (e) {
19 |     console.warn('Could not load user from API:', e.message);
20 |   }
21 | }
22 | 
23 | // ── Profile / account switcher dropdown ──────────────────────
24 | function wireProfileDropdown() {
25 |   const userSection = document.getElementById('topnavUser');
26 |   const dropdown    = document.getElementById('userDropdown');
27 | 
28 |   if (!userSection || !dropdown) return;
29 | 
30 |   // Toggle on name click
31 |   function toggleDropdown(e) {
32 |     e.stopPropagation();
33 |     dropdown.classList.toggle('open');
34 |   }
35 |   document.getElementById('currentUserName')?.addEventListener('click', toggleDropdown);
36 |   userSection.addEventListener('click', toggleDropdown);
37 | 
38 |   // Close on outside click
39 |   document.addEventListener('click', e => {
40 |     if (!userSection.contains(e.target)) {
41 |       dropdown.classList.remove('open');
42 |     }
43 |   });
44 | 
45 |   // Profile switcher items
46 |   dropdown.querySelectorAll('.user-dropdown-item').forEach(item => {
47 |     item.addEventListener('click', e => {
48 |       e.stopPropagation();
49 |       dropdown.querySelectorAll('.user-dropdown-item').forEach(i => i.classList.remove('active'));
50 |       item.classList.add('active');
51 | 
52 |       const profile = item.dataset.profile;
53 |       const nameEl  = document.getElementById('currentUserName');
54 | 
55 |       if (profile === 'sydney')  nameEl.textContent = 'Sydney Chin';
56 |       else if (profile === 'manager') nameEl.textContent = 'Chris Kennedy';
57 |       else if (profile === 'admin')   nameEl.textContent = 'Admin';
58 | 
59 |       dropdown.classList.remove('open');
60 |     });
61 |   });
62 | }
63 | 
64 | // ── View registry ─────────────────────────────────────────────
65 | const VIEW_RENDERERS = {
66 |   colony:   renderColony,
67 |   seller:   renderSeller,
68 |   network:  renderNetwork,
69 |   accounts: renderAccounts,
70 | };
71 | 
72 | const rendered = new Set();
73 | 
74 | async function activateView(viewName) {
75 |   // Update sidebar
76 |   document.querySelectorAll('.nav-item').forEach(n => {
77 |     n.classList.toggle('active', n.dataset.view === viewName);
78 |   });
79 | 
80 |   // Update top nav links
81 |   document.querySelectorAll('.topnav-link[data-view-link]').forEach(n => {
82 |     n.classList.toggle('active', n.dataset.viewLink === viewName);
83 |   });
84 | 
85 |   // Show the right view container
86 |   document.querySelectorAll('.main > .view').forEach(v => {
87 |     v.classList.toggle('active', v.id === `view-${viewName}`);
88 |   });
89 | 
90 |   // Render the view if not already rendered
91 |   const container = document.getElementById(`view-${viewName}`);
92 |   if (!container) return;
93 | 
94 |   if (!rendered.has(viewName)) {
95 |     rendered.add(viewName);
96 |     try {
97 |       await VIEW_RENDERERS[viewName]?.(container);
98 |     } catch (err) {
99 |       container.innerHTML = `
100 |         <div class="page-header">
101 |           <div class="page-title">Error</div>
102 |           <div class="page-sub">Could not load view: ${err.message}</div>
103 |         </div>
104 |         <div class="content" style="color:var(--muted);font-size:13px">
105 |           Make sure the server is running (<code>npm start</code>) and the database is seeded (<code>npm run seed</code>).
106 |         </div>
107 |       `;
108 |     }
109 |   }
110 | }
111 | 
112 | // ── Sidebar nav clicks ────────────────────────────────────────
113 | document.querySelectorAll('.nav-item').forEach(item => {
114 |   item.addEventListener('click', () => activateView(item.dataset.view));
115 | });
116 | 
117 | // ── Top nav link clicks ───────────────────────────────────────
118 | document.querySelectorAll('.topnav-link[data-view-link]').forEach(item => {
119 |   item.addEventListener('click', () => activateView(item.dataset.viewLink));
120 | });
121 | 
122 | // ── Init ──────────────────────────────────────────────────────
123 | boot();
124 | wireProfileDropdown();
125 | activateView('colony');
126 |

