126 | function renderSidebar(viewName) {
127 |   const sidebar = document.getElementById('appSidebar');
128 |   if (!sidebar) return;
129 | 
130 |   const def = SIDEBAR_DEFS[viewName];
131 |   if (!def) { sidebar.innerHTML = ''; return; }
132 | 
133 |   let html = '';
134 |   def.sections.forEach(section => {
135 |     if (section.label) {
136 |       html += `<div class="sb-section-label">${section.label}</div>`;
137 |     }
138 |     section.items.forEach(item => {
139 |       if (item.expandable && item.children) {
140 |         html += `
141 |           <div class="sb-group" data-group="${item.id}">
142 |             <div class="sb-group-header" data-toggle="${item.id}">
143 |               <span>${item.label}</span>
144 |               <span class="sb-caret">›</span>
145 |             </div>
146 |             <div class="sb-group-body" id="sbg-${item.id}">
147 |               <input class="sb-search" type="text" placeholder="Search…" data-group="${item.id}"/>
148 |               ${item.children.map(c => `
149 |                 <div class="sb-child" data-filter="${item.id}" data-value="${c.id}">${c.label}</div>
150 |               `).join('')}
151 |             </div>
152 |           </div>
153 |         `;
154 |       } else {
155 |         html += `
156 |           <div class="sb-item${item.active ? ' active' : ''}" data-sb-item="${item.id}">${item.label}</div>
157 |         `;
158 |       }
159 |     });
160 |   });
161 | 
162 |   sidebar.innerHTML = html;
163 | 
164 |   // Wire expandable group toggles
165 |   sidebar.querySelectorAll('.sb-group-header').forEach(header => {
166 |     const id   = header.dataset.toggle;
167 |     const body = document.getElementById(`sbg-${id}`);
168 |     header.addEventListener('click', () => {
169 |       const open = body.classList.toggle('open');
170 |       header.querySelector('.sb-caret').textContent = open ? '⌄' : '›';
171 |     });
172 |   });
173 | 
174 |   // Wire search within groups
175 |   sidebar.querySelectorAll('.sb-search').forEach(input => {
176 |     input.addEventListener('input', e => {
177 |       const q = e.target.value.toLowerCase();
178 |       const group = e.target.dataset.group;
179 |       sidebar.querySelectorAll(`.sb-child[data-filter="${group}"]`).forEach(child => {
180 |         child.style.display = child.textContent.toLowerCase().includes(q) ? '' : 'none';
181 |       });
182 |     });
183 |   });
184 | 
185 |   // Wire filter items — broadcast to active view
186 |   sidebar.querySelectorAll('.sb-child, .sb-item').forEach(el => {
187 |     el.addEventListener('click', () => {
188 |       sidebar.querySelectorAll('.sb-child.active, .sb-item.active').forEach(a => a.classList.remove('active'));
189 |       el.classList.add('active');
190 |       // Fire a custom event the active view can listen to
191 |       document.dispatchEvent(new CustomEvent('sidebar:filter', {
192 |         detail: { group: el.dataset.filter || el.dataset.sbItem, value: el.dataset.value || el.dataset.sbItem }
193 |       }));
194 |     });
195 |   });
196 | }
