1 | /**
2 |  * hive.js — The Hive: all-black, white grid-line hexagon map of all people.
3 |  *
4 |  * • All cells are #000 with 1px white stroke — no colors anywhere.
5 |  * • Names hidden at low zoom; appear at zoom > 0.55.
6 |  * • Colony section labels appear at zoom > 0.3.
7 |  * • Sidebar filter events (portfolios / jobs / markets) dim non-matching cells.
8 |  * • Click any cell → person detail panel.
9 |  */
10 | import { getPeople } from '../api.js';
