13 | const COLONY_ORDER = [
14 |   'Data & AI Colony',
15 |   'Automation Colony',
16 |   'Sustainability Colony',
17 |   'Security Colony',
18 |   'Infrastructure Colony',
19 |   'Hybrid Cloud Colony',
20 | ];
