22 | const ROLE_LABELS = {
23 |   exec: 'VP / Exec', director: 'Director', manager: 'Manager',
24 |   bss: 'BSS', bts: 'BTS', csm: 'CSM', ae: 'AE',
25 |   tse: 'BTS', sdr: 'SDR', partner: 'Partner', intern: 'Intern', other: '',
26 | };
27 | 
28 | const ROLE_ORDER = {
29 |   exec: 0, director: 1, manager: 2, bss: 3, ae: 3,
30 |   bts: 4, tse: 4, csm: 5, sdr: 6, partner: 7, intern: 8, other: 9,
31 | };
32 | 
33 | // Map sidebar filter IDs to data fields
34 | const COLONY_MAP = {
35 |   'data-ai': 'Data & AI Colony',
36 |   'automation': 'Automation Colony',
37 |   'sustainability': 'Sustainability Colony',
38 |   'security': 'Security Colony',
39 |   'infrastructure': 'Infrastructure Colony',
40 |   'hybrid-cloud': 'Hybrid Cloud Colony',
41 | };
42 | 
43 | const MARKET_MAP = {
44 |   enterprise: 'Enterprise',
45 |   strategic:  'Strategic',
46 |   horizon:    'Horizon',
47 |   territory:  'Territory',
48 | };
49 | 
50 | // Hex geometry — pointy-top
51 | const HEX_R = 44;
52 | const HEX_W = Math.round(Math.sqrt(3) * HEX_R);
53 | const ROW_H = HEX_R * 1.5;
54 | 
55 | function hexRegion(N) {
56 |   const cells = [];
57 |   for (let q = -N; q <= N; q++) {
58 |     const r1 = Math.max(-N, -q - N);
59 |     const r2 = Math.min(N,  -q + N);
60 |     for (let r = r1; r <= r2; r++) cells.push({ q, r });
61 |   }
62 |   return cells;
63 | }
64 | 
65 | function axialToPixel(q, r) {
66 |   return { x: HEX_W * (q + r / 2), y: ROW_H * r };
67 | }
68 | 
69 | function hexPoints(cx, cy, r) {
70 |   return Array.from({length: 6}, (_, i) => {
71 |     const a = Math.PI / 180 * (60 * i - 30);
72 |     return `${cx + r * Math.cos(a)},${cy + r * Math.sin(a)}`;
73 |   }).join(' ');
74 | }
