86 |         </div>
87 |         <div class="hive-toolbar-controls">
88 |           <button class="colony-zoom-btn" id="hiveZoomIn"  title="Zoom in">+</button>
89 |           <button class="colony-zoom-btn" id="hiveZoomOut" title="Zoom out">−</button>
90 |           <button class="colony-zoom-btn" id="hiveZoomReset" title="Fit" style="font-size:11px">Fit</button>
91 |         </div>
92 |       </div>
