117 | function sortedPeople() {
118 |   // Group by colony, sorted by role within colony
119 |   const byColony = {};
120 |   COLONY_ORDER.forEach(c => { byColony[c] = []; });
121 |   _people.forEach(p => {
122 |     const key = p.comb || 'Other';
123 |     if (!byColony[key]) byColony[key] = [];
124 |     byColony[key].push(p);
125 |   });
126 |   COLONY_ORDER.forEach(c => {
127 |     if (byColony[c]) byColony[c].sort((a, b) =>
128 |       (ROLE_ORDER[a.role_type] ?? 9) - (ROLE_ORDER[b.role_type] ?? 9)
129 |     );
130 |   });
131 |   const sorted = COLONY_ORDER.flatMap(c => byColony[c] || []);
132 |   const seen = new Set();
133 |   return sorted.filter(p => { if (seen.has(p.id)) return false; seen.add(p.id); return true; });
134 | }
