136 | function isFiltered(p) {
137 |   if (!_activeFilter) return false;
138 |   const { group, value } = _activeFilter;
139 |   if (group === 'portfolios') {
140 |     return p.comb !== COLONY_MAP[value];
141 |   }
142 |   if (group === 'jobs') {
143 |     // map sidebar role id to role_type
144 |     const roleTypeMap = {
145 |       bss: 'bss', bts: 'bts', csm: 'csm',
146 |       manager: 'manager', director: 'director',
147 |       exec: 'exec', partner: 'partner', sdr: 'sdr',
148 |     };
149 |     return p.role_type !== roleTypeMap[value];
150 |   }
151 |   if (group === 'markets') {
152 |     return p.market !== MARKET_MAP[value];
153 |   }
154 |   return false;
155 | }
