157 | function buildSvg() {
158 |   const svg = document.getElementById('hiveSvg');
159 |   if (!svg) return;
160 | 
161 |   const people = sortedPeople();
162 |   let N = 1;
163 |   while (hexRegion(N).length < people.length) N++;
164 |   const cells = hexRegion(N);
165 | 
166 |   // Sort cells: center-out, then by angle so colonies cluster
167 |   cells.sort((a, b) => {
168 |     const ra = Math.max(Math.abs(a.q), Math.abs(a.r), Math.abs(a.q + a.r));
169 |     const rb = Math.max(Math.abs(b.q), Math.abs(b.r), Math.abs(b.q + b.r));
170 |     if (ra !== rb) return ra - rb;
171 |     const pa = axialToPixel(a.q, a.r);
172 |     const pb = axialToPixel(b.q, b.r);
173 |     return Math.atan2(pa.y, pa.x) - Math.atan2(pb.y, pb.x);
174 |   });
175 | 
176 |   const assignments = cells.slice(0, people.length).map((cell, i) => ({
177 |     ...cell, person: people[i], px: axialToPixel(cell.q, cell.r),
178 |   }));
179 | 
180 |   // SVG bounds
181 |   const xs = assignments.map(a => a.px.x);
182 |   const ys = assignments.map(a => a.px.y);
183 |   const minX = Math.min(...xs) - HEX_R - 2;
184 |   const maxX = Math.max(...xs) + HEX_R + 2;
185 |   const minY = Math.min(...ys) - HEX_R - 2;
186 |   const maxY = Math.max(...ys) + HEX_R + 2;
187 |   const W = maxX - minX + 4;
188 |   const H = maxY - minY + 4;
189 | 
190 |   svg.setAttribute('viewBox', `${minX - 2} ${minY - 2} ${W} ${H}`);
191 |   svg.setAttribute('width', W);
192 |   svg.setAttribute('height', H);
193 | 
194 |   while (svg.firstChild) svg.removeChild(svg.firstChild);
195 | 
196 |   const ns = 'http://www.w3.org/2000/svg';
197 | 
198 |   // Background rect — pure black
199 |   const bg = document.createElementNS(ns, 'rect');
200 |   bg.setAttribute('x', minX - 2); bg.setAttribute('y', minY - 2);
201 |   bg.setAttribute('width', W + 4); bg.setAttribute('height', H + 4);
202 |   bg.setAttribute('fill', '#000');
203 |   svg.appendChild(bg);
204 | 
205 |   // Draw cells
206 |   assignments.forEach(a => {
207 |     const { x, y } = a.px;
208 |     const p = a.person;
209 |     const dimmed = isFiltered(p);
210 |     const isYou  = p.is_current_user;
211 | 
212 |     // Cell body — black fill, white stroke
213 |     const poly = document.createElementNS(ns, 'polygon');
214 |     poly.setAttribute('points', hexPoints(x, y, HEX_R - 0.5));
215 |     poly.setAttribute('fill', isYou ? '#111' : '#000');
216 |     poly.setAttribute('stroke', dimmed ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.22)');
217 |     poly.setAttribute('stroke-width', '1');
218 |     svg.appendChild(poly);
219 | 
220 |     // "You" inner ring
221 |     if (isYou) {
