342 | function wireZoom() {
343 |   const viewport = document.getElementById('hiveViewport');
344 |   const svg      = document.getElementById('hiveSvg');
345 |   if (!viewport || !svg) return;
346 | 
347 |   let scale = 1, tx = 0, ty = 0;
348 |   let dragging = false, didDrag = false, sx = 0, sy = 0, stx = 0, sty = 0;
349 | 
350 |   function applyTransform() {
351 |     svg.style.transform = `translate(${tx}px,${ty}px) scale(${scale})`;
352 |     svg.style.transformOrigin = '0 0';
353 |     updateLabelVisibility(scale);
354 |   }
355 | 
356 |   function fit() {
357 |     const vw = viewport.clientWidth || 800;
358 |     const vh = viewport.clientHeight || 600;
359 |     const sw = parseFloat(svg.getAttribute('width') || vw);
360 |     const sh = parseFloat(svg.getAttribute('height') || vh);
361 |     scale = Math.min(vw / sw, vh / sh) * 0.92;
362 |     tx = (vw - sw * scale) / 2;
363 |     ty = (vh - sh * scale) / 2;
364 |     applyTransform();
365 |   }
366 | 
367 |   requestAnimationFrame(() => requestAnimationFrame(fit));
368 | 
369 |   const zoom = (factor, cx, cy) => {
370 |     cx = cx ?? viewport.clientWidth / 2;
371 |     cy = cy ?? viewport.clientHeight / 2;
372 |     const ns = Math.min(Math.max(scale * factor, 0.06), 6);
373 |     tx = cx - (cx - tx) * (ns / scale);
374 |     ty = cy - (cy - ty) * (ns / scale);
375 |     scale = ns;
376 |     applyTransform();
377 |   };
378 | 
379 |   document.getElementById('hiveZoomIn')?.addEventListener('click', () => zoom(1.35));
380 |   document.getElementById('hiveZoomOut')?.addEventListener('click', () => zoom(1 / 1.35));
381 |   document.getElementById('hiveZoomReset')?.addEventListener('click', fit);
382 | 
383 |   viewport.addEventListener('wheel', e => {
384 |     e.preventDefault();
385 |     const rect = viewport.getBoundingClientRect();
386 |     zoom(e.deltaY < 0 ? 1.12 : 0.89, e.clientX - rect.left, e.clientY - rect.top);
387 |   }, { passive: false });
388 | 
389 |   viewport.addEventListener('mousedown', e => {
390 |     if (e.button !== 0) return;
391 |     dragging = true; didDrag = false;
392 |     sx = e.clientX; sy = e.clientY; stx = tx; sty = ty;
393 |     viewport.style.cursor = 'grabbing';
394 |   });
395 |   window.addEventListener('mousemove', e => {
396 |     if (!dragging) return;
397 |     const dx = e.clientX - sx, dy = e.clientY - sy;
398 |     if (Math.abs(dx) > 4 || Math.abs(dy) > 4) didDrag = true;
399 |     tx = stx + dx; ty = sty + dy;
400 |     applyTransform();
401 |   });
402 |   window.addEventListener('mouseup', () => {
403 |     dragging = false;
404 |     if (viewport) viewport.style.cursor = 'grab';
405 |   });
406 |   viewport.addEventListener('click', e => {
407 |     if (didDrag) { e.stopImmediatePropagation(); didDrag = false; }
408 |   }, true);
