  border: 1px solid rgba(255,255,255,0.1);
  color: #a8a8a8;
  letter-spacing: 0.16px;
}
.org-modal-person-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px 16px;
}
.org-modal-field {
  display: flex;
  flex-direction: column;
  gap: 3px;
  font-size: 13px;
  color: #f4f4f4;
}
.org-modal-field-label {
  font-size: 11px;
  color: #525252;
  text-transform: uppercase;
  letter-spacing: 0.32px;
}

/* ── CELL / STRUCTURE HEX GRID ───────────────────────────────── */
.cell-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}
.cell-hex-grid {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  padding: 32px 24px;
}
.cell-hex-row {
  display: flex;
  gap: 3px;
  margin-bottom: -14px;
}
.cell-hex-row:nth-child(even) { margin-left: 57px; }
.cell-hex-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
}
.cell-hex-svg {
  display: block;
  overflow: visible;
}
.cell-hex-label {
  font-size: 10px;
  color: #a8a8a8;
  margin-top: 4px;
  text-align: center;
  max-width: 90px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cell-hex-label.you { color: #4d7bff; font-weight: 500; }

/* ── CONNECTIONS NETWORK ─────────────────────────────────────── */
.connections-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  padding: 24px;
  gap: 20px;
}

/* ── RESOURCES ───────────────────────────────────────────────── */
.res-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow-y: auto;
}
.res-header {
  padding: 24px 28px 16px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.res-header-title {
  font-size: 18px;
  font-weight: 300;
  letter-spacing: -0.2px;
  margin-bottom: 4px;
}
.res-header-sub {
  font-size: 12px;
  color: #525252;
}
.res-body {
  padding: 24px 28px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}
.res-section-title {
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.64px;
  color: #525252;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.res-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1px;
  background: rgba(255,255,255,0.06);
}
.res-card {
  background: #0d0d0d;
  padding: 16px 18px;
  cursor: pointer;
  transition: background 0.12s;
  border-left: 2px solid transparent;
}
.res-card:hover {
  background: #111;
  border-left-color: var(--ibm-blue-50);
}
.res-card-name {
  font-size: 13px;
  font-weight: 500;
  color: #f4f4f4;
  margin-bottom: 4px;
}
.res-card-desc {
  font-size: 12px;
  color: #525252;
  line-height: 1.55;
}
.res-card-link {
  font-size: 11px;
  color: var(--ibm-blue-40);
  margin-top: 8px;
  text-decoration: none;
}
.res-card-link:hover { text-decoration: underline; }
.res-team-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.res-team-table th {
  text-align: left;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.32px;
  color: #525252;
  padding: 0 12px 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.res-team-table td {
  padding: 10px 12px 10px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  color: #c6c6c6;
  vertical-align: middle;
}
.res-team-table tr:last-child td { border-bottom: none; }
.res-role-pill {
  display: inline-block;
  font-size: 10px;
  padding: 2px 7px;
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.1);
  color: #a8a8a8;
  letter-spacing: 0.16px;
  white-space: nowrap;
}
.res-product-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.res-product-pill {
  font-size: 12px;
  padding: 5px 12px;
  background: rgba(77,123,255,0.1);
  border: 1px solid rgba(77,123,255,0.2);
  color: #4d7bff;
  letter-spacing: 0.16px;
}

