          <div class="nc-tag ${tag}">${lbl}</div>
          ${c.notes ? `<div class="nc-note">${c.notes}</div>` : ''}
          ${c.needs_followup ? `<div class="nc-followup">⚑ Follow up</div>` : ''}
        </div>
      `;
    }).join('');

    container.innerHTML = `
      <div style="flex:1;overflow-y:auto">
