    color: '#a855f7',
    desc: 'IBM Power, Storage, and z Systems. Sells IBM PowerVS, IBM FlashSystems, and IBM Fusion to all US enterprise accounts.',
    headcount: '~61,000',
    products: ['IBM PowerVS', 'IBM FlashSystem', 'IBM Fusion', 'IBM z16', 'IBM LinuxONE'],
  },
  'Hybrid Cloud Colony': {
    label: 'Hybrid Cloud',
    color: '#ee5396',
    desc: 'Red Hat OpenShift, IBM Cloud, and hybrid multi-cloud strategy. Bridges on-premises and cloud-native workloads.',
    headcount: '~51,000',
    products: ['Red Hat OpenShift', 'IBM Cloud', 'IBM Cloud Paks', 'Red Hat Ansible'],
  },
};

const COLONY_MAP = {
  'data-ai':        'Data & AI Colony',
  'automation':     'Automation Colony',
  'sustainability': 'Sustainability Colony',
  'security':       'Security Colony',
  'infrastructure': 'Infrastructure Colony',
  'hybrid-cloud':   'Hybrid Cloud Colony',
};

const MARKET_MAP = {
  enterprise: 'Enterprise',
  strategic:  'Strategic',
  horizon:    'Horizon',
  territory:  'Territory',
};

const ROLE_ORDER = {
  exec: 0, director: 1, manager: 2, bss: 3, bts: 4,
  csm: 5, sdr: 6, partner: 7, intern: 8, other: 9,
};

// Hex geometry — pointy-top
// Background canvas cells are tiny (3px) so all 270k fit in a ~4700×2700 canvas.
// SVG person overlays use the same coordinate system and scale with transform.
const HEX_R  = 3;    // background canvas hex radius (px)
const HEX_W  = Math.sqrt(3) * HEX_R;
const ROW_H  = HEX_R * 1.5;

// SVG person overlay cells are drawn at a larger display radius
const PERSON_R = 28; // px — how big a person hex appears at scale=1

// Virtual N — hexRegion(N) gives us ≈ 270k cells
const VIRTUAL_N = 300; // exactly 270,901

function axialToPixel(q, r) {
  return { x: HEX_W * (q + r / 2), y: ROW_H * r };
}

function hexPoints(cx, cy, r) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = Math.PI / 180 * (60 * i - 30);
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(' ');
}

// Draw a single flat-stroke hexagon on a canvas context
function drawHex(ctx, cx, cy, r) {
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = Math.PI / 180 * (60 * i - 30);
    const x = cx + r * Math.cos(a);
    const y = cy + r * Math.sin(a);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

// Which colony sector does this axial cell belong to?
function cellColony(q, r) {
  if (q === 0 && r === 0) return COLONY_ORDER[0];
  const { x, y } = axialToPixel(q, r);
  let angle = Math.atan2(y, x); // -π to π
  // Normalize to 0..2π
  if (angle < 0) angle += Math.PI * 2;
  const idx = Math.floor((angle / (Math.PI * 2)) * 6) % 6;
  return COLONY_ORDER[idx];
}

// Colony accent colors (very subtle tint for canvas cells)
const COLONY_TINTS = {
  'Data & AI Colony':      '#0a1a2a',
  'Automation Colony':     '#0d0d20',
  'Sustainability Colony': '#0a1a0e',
  'Security Colony':       '#1a0a0a',
  'Infrastructure Colony': '#150a2a',
  'Hybrid Cloud Colony':   '#1a0a14',
};

let _people      = [];
let _activeFilter = null;
let _currentScale = 0.04; // starts zoomed way out
let _canvasW = 0, _canvasH = 0;

// Precomputed pixel centers for all cells, keyed "q,r"
const _cellPixels = new Map();

export async function renderOrg(container) {
  container.innerHTML = `
    <div class="org-hive-page">
      <div class="org-hive-toolbar">
        <div class="org-hive-toolbar-left">
          <span class="org-hive-title">Organization</span>
          <span class="org-hive-subtitle" id="orgSubtitle">270,000 bees · 6 colonies</span>
        </div>
        <div class="org-hive-controls">
          <button class="colony-zoom-btn" id="orgZoomIn"    title="Zoom in">+</button>
          <button class="colony-zoom-btn" id="orgZoomOut"   title="Zoom out">−</button>
          <button class="colony-zoom-btn" id="orgZoomReset" title="Fit" style="font-size:11px">Fit</button>
        </div>
      </div>
      <div class="colony-viewport" id="orgViewport" style="position:relative;cursor:grab;overflow:hidden;flex:1">
        <canvas id="orgCanvas" style="position:absolute;top:0;left:0;transform-origin:0 0;will-change:transform"></canvas>
        <svg id="orgSvg" xmlns="http://www.w3.org/2000/svg"
             style="position:absolute;top:0;left:0;transform-origin:0 0;will-change:transform;overflow:visible;pointer-events:none"></svg>
      </div>
    </div>

    <!-- Colony / Person Modal -->
    <div class="org-modal-overlay" id="orgModalOverlay">
      <div class="org-modal" id="orgModal">
        <div class="org-modal-header">
          <div class="org-modal-title" id="orgModalTitle"></div>
          <div class="org-modal-close" id="orgModalClose">✕</div>
        </div>
        <div class="org-modal-body" id="orgModalBody"></div>
      </div>
    </div>
  `;

  _people = await getPeople();

  // Sort people by colony then role
  const byColony = {};
  COLONY_ORDER.forEach(c => { byColony[c] = []; });
  _people.forEach(p => {
    const key = p.comb || COLONY_ORDER[0];
    if (!byColony[key]) byColony[key] = [];
    byColony[key].push(p);
  });
  COLONY_ORDER.forEach(c => {
    byColony[c].sort((a, b) => (ROLE_ORDER[a.role_type] ?? 9) - (ROLE_ORDER[b.role_type] ?? 9));
  });
  const realPeople = COLONY_ORDER.flatMap(c => byColony[c] || []);

  // Precompute canvas dimensions from VIRTUAL_N
  const edgeX = Math.abs(axialToPixel(VIRTUAL_N, 0).x) + HEX_R + 4;
  const edgeY = Math.abs(axialToPixel(0, VIRTUAL_N).y) + HEX_R + 4;
  _canvasW = Math.ceil(edgeX * 2 + 8);
  _canvasH = Math.ceil(edgeY * 2 + 8);
  const OX = _canvasW / 2;
  const OY = _canvasH / 2;

  // Assign real people to center-ring cells so they cluster naturally
  let smallN = 1;
  {
    let count = 0;
    for (let q = -smallN; q <= smallN; q++) {
      const r1 = Math.max(-smallN, -q - smallN);
      const r2 = Math.min(smallN, -q + smallN);
      count += r2 - r1 + 1;
    }
    while (count < realPeople.length) {
      smallN++;
      count = 0;
      for (let q = -smallN; q <= smallN; q++) {
        const r1 = Math.max(-smallN, -q - smallN);
        const r2 = Math.min(smallN, -q + smallN);
        count += r2 - r1 + 1;
      }
    }
  }

  // Sort small cells center-out, then by angle
  const smallCells = [];
  for (let q = -smallN; q <= smallN; q++) {
    const r1 = Math.max(-smallN, -q - smallN);
    const r2 = Math.min(smallN, -q + smallN);
    for (let r = r1; r <= r2; r++) smallCells.push({ q, r });
  }
  smallCells.sort((a, b) => {
    const ra = Math.max(Math.abs(a.q), Math.abs(a.r), Math.abs(a.q + a.r));
    const rb = Math.max(Math.abs(b.q), Math.abs(b.r), Math.abs(b.q + b.r));
    if (ra !== rb) return ra - rb;
    const pa = axialToPixel(a.q, a.r);
    const pb = axialToPixel(b.q, b.r);
    return Math.atan2(pa.y, pa.x) - Math.atan2(pb.y, pb.x);
  });

  const personByKey = new Map();
  smallCells.slice(0, realPeople.length).forEach((c, i) => {
    personByKey.set(`${c.q},${c.r}`, realPeople[i]);
  });

  // Draw canvas (background — all virtual cells)
  const canvas = document.getElementById('orgCanvas');
  canvas.width  = _canvasW;
  canvas.height = _canvasH;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, _canvasW, _canvasH);

  // Batch by colony color
  const colonyBatches = {};
  COLONY_ORDER.forEach(c => { colonyBatches[c] = []; });

  for (let q = -VIRTUAL_N; q <= VIRTUAL_N; q++) {
    const r1 = Math.max(-VIRTUAL_N, -q - VIRTUAL_N);
    const r2 = Math.min(VIRTUAL_N, -q + VIRTUAL_N);
    for (let r = r1; r <= r2; r++) {
      const { x, y } = axialToPixel(q, r);
      const cx = x + OX;
      const cy = y + OY;
      _cellPixels.set(`${q},${r}`, { cx, cy });
      const colony = personByKey.has(`${q},${r}`)
        ? (personByKey.get(`${q},${r}`).comb || COLONY_ORDER[0])
        : cellColony(q, r);
      colonyBatches[colony].push({ cx, cy });
    }
  }

  // Draw all cells per colony — batch into one path per colony for speed
  COLONY_ORDER.forEach(colony => {
    const tint = COLONY_TINTS[colony] || '#1a1a1a';
    const cells = colonyBatches[colony];
    // Fill all cells in one batched path
    ctx.beginPath();
    cells.forEach(({ cx, cy }) => {
      for (let i = 0; i < 6; i++) {
        const a = Math.PI / 180 * (60 * i - 30);
        const x = cx + (HEX_R - 0.5) * Math.cos(a);
        const y = cy + (HEX_R - 0.5) * Math.sin(a);
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.closePath();
    });
    ctx.fillStyle = tint;
    ctx.fill();
    // Stroke all cells in one batched path
    ctx.beginPath();
    cells.forEach(({ cx, cy }) => {
      for (let i = 0; i < 6; i++) {
        const a = Math.PI / 180 * (60 * i - 30);
        const x = cx + (HEX_R - 0.5) * Math.cos(a);
        const y = cy + (HEX_R - 0.5) * Math.sin(a);
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.closePath();
    });
    ctx.strokeStyle = 'rgba(255,255,255,0.12)';
    ctx.lineWidth = 0.5;
    ctx.stroke();
  });

  // Build SVG overlay — only real person cells
  const svg = document.getElementById('orgSvg');
  svg.setAttribute('width',  _canvasW);
  svg.setAttribute('height', _canvasH);
  svg.setAttribute('viewBox', `0 0 ${_canvasW} ${_canvasH}`);
  svg.style.pointerEvents = 'none'; // SVG itself passes events, only polygons catch

  personByKey.forEach((person, key) => {
    const { cx, cy } = _cellPixels.get(key);
    const isMe = person.is_current_user;

    const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
    poly.setAttribute('points', hexPoints(cx, cy, HEX_R - 0.5));
    poly.setAttribute('fill', isMe ? '#1a2e5e' : '#1e1e2e');
    poly.setAttribute('stroke', isMe ? 'rgba(77,123,255,0.8)' : 'rgba(255,255,255,0.5)');
    poly.setAttribute('stroke-width', isMe ? '1.5' : '1');
    poly.setAttribute('data-person-id', person.id);
    poly.setAttribute('data-person-key', key);
    poly.style.pointerEvents = 'fill';
    poly.style.cursor = 'pointer';

    if (isMe) {
      const ring = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
      ring.setAttribute('points', hexPoints(cx, cy, HEX_R - 5));
      ring.setAttribute('fill', 'none');
      ring.setAttribute('stroke', 'rgba(77,123,255,0.4)');
      ring.setAttribute('stroke-width', '1');
      ring.style.pointerEvents = 'none';
      svg.appendChild(ring);
    }

    svg.appendChild(poly);
    poly.addEventListener('click', e => {
      e.stopPropagation();
      openPersonModal(person);
    });
  });

  // Colony section labels on SVG (only shown when zoomed out)
  const colonyLabelPos = {};
  personByKey.forEach((person, key) => {
    const { cx, cy } = _cellPixels.get(key);
    const c = person.comb || COLONY_ORDER[0];
    if (!colonyLabelPos[c]) colonyLabelPos[c] = { xs: [], ys: [] };
    colonyLabelPos[c].xs.push(cx);
    colonyLabelPos[c].ys.push(cy);
  });

  // Also sample virtual cells for colony label positions
  for (let q = -VIRTUAL_N; q <= VIRTUAL_N; q += 10) {
    const r1 = Math.max(-VIRTUAL_N, -q - VIRTUAL_N);
    const r2 = Math.min(VIRTUAL_N, -q + VIRTUAL_N);
    for (let r = r1; r <= r2; r += 10) {
      const { cx, cy } = _cellPixels.get(`${q},${r}`) || {};
      if (!cx) continue;
      const colony = cellColony(q, r);
      if (!colonyLabelPos[colony]) colonyLabelPos[colony] = { xs: [], ys: [] };
      colonyLabelPos[colony].xs.push(cx);
      colonyLabelPos[colony].ys.push(cy);
    }
  }

  COLONY_ORDER.forEach(colony => {
    const ld = colonyLabelPos[colony];
    if (!ld || !ld.xs.length) return;
    const labelX = ld.xs.reduce((s, v) => s + v, 0) / ld.xs.length;
    const labelY = ld.ys.reduce((s, v) => s + v, 0) / ld.ys.length;
    const info   = COLONY_INFO[colony] || {};

    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.classList.add('colony-section-label');
    g.style.pointerEvents = 'auto';
    g.style.cursor = 'pointer';

    const textEl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    textEl.setAttribute('x', labelX);
    textEl.setAttribute('y', labelY);
    textEl.setAttribute('text-anchor', 'middle');
    textEl.setAttribute('dominant-baseline', 'middle');
    textEl.setAttribute('fill', info.color || 'rgba(255,255,255,0.5)');
    textEl.setAttribute('font-size', '240');
    textEl.setAttribute('font-weight', '600');
    textEl.setAttribute('font-family', 'IBM Plex Sans, system-ui, sans-serif');
    textEl.setAttribute('letter-spacing', '16');
    textEl.setAttribute('pointer-events', 'none');
    textEl.textContent = (info.label || colony.replace(' Colony', '')).toUpperCase();

    g.appendChild(textEl);
    svg.appendChild(g);
    g.addEventListener('click', () => openColonyModal(colony));
  });

  // Person name labels (shown at high zoom, tied to SVG polygons)
  personByKey.forEach((person, key) => {
    const { cx, cy } = _cellPixels.get(key);
    const nameEl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    const name   = person.first_name + ' ' + person.last_name;
    nameEl.setAttribute('x', cx);
    nameEl.setAttribute('y', cy - 4);
    nameEl.setAttribute('text-anchor', 'middle');
    nameEl.setAttribute('dominant-baseline', 'middle');
    nameEl.setAttribute('fill', 'rgba(255,255,255,0.88)');
    nameEl.setAttribute('font-size', '11');
    nameEl.setAttribute('font-weight', '500');
    nameEl.setAttribute('font-family', 'IBM Plex Sans, system-ui, sans-serif');
    nameEl.setAttribute('pointer-events', 'none');
    nameEl.classList.add('org-hex-name');
    nameEl.textContent = name;
    svg.appendChild(nameEl);
  });

  updateLabelVisibility(_currentScale);
  wireZoom();
  wireModal();

  document.addEventListener('sidebar:filter', onFilter);
  container._cleanup = () => document.removeEventListener('sidebar:filter', onFilter);
}

function onFilter(e) {
  _activeFilter = e.detail;
  const count = _activeFilter
    ? _people.filter(p => !isFiltered(p)).length
    : 270000;
  const subtitle = document.getElementById('orgSubtitle');
  if (subtitle) {
    subtitle.textContent = _activeFilter
      ? `${count.toLocaleString()} matching · 6 colonies`
      : '270,000 bees · 6 colonies';
  }
  updatePersonCells();
}

function isFiltered(p) {
  if (!_activeFilter) return false;
  const { group, value } = _activeFilter;
  if (group === 'colonies')  return p.comb !== COLONY_MAP[value];
  if (group === 'jobs') {
    const map = { bss:'bss',bts:'bts',csm:'csm',manager:'manager',
                  director:'director',exec:'exec',partner:'partner',sdr:'sdr',intern:'intern' };
    return p.role_type !== map[value];
  }
  if (group === 'markets') return p.market !== MARKET_MAP[value];
  return false;
}

function updatePersonCells() {
  const svg = document.getElementById('orgSvg');
  if (!svg) return;
  svg.querySelectorAll('[data-person-id]').forEach(poly => {
    const pid = poly.dataset.personId;
    const person = _people.find(p => String(p.id) === pid);
    if (!person) return;
    const dimmed = isFiltered(person);
    const isMe   = person.is_current_user;
    poly.setAttribute('fill', dimmed ? '#111' : (isMe ? '#1a2e5e' : '#1e1e2e'));
    poly.setAttribute('stroke', dimmed ? 'rgba(255,255,255,0.1)' : (isMe ? 'rgba(77,123,255,0.8)' : 'rgba(255,255,255,0.5)'));
    poly.style.opacity = dimmed ? '0.3' : '1';
  });
}

function updateLabelVisibility(scale) {
  _currentScale = scale;
  const svg = document.getElementById('orgSvg');
  if (!svg) return;
  // Colony labels readable when very zoomed out
  const showColony = scale < 0.06;
  svg.querySelectorAll('.colony-section-label').forEach(el => {
    el.style.opacity = showColony ? '1' : '0';
    el.style.pointerEvents = showColony ? 'auto' : 'none';
  });
  // Person names at high zoom
  const showNames = scale > 0.55;
  svg.querySelectorAll('.org-hex-name').forEach(el => {
    el.style.opacity = showNames ? '1' : '0';
  });
}

// ── Modal helpers ─────────────────────────────────────────────────
function openColonyModal(colony) {
  const info    = COLONY_INFO[colony] || {};
  const titleEl = document.getElementById('orgModalTitle');
  const bodyEl  = document.getElementById('orgModalBody');
  const overlay = document.getElementById('orgModalOverlay');
  if (!overlay) return;

  titleEl.textContent = info.label || colony;
  titleEl.style.color = info.color || '#fff';

  bodyEl.innerHTML = `
    <div class="org-modal-meta">
      <span class="org-modal-badge" style="background:${info.color}22;color:${info.color};border-color:${info.color}44">${info.headcount || ''} employees</span>
    </div>
    <p class="org-modal-desc">${info.desc || ''}</p>
    ${info.products ? `
      <div class="org-modal-section-title">Key products</div>
      <div class="org-modal-tags">
        ${info.products.map(p => `<span class="org-modal-tag">${p}</span>`).join('')}
      </div>
    ` : ''}
  `;

  overlay.classList.add('open');
}

function openPersonModal(person) {
  const titleEl = document.getElementById('orgModalTitle');
  const bodyEl  = document.getElementById('orgModalBody');
  const overlay = document.getElementById('orgModalOverlay');
  if (!overlay) return;

  titleEl.textContent = person.first_name + ' ' + person.last_name;
  titleEl.style.color = '#fff';

  const colonyInfo = COLONY_INFO[person.comb] || {};

  bodyEl.innerHTML = `
    <div class="org-modal-meta">
      <span class="org-modal-badge" style="background:${colonyInfo.color || '#333'}22;color:${colonyInfo.color || '#aaa'};border-color:${colonyInfo.color || '#333'}44">
        ${colonyInfo.label || person.comb || '—'}
      </span>
      ${person.is_current_user ? '<span class="org-modal-badge" style="background:rgba(77,123,255,0.12);color:#4d7bff;border-color:rgba(77,123,255,0.2)">You</span>' : ''}
    </div>
    <div class="org-modal-person-grid">
      <div class="org-modal-field"><div class="org-modal-field-label">Role</div><div>${person.role || '—'}</div></div>
      <div class="org-modal-field"><div class="org-modal-field-label">Market</div><div>${person.market || '—'}</div></div>
      <div class="org-modal-field"><div class="org-modal-field-label">Location</div><div>${person.location || '—'}</div></div>
      <div class="org-modal-field"><div class="org-modal-field-label">Email</div><div style="color:#4d7bff">${person.email || '—'}</div></div>
    </div>
  `;

  overlay.classList.add('open');
}

function wireModal() {
  const overlay  = document.getElementById('orgModalOverlay');
  const closeBtn = document.getElementById('orgModalClose');
  if (!overlay) return;
  closeBtn?.addEventListener('click', () => overlay.classList.remove('open'));
  overlay.addEventListener('click', e => {
    if (e.target === overlay) overlay.classList.remove('open');
  });
}

// ── Zoom + pan ────────────────────────────────────────────────────
function wireZoom() {
  const viewport = document.getElementById('orgViewport');
  const canvas   = document.getElementById('orgCanvas');
  const svg      = document.getElementById('orgSvg');
  if (!viewport || !canvas || !svg) return;

  let scale = 1, tx = 0, ty = 0;
  let dragging = false, didDrag = false, sx = 0, sy = 0, stx = 0, sty = 0;

  function applyTransform() {
    const t = `translate(${tx}px,${ty}px) scale(${scale})`;
    canvas.style.transform = t;
    svg.style.transform    = t;
    updateLabelVisibility(scale);
  }

  function fit() {
    const vw = viewport.clientWidth  || 900;
    const vh = viewport.clientHeight || 700;
    // Start zoomed very far out — hive is a tiny hex speck
    scale = Math.min(vw / _canvasW, vh / _canvasH) * 0.12;
    tx = (vw - _canvasW * scale) / 2;
    ty = (vh - _canvasH * scale) / 2;
    applyTransform();
  }

  requestAnimationFrame(() => requestAnimationFrame(fit));

  const zoom = (factor, cx, cy) => {
    cx = cx ?? viewport.clientWidth  / 2;
    cy = cy ?? viewport.clientHeight / 2;
    const ns = Math.min(Math.max(scale * factor, 0.03), 8);
    tx = cx - (cx - tx) * (ns / scale);
    ty = cy - (cy - ty) * (ns / scale);
    scale = ns;
    applyTransform();
  };

  document.getElementById('orgZoomIn')?.addEventListener('click',    () => zoom(1.4));
  document.getElementById('orgZoomOut')?.addEventListener('click',   () => zoom(1 / 1.4));
  document.getElementById('orgZoomReset')?.addEventListener('click', fit);

  viewport.addEventListener('wheel', e => {
    e.preventDefault();
    const rect = viewport.getBoundingClientRect();
    zoom(e.deltaY < 0 ? 1.12 : 0.89, e.clientX - rect.left, e.clientY - rect.top);
  }, { passive: false });

  viewport.addEventListener('mousedown', e => {
    if (e.button !== 0) return;
    dragging = true; didDrag = false;
    sx = e.clientX; sy = e.clientY; stx = tx; sty = ty;
    viewport.style.cursor = 'grabbing';
  });
  window.addEventListener('mousemove', e => {
    if (!dragging) return;
    const dx = e.clientX - sx, dy = e.clientY - sy;
    if (Math.abs(dx) > 4 || Math.abs(dy) > 4) didDrag = true;
    tx = stx + dx; ty = sty + dy;
    applyTransform();
  });
  window.addEventListener('mouseup', () => {
    dragging = false;
    if (viewport) viewport.style.cursor = 'grab';
  });
  viewport.addEventListener('click', e => {
    if (didDrag) { e.stopImmediatePropagation(); didDrag = false; }
  }, true);

  // Pinch zoom
  let lastDist = 0;
  viewport.addEventListener('touchstart', e => {
    if (e.touches.length === 2) {
      lastDist = Math.hypot(
        e.touches[0].clientX - e.touches[1].clientX,
        e.touches[0].clientY - e.touches[1].clientY
      );
    }
  }, { passive: true });
  viewport.addEventListener('touchmove', e => {
    if (e.touches.length === 2) {
      e.preventDefault();
      const dist = Math.hypot(
        e.touches[0].clientX - e.touches[1].clientX,
        e.touches[0].clientY - e.touches[1].clientY
      );
      const midX = (e.touches[0].clientX + e.touches[1].clientX) / 2;
      const midY = (e.touches[0].clientY + e.touches[1].clientY) / 2;
      const rect = viewport.getBoundingClientRect();
      zoom(dist / lastDist, midX - rect.left, midY - rect.top);
      lastDist = dist;
    }
  }, { passive: false });
}

