    poly.setAttribute('fill', dim ? '#080808' : (me ? '#1a2e5e' : '#1e1e2e'));
    poly.setAttribute('stroke', dim ? 'rgba(255,255,255,0.08)' : (me ? 'rgba(77,123,255,0.9)' : 'rgba(255,255,255,0.6)'));
