const HEX_R = 3;
const HEX_W = Math.sqrt(3) * HEX_R;
const ROW_H = HEX_R * 1.5;
const N = 300;
function axialToPixel(q, r) { return { x: HEX_W*(q+r/2), y: ROW_H*r }; }
const edgeX = Math.abs(axialToPixel(N,0).x) + HEX_R + 4;
const edgeY = Math.abs(axialToPixel(0,-N).y) + HEX_R + 4;
const W = Math.ceil(edgeX*2+8);
const H = Math.ceil(edgeY*2+8);
console.log('Canvas:', W+'x'+H, '=', ((W*H*4)/1024/1024).toFixed(0)+'MB');
console.log('OX:', W/2, 'OY:', H/2);
