/**
 * org.js — Organization: a hive shaped like the IBM Hive logo.
 *
 * The hive is a diamond / beehive silhouette built from hexagonal cells —
 * wide in the middle, tapering to narrower rows at top and bottom, mirroring
 * the stacked-bar logo shape.
 *
 * Visual style:
 *  • Black background
 *  • Dark #1a1a1a hex cells with thin rgba(255,255,255,0.18) stroke — crisp
 *    white grid lines that read clearly at any zoom level
 *  • Real people get a slightly brighter cell + name on zoom-in
 *  • Default zoom: hive fills ~80% of viewport — immediately readable
 *
 * Rendered on a single <canvas> (no DOM per-cell, fast).
 * SVG overlay for person cells (clickable) and portfolio labels.
 */
import { getPeople } from '../api.js';

// ── Colony / Portfolio data ───────────────────────────────────────
const COLONY_ORDER = [
  'Data & AI Colony',
  'Automation Colony',
  'Sustainability Colony',
  'Security Colony',
  'Infrastructure Colony',
  'Hybrid Cloud Colony',
];

const COLONY_INFO = {
  'Data & AI Colony': {
    label: 'Data & AI',
    color: '#0f62fe',
    desc: 'watsonx, data platforms, analytics, and AI governance. The largest colony — driving AI adoption across enterprise accounts.',
    headcount: '~47,000',
    products: ['watsonx.ai', 'watsonx.data', 'watsonx.governance', 'IBM Db2', 'IBM Cognos'],
  },
  'Automation Colony': {
    label: 'Automation',
    color: '#6c63ff',
    desc: 'Business automation, workflow intelligence, and RPA. Reduces operational overhead and accelerates decision-making.',
    headcount: '~38,000',
    products: ['IBM Business Automation Workflow', 'IBM RPA', 'IBM Datacap', 'IBM FileNet'],
  },
  'Sustainability Colony': {
    label: 'Sustainability',
    color: '#24a148',
    desc: 'Environmental intelligence and sustainability reporting. Enables organizations to measure, manage, and improve their environmental footprint.',
    headcount: '~29,000',
    products: ['IBM Envizi', 'IBM TRIRIGA', 'IBM Maximo'],
  },
  'Security Colony': {
    label: 'Security',
    color: '#da1e28',
    desc: 'Threat intelligence, SOC operations, identity, and data security. Protects critical infrastructure and enterprise data.',
    headcount: '~44,000',
    products: ['IBM QRadar', 'IBM Guardium', 'IBM Verify', 'IBM Security X-Force'],
  },
  'Infrastructure Colony': {
    label: 'Infrastructure',
    color: '#a855f7',
    desc: 'IBM Power, Storage, and z Systems. Sells IBM PowerVS, IBM FlashSystems, and IBM Fusion to all US enterprise accounts.',
    headcount: '~61,000',
    products: ['IBM PowerVS', 'IBM FlashSystem', 'IBM Fusion', 'IBM z16', 'IBM LinuxONE'],
  },
  'Hybrid Cloud Colony': {
    label: 'Hybrid Cloud',
    color: '#ee5396',
    desc: 'Red Hat OpenShift, IBM Cloud, and hybrid multi-cloud strategy. Bridges on-premises and cloud-native workloads.',
    headcount: '~51,000',
    products: ['Red Hat OpenShift', 'IBM Cloud', 'IBM Cloud Paks', 'Red Hat Ansible'],
  },
};

const COLONY_MAP = {
  'data-ai':        'Data & AI Colony',
  'automation':     'Automation Colony',
  'sustainability': 'Sustainability Colony',
  'security':       'Security Colony',
  'infrastructure': 'Infrastructure Colony',
  'hybrid-cloud':   'Hybrid Cloud Colony',
};

const MARKET_MAP = {
  enterprise: 'Enterprise', strategic: 'Strategic',
  horizon:    'Horizon',    territory: 'Territory',
};

const ROLE_ORDER = {
  exec:0, director:1, manager:2, bss:3, bts:4, csm:5, sdr:6, partner:7, intern:8, other:9,
};

// ── Hex geometry — flat-top orientation ──────────────────────────
// Flat-top gives wider rows that mirror the logo's horizontal bars better.
const HEX_R  = 22;   // cell radius (pixels) — large enough to see clearly
const HEX_W  = HEX_R * 2;
const HEX_H  = Math.sqrt(3) * HEX_R;
const COL_W  = HEX_W * 0.75;  // horizontal spacing center-to-center
const ROW_H  = HEX_H;         // vertical spacing center-to-center

// Flat-top hex: axial → pixel
function axialToPixel(q, r) {
  const x = COL_W * q;
  const y = ROW_H * (r + q / 2);
  return { x, y };
}

// Flat-top hex points (6 corners)
function hexPath(ctx, cx, cy, r) {
  for (let i = 0; i < 6; i++) {
    const a = (Math.PI / 3) * i; // 0, 60, 120, 180, 240, 300°
    const x = cx + r * Math.cos(a);
    const y = cy + r * Math.sin(a);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

function svgHexPoints(cx, cy, r) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = (Math.PI / 3) * i;
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(' ');
}

// ── Logo-shaped hive: define which axial cells are included ───────
//
// The IBM Hive logo is 5 horizontal bars tapering like:
//   row -4:  width 3  (top, narrow)
//   row -2:  width 5
//   row  0:  width 6  (widest)
//   row +2:  width 5
//   row +4:  width 3  (bottom, narrow)
//
// We'll build a flat-top hex grid where the "row" is the r-coordinate
// (adjusted for the flat-top offset) and the width per row follows
// a diamond/beehive profile.
//
// Profile (r = axial row, half-width in hex units):
//   r = -6  → 2  cells
//   r = -5  → 3  cells
//   r = -4  → 4  cells
//   r = -3  → 5  cells
//   r = -2  → 6  cells
//   r = -1  → 6  cells
//   r =  0  → 7  cells  ← widest
//   r =  1  → 6  cells
//   r =  2  → 6  cells
//   r =  3  → 5  cells
//   r =  4  → 4  cells
//   r =  5  → 3  cells
//   r =  6  → 2  cells
//
// For flat-top hex, the axial → pixel mapping already handles the
// half-offset between columns, so rows line up like the logo bars.

const ROW_WIDTHS = [
  [-6, 2], [-5, 3], [-4, 4], [-3, 5], [-2, 6], [-1, 6],
  [ 0, 7],
  [ 1, 6], [ 2, 6], [ 3, 5], [ 4, 4], [ 5, 3], [ 6, 2],
];

// Generate cells for the hive shape — use offset-grid rows
// We'll work in offset-column coordinates then convert to axial.
function buildHiveCells() {
  const cells = []; // { q, r } axial coords

  // Use "offset-row" grid: for each row R, cells span q from -(hw-1) to +(hw-1) in q
  // In flat-top axial: for a given r, q can range freely.
  // We'll set q such that pixel x is centered.
  ROW_WIDTHS.forEach(([rowR, halfW]) => {
    // halfW = number of cells on each side + center
    for (let qi = -(halfW - 1); qi <= (halfW - 1); qi++) {
      // For flat-top hex, to keep rows horizontally centered we need to offset
      // q so the row starts at the right place.
      // In flat-top axial, r controls the row. For a given r, pixel x = COL_W * q
      // with a small y-offset. To center the row of halfW*2-1 cells:
      cells.push({ q: qi, r: rowR });
    }
  });

  return cells;
}

// Assign colony to a cell based on which "sextant" of the hive it's in
// We divide the hive into 6 vertical bands (left→right = 6 portfolios)
function cellColony(q, r, totalCols) {
  // Map q from [-(totalCols-1), +(totalCols-1)] to [0..5]
  const maxQ = 6;
  const normalized = (q + maxQ) / (maxQ * 2);
  const idx = Math.min(5, Math.floor(normalized * 6));
  return COLONY_ORDER[idx];
}

// ── Module state ─────────────────────────────────────────────────
let _people       = [];
let _activeFilter = null;
let _scale        = 1;
let _canvasW      = 0;
let _canvasH      = 0;

const _cellPx     = new Map(); // "q,r" → {cx,cy}

export async function renderOrg(container) {
  container.innerHTML = `
    <div class="org-hive-page">
      <div class="org-hive-toolbar">
        <div class="org-hive-toolbar-left">
          <span class="org-hive-title">Organization</span>
          <span class="org-hive-subtitle" id="orgSubtitle">270,000 bees · 6 portfolios</span>
        </div>
        <div class="org-hive-controls">
          <button class="colony-zoom-btn" id="orgZoomIn"    title="Zoom in">+</button>
          <button class="colony-zoom-btn" id="orgZoomOut"   title="Zoom out">−</button>
          <button class="colony-zoom-btn" id="orgZoomReset" title="Fit" style="font-size:11px">Fit</button>
        </div>
      </div>
      <div class="colony-viewport" id="orgViewport"
           style="position:relative;cursor:grab;overflow:hidden;flex:1;min-height:0;background:#000">
        <canvas id="orgCanvas"
                style="position:absolute;top:0;left:0;transform-origin:0 0;will-change:transform"></canvas>
        <svg id="orgSvg" xmlns="http://www.w3.org/2000/svg"
             style="position:absolute;top:0;left:0;transform-origin:0 0;will-change:transform;overflow:visible"></svg>
      </div>
    </div>
    <div class="org-modal-overlay" id="orgModalOverlay">
      <div class="org-modal">
        <div class="org-modal-header">
          <div class="org-modal-title" id="orgModalTitle"></div>
          <div class="org-modal-close" id="orgModalClose">✕</div>
        </div>
        <div class="org-modal-body" id="orgModalBody"></div>
      </div>
    </div>
  `;

  _people = await getPeople();

  // Sort people: colony → role
  const byColony = {};
  COLONY_ORDER.forEach(c => { byColony[c] = []; });
  _people.forEach(p => {
    const c = p.comb || COLONY_ORDER[0];
    if (!byColony[c]) byColony[c] = [];
    byColony[c].push(p);
  });
  COLONY_ORDER.forEach(c => {
    byColony[c].sort((a, b) => (ROLE_ORDER[a.role_type] ?? 9) - (ROLE_ORDER[b.role_type] ?? 9));
  });
  const realPeople = COLONY_ORDER.flatMap(c => byColony[c] || []);

  // Build the logo-shaped cell set
  const hiveCells = buildHiveCells();

  // Canvas bounding box
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  hiveCells.forEach(({ q, r }) => {
    const { x, y } = axialToPixel(q, r);
    if (x - HEX_R < minX) minX = x - HEX_R;
    if (x + HEX_R > maxX) maxX = x + HEX_R;
    if (y - HEX_H / 2 < minY) minY = y - HEX_H / 2;
    if (y + HEX_H / 2 > maxY) maxY = y + HEX_H / 2;
  });
  const pad = 8;
  _canvasW = Math.ceil(maxX - minX + pad * 2);
  _canvasH = Math.ceil(maxY - minY + pad * 2);
  const OX = -minX + pad;
  const OY = -minY + pad;

  // Precompute pixel centers
  hiveCells.forEach(({ q, r }) => {
    const { x, y } = axialToPixel(q, r);
    _cellPx.set(`${q},${r}`, { cx: x + OX, cy: y + OY });
  });

  // Assign real people to cells (center-outward order within each colony group)
  // Divide hive into 6 vertical bands for portfolios
  const colonyBands = {};
  COLONY_ORDER.forEach(c => { colonyBands[c] = []; });
  hiveCells.forEach(cell => {
    const c = cellColony(cell.q, cell.r, 7);
    colonyBands[c].push(cell);
  });

  // Sort each band center-out so people land near the center of their band
  Object.keys(colonyBands).forEach(c => {
    colonyBands[c].sort((a, b) => (Math.abs(a.r)) - (Math.abs(b.r)) || Math.abs(a.q) - Math.abs(b.q));
  });

  // Assign people colony by colony
  const personByKey = new Map();
  let pIdx = 0;
  COLONY_ORDER.forEach((colony, ci) => {
    const colonyPeople = byColony[colony] || [];
    const band = colonyBands[colony] || [];
    colonyPeople.forEach((person, i) => {
      if (i < band.length) {
        const { q, r } = band[i];
        personByKey.set(`${q},${r}`, person);
      }
    });
  });

  // ── Draw canvas ───────────────────────────────────────────────
  const canvas = document.getElementById('orgCanvas');
  canvas.width  = _canvasW;
  canvas.height = _canvasH;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, _canvasW, _canvasH);

  // Draw ALL cells in one fill pass (uniform dark gray fill)
  ctx.beginPath();
  hiveCells.forEach(({ q, r }) => {
    const { cx, cy } = _cellPx.get(`${q},${r}`);
    hexPath(ctx, cx, cy, HEX_R - 0.5);
  });
  ctx.fillStyle = '#1a1a1a';
  ctx.fill();

  // Stroke all cells in one pass — thin white lines
  ctx.beginPath();
  hiveCells.forEach(({ q, r }) => {
    const { cx, cy } = _cellPx.get(`${q},${r}`);
    hexPath(ctx, cx, cy, HEX_R - 0.5);
  });
  ctx.strokeStyle = 'rgba(255,255,255,0.22)';
  ctx.lineWidth = 0.8;
  ctx.stroke();

  // ── SVG overlay — person + portfolio labels ───────────────────
  const svg = document.getElementById('orgSvg');
  svg.setAttribute('width',   _canvasW);
  svg.setAttribute('height',  _canvasH);
  svg.setAttribute('viewBox', `0 0 ${_canvasW} ${_canvasH}`);

  // Render person cells on SVG (slightly lighter, clickable)
  personByKey.forEach((person, key) => {
    const px = _cellPx.get(key);
    if (!px) return;
    const { cx, cy } = px;
    const isMe = person.is_current_user;

    const poly = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
    poly.setAttribute('points', svgHexPoints(cx, cy, HEX_R - 0.5));
    poly.setAttribute('fill', isMe ? '#0d1f3c' : '#252525');
    poly.setAttribute('stroke', isMe ? 'rgba(77,123,255,0.85)' : 'rgba(255,255,255,0.45)');
    poly.setAttribute('stroke-width', isMe ? '1.2' : '0.8');
    poly.setAttribute('data-person-id', person.id);
    poly.style.cursor = 'pointer';
    svg.appendChild(poly);

    if (isMe) {
      const ring = document.createElementNS('http://www.w3.org/2000/svg', 'polygon');
      ring.setAttribute('points', svgHexPoints(cx, cy, HEX_R - 5));
      ring.setAttribute('fill', 'none');
      ring.setAttribute('stroke', 'rgba(77,123,255,0.3)');
      ring.setAttribute('stroke-width', '0.8');
      ring.style.pointerEvents = 'none';
      svg.appendChild(ring);
    }

    poly.addEventListener('click', e => { e.stopPropagation(); openPersonModal(person); });

    // Name label (shown only at high zoom)
    const nameEl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    nameEl.setAttribute('x', cx);
    nameEl.setAttribute('y', cy);
    nameEl.setAttribute('text-anchor', 'middle');
    nameEl.setAttribute('dominant-baseline', 'middle');
    nameEl.setAttribute('fill', isMe ? '#4d7bff' : 'rgba(255,255,255,0.85)');
    nameEl.setAttribute('font-size', String(HEX_R * 0.42));
    nameEl.setAttribute('font-weight', isMe ? '500' : '400');
    nameEl.setAttribute('font-family', 'IBM Plex Sans, system-ui, sans-serif');
    nameEl.setAttribute('pointer-events', 'none');
    nameEl.classList.add('org-hex-name');
    nameEl.textContent = person.first_name + ' ' + person.last_name;
    svg.appendChild(nameEl);
  });

  // Portfolio band labels — one per column band, centered vertically in the hive
  COLONY_ORDER.forEach((colony, ci) => {
    const band = colonyBands[colony] || [];
    if (!band.length) return;
    const info = COLONY_INFO[colony] || {};

    // Centroid of the band
    let sx = 0, sy = 0;
    band.forEach(({ q, r }) => {
      const px = _cellPx.get(`${q},${r}`);
      if (px) { sx += px.cx; sy += px.cy; }
    });
    const lx = sx / band.length;
    const ly = sy / band.length;

    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.classList.add('colony-section-label');
    g.style.cursor = 'pointer';

    const t = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    t.setAttribute('x', lx);
    t.setAttribute('y', ly);
    t.setAttribute('text-anchor', 'middle');
    t.setAttribute('dominant-baseline', 'middle');
    t.setAttribute('fill', info.color || 'rgba(255,255,255,0.5)');
    t.setAttribute('font-size', String(HEX_R * 0.7));
    t.setAttribute('font-weight', '600');
    t.setAttribute('font-family', 'IBM Plex Sans, system-ui, sans-serif');
    t.setAttribute('letter-spacing', '1');
    t.setAttribute('pointer-events', 'none');
    // Short label to fit in cells
    t.textContent = (info.label || colony.replace(' Colony', '')).toUpperCase();

    g.appendChild(t);
    svg.appendChild(g);
    g.addEventListener('click', () => openColonyModal(colony));
  });

  updateVisibility(_scale);
  wireZoom();
  wireModal();

  document.addEventListener('sidebar:filter', onFilter);
  container._cleanup = () => document.removeEventListener('sidebar:filter', onFilter);
}

// ── Filter ────────────────────────────────────────────────────────
function onFilter(e) {
  _activeFilter = e.detail;
  const svg = document.getElementById('orgSvg');
  if (!svg) return;

  const sub = document.getElementById('orgSubtitle');
  if (sub) {
    const count = _activeFilter ? _people.filter(p => !isFiltered(p)).length : 270000;
    sub.textContent = _activeFilter
      ? `${count.toLocaleString()} matching · 6 portfolios`
      : '270,000 bees · 6 portfolios';
  }

  svg.querySelectorAll('[data-person-id]').forEach(poly => {
    const person = _people.find(p => String(p.id) === poly.dataset.personId);
    if (!person) return;
    const dim = isFiltered(person);
    const me  = person.is_current_user;
    poly.setAttribute('fill', dim ? '#0d0d0d' : (me ? '#0d1f3c' : '#252525'));
    poly.setAttribute('stroke', dim ? 'rgba(255,255,255,0.06)' : (me ? 'rgba(77,123,255,0.85)' : 'rgba(255,255,255,0.45)'));
    poly.style.opacity = dim ? '0.2' : '1';
  });

  // Portfolio filter — dim other bands
  const canvas = document.getElementById('orgCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');

  // Redraw canvas with correct highlight
  const hiveCells = buildHiveCells();
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, _canvasW, _canvasH);

  const activeColony = _activeFilter?.group === 'portfolios' ? COLONY_MAP[_activeFilter.value] : null;

  hiveCells.forEach(({ q, r }) => {
    const { cx, cy } = _cellPx.get(`${q},${r}`);
    const c = cellColony(q, r, 7);
    const dimmed = activeColony && c !== activeColony;

    ctx.beginPath();
    hexPath(ctx, cx, cy, HEX_R - 0.5);
    ctx.fillStyle = dimmed ? '#0d0d0d' : '#1a1a1a';
    ctx.fill();
    ctx.strokeStyle = dimmed ? 'rgba(255,255,255,0.06)' : 'rgba(255,255,255,0.22)';
    ctx.lineWidth = 0.8;
    ctx.stroke();
  });
}

function isFiltered(p) {
  if (!_activeFilter) return false;
  const { group, value } = _activeFilter;
  if (group === 'portfolios') return p.comb !== COLONY_MAP[value];
  if (group === 'jobs') {
    const m = { bss:'bss',bts:'bts',csm:'csm',manager:'manager',
                director:'director',exec:'exec',partner:'partner',sdr:'sdr',intern:'intern' };
    return p.role_type !== m[value];
  }
  if (group === 'markets') return p.market !== MARKET_MAP[value];
  return false;
}

// ── Label / name visibility ───────────────────────────────────────
function updateVisibility(scale) {
  _scale = scale;
  const svg = document.getElementById('orgSvg');
  if (!svg) return;

  // Portfolio labels: always on (they sit inside cells, scale naturally)
  const showLabels = scale >= 0.4;
  svg.querySelectorAll('.colony-section-label').forEach(el => {
    el.style.opacity = showLabels ? '0.7' : '0';
    el.style.pointerEvents = showLabels ? 'auto' : 'none';
  });

  // Person names: readable at medium+ zoom
  const showNames = scale >= 1.5;
  svg.querySelectorAll('.org-hex-name').forEach(el => {
    el.style.opacity = showNames ? '1' : '0';
  });
}

// ── Modals ────────────────────────────────────────────────────────
function openColonyModal(colony) {
  const info = COLONY_INFO[colony] || {};
  const el   = document.getElementById('orgModalTitle');
  const body = document.getElementById('orgModalBody');
  const ov   = document.getElementById('orgModalOverlay');
  if (!ov) return;

  el.textContent = info.label || colony;
  el.style.color = info.color || '#fff';
  body.innerHTML = `
    <div class="org-modal-meta">
      <span class="org-modal-badge" style="background:${info.color}22;color:${info.color};border-color:${info.color}44">
        ${info.headcount || ''} employees
      </span>
    </div>
    <p class="org-modal-desc">${info.desc || ''}</p>
    ${info.products ? `
      <div class="org-modal-section-title">Key products</div>
      <div class="org-modal-tags">${info.products.map(p => `<span class="org-modal-tag">${p}</span>`).join('')}</div>
    ` : ''}
  `;
  ov.classList.add('open');
}

function openPersonModal(person) {
  const el   = document.getElementById('orgModalTitle');
  const body = document.getElementById('orgModalBody');
  const ov   = document.getElementById('orgModalOverlay');
  if (!ov) return;

  el.textContent = person.first_name + ' ' + person.last_name;
  el.style.color = '#fff';
  const ci = COLONY_INFO[person.comb] || {};
  body.innerHTML = `
    <div class="org-modal-meta">
      <span class="org-modal-badge" style="background:${ci.color||'#333'}22;color:${ci.color||'#aaa'};border-color:${ci.color||'#333'}44">
        ${ci.label || person.comb || '—'}
      </span>
      ${person.is_current_user ? '<span class="org-modal-badge" style="background:rgba(77,123,255,0.12);color:#4d7bff;border-color:rgba(77,123,255,0.2)">You</span>' : ''}
    </div>
    <div class="org-modal-person-grid">
      <div class="org-modal-field"><div class="org-modal-field-label">Role</div><div>${person.role || '—'}</div></div>
      <div class="org-modal-field"><div class="org-modal-field-label">Market</div><div>${person.market || '—'}</div></div>
      <div class="org-modal-field"><div class="org-modal-field-label">Location</div><div>${person.location || '—'}</div></div>
      <div class="org-modal-field"><div class="org-modal-field-label">Email</div><div style="color:#4d7bff">${person.email || '—'}</div></div>
    </div>
  `;
  ov.classList.add('open');
}

function wireModal() {
  const ov  = document.getElementById('orgModalOverlay');
  const btn = document.getElementById('orgModalClose');
  if (!ov) return;
  btn?.addEventListener('click', () => ov.classList.remove('open'));
  ov.addEventListener('click', e => { if (e.target === ov) ov.classList.remove('open'); });
}

// ── Zoom + pan ────────────────────────────────────────────────────
function wireZoom() {
  const viewport = document.getElementById('orgViewport');
  const canvas   = document.getElementById('orgCanvas');
  const svg      = document.getElementById('orgSvg');
  if (!viewport || !canvas || !svg) return;

  let scale = 1, tx = 0, ty = 0;
  let dragging = false, didDrag = false, sx = 0, sy = 0, stx = 0, sty = 0;

  function applyTransform() {
    const t = `translate(${tx}px,${ty}px) scale(${scale})`;
    canvas.style.transform = t;
    svg.style.transform    = t;
    updateVisibility(scale);
  }

  function fit() {
    const vw = viewport.clientWidth  || 900;
    const vh = viewport.clientHeight || 700;
    // Fill ~80% of the viewport — hive is large and immediately legible
    scale = Math.min(vw / _canvasW, vh / _canvasH) * 0.80;
    tx = (vw - _canvasW * scale) / 2;
    ty = (vh - _canvasH * scale) / 2;
    applyTransform();
  }

  requestAnimationFrame(() => requestAnimationFrame(fit));

  const zoom = (factor, cx, cy) => {
    cx = cx ?? viewport.clientWidth  / 2;
    cy = cy ?? viewport.clientHeight / 2;
    const ns = Math.min(Math.max(scale * factor, 0.05), 20);
    tx = cx - (cx - tx) * (ns / scale);
    ty = cy - (cy - ty) * (ns / scale);
    scale = ns;
    applyTransform();
  };

  document.getElementById('orgZoomIn')?.addEventListener('click',    () => zoom(1.5));
  document.getElementById('orgZoomOut')?.addEventListener('click',   () => zoom(1 / 1.5));
  document.getElementById('orgZoomReset')?.addEventListener('click', fit);

  viewport.addEventListener('wheel', e => {
    e.preventDefault();
    const r = viewport.getBoundingClientRect();
    zoom(e.deltaY < 0 ? 1.12 : 0.89, e.clientX - r.left, e.clientY - r.top);
  }, { passive: false });

  viewport.addEventListener('mousedown', e => {
    if (e.button !== 0) return;
    dragging = true; didDrag = false;
    sx = e.clientX; sy = e.clientY; stx = tx; sty = ty;
    viewport.style.cursor = 'grabbing';
  });
  window.addEventListener('mousemove', e => {
    if (!dragging) return;
    const dx = e.clientX - sx, dy = e.clientY - sy;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) didDrag = true;
    tx = stx + dx; ty = sty + dy;
    applyTransform();
  });
  window.addEventListener('mouseup', () => {
    dragging = false;
    if (viewport) viewport.style.cursor = 'grab';
  });
  viewport.addEventListener('click', e => {
    if (didDrag) { e.stopImmediatePropagation(); didDrag = false; }
  }, true);

  // Pinch-to-zoom
  let lastDist = 0;
  viewport.addEventListener('touchstart', e => {
    if (e.touches.length === 2)
      lastDist = Math.hypot(e.touches[0].clientX - e.touches[1].clientX,
                            e.touches[0].clientY - e.touches[1].clientY);
  }, { passive: true });
  viewport.addEventListener('touchmove', e => {
    if (e.touches.length !== 2) return;
    e.preventDefault();
    const dist = Math.hypot(e.touches[0].clientX - e.touches[1].clientX,
                            e.touches[0].clientY - e.touches[1].clientY);
    const r    = viewport.getBoundingClientRect();
    zoom(dist / lastDist, (e.touches[0].clientX + e.touches[1].clientX) / 2 - r.left,
                          (e.touches[0].clientY + e.touches[1].clientY) / 2 - r.top);
    lastDist = dist;
  }, { passive: false });
}

