63 | function renderStats(accounts) {
64 |   const el = document.getElementById('acct-stats');
65 |   if (!el) return;
66 | 
67 |   const total     = accounts.length;
68 |   const closedWon = accounts.filter(a => a.stage === 'Closed Won').reduce((s,a) => s + (a.value_usd||0), 0);
69 |   const pipeline  = accounts.filter(a => ['Negotiation','Proposal'].includes(a.stage)).reduce((s,a) => s + (a.value_usd||0), 0);
70 |   const atRisk    = accounts.filter(a => a.stage === 'At Risk').reduce((s,a) => s + (a.value_usd||0), 0);
