80 | function renderHive(accounts, activeStage) {
81 |   const hive = document.getElementById('acct-hive');
82 |   if (!hive) return;
83 | 
84 |   // Chunk accounts into rows of 4–5 (offset every other)
85 |   const ROW_SIZE = 4;
86 |   const rows = [];
87 |   for (let i = 0; i < accounts.length; i += ROW_SIZE) {
88 |     rows.push(accounts.slice(i, i + ROW_SIZE));
89 |   }
90 | 
91 |   hive.innerHTML = rows.map((row, ri) => `
92 |     <div class="hex-row acct-row" style="${ri % 2 === 1 ? 'margin-left:44px' : ''}">
93 |       ${row.map(a => {
94 |         const color   = STAGE_COLORS[a.stage] || 'var(--stage-prospect)';
95 |         const dimmed  = activeStage && a.stage !== activeStage;
96 |         const valStr  = a.value_usd ? '$' + (a.value_usd / 1000).toFixed(0) + 'K' : '—';
97 |         return `
98 |           <div class="acct-hex" data-acct-id="${a.id}"
99 |                style="background:${color};opacity:${dimmed ? 0.2 : 1};pointer-events:${dimmed ? 'none' : 'auto'}">
100 |             <div class="acct-name">${a.short_name || a.name}</div>
101 |             <div class="acct-val">${valStr}</div>
102 |             <div class="acct-stage">${a.stage}</div>
103 |           </div>
104 |         `;
105 |       }).join('')}
106 |     </div>
107 |   `).join('');
108 | 
109 |   hive.querySelectorAll('[data-acct-id]').forEach(el => {
110 |     el.addEventListener('click', () => openAccount(el.dataset.acctId));
111 |   });
112 | }
113 | 
114 | function fmt(n) {
115 |   if (n >= 1_000_000) return '$' + (n / 1_000_000).toFixed(1) + 'M';
116 |   if (n >= 1_000)     return '$' + (n / 1_000).toFixed(0) + 'K';
117 |   return '$' + n;
118 | }
