183 | async function boot() {
184 |   try {
185 |     const people = await getPeople();
186 |     const me = people.find(p => p.is_current_user);
187 |     if (me) {
188 |       document.getElementById('currentUserName').textContent = me.first_name + ' ' + me.last_name;
189 |     }
