196 | function wireProfileDropdown() {
197 |   const userSection = document.getElementById('topnavUser');
198 |   const dropdown    = document.getElementById('userDropdown');
199 |   if (!userSection || !dropdown) return;
200 | 
201 |   userSection.addEventListener('click', e => {
202 |     e.stopPropagation();
203 |     dropdown.classList.toggle('open');
204 |   });
205 |   document.addEventListener('click', e => {
206 |     if (!userSection.contains(e.target)) dropdown.classList.remove('open');
207 |   });
208 | 
209 |   dropdown.querySelectorAll('.user-dropdown-item').forEach(item => {
210 |     item.addEventListener('click', e => {
211 |       e.stopPropagation();
212 |       dropdown.querySelectorAll('.user-dropdown-item').forEach(i => i.classList.remove('active'));
213 |       item.classList.add('active');
214 |       const nameEl = document.getElementById('currentUserName');
215 |       if (item.dataset.profile === 'sydney')       nameEl.textContent = 'Sydney Chin';
216 |       else if (item.dataset.profile === 'manager') nameEl.textContent = 'Chris Kennedy';
217 |       else if (item.dataset.profile === 'admin')   nameEl.textContent = 'Admin';
218 |       dropdown.classList.remove('open');
219 |     });
220 |   });
221 | }
