234 | async function activateView(viewName) {
235 |   // Update top nav
236 |   document.querySelectorAll('.topnav-link[data-view-link]').forEach(n => {
237 |     n.classList.toggle('active', n.dataset.viewLink === viewName);
238 |   });
239 | 
240 |   // Show the right view container
241 |   document.querySelectorAll('.main > .view').forEach(v => {
242 |     v.classList.toggle('active', v.id === `view-${viewName}`);
243 |   });
244 | 
245 |   // Render context-appropriate sidebar
246 |   renderSidebar(viewName);
247 | 
248 |   // Render the view if not yet rendered
249 |   const container = document.getElementById(`view-${viewName}`);
250 |   if (!container) return;
251 | 
252 |   if (!rendered.has(viewName)) {
253 |     rendered.add(viewName);
254 |     try {
255 |       await VIEW_RENDERERS[viewName]?.(container);
256 |     } catch (err) {
257 |       container.innerHTML = `
258 |         <div class="page-header">
259 |           <div class="page-title">Error</div>
260 |           <div class="page-sub">${err.message}</div>
261 |         </div>
262 |         <div class="content" style="color:var(--muted);font-size:13px">
263 |           Make sure the server is running (<code>npm start</code>) and seeded (<code>npm run seed</code>).
264 |         </div>
265 |       `;
266 |     }
267 |   }
268 | }
269 | 
270 | // ── Top nav link clicks ──────────────────────────────────────────
271 | document.querySelectorAll('.topnav-link[data-view-link]').forEach(item => {
272 |   item.addEventListener('click', () => activateView(item.dataset.viewLink));
273 | });
274 | 
275 | // ── Init ──────────────────────────────────────────────────────────
276 | boot();
277 | wireProfileDropdown();
278 | activateView('org');
