570 | // ── Zoom + pan ────────────────────────────────────────────────────
571 | function wireZoom() {
572 |   const viewport = document.getElementById('orgViewport');
573 |   const canvas   = document.getElementById('orgCanvas');
574 |   const svg      = document.getElementById('orgSvg');
575 |   if (!viewport || !canvas || !svg) return;
576 | 
577 |   let scale = 1, tx = 0, ty = 0;
578 |   let dragging = false, didDrag = false, sx = 0, sy = 0, stx = 0, sty = 0;
579 | 
580 |   function applyTransform() {
581 |     const t = `translate(${tx}px,${ty}px) scale(${scale})`;
582 |     canvas.style.transform = t;
583 |     svg.style.transform    = t;
584 |     updateVisibility(scale);
585 |   }
586 | 
587 |   function fit() {
588 |     const vw = viewport.clientWidth  || 900;
589 |     const vh = viewport.clientHeight || 700;
590 |     // Fill ~80% of the viewport — hive is large and immediately legible
591 |     scale = Math.min(vw / _canvasW, vh / _canvasH) * 0.80;
592 |     tx = (vw - _canvasW * scale) / 2;
593 |     ty = (vh - _canvasH * scale) / 2;
594 |     applyTransform();
595 |   }
596 | 
597 |   requestAnimationFrame(() => requestAnimationFrame(fit));
598 | 
599 |   const zoom = (factor, cx, cy) => {
600 |     cx = cx ?? viewport.clientWidth  / 2;
601 |     cy = cy ?? viewport.clientHeight / 2;
602 |     const ns = Math.min(Math.max(scale * factor, 0.05), 20);
603 |     tx = cx - (cx - tx) * (ns / scale);
604 |     ty = cy - (cy - ty) * (ns / scale);
605 |     scale = ns;
606 |     applyTransform();
607 |   };
608 | 
609 |   document.getElementById('orgZoomIn')?.addEventListener('click',    () => zoom(1.5));
610 |   document.getElementById('orgZoomOut')?.addEventListener('click',   () => zoom(1 / 1.5));
611 |   document.getElementById('orgZoomReset')?.addEventListener('click', fit);
612 | 
613 |   viewport.addEventListener('wheel', e => {
614 |     e.preventDefault();
615 |     const r = viewport.getBoundingClientRect();
616 |     zoom(e.deltaY < 0 ? 1.12 : 0.89, e.clientX - r.left, e.clientY - r.top);
617 |   }, { passive: false });
618 | 
619 |   viewport.addEventListener('mousedown', e => {
620 |     if (e.button !== 0) return;
621 |     dragging = true; didDrag = false;
622 |     sx = e.clientX; sy = e.clientY; stx = tx; sty = ty;
623 |     viewport.style.cursor = 'grabbing';
624 |   });
625 |   window.addEventListener('mousemove', e => {
626 |     if (!dragging) return;
627 |     const dx = e.clientX - sx, dy = e.clientY - sy;
628 |     if (Math.abs(dx) > 3 || Math.abs(dy) > 3) didDrag = true;
629 |     tx = stx + dx; ty = sty + dy;
630 |     applyTransform();
631 |   });
632 |   window.addEventListener('mouseup', () => {
633 |     dragging = false;
634 |     if (viewport) viewport.style.cursor = 'grab';
635 |   });
636 |   viewport.addEventListener('click', e => {
637 |     if (didDrag) { e.stopImmediatePropagation(); didDrag = false; }
638 |   }, true);
639 | 
640 |   // Pinch-to-zoom
641 |   let lastDist = 0;
642 |   viewport.addEventListener('touchstart', e => {
643 |     if (e.touches.length === 2)
644 |       lastDist = Math.hypot(e.touches[0].clientX - e.touches[1].clientX,
645 |                             e.touches[0].clientY - e.touches[1].clientY);
646 |   }, { passive: true });
647 |   viewport.addEventListener('touchmove', e => {
648 |     if (e.touches.length !== 2) return;
649 |     e.preventDefault();
650 |     const dist = Math.hypot(e.touches[0].clientX - e.touches[1].clientX,
651 |                             e.touches[0].clientY - e.touches[1].clientY);
652 |     const r    = viewport.getBoundingClientRect();
653 |     zoom(dist / lastDist, (e.touches[0].clientX + e.touches[1].clientX) / 2 - r.left,
654 |                           (e.touches[0].clientY + e.touches[1].clientY) / 2 - r.top);
655 |     lastDist = dist;
656 |   }, { passive: false });
657 | }

