9 |   if (!res.ok) throw new Error(`GET ${path} → ${res.status}`);
10 |   return res.json();
11 | }
12 | 
13 | async function post(path, body) {
14 |   const res = await fetch(BASE + path, {
15 |     method: 'POST',
16 |     headers: { 'Content-Type': 'application/json' },
17 |     body: JSON.stringify(body),
18 |   });
19 |   if (!res.ok) throw new Error(`POST ${path} → ${res.status}`);
20 |   return res.json();
21 | }
22 | 
23 | async function patch(path, body) {
24 |   const res = await fetch(BASE + path, {
25 |     method: 'PATCH',
26 |     headers: { 'Content-Type': 'application/json' },
27 |     body: JSON.stringify(body),
28 |   });
29 |   if (!res.ok) throw new Error(`PATCH ${path} → ${res.status}`);
30 |   return res.json();
31 | }
32 | 
33 | async function del(path) {
34 |   const res = await fetch(BASE + path, { method: 'DELETE' });
