// ── Hex geometry — flat-top orientation ──────────────────────────
// Flat-top gives wider rows that mirror the logo's horizontal bars better.
const HEX_R  = 22;   // cell radius (pixels) — large enough to see clearly
const HEX_W  = HEX_R * 2;
const HEX_H  = Math.sqrt(3) * HEX_R;
const COL_W  = HEX_W * 0.75;  // horizontal spacing center-to-center
const ROW_H  = HEX_H;         // vertical spacing center-to-center

// Flat-top hex: axial → pixel
function axialToPixel(q, r) {
  const x = COL_W * q;
  const y = ROW_H * (r + q / 2);
  return { x, y };
}

// Flat-top hex points (6 corners)
function hexPath(ctx, cx, cy, r) {
  for (let i = 0; i < 6; i++) {
    const a = (Math.PI / 3) * i; // 0, 60, 120, 180, 240, 300°
    const x = cx + r * Math.cos(a);
    const y = cy + r * Math.sin(a);
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

function svgHexPoints(cx, cy, r) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = (Math.PI / 3) * i;
    return `${(cx + r * Math.cos(a)).toFixed(1)},${(cy + r * Math.sin(a)).toFixed(1)}`;
  }).join(' ');
}

// ── Logo-shaped hive: define which axial cells are included ───────
//
// The IBM Hive logo is 5 horizontal bars tapering like:
//   row -4:  width 3  (top, narrow)
//   row -2:  width 5
//   row  0:  width 6  (widest)
//   row +2:  width 5
//   row +4:  width 3  (bottom, narrow)
//
// We'll build a flat-top hex grid where the "row" is the r-coordinate
// (adjusted for the flat-top offset) and the width per row follows
// a diamond/beehive profile.
//
// Profile (r = axial row, half-width in hex units):
//   r = -6  → 2  cells
//   r = -5  → 3  cells
//   r = -4  → 4  cells
//   r = -3  → 5  cells
//   r = -2  → 6  cells
//   r = -1  → 6  cells
//   r =  0  → 7  cells  ← widest
//   r =  1  → 6  cells
//   r =  2  → 6  cells
//   r =  3  → 5  cells
//   r =  4  → 4  cells
//   r =  5  → 3  cells
//   r =  6  → 2  cells
//
// For flat-top hex, the axial → pixel mapping already handles the
// half-offset between columns, so rows line up like the logo bars.

const ROW_WIDTHS = [
  [-6, 2], [-5, 3], [-4, 4], [-3, 5], [-2, 6], [-1, 6],
  [ 0, 7],
  [ 1, 6], [ 2, 6], [ 3, 5], [ 4, 4], [ 5, 3], [ 6, 2],
];

// Generate cells for the hive shape — use offset-grid rows
// We'll work in offset-column coordinates then convert to axial.
function buildHiveCells() {
  const cells = []; // { q, r } axial coords

  // Use "offset-row" grid: for each row R, cells span q from -(hw-1) to +(hw-1) in q
  // In flat-top axial: for a given r, q can range freely.
  // We'll set q such that pixel x is centered.
  ROW_WIDTHS.forEach(([rowR, halfW]) => {
    // halfW = number of cells on each side + center
    for (let qi = -(halfW - 1); qi <= (halfW - 1); qi++) {
      // For flat-top hex, to keep rows horizontally centered we need to offset
      // q so the row starts at the right place.
      // In flat-top axial, r controls the row. For a given r, pixel x = COL_W * q
      // with a small y-offset. To center the row of halfW*2-1 cells:
      cells.push({ q: qi, r: rowR });
    }
  });

  return cells;
}

// Assign colony to a cell based on which "sextant" of the hive it's in
// We divide the hive into 6 vertical bands (left→right = 6 portfolios)
function cellColony(q, r, totalCols) {
  // Map q from [-(totalCols-1), +(totalCols-1)] to [0..5]
  const maxQ = 6;
  const normalized = (q + maxQ) / (maxQ * 2);
  const idx = Math.min(5, Math.floor(normalized * 6));
  return COLONY_ORDER[idx];
}

