}
.topnav-search input::placeholder { color: #6f6f6f; }
.topnav-search svg { flex-shrink: 0; }

.topnav-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 20px;
  height: 100%;
  font-size: 13px;
  color: #c6c6c6;
