}
.sb-item:hover { color: #c6c6c6; }
.sb-item.active { color: #fff; border-left-color: var(--ibm-blue-50); }

/* Expandable group */
.sb-group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  font-size: 13px;
  color: #6f6f6f;
