/* ── ORG TREE ────────────────────────────────────────────────── */
.org-tree { display: flex; flex-direction: column; overflow-x: auto; padding-bottom: 16px; }
.org-level { display: flex; justify-content: center; gap: 12px; padding: 10px 0; }
.org-connector { display: flex; justify-content: center; }
.org-connector-line { width: 1px; height: 16px; background: var(--border); }

.org-card {
  background: var(--surface);
  border: 1px solid var(--border-subtle);
  border-left: 3px solid transparent;
  padding: 12px 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 190px;
  max-width: 220px;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
.org-card:hover { background: var(--surface-2); border-left-color: var(--ibm-blue-50); }
.org-card.highlight { border-left-color: var(--ibm-purple-50); background: rgba(138, 63, 252, 0.08); }
.org-card.you       { border-left-color: var(--ibm-blue-50); background: rgba(69, 137, 255, 0.08); }

/* Hex-shaped avatar in org cards */
.org-avatar {
  width: 36px;
  height: 40px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
  flex-shrink: 0;
  color: #fff;
}
.org-info { flex: 1; min-width: 0; }
.org-name  { font-size: 13px; font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.org-role  { font-size: 12px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }
.org-badge {
  font-size: 11px;
  background: transparent;
  border: 1px solid var(--border);
  padding: 1px 6px;
  color: var(--muted);
  white-space: nowrap;
  margin-top: 4px;
  display: inline-block;
  letter-spacing: 0.16px;
}

/* ── NETWORK GRID ────────────────────────────────────────────── */
.network-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 1px; background: var(--border-subtle); }
.network-card {
  background: var(--surface);
  padding: 16px;
  cursor: pointer;
  transition: background 0.1s;
  border-left: 3px solid transparent;
}
.network-card:hover { background: var(--surface-2); border-left-color: var(--ibm-blue-50); }

.nc-top { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }

/* Hex-shaped avatar on network / connection cards */
.nc-avatar {
  width: 44px;
  height: 50px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.nc-name { font-size: 14px; font-weight: 500; letter-spacing: 0.16px; }
.nc-role { font-size: 12px; color: var(--muted); margin-top: 1px; }
.nc-tag  { display: inline-block; font-size: 11px; padding: 2px 8px; font-weight: 500; margin-top: 6px; letter-spacing: 0.32px; text-transform: uppercase; }
.tag-close   { background: rgba(69,137,255,0.16);  color: var(--ibm-blue-40); }
.tag-partner { background: rgba(165,110,255,0.18);  color: var(--ibm-purple-40); }
.tag-cross   { background: rgba(217,70,239,0.16);   color: #f0abfc; }
.tag-client  { background: rgba(108,99,255,0.18);   color: #bcb6ff; }
.tag-peer    { background: rgba(96,165,250,0.16);   color: #bfdbfe; }
.nc-note {
  font-size: 12px;
  color: var(--muted);
  margin-top: 10px;
  border-top: 1px solid var(--border-subtle);
  padding-top: 10px;
  line-height: 1.5;
}
.nc-followup {
  font-size: 11px;
  color: var(--accent-magenta);
  font-weight: 600;
  margin-top: 6px;
  text-transform: uppercase;
  letter-spacing: 0.32px;
}

/* ── ACCOUNT HIVE ────────────────────────────────────────────── */
.accounts-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}
.acct-filter {
  font-size: 12px;
  padding: 5px 12px;
  border: 1px solid var(--border);
  background: var(--surface);
  cursor: pointer;
  color: var(--muted);
  transition: all 0.1s;
  letter-spacing: 0.32px;
  text-transform: uppercase;
  font-weight: 500;
  border-radius: 0;
}
.acct-filter:hover { background: var(--surface-2); color: var(--text); }
.acct-filter.active { background: var(--ibm-blue-60); color: #fff; border-color: var(--ibm-blue-60); }
.acct-legend { display: flex; align-items: center; gap: 16px; margin-left: auto; flex-wrap: wrap; }
.legend-item { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.32px; }
.legend-dot  { width: 10px; height: 10px; flex-shrink: 0; }

.acct-hex {
  width: 90px;
  height: 100px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform 0.15s, filter 0.15s, opacity 0.2s;
  padding: 10px 6px;
  text-align: center;
}
.acct-hex:hover { transform: scale(1.06); filter: brightness(1.2); }
.acct-name  { font-size: 9px; font-weight: 700; color: #fff; text-shadow: 0 1px 3px rgba(0,0,0,0.5); line-height: 1.2; max-width: 78px; overflow: hidden; text-overflow: ellipsis; }
.acct-val   { font-size: 8px; color: rgba(255,255,255,0.9); margin-top: 3px; text-shadow: 0 1px 2px rgba(0,0,0,0.4); font-weight: 600; }
.acct-stage { font-size: 8px; color: rgba(255,255,255,0.7); margin-top: 1px; }

/* Stage colors */
.col-won        { background: var(--stage-won); }
.col-negotiation{ background: var(--stage-negotiation); }
.col-proposal   { background: var(--stage-proposal); }
.col-risk       { background: var(--stage-risk); }
.col-prospect   { background: var(--stage-prospect); }

/* ── EXEC VIEW ───────────────────────────────────────────────── */
.exec-section { margin-bottom: 36px; }
.exec-title {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--muted);
}
.exec-badge {
  font-size: 11px;
  padding: 2px 8px;
  color: #fff;
  font-weight: 600;
  letter-spacing: 0.32px;
}

/* ── DETAIL PANEL (slide-over) ───────────────────────────────── */
.panel-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  z-index: 100;
  display: none;
  align-items: flex-start;
  justify-content: flex-end;
}
.panel-overlay.open { display: flex; }

.detail-panel {
  background: var(--surface);
  width: 352px;
  height: 100%;
  overflow-y: auto;
  box-shadow: -4px 0 32px rgba(0,0,0,0.6);
  display: flex;
  flex-direction: column;
  border-left: 1px solid var(--border-subtle);
}

.dp-header {
  padding: 20px 20px 16px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: flex-start;
  gap: 14px;
  background: var(--sidebar-bg);
}

/* Hex-shaped avatar in detail panel — all profile views are hive-shaped */
.dp-avatar {
  width: 56px;
  height: 63px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}

.dp-name   { font-size: 16px; font-weight: 400; letter-spacing: 0; color: var(--text); }
.dp-role   { font-size: 12px; color: var(--muted); margin-top: 3px; }
.dp-market {
  font-size: 11px;
  padding: 2px 8px;
  background: rgba(69,137,255,0.14);
  color: var(--ibm-blue-40);
  display: inline-block;
  margin-top: 6px;
  font-weight: 500;
  letter-spacing: 0.32px;
  text-transform: uppercase;
}
.dp-close {
  margin-left: auto;
  font-size: 18px;
  cursor: pointer;
  color: var(--muted);
  padding: 2px 6px;
  line-height: 1;
  transition: color 0.1s;
}
.dp-close:hover { color: var(--text); }

.dp-body { padding: 16px 20px; flex: 1; display: flex; flex-direction: column; gap: 20px; }
.dp-section { display: flex; flex-direction: column; gap: 8px; }
.dp-section-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
  font-weight: 600;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-subtle);
}
.dp-row { display: flex; align-items: flex-start; gap: 10px; font-size: 13px; }
.dp-label { color: var(--muted); min-width: 80px; font-size: 12px; flex-shrink: 0; letter-spacing: 0.16px; }
.dp-value { color: var(--text); font-weight: 400; }
.dp-link  { color: var(--ibm-blue-40); text-decoration: none; font-size: 13px; }
.dp-link:hover { text-decoration: underline; }

.dp-note-item {
  font-size: 13px;
  color: var(--text);
  line-height: 1.6;
  background: var(--surface-2);
  padding: 10px 12px;
  border-left: 3px solid var(--ibm-blue-60);
  margin-bottom: 6px;
}
.dp-note-date { font-size: 11px; color: var(--muted); margin-top: 4px; }

.dp-tag-row { display: flex; gap: 6px; flex-wrap: wrap; }
.dp-tag {
  font-size: 11px;
  padding: 3px 10px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--text-secondary);
  letter-spacing: 0.32px;
}

/* ── LOADING STATE ───────────────────────────────────────────── */
.loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px;
  color: var(--muted);
  font-size: 14px;
}


/* ── ROLE-CATEGORY LEGEND ────────────────────────────────────── */
.cat-legend {
  display: flex;
  align-items: center;
  gap: 24px;
  flex-wrap: wrap;
  margin-top: 20px;
  padding: 12px 16px;
  border-top: 1px solid var(--border-subtle);
  background: var(--surface);
}
.cat-legend-item { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 500; color: var(--muted); letter-spacing: 0.32px; text-transform: uppercase; }
.cat-legend-marker { width: 9px; height: 9px; background: rgba(255,255,255,0.85); flex-shrink: 0; }
.cat-legend-marker.cat-sales   { border-radius: 50%; }
.cat-legend-marker.cat-tech    { transform: rotate(45deg); }
.cat-legend-marker.cat-support { clip-path: polygon(0 0, 100% 0, 100% 100%); }

/* ── BUTTONS ─────────────────────────────────────────────────── */
.btn-primary {
  padding: 8px 16px;
  border: none;
  background: var(--ibm-blue-60);
  color: #fff;
  font-size: 14px;
  font-weight: 400;
  cursor: pointer;
  letter-spacing: 0.16px;
  font-family: inherit;
  transition: background 0.1s;
  border-radius: 0;
}
.btn-primary:hover { background: var(--ibm-blue-70); }

.btn-secondary {
  padding: 8px 16px;
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text);
  font-size: 14px;
  cursor: pointer;
  letter-spacing: 0.16px;
  font-family: inherit;
  transition: background 0.1s;
  border-radius: 0;
}
.btn-secondary:hover { background: var(--surface-2); }

.btn-danger {
  padding: 8px 16px;
  border: 1px solid rgba(217,70,239,0.4);
  background: transparent;
  color: var(--accent-magenta);
  font-size: 14px;
  cursor: pointer;
  letter-spacing: 0.16px;
  font-family: inherit;
  border-radius: 0;
}
.btn-danger:hover { background: rgba(217,70,239,0.1); }

/* ── CONNECTIONS TOOLBAR / CRUD ─────────────────────────────── */
.nc-actions {
  display: flex;
  gap: 4px;
  margin-left: auto;
}
.nc-icon-btn {
  width: 26px; height: 26px;
  border: 1px solid var(--border-subtle);
  background: var(--surface);
  color: var(--muted);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  font-size: 12px;
  flex-shrink: 0;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
}
.nc-icon-btn:hover { background: var(--surface-2); color: var(--text); border-color: var(--ibm-blue-50); }
.nc-icon-btn.danger:hover { border-color: var(--accent-magenta); color: var(--accent-magenta); background: rgba(217,70,239,0.08); }

/* ── MODAL ───────────────────────────────────────────────────── */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.65);
  z-index: 200;
  display: none;
  align-items: center;
  justify-content: center;
}
.modal-overlay.open { display: flex; }
.modal {
  background: var(--surface);
  border: 1px solid var(--border);
  width: 400px;
  max-width: calc(100vw - 32px);
  max-height: calc(100vh - 64px);
  overflow-y: auto;
  box-shadow: 0 16px 48px rgba(0,0,0,0.6);
  border-radius: 0;
}
.modal-header {
  padding: 16px 20px;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--sidebar-bg);
}
.modal-title { font-size: 16px; font-weight: 400; letter-spacing: 0; }
.modal-close { cursor: pointer; color: var(--muted); font-size: 16px; padding: 2px 6px; transition: color 0.1s; }
.modal-close:hover { color: var(--text); }
.modal-body { padding: 20px; display: flex; flex-direction: column; gap: 16px; }
.modal-body label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 12px;
  color: var(--muted);
  font-weight: 600;
  letter-spacing: 0.32px;
  text-transform: uppercase;
}
.modal-body input[type="text"],
.modal-body select,
.modal-body textarea {
  padding: 8px 10px;
  border: none;
  border-bottom: 2px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  resize: vertical;
  border-radius: 0;
  transition: border-color 0.1s;
}
.modal-body input[type="text"]:focus,
.modal-body select:focus,
.modal-body textarea:focus { outline: none; border-bottom-color: var(--ibm-blue-50); }
.modal-checkbox { flex-direction: row !important; align-items: center; gap: 8px !important; text-transform: none !important; letter-spacing: 0 !important; font-size: 13px !important; }
.modal-checkbox input { width: auto; accent-color: var(--ibm-blue-50); }
.modal-actions { display: flex; align-items: center; gap: 8px; margin-top: 4px; }

/* ── RESPONSIVE ──────────────────────────────────────────────── */
@media (max-width: 640px) {
  .sidebar { display: none; }
  .content { padding: 16px; }
  .detail-panel { width: 100vw; }
  .topnav-search { display: none; }
  .topnav-links { display: none; }
}

/* ─────────────────────────────────────────────────────────────
   COLONY HIVE VIEW — full-screen zoomable hexagon grid
   ───────────────────────────────────────────────────────────── */

/* Colony view fills the full flex area with its own layout */
.colony-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

/* Sticky toolbar at top of colony view */
.colony-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  height: 48px;
  flex-shrink: 0;
  background: var(--sidebar-bg);
  border-bottom: 1px solid var(--border-subtle);
  gap: 16px;
}
.colony-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.colony-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.16px;
}
.colony-subtitle {
  font-size: 12px;
  color: var(--muted);
}
.colony-toolbar-controls {
  display: flex;
  align-items: center;
  gap: 6px;
}
.colony-zoom-btn {
  width: 32px;
  height: 32px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text-secondary);
  font-size: 18px;
  font-family: inherit;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
  flex-shrink: 0;
}
.colony-zoom-btn:hover { background: var(--surface-2); color: #fff; }

/* The scrollable viewport — cursor:grab, overflow:hidden */
.colony-viewport {
  flex: 1;
  overflow: hidden;
  position: relative;
  cursor: grab;
  background: var(--bg);
}
.colony-viewport:active { cursor: grabbing; }

/* SVG colony hive — transforms applied by JS */
.colony-svg {
  position: absolute;
  top: 0;
  left: 0;
  transform-origin: 0 0;
  will-change: transform;
  overflow: visible;
  display: block;
}

/* SVG text labels — initially hidden, JS toggles opacity based on scale */
.colony-svg .hex-label-name,
.colony-svg .hex-label-role,
.colony-svg .colony-section-label {
  transition: opacity 0.2s;
  user-select: none;
}

/* Hover brightening on hex polygons — done via JS filter on parent SVG element */

/* ─────────────────────────────────────────────────────────────
   PROFILE / ACCOUNT SWITCHER DROPDOWN (name click)
   ───────────────────────────────────────────────────────────── */
.topnav-user {
  position: relative;
}
.user-dropdown {
  position: absolute;
  top: 100%;
  right: 0;
  background: #111111;
  border: 1px solid rgba(255,255,255,0.12);
  min-width: 220px;
  z-index: 500;
  display: none;
  flex-direction: column;
  box-shadow: 0 8px 32px rgba(0,0,0,0.7);
}
.user-dropdown.open { display: flex; }
.user-dropdown-header {
  padding: 10px 16px 8px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #525252;
  font-weight: 600;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.user-dropdown-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 16px;
  cursor: pointer;
  font-size: 13px;
  color: #8d8d8d;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  border-left: 2px solid transparent;
  transition: color 0.1s;
}
.user-dropdown-item:last-child { border-bottom: none; }
.user-dropdown-item:hover { color: #fff; }
.user-dropdown-item.active {
  color: #fff;
  border-left-color: rgba(255,255,255,0.5);
}
.user-dropdown-avatar {
  width: 22px;
  height: 25px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  background: #333333;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  font-weight: 700;
  color: #8d8d8d;
  flex-shrink: 0;
}
.user-dropdown-info { display: flex; flex-direction: column; gap: 2px; }
.user-dropdown-name { font-size: 13px; font-weight: 400; color: inherit; }
.user-dropdown-role { font-size: 11px; color: #525252; }

/* ── HIVE VIEW (The Hive tab) ─────────────────────────────────── */
.hive-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}
.hive-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px;
  height: 44px;
  flex-shrink: 0;
  background: #000;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  gap: 16px;
}
.hive-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.hive-title {
  font-size: 13px;
  font-weight: 500;
  color: #c6c6c6;
}
.hive-subtitle {
  font-size: 11px;
  color: #3a3a3a;
}
.hive-toolbar-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ── RESOURCES EMPTY STATE ───────────────────────────────────── */
.resources-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 24px;
  text-align: center;
  color: var(--muted);
}
.resources-empty-icon {
  font-size: 40px;
  margin-bottom: 20px;
  color: #2a2a2a;
}
.resources-empty-title {
  font-size: 16px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: 8px;
}
.resources-empty-sub {
  font-size: 13px;
  color: var(--muted);
  max-width: 360px;
  line-height: 1.6;
}

/* ── ORG HIVE PAGE ───────────────────────────────────────────── */
.org-hive-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: #000;
}
.org-hive-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 40px;
  padding: 0 20px;
  background: #000;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  flex-shrink: 0;
  gap: 16px;
}
.org-hive-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.org-hive-title {
  font-size: 13px;
  font-weight: 500;
  color: #c6c6c6;
}
.org-hive-subtitle {
  font-size: 11px;
  color: #3a3a3a;
}
.org-hive-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ── ORG COLONY / PERSON MODAL ──────────────────────────────── */
