/* ── PEOPLE DIRECTORY ────────────────────────────────────────── */
.people-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  flex-shrink: 0;
  flex-wrap: wrap;
  background: var(--sidebar-bg);
}

.people-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1px;
  background: rgba(255,255,255,0.05);
  flex: 1;
  overflow-y: auto;
  align-content: start;
}

.people-card {
  background: var(--surface);
  padding: 14px 16px;
  cursor: pointer;
  transition: background 0.1s;
  border-left: 2px solid transparent;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.people-card:hover { background: var(--surface-2); border-left-color: var(--ibm-blue-50); }
.people-card.people-card-me { border-left-color: rgba(77,123,255,0.6); background: rgba(15,33,77,0.3); }
.people-card.people-card-me:hover { background: rgba(15,33,77,0.5); }

.pc-top {
  display: flex;
  align-items: center;
  gap: 12px;
}
.pc-avatar-hex {
  flex-shrink: 0;
  display: block;
}
.pc-info { flex: 1; min-width: 0; }
.pc-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: 0.16px;
}
.pc-you {
  font-size: 10px;
  padding: 1px 6px;
  background: rgba(77,123,255,0.15);
  color: #4d7bff;
  font-weight: 600;
  letter-spacing: 0.32px;
  margin-left: 4px;
  vertical-align: middle;
}
.pc-role {
  font-size: 11px;
  color: var(--muted);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pc-colony {
  font-size: 10px;
  font-weight: 500;
  margin-top: 3px;
  letter-spacing: 0.16px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pc-meta {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.pc-badge {
  font-size: 10px;
  padding: 2px 7px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  color: #6f6f6f;
  letter-spacing: 0.16px;
  white-space: nowrap;
}
.pc-badge-market {
  background: rgba(69,137,255,0.08);
  border-color: rgba(69,137,255,0.2);
  color: #4d7bff;
}

