}
.hive-toolbar-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ── RESOURCES EMPTY STATE ───────────────────────────────────── */
.resources-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 24px;
  text-align: center;
