}
.resources-empty-icon {
  font-size: 40px;
  margin-bottom: 20px;
  color: #2a2a2a;
}
.resources-empty-title {
  font-size: 16px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: 8px;
}
.resources-empty-sub {
  font-size: 13px;
  color: var(--muted);
  max-width: 360px;
  line-height: 1.6;
}

/* ── ORG HIVE PAGE ───────────────────────────────────────────── */
.org-hive-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: #000;
}
.org-hive-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 44px;
  padding: 0 20px;
  background: #000;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  flex-shrink: 0;
  gap: 16px;
}
.org-hive-toolbar-left {
  display: flex;
  align-items: baseline;
  gap: 12px;
}
.org-hive-title {
  font-size: 13px;
  font-weight: 500;
  color: #c6c6c6;
}
.org-hive-subtitle {
  font-size: 11px;
  color: #3a3a3a;
}
.org-hive-controls {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Sort buttons in org toolbar */
.org-sort-btn {
