}
.org-modal-section-title {
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.64px;
  color: #525252;
  margin-bottom: -4px;
}
.org-modal-tags {
  display: flex;
  flex-wrap: wrap;
