  gap: 3px;
  font-size: 13px;
  color: #f4f4f4;
}
.org-modal-field-label {
  font-size: 11px;
  color: #525252;
  text-transform: uppercase;
  letter-spacing: 0.32px;
}

/* ── CELL / STRUCTURE HEX GRID ───────────────────────────────── */
.cell-page {
