  flex: 1;
  min-height: 0;
}
.cell-hex-grid {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  padding: 32px 24px;
}
.cell-hex-row {
  display: flex;
  gap: 3px;
  margin-bottom: -14px;
}
.cell-hex-row:nth-child(even) { margin-left: 57px; }
.cell-hex-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
}
.cell-hex-svg {
  display: block;
