/* ── CONNECTIONS NETWORK ─────────────────────────────────────── */
.connections-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  padding: 24px;
  gap: 20px;
}

/* ── RESOURCES ───────────────────────────────────────────────── */
.res-page {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow-y: auto;
}
.res-header {
  padding: 24px 28px 16px;
