  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pc-colony {
  font-size: 10px;
  font-weight: 500;
  margin-top: 3px;
  letter-spacing: 0.16px;
  white-space: nowrap;
