/**
 * org.js — Organization: a massive hexagon grid of all people.
 *
 * Every person is a hexagon. People cluster by colony (portfolio).
 * Colonies are laid out as contiguous hex-grid regions.
 * Zoom in/out to see names; click any hex to open person detail.
 * Sort by Colony, Market, or Role.
 */
import { getPeople } from '../api.js';

// ── Colony data ───────────────────────────────────────────────────
const COLONY_ORDER = [
  'Data & AI Colony',
  'Automation Colony',
  'Sustainability Colony',
  'Security Colony',
  'Infrastructure Colony',
  'Hybrid Cloud Colony',
];

const COLONY_INFO = {
  'Data & AI Colony':      { label: 'Data & AI',      color: '#0f62fe', short: 'D&AI' },
  'Automation Colony':     { label: 'Automation',      color: '#6c63ff', short: 'AUTO' },
  'Sustainability Colony': { label: 'Sustainability',  color: '#24a148', short: 'SUST' },
  'Security Colony':       { label: 'Security',        color: '#da1e28', short: 'SEC'  },
  'Infrastructure Colony': { label: 'Infrastructure',  color: '#a855f7', short: 'INFRA' },
  'Hybrid Cloud Colony':   { label: 'Hybrid Cloud',    color: '#ee5396', short: 'HYBR' },
};

const COLONY_MAP = {
  'data-ai':        'Data & AI Colony',
  'automation':     'Automation Colony',
  'sustainability': 'Sustainability Colony',
  'security':       'Security Colony',
  'infrastructure': 'Infrastructure Colony',
  'hybrid-cloud':   'Hybrid Cloud Colony',
};

const MARKET_MAP = {
  enterprise: 'Enterprise',
  strategic:  'Strategic',
  horizon:    'Horizon',
  territory:  'Territory',
};

const ROLE_ORDER = {
  exec:0, director:1, manager:2, bss:3, bts:4, csm:5, sdr:6, partner:7, intern:8, other:9,
};

const ROLE_COLOR = {
  exec:     '#7c3aed',
  director: '#9333ea',
  manager:  '#6c63ff',
  bss:      '#2563eb',
  bts:      '#0e7490',
  intern:   '#4d7bff',
  csm:      '#0f766e',
  sdr:      '#1d4ed8',
  partner:  '#7e22ce',
  other:    '#2a2a2a',
};

// ── Hex geometry — pointy-top orientation ─────────────────────────
// Pointy-top: easier to pack lots of people with natural row flow.
const HEX_R = 32;   // radius of each person hex (pixels)
const HEX_W = Math.sqrt(3) * HEX_R;   // width of pointy-top hex
const HEX_H = HEX_R * 2;              // height of pointy-top hex
const COL_STEP = HEX_W;               // center-to-center horizontal
const ROW_STEP = HEX_R * 1.5;         // center-to-center vertical

// Pointy-top hex: axial → pixel (offset for even/odd rows)
function hexCenterOffset(col, row) {
  const x = col * COL_STEP + (row % 2 === 1 ? COL_STEP / 2 : 0);
  const y = row * ROW_STEP;
  return { x, y };
}

// SVG polygon points for a pointy-top hexagon
function svgHexPoints(cx, cy, r) {
  return Array.from({ length: 6 }, (_, i) => {
    const a = Math.PI / 3 * i - Math.PI / 6; // pointy-top: start at 30°
    return `${(cx + r * Math.cos(a)).toFixed(2)},${(cy + r * Math.sin(a)).toFixed(2)}`;
  }).join(' ');
}

// ── Layout: place all people into a grid per colony ───────────────
// Each colony occupies a rectangular "block" of rows.
// Colonies are arranged in a 2-column layout:
//   Col A (left):  Data & AI, Sustainability, Infrastructure
//   Col B (right): Automation, Security, Hybrid Cloud
// Each block is a tight hex grid, sized to fit the colony headcount.

const COLS_PER_BLOCK = 7; // hex columns per colony block

function buildLayout(people, sortMode) {
  // Group people
  let groups;

  if (sortMode === 'market') {
    const marketOrder = ['Enterprise', 'Strategic', 'Horizon', 'Territory'];
    const byMarket = {};
    marketOrder.forEach(m => { byMarket[m] = []; });
    people.forEach(p => {
      const mkt = p.market || 'Other';
      if (!byMarket[mkt]) byMarket[mkt] = [];
      byMarket[mkt].push(p);
    });
    groups = marketOrder
      .filter(m => byMarket[m].length > 0)
      .map(m => ({ label: m, color: marketColor(m), people: byMarket[m] }));
  } else if (sortMode === 'role') {
    const roleOrder = ['exec','director','manager','bss','bts','csm','sdr','partner','intern','other'];
    const roleLabel = {
      exec:'VP / Executive', director:'Director', manager:'Manager',
      bss:'Brand Sales Spec.', bts:'Brand Tech. Sales', csm:'Customer Success',
      sdr:'SDR', partner:'Partner', intern:'Intern', other:'Other',
    };
    const byRole = {};
    roleOrder.forEach(r => { byRole[r] = []; });
    people.forEach(p => {
      const rt = p.role_type || 'other';
      if (!byRole[rt]) byRole[rt] = [];
      byRole[rt].push(p);
    });
    groups = roleOrder
      .filter(r => byRole[r].length > 0)
      .map(r => ({ label: roleLabel[r] || r, color: ROLE_COLOR[r] || '#2a2a2a', people: byRole[r] }));
  } else {
    // Default: by colony
    const byColony = {};
    COLONY_ORDER.forEach(c => { byColony[c] = []; });
    people.forEach(p => {
      const c = p.comb || COLONY_ORDER[0];
      if (!byColony[c]) byColony[c] = [];
      byColony[c].push(p);
    });
    COLONY_ORDER.forEach(c => {
      byColony[c].sort((a, b) => (ROLE_ORDER[a.role_type] ?? 9) - (ROLE_ORDER[b.role_type] ?? 9));
    });
    groups = COLONY_ORDER
      .filter(c => byColony[c].length > 0)
      .map(c => ({
        label: COLONY_INFO[c]?.label || c,
        color: COLONY_INFO[c]?.color || '#333',
        people: byColony[c],
        colony: c,
      }));
  }

  // Lay out each group as a hex-grid block, arranged in 2 columns
  const PAD = HEX_W * 0.8; // padding between blocks
  const LABEL_H = HEX_R * 1.2; // vertical space for the group label
  const cells = []; // { person, cx, cy, color, group }
  const labels = []; // { text, color, cx, cy }
  const outlines = []; // { points[], color } — convex hull of each group

  // Two-column layout
  const colAGroups = groups.filter((_, i) => i % 2 === 0);
  const colBGroups = groups.filter((_, i) => i % 2 === 1);

  // Process each column
  let globalMinX = Infinity, globalMinY = Infinity;
  let globalMaxX = -Infinity, globalMaxY = -Infinity;

  const colOffsets = [0, 0];
  const cols = [colAGroups, colBGroups];

  // First pass: calculate block widths to determine column X offset
  const colBlockW = COLS_PER_BLOCK * COL_STEP + COL_STEP / 2;
  const colAx = 0;
  const colBx = colBlockW + PAD * 2;

  cols.forEach((colGroups, ci) => {
    const baseX = ci === 0 ? colAx : colBx;
    let currentY = 0;

    colGroups.forEach(group => {
      const n = group.people.length;
      const rows = Math.ceil(n / COLS_PER_BLOCK);

      // Place cells
      group.people.forEach((person, idx) => {
        const col = idx % COLS_PER_BLOCK;
        const row = Math.floor(idx / COLS_PER_BLOCK);
        const { x, y } = hexCenterOffset(col, row);
        const cx = baseX + x + COL_STEP / 2;
        const cy = currentY + LABEL_H + y + HEX_R;

        const isMe = person.is_current_user;
        const color = isMe
          ? '#1a2e5e'
          : (group.colony ? (colonyPersonColor(person, group.colony)) : group.color);

        cells.push({ person, cx, cy, color, isMe, groupColor: group.color, group: group.label });

        if (cx - HEX_R < globalMinX) globalMinX = cx - HEX_R;
        if (cx + HEX_R > globalMaxX) globalMaxX = cx + HEX_R;
        if (cy - HEX_R < globalMinY) globalMinY = cy - HEX_R;
        if (cy + HEX_R > globalMaxY) globalMaxY = cy + HEX_R;
      });

      // Group label — centered above block
      const blockCenterX = baseX + (COLS_PER_BLOCK * COL_STEP) / 2;
      labels.push({
        text: group.label,
        color: group.color,
        cx: blockCenterX,
        cy: currentY + LABEL_H * 0.55,
        count: n,
      });

      // Bounding outline rectangle for the group (slightly inset)
      const bx0 = baseX;
      const bx1 = baseX + COLS_PER_BLOCK * COL_STEP + COL_STEP * 0.5;
      const by0 = currentY + LABEL_H * 0.1;
      const rowH = rows * ROW_STEP + HEX_R * 0.5;
      const by1 = currentY + LABEL_H + rowH + HEX_R * 0.5;
      outlines.push({ x0: bx0, y0: by0, x1: bx1, y1: by1, color: group.color });

      const blockH = LABEL_H + rows * ROW_STEP + HEX_R * 1.5;
      currentY += blockH + PAD;
    });
  });

  const canvasW = colBx + colBlockW + PAD;
  const canvasH = Math.max(...cols.map((colGroups, ci) => {
    return colGroups.reduce((acc, g) => {
      const rows = Math.ceil(g.people.length / COLS_PER_BLOCK);
      return acc + LABEL_H + rows * ROW_STEP + HEX_R * 1.5 + PAD;
    }, 0);
  }));

  return { cells, labels, outlines, canvasW, canvasH: canvasH + PAD };
}

function colonyPersonColor(person, colony) {
  // Within a colony, shade by role
  const base = COLONY_INFO[colony]?.color || '#333';
  // Slightly brighten for managers, dim for interns
  if (person.role_type === 'manager' || person.role_type === 'director') return lighten(base, 0.15);
  if (person.role_type === 'exec') return lighten(base, 0.3);
  if (person.role_type === 'intern') return darken(base, 0.2);
  return base;
}

function marketColor(mkt) {
  const m = { Enterprise: '#0f62fe', Strategic: '#a855f7', Horizon: '#6c63ff', Territory: '#d946ef' };
  return m[mkt] || '#525252';
}

function lighten(hex, amt) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  const l = (v) => Math.min(255, Math.round(v + (255 - v) * amt));
  return `rgb(${l(r)},${l(g)},${l(b)})`;
}
function darken(hex, amt) {
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  const d = (v) => Math.round(v * (1 - amt));
  return `rgb(${d(r)},${d(g)},${d(b)})`;
}

// ── Module state ─────────────────────────────────────────────────
let _people       = [];
let _activeFilter = null;
let _sortMode     = 'colony';
let _layout       = null;

export async function renderOrg(container) {
  container.innerHTML = `
