110 | // ── Sidebar rendering ────────────────────────────────────────────
111 | function renderSidebar(viewName) {
112 |   const sidebar = document.getElementById('appSidebar');
113 |   if (!sidebar) return;
114 | 
115 |   const def = SIDEBAR_DEFS[viewName];
116 |   if (!def) { sidebar.innerHTML = ''; return; }
117 | 
118 |   let html = '';
119 |   def.sections.forEach(section => {
120 |     if (section.label) {
121 |       html += `<div class="sb-section-label">${section.label}</div>`;
122 |     }
123 |     section.items.forEach(item => {
124 |       if (item.expandable && item.children) {
125 |         html += `
126 |           <div class="sb-group" data-group="${item.id}">
127 |             <div class="sb-group-header" data-toggle="${item.id}">
128 |               <span>${item.label}</span>
129 |               <span class="sb-caret">›</span>
130 |             </div>
131 |             <div class="sb-group-body" id="sbg-${item.id}">
132 |               <input class="sb-search" type="text" placeholder="Search…" data-group="${item.id}"/>
133 |               ${item.children.map(c => `
134 |                 <div class="sb-child" data-filter="${item.id}" data-value="${c.id}">${c.label}</div>
135 |               `).join('')}
136 |             </div>
137 |           </div>
138 |         `;
139 |       } else {
140 |         html += `
141 |           <div class="sb-item${item.active ? ' active' : ''}" data-sb-item="${item.id}">${item.label}</div>
142 |         `;
143 |       }
144 |     });
145 |   });
146 | 
147 |   sidebar.innerHTML = html;
148 | 
149 |   // Wire expandable group toggles
150 |   sidebar.querySelectorAll('.sb-group-header').forEach(header => {
151 |     const id   = header.dataset.toggle;
152 |     const body = document.getElementById(`sbg-${id}`);
153 |     header.addEventListener('click', () => {
154 |       const open = body.classList.toggle('open');
155 |       header.querySelector('.sb-caret').textContent = open ? '⌄' : '›';
156 |     });
157 |   });
158 | 
159 |   // Wire search within groups
160 |   sidebar.querySelectorAll('.sb-search').forEach(input => {
161 |     input.addEventListener('input', e => {
162 |       const q = e.target.value.toLowerCase();
163 |       const group = e.target.dataset.group;
164 |       sidebar.querySelectorAll(`.sb-child[data-filter="${group}"]`).forEach(child => {
165 |         child.style.display = child.textContent.toLowerCase().includes(q) ? '' : 'none';
166 |       });
167 |     });
168 |   });
169 | 
170 |   // Wire filter items — broadcast to active view
171 |   sidebar.querySelectorAll('.sb-child, .sb-item').forEach(el => {
172 |     el.addEventListener('click', () => {
173 |       sidebar.querySelectorAll('.sb-child.active, .sb-item.active').forEach(a => a.classList.remove('active'));
174 |       el.classList.add('active');
175 |       document.dispatchEvent(new CustomEvent('sidebar:filter', {
176 |         detail: { group: el.dataset.filter || el.dataset.sbItem, value: el.dataset.value || el.dataset.sbItem }
177 |       }));
178 |     });
179 |   });
180 | }
181 | 
182 | // ── Boot: populate current user in nav ───────────────────────────
183 | async function boot() {
184 |   try {
185 |     const people = await getPeople();
186 |     const me = people.find(p => p.is_current_user);
187 |     if (me) {
188 |       document.getElementById('currentUserName').textContent = me.first_name + ' ' + me.last_name;
189 |     }
190 |   } catch (e) {
191 |     console.warn('Could not load user:', e.message);
192 |   }
193 | }
194 | 
195 | // ── Profile / account switcher dropdown ─────────────────────────
196 | function wireProfileDropdown() {
197 |   const userSection = document.getElementById('topnavUser');
198 |   const dropdown    = document.getElementById('userDropdown');
199 |   if (!userSection || !dropdown) return;
200 | 
201 |   userSection.addEventListener('click', e => {
202 |     e.stopPropagation();
203 |     dropdown.classList.toggle('open');
204 |   });
205 |   document.addEventListener('click', e => {
206 |     if (!userSection.contains(e.target)) dropdown.classList.remove('open');
207 |   });
208 | 
209 |   dropdown.querySelectorAll('.user-dropdown-item').forEach(item => {
210 |     item.addEventListener('click', e => {
211 |       e.stopPropagation();
212 |       dropdown.querySelectorAll('.user-dropdown-item').forEach(i => i.classList.remove('active'));
213 |       item.classList.add('active');
214 |       const nameEl = document.getElementById('currentUserName');
215 |       if (item.dataset.profile === 'sydney')       nameEl.textContent = 'Sydney Chin';
216 |       else if (item.dataset.profile === 'manager') nameEl.textContent = 'Chris Kennedy';
217 |       else if (item.dataset.profile === 'admin')   nameEl.textContent = 'Admin';
218 |       dropdown.classList.remove('open');
219 |     });
220 |   });
221 | }
222 | 
223 | // ── View registry ────────────────────────────────────────────────
224 | const VIEW_RENDERERS = {
225 |   org:       renderOrg,
226 |   cell:      renderSeller,
227 |   people:    renderPeople,
228 |   accounts:  renderAccounts,
229 |   resources: renderResources,
230 | };
231 | 
232 | const rendered = new Set();
233 | 
234 | async function activateView(viewName) {
235 |   // Update top nav
236 |   document.querySelectorAll('.topnav-link[data-view-link]').forEach(n => {
237 |     n.classList.toggle('active', n.dataset.viewLink === viewName);
238 |   });
239 | 
240 |   // Show the right view container
241 |   document.querySelectorAll('.main > .view').forEach(v => {
242 |     v.classList.toggle('active', v.id === `view-${viewName}`);
243 |   });
244 | 
245 |   // Render context-appropriate sidebar
246 |   renderSidebar(viewName);
247 | 
248 |   // Render the view if not yet rendered
249 |   const container = document.getElementById(`view-${viewName}`);
250 |   if (!container) return;
251 | 
252 |   if (!rendered.has(viewName)) {
253 |     rendered.add(viewName);
254 |     try {
255 |       await VIEW_RENDERERS[viewName]?.(container);
256 |     } catch (err) {
257 |       container.innerHTML = `
258 |         <div class="page-header">
259 |           <div class="page-title">Error</div>
260 |           <div class="page-sub">${err.message}</div>
261 |         </div>
262 |         <div class="content" style="color:var(--muted);font-size:13px">
263 |           Make sure the server is running (<code>npm start</code>) and seeded (<code>npm run seed</code>).
264 |         </div>
265 |       `;
266 |     }
267 |   }
268 | }
269 | 
270 | // ── Top nav link clicks ──────────────────────────────────────────
271 | document.querySelectorAll('.topnav-link[data-view-link]').forEach(item => {
272 |   item.addEventListener('click', () => activateView(item.dataset.viewLink));
273 | });
274 | 
275 | // ── Init ──────────────────────────────────────────────────────────
276 | boot();
277 | wireProfileDropdown();
278 | activateView('org');
279 |

