3 | const { Router } = require('express');
4 | const { getDb } = require('../db');
5 | 
6 | const router = Router();
7 | 
8 | // GET /api/people
9 | // Query params: ?market=Enterprise  ?role_type=ae  ?search=jordan
10 | router.get('/', (req, res) => {
11 |   const db = getDb();
12 |   let sql = `
13 |     SELECT
14 |       p.id, p.first_name, p.last_name, p.initials, p.role, p.role_type,
15 |       p.email, p.slack, p.location, p.color, p.is_current_user, p.joined_date,
16 |       m.name  AS market,
17 |       m.color AS market_color,
18 |       c.name  AS comb,
19 |       mgr.first_name || ' ' || mgr.last_name AS manager_name,
20 |       p.manager_id
21 |     FROM people p
22 |     LEFT JOIN markets m ON m.id = p.market_id
23 |     LEFT JOIN combs   c ON c.id = p.comb_id
24 |     LEFT JOIN people mgr ON mgr.id = p.manager_id
25 |     WHERE 1=1
26 |   `;
27 |   const params = [];
28 | 
29 |   if (req.query.market) {
30 |     sql += ' AND m.name = ?';
31 |     params.push(req.query.market);
32 |   }
33 |   if (req.query.role_type) {
34 |     sql += ' AND p.role_type = ?';
35 |     params.push(req.query.role_type);
36 |   }
37 |   if (req.query.search) {
38 |     sql += ' AND (p.first_name || " " || p.last_name LIKE ? OR p.role LIKE ?)';
39 |     const term = `%${req.query.search}%`;
40 |     params.push(term, term);
41 |   }
42 |   sql += ' ORDER BY p.role_type, p.last_name';
43 | 
44 |   res.json(db.prepare(sql).all(...params));
45 | });
46 | 
47 | // GET /api/people/:id — full detail + chain
48 | router.get('/:id', (req, res) => {
49 |   const db = getDb();
50 |   const person = db.prepare(`
51 |     SELECT
52 |       p.*,
53 |       m.name  AS market,
54 |       m.color AS market_color,
55 |       c.name  AS comb,
56 |       mgr.first_name || ' ' || mgr.last_name AS manager_name,
57 |       mgr.role AS manager_role,
58 |       mgr.email AS manager_email
59 |     FROM people p
60 |     LEFT JOIN markets m  ON m.id  = p.market_id
61 |     LEFT JOIN combs   c  ON c.id  = p.comb_id
62 |     LEFT JOIN people mgr ON mgr.id = p.manager_id
63 |     WHERE p.id = ?
64 |   `).get(req.params.id);
65 | 
66 |   if (!person) return res.status(404).json({ error: 'Not found' });
67 | 
68 |   // network connection (if any, from current user's perspective)
69 |   person.connection = db.prepare(`
70 |     SELECT nc.relationship, nc.how_we_met, nc.notes, nc.needs_followup
71 |     FROM network_connections nc WHERE nc.person_id = ?
72 |   `).get(person.id) || null;
73 | 
74 |   res.json(person);
75 | });
