  'Automation Colony':     { label: 'Automation',      color: '#6c63ff', short: 'AUTO' },
  'Sustainability Colony': { label: 'Sustainability',  color: '#24a148', short: 'SUST' },
  'Security Colony':       { label: 'Security',        color: '#da1e28', short: 'SEC'  },
  'Infrastructure Colony': { label: 'Infrastructure',  color: '#a855f7', short: 'INFRA' },
