        ],
      },
    ],
  },

  accounts: {
    sections: [
      {
        label: 'Pipeline',
        items: [
          { id: 'acct-all',         label: 'All accounts', active: true },
          { id: 'acct-won',         label: 'Closed won' },
          { id: 'acct-negotiation', label: 'Negotiation' },
