/**
 * org.js — Organization context view
 *
 * Purpose: help every employee understand WHERE they fit in IBM,
 * WHO they work with, and WHO their manager is — at a glance.
 *
 * Structure:
 *  - Breadcrumb:   IBM › Infrastructure Colony › Horizon Market › Sydney Chin
 *  - "You Are Here" persistent banner
 *  - Level navigator: IBM · Colony · Cell · Bee (drillable)
 *  - Node grid with name + role on every card
 *  - Right-side details panel for selected person
 *  - Relationship highlights: reporting chain, direct team, peers
 *  - Sidebar: multi-select filters (colony, market, role) with deselect
 */
import { getPeople } from '../api.js';

// ── Static data ───────────────────────────────────────────────────
const COLONY_INFO = {
  'Data & AI Colony':      { color: '#0f62fe', products: ['watsonx.ai', 'watsonx.data', 'IBM Db2', 'IBM Cognos'] },
  'Automation Colony':     { color: '#6c63ff', products: ['IBM BAW', 'IBM RPA', 'IBM FileNet'] },
  'Sustainability Colony': { color: '#24a148', products: ['IBM Envizi', 'IBM TRIRIGA', 'IBM Maximo'] },
  'Security Colony':       { color: '#da1e28', products: ['IBM QRadar', 'IBM Guardium', 'IBM Verify'] },
  'Infrastructure Colony': { color: '#a855f7', products: ['IBM PowerVS', 'IBM FlashSystem', 'IBM Fusion', 'IBM z16'] },
  'Hybrid Cloud Colony':   { color: '#ee5396', products: ['Red Hat OpenShift', 'IBM Cloud', 'IBM Cloud Paks'] },
};

const ROLE_LABEL = {
  exec:'VP / Executive', director:'Director', manager:'Manager',
  bss:'Brand Sales Spec.', bts:'Brand Tech. Sales',
  csm:'Customer Success', sdr:'SDR', partner:'Partner',
  intern:'Intern', other:'—',
};

const ROLE_COLOR = {
  exec:'#d946ef', director:'#a855f7', manager:'#6c63ff',
  bss:'#4589ff', bts:'#0ea5e9', csm:'#10b981',
  sdr:'#f59e0b', partner:'#8b5cf6', intern:'#60a5fa', other:'#525252',
};

// ── View state ────────────────────────────────────────────────────
let _all        = [];   // all people from API
let _me         = null; // current user
let _selected   = null; // selected person id
let _level      = 'colony'; // 'ibm' | 'colony' | 'cell' | 'bee'
let _focusColony = null;
let _filters    = { colony: new Set(), market: new Set(), role: new Set() };

// ── Entry point ───────────────────────────────────────────────────
export async function renderOrg(container) {
  container.innerHTML = buildShell();

  _all  = await getPeople();
  _me   = _all.find(p => p.is_current_user) || _all[0];
  _selected = _me?.id ?? null;
  _level = 'colony';
  _focusColony = _me?.comb ?? null;

  wireNav(container);
  wireDetailClose(container);
  render(container);

  // Sidebar multi-select filters
  document.addEventListener('sidebar:filter', e => {
    const { group, value, action } = e.detail;
    if (group === 'portfolios') {
      if (action === 'deselect') _filters.colony.delete(value);
      else if (action === 'clear') _filters.colony.clear();
      else _filters.colony.has(value) ? _filters.colony.delete(value) : _filters.colony.add(value);
    } else if (group === 'markets') {
      if (action === 'deselect') _filters.market.delete(value);
      else if (action === 'clear') _filters.market.clear();
      else _filters.market.has(value) ? _filters.market.delete(value) : _filters.market.add(value);
    } else if (group === 'jobs') {
      if (action === 'deselect') _filters.role.delete(value);
      else if (action === 'clear') _filters.role.clear();
      else _filters.role.has(value) ? _filters.role.delete(value) : _filters.role.add(value);
    }
    render(container);
  });

  container._cleanup = () => {
    document.removeEventListener('sidebar:filter', () => {});
  };
}

// ── Shell HTML ────────────────────────────────────────────────────
function buildShell() {
  return `
  <div class="org-page">
    <!-- Breadcrumb + You Are Here banner -->
    <div class="org-topbar">
      <div class="org-breadcrumb" id="orgBreadcrumb"></div>
      <div class="org-you-here" id="orgYouHere"></div>
    </div>

    <!-- Level navigator tabs -->
    <div class="org-level-nav" id="orgLevelNav">
      <button class="org-level-btn" data-level="ibm">IBM</button>
      <span class="org-level-sep">›</span>
      <button class="org-level-btn active" data-level="colony">Colony</button>
      <span class="org-level-sep">›</span>
      <button class="org-level-btn" data-level="cell">Cell</button>
      <span class="org-level-sep">›</span>
      <button class="org-level-btn" data-level="bee">Bee</button>
    </div>

    <!-- Active filters bar -->
    <div class="org-filter-bar" id="orgFilterBar" style="display:none"></div>

    <!-- Body: node grid + detail panel -->
    <div class="org-body">
      <div class="org-grid-wrap" id="orgGridWrap">
        <!-- Node grid rendered here -->
      </div>
      <div class="org-detail" id="orgDetail" style="display:none">
        <div class="org-detail-close" id="orgDetailClose">✕</div>
        <div class="org-detail-inner" id="orgDetailInner"></div>
      </div>
    </div>
  </div>
  `;
}

// ── Wire level nav buttons ────────────────────────────────────────
function wireNav(container) {
  container.querySelectorAll('.org-level-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      _level = btn.dataset.level;
      if (_level === 'ibm') _focusColony = null;
      if (_level === 'colony') _focusColony = _me?.comb ?? null;
      container.querySelectorAll('.org-level-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      render(container);
    });
  });
}

function wireDetailClose(container) {
  container.querySelector('#orgDetailClose')?.addEventListener('click', () => {
    _selected = null;
    container.querySelector('#orgDetail').style.display = 'none';
  });
}

// ── Main render ───────────────────────────────────────────────────
function render(container) {
  updateBreadcrumb(container);
  updateYouHere(container);
  updateFilterBar(container);
  renderGrid(container);
  if (_selected) renderDetail(container, _selected);
}

// ── Breadcrumb ────────────────────────────────────────────────────
function updateBreadcrumb(container) {
  const el = container.querySelector('#orgBreadcrumb');
  if (!el || !_me) return;
  const colony = _me.comb || '—';
  const market = _me.market || '—';
  const name   = _me.first_name + ' ' + _me.last_name;
  const ci = COLONY_INFO[colony] || {};
  el.innerHTML = `
    <span class="bc-segment" data-level="ibm" style="cursor:pointer">IBM</span>
    <span class="bc-sep">›</span>
    <span class="bc-segment" data-level="colony" style="color:${ci.color||'#fff'};cursor:pointer">${colony.replace(' Colony','')}</span>
    <span class="bc-sep">›</span>
    <span class="bc-segment" data-level="cell" style="cursor:pointer">${market} Market</span>
    <span class="bc-sep">›</span>
    <span class="bc-segment bc-you">You: ${name}</span>
  `;
  el.querySelectorAll('[data-level]').forEach(seg => {
    seg.addEventListener('click', () => {
      _level = seg.dataset.level;
      if (_level === 'colony') _focusColony = _me?.comb ?? null;
      if (_level === 'ibm') _focusColony = null;
      container.querySelectorAll('.org-level-btn').forEach(b => {
        b.classList.toggle('active', b.dataset.level === _level);
      });
      render(container);
    });
  });
}

// ── You Are Here banner ───────────────────────────────────────────
function updateYouHere(container) {
  const el = container.querySelector('#orgYouHere');
  if (!el || !_me) return;
  const mgr = _all.find(p => p.id === _me.manager_id);
  el.innerHTML = `
    <div class="yah-label">You are here</div>
    <div class="yah-name">${_me.first_name} ${_me.last_name}</div>
    <div class="yah-meta">${_me.role || ROLE_LABEL[_me.role_type] || '—'} · ${_me.comb?.replace(' Colony','') || '—'} · ${_me.market || '—'} Market</div>
    ${mgr ? `<div class="yah-mgr">Reports to <strong>${mgr.first_name} ${mgr.last_name}</strong> · ${mgr.role || ''}</div>` : ''}
  `;
}

// ── Filter bar ────────────────────────────────────────────────────
function updateFilterBar(container) {
  const bar = container.querySelector('#orgFilterBar');
  if (!bar) return;
  const chips = [];

  _filters.colony.forEach(v => {
    chips.push(`<span class="org-chip" data-group="portfolios" data-value="${v}">${v.replace(' Colony','')} <span class="org-chip-x">×</span></span>`);
  });
  _filters.market.forEach(v => {
    chips.push(`<span class="org-chip" data-group="markets" data-value="${v}">${v} <span class="org-chip-x">×</span></span>`);
  });
  _filters.role.forEach(v => {
    chips.push(`<span class="org-chip" data-group="jobs" data-value="${v}">${ROLE_LABEL[v] || v} <span class="org-chip-x">×</span></span>`);
  });

  if (chips.length === 0) {
    bar.style.display = 'none';
    return;
  }
  bar.style.display = 'flex';
  bar.innerHTML = `
    <span class="org-chip-label">Filters:</span>
    ${chips.join('')}
    <span class="org-chip org-chip-clear">Clear all</span>
  `;

  bar.querySelectorAll('.org-chip[data-group]').forEach(chip => {
    chip.addEventListener('click', () => {
      const g = chip.dataset.group, v = chip.dataset.value;
      if (g === 'portfolios') _filters.colony.delete(v);
      else if (g === 'markets') _filters.market.delete(v);
      else if (g === 'jobs') _filters.role.delete(v);
      render(container);
    });
  });
  bar.querySelector('.org-chip-clear')?.addEventListener('click', () => {
    _filters.colony.clear(); _filters.market.clear(); _filters.role.clear();
    render(container);
  });
}

// ── Apply filters to people list ──────────────────────────────────
function applyFilters(people) {
  return people.filter(p => {
    if (_filters.colony.size && !_filters.colony.has(p.comb)) return false;
    if (_filters.market.size && !_filters.market.has(p.market)) return false;
    const roleKey = p.role_type;
    if (_filters.role.size && !_filters.role.has(roleKey)) return false;
    return true;
  });
}

// ── Compute relationship sets for the current user ────────────────
function getRelationships() {
  if (!_me) return { chain: new Set(), team: new Set(), peers: new Set() };

  // Reporting chain: me → manager → skip-level → ...
  const chain = new Set();
  let cur = _me;
  while (cur?.manager_id) {
    chain.add(cur.manager_id);
    cur = _all.find(p => p.id === cur.manager_id);
  }

  // Direct team: people who share my manager
  const team = new Set(
    _all.filter(p => p.manager_id === _me.manager_id && p.id !== _me.id).map(p => p.id)
  );

  // My direct reports
  const reports = new Set(_all.filter(p => p.manager_id === _me.id).map(p => p.id));

  // Peers in same colony + market
  const peers = new Set(
    _all.filter(p =>
      p.id !== _me.id &&
      p.comb === _me.comb &&
      p.market === _me.market &&
      !chain.has(p.id) &&
      !team.has(p.id)
    ).map(p => p.id)
  );

  return { chain, team, reports, peers };
}

// ── Grid renderer ─────────────────────────────────────────────────
function renderGrid(container) {
  const wrap = container.querySelector('#orgGridWrap');
  if (!wrap) return;
  const { chain, team, reports, peers } = getRelationships();

  // Determine what to show at each level
  let sections = [];

  if (_level === 'ibm') {
    // Show all 6 colonies as expandable sections
    const colonies = [...new Set(_all.map(p => p.comb).filter(Boolean))];
    sections = colonies.map(c => ({
      title: c.replace(' Colony', ''),
      subtitle: `${_all.filter(p=>p.comb===c).length} people`,
      color: COLONY_INFO[c]?.color || '#525252',
      people: applyFilters(_all.filter(p => p.comb === c)),
      isMyColony: c === _me?.comb,
    }));
  } else if (_level === 'colony') {
    const colony = _focusColony || _me?.comb;
    const inColony = _all.filter(p => p.comb === colony);
    // Group by market within colony
    const markets = [...new Set(inColony.map(p => p.market).filter(Boolean))];
    sections = markets.map(m => ({
      title: m + ' Market',
      subtitle: `${inColony.filter(p=>p.market===m).length} people`,
      color: '#a8a8a8',
      people: applyFilters(inColony.filter(p => p.market === m)),
      isMyMarket: m === _me?.market,
    }));
    // If none, just show all colony people
    if (!sections.length) {
      sections = [{ title: colony, color: COLONY_INFO[colony]?.color||'#525252', people: applyFilters(inColony), subtitle:'' }];
    }
  } else if (_level === 'cell') {
    // My direct team: manager + peers + me
    const myMgr = _all.find(p => p.id === _me?.manager_id);
    const directTeam = _all.filter(p =>
      p.id === _me?.id ||
      p.id === _me?.manager_id ||
      (p.manager_id === _me?.manager_id) ||
      (p.manager_id === _me?.id)
    );
    const others = applyFilters(_all.filter(p =>
      p.comb === _me?.comb &&
      !directTeam.find(d => d.id === p.id)
    ));
    sections = [
      { title: 'My Cell', subtitle: 'Direct team', color: '#6c63ff', people: applyFilters(directTeam), highlight: true },
      ...(others.length ? [{ title: 'Also in Colony', subtitle: 'Same portfolio', color: '#393939', people: others }] : []),
    ];
  } else if (_level === 'bee') {
    // Just me + my manager chain + direct reports
    const beeSet = new Set([_me?.id, ...[...chain], ...[...reports]]);
    sections = [
      {
        title: 'My Reporting Chain',
        subtitle: 'You + your management chain',
        color: '#4589ff',
        people: applyFilters(_all.filter(p => beeSet.has(p.id))),
        highlight: true,
      },
    ];
  }

  // Render
  const totalVisible = sections.reduce((n, s) => n + s.people.length, 0);
  const filtersActive = _filters.colony.size || _filters.market.size || _filters.role.size;

  let html = '';

  // Summary bar
  html += `<div class="org-summary">
    <span class="org-summary-count">${totalVisible} people${filtersActive ? ' (filtered)' : ''}</span>
    <div class="org-legend">
      <span class="org-legend-item"><span class="org-legend-dot" style="background:#4589ff"></span>You</span>
      <span class="org-legend-item"><span class="org-legend-dot" style="background:#6c63ff"></span>Manager / Chain</span>
      <span class="org-legend-item"><span class="org-legend-dot" style="background:#0ea5e9"></span>Direct team</span>
      <span class="org-legend-item"><span class="org-legend-dot" style="background:#393939;border:1px solid #525252"></span>Colleague</span>
    </div>
  </div>`;

  if (sections.length === 0 || totalVisible === 0) {
    html += `<div class="org-empty">No people match the current filters. <a href="#" class="org-empty-clear">Clear filters</a></div>`;
  }

  sections.forEach(sec => {
    if (!sec.people.length) return;

    html += `<div class="org-section">`;
    html += `<div class="org-section-header">
      <span class="org-section-dot" style="background:${sec.color}"></span>
      <span class="org-section-title">${sec.title}</span>
      <span class="org-section-sub">${sec.subtitle || ''}</span>
      ${sec.isMyColony || sec.isMyMarket ? `<span class="org-section-you-badge">Your ${sec.isMyColony ? 'Colony' : 'Market'}</span>` : ''}
    </div>`;

    html += `<div class="org-node-grid">`;
    sec.people.forEach(p => {
      const isMe      = p.id === _me?.id;
      const inChain   = chain.has(p.id);
      const inTeam    = team.has(p.id);
      const isReport  = reports.has(p.id);
      const isSelected = p.id === _selected;

      let rel = 'colleague';
      if (isMe)     rel = 'me';
      else if (inChain) rel = 'chain';
      else if (inTeam || isReport) rel = 'team';

      const roleCol = ROLE_COLOR[p.role_type] || '#525252';
      const ci = COLONY_INFO[p.comb] || {};

      html += `<div class="org-node org-node-${rel}${isSelected?' org-node-selected':''}" data-pid="${p.id}" tabindex="0" role="button">
        <div class="org-node-hex" style="background:${nodeColor(rel, roleCol, isMe)}">
          <div class="org-node-hex-inner"></div>
        </div>
        <div class="org-node-body">
          <div class="org-node-name">${p.first_name} ${p.last_name}${isMe ? ' <span class="org-you-tag">You</span>' : ''}</div>
          <div class="org-node-role">${p.role || ROLE_LABEL[p.role_type] || '—'}</div>
          <div class="org-node-meta">
            ${p.market ? `<span class="org-node-badge">${p.market}</span>` : ''}
            ${inChain ? `<span class="org-node-badge org-node-badge-chain">Manager chain</span>` : ''}
            ${(inTeam||isReport) ? `<span class="org-node-badge org-node-badge-team">Direct team</span>` : ''}
          </div>
        </div>
        <div class="org-node-arrow">›</div>
      </div>`;
    });
    html += `</div></div>`;
  });

  wrap.innerHTML = html;

  // Wire node clicks
  wrap.querySelectorAll('.org-node').forEach(node => {
    node.addEventListener('click', () => {
      const pid = parseInt(node.dataset.pid, 10);
      _selected = pid;
      // Highlight selected
      wrap.querySelectorAll('.org-node').forEach(n => n.classList.remove('org-node-selected'));
      node.classList.add('org-node-selected');
      renderDetail(container, pid);
    });
    node.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') node.click();
    });
  });

  wrap.querySelector('.org-empty-clear')?.addEventListener('click', e => {
    e.preventDefault();
    _filters.colony.clear(); _filters.market.clear(); _filters.role.clear();
    render(container);
  });
}

function nodeColor(rel, roleCol, isMe) {
  if (isMe)         return '#0d1f4c';
  if (rel === 'chain') return '#1e1a3c';
  if (rel === 'team')  return '#0e2030';
  return '#1c1c1c';
}

// ── Detail panel ──────────────────────────────────────────────────
function renderDetail(container, pid) {
  const panel = container.querySelector('#orgDetail');
  const inner = container.querySelector('#orgDetailInner');
  if (!panel || !inner) return;

  const p = _all.find(x => x.id === pid);
  if (!p) return;

  const isMe     = p.id === _me?.id;
  const mgr      = _all.find(x => x.id === p.manager_id);
  const myReports = _all.filter(x => x.manager_id === p.id);
  const ci       = COLONY_INFO[p.comb] || {};
  const roleCol  = ROLE_COLOR[p.role_type] || '#525252';

  // Relationship description
  const { chain, team, reports } = getRelationships();
  let relDesc = '';
  if (isMe) relDesc = 'This is you';
  else if (chain.has(p.id)) relDesc = 'In your reporting chain';
  else if (team.has(p.id))  relDesc = 'On your direct team (same manager)';
  else if (reports.has(p.id)) relDesc = 'Reports to you';
  else if (p.comb === _me?.comb) relDesc = 'Same colony';

  inner.innerHTML = `
    <div class="odp-header">
      <div class="odp-hex" style="background:${nodeColor(relDesc.includes('chain') ? 'chain' : relDesc.includes('team') ? 'team' : isMe ? 'me' : 'colleague', roleCol, isMe)};border-color:${roleCol}"></div>
      <div class="odp-title">
        <div class="odp-name">${p.first_name} ${p.last_name}${isMe ? ' <span class="org-you-tag">You</span>':''}</div>
        <div class="odp-role">${p.role || ROLE_LABEL[p.role_type] || '—'}</div>
        ${relDesc ? `<div class="odp-rel">${relDesc}</div>` : ''}
      </div>
    </div>

    <div class="odp-sections">

      <div class="odp-section">
        <div class="odp-section-title">Identity</div>
        ${odpRow('Function', p.role_type ? (ROLE_LABEL[p.role_type]||p.role_type) : '—')}
        ${odpRow('Colony', p.comb ? `<span style="color:${ci.color||'#fff'}">${p.comb}</span>` : '—')}
        ${odpRow('Market', p.market || '—')}
        ${odpRow('Location', p.location || '—')}
      </div>

      <div class="odp-section">
        <div class="odp-section-title">Reporting</div>
        ${mgr ? odpRow('Manager', personLink(mgr, container)) : odpRow('Manager', '— (top of chain)')}
        ${myReports.length ? odpRow('Direct reports', myReports.map(r => personLink(r, container)).join(', ')) : ''}
      </div>

      <div class="odp-section">
        <div class="odp-section-title">Contact</div>
        ${odpRow('Email', p.email ? `<a href="mailto:${p.email}" class="odp-link">${p.email}</a>` : '—')}
        ${odpRow('Slack', p.slack || '—')}
      </div>

      ${ci.products ? `<div class="odp-section">
        <div class="odp-section-title">Products (colony)</div>
        <div class="odp-tags">${ci.products.map(pr=>`<span class="odp-tag">${pr}</span>`).join('')}</div>
      </div>` : ''}

    </div>

    <div class="odp-actions">
      ${!isMe ? `<button class="odp-btn-primary" onclick="window.open('mailto:${p.email}','_self')">Email ${p.first_name}</button>` : ''}
      <button class="odp-btn-secondary" id="odpViewColony">View their colony</button>
    </div>
  `;

  panel.style.display = 'flex';

  // Wire view colony button
  inner.querySelector('#odpViewColony')?.addEventListener('click', () => {
    _focusColony = p.comb;
    _level = 'colony';
    container.querySelectorAll('.org-level-btn').forEach(b => b.classList.toggle('active', b.dataset.level === 'colony'));
    render(container);
  });

  // Wire person links in detail
  inner.querySelectorAll('[data-detail-pid]').forEach(a => {
    a.addEventListener('click', e => {
      e.preventDefault();
      const newPid = parseInt(a.dataset.detailPid, 10);
      _selected = newPid;
      container.querySelectorAll('.org-node').forEach(n => {
        n.classList.toggle('org-node-selected', parseInt(n.dataset.pid,10) === newPid);
      });
      renderDetail(container, newPid);
    });
  });
}

function odpRow(label, value) {
  return `<div class="odp-row"><span class="odp-label">${label}</span><span class="odp-value">${value}</span></div>`;
}

function personLink(p, container) {
  return `<a href="#" class="odp-link" data-detail-pid="${p.id}">${p.first_name} ${p.last_name}</a>`;
}

