  def.sections.forEach(section => {
    if (section.label) {
      html += `<div class="sb-section-label">${section.label}</div>`;
    }
    section.items.forEach(item => {
      if (item.expandable && item.children) {
        html += `
          <div class="sb-group" data-group="${item.id}">
