    if (isOrgView) { body.classList.add('open'); header.querySelector('.sb-caret').textContent = '⌄'; }
    header.addEventListener('click', () => {
      const open = body.classList.toggle('open');
      header.querySelector('.sb-caret').textContent = open ? '⌄' : '›';
    });
  });

