/* ═══════════════════════════════════════════════════════════════
   HIVE MAP — org.js zoomable organizational map
   ═══════════════════════════════════════════════════════════════ */

.hmap-shell {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
