  right: 0;
  bottom: 0;
  width: 300px;
  background: #111;
  border-left: 1px solid rgba(255,255,255,0.08);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  z-index: 10;
  box-shadow: -8px 0 32px rgba(0,0,0,0.5);
}
.hmap-detail-close {
  position: absolute;
  top: 10px; right: 12px;
  background: none;
  border: none;
  color: var(--muted);
  font-size: 15px;
  cursor: pointer;
  padding: 4px 6px;
  transition: color 0.1s;
  z-index: 1;
}
.hmap-detail-close:hover { color: #fff; }

/* Detail panel body */
#hmapDetailBody { padding: 18px; }

.hdp-header {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding-right: 24px;
}
.hdp-hex {
  width: 40px; height: 46px;
  clip-path: polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%);
  flex-shrink: 0;
  border: 2px solid;
}
.hdp-circle {
  width: 40px; height: 40px;
  border-radius: 50%;
  flex-shrink: 0;
  border: 2px solid;
}
.hdp-name {
  font-size: 16px;
  font-weight: 400;
  color: var(--text);
  line-height: 1.3;
}
.hdp-role { font-size: 12px; color: var(--muted); margin-top: 3px; }

.hdp-sections {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.hdp-section { display: flex; flex-direction: column; gap: 3px; }
.hdp-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  font-weight: 600;
}
.hdp-val {
  font-size: 13px;
  color: var(--text);
  line-height: 1.5;
}
.hdp-link { color: var(--ibm-blue-40); text-decoration: none; font-size: 13px; }
.hdp-link:hover { text-decoration: underline; }
.hdp-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 2px; }
.hdp-tag {
  font-size: 11px;
  padding: 2px 8px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--text-secondary);
}
.you-tag {
  font-size: 10px; padding: 1px 6px;
  background: rgba(69,137,255,0.15); color: var(--ibm-blue-40);
  font-weight: 600; letter-spacing: 0.32px;
  margin-left: 5px; vertical-align: middle;
}

/* ═══════════════════════════════════════════════════════════════
   CELL VIEW — BTSS↔TSS pairing diagram
   ═══════════════════════════════════════════════════════════════ */

.cell-structure-wrap {
  flex: 1;
  padding: 24px 32px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.cell-structure-header {
  border-bottom: 1px solid rgba(255,255,255,0.07);
  padding-bottom: 14px;
}
.cell-header-breadcrumb {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  margin-bottom: 6px;
}
.cell-bc { color: var(--muted); }
.cell-bc-sep { color: #333; }
.cell-bc-active { color: var(--text); font-weight: 500; }
.cell-header-sub { font-size: 12px; color: #525252; }

.cell-diagram-wrap {
  overflow-x: auto;
  padding-bottom: 8px;
}

.cell-legend {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
  font-size: 12px;
  color: var(--muted);
  padding: 10px 0;
  border-top: 1px solid rgba(255,255,255,0.06);
}
.cell-leg-item { display: flex; align-items: center; gap: 7px; }
.cell-leg-line {
  display: inline-block;
  width: 28px; height: 2px;
  flex-shrink: 0;
}
.cell-leg-solid  { background: #0ea5e9; }
.cell-leg-dashed { background: none; border-top: 2px dashed #6c63ff; }
.cell-leg-dot {
  width: 10px; height: 10px;
  border-radius: 2px; flex-shrink: 0;
}

.cell-products {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cell-products-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  font-weight: 600;
}
.cell-products-list { display: flex; gap: 6px; flex-wrap: wrap; }
.cell-product-tag {
  font-size: 12px;
  padding: 4px 12px;
  background: rgba(77,123,255,0.08);
  border: 1px solid rgba(77,123,255,0.2);
  color: var(--ibm-blue-40);
}

.cell-pairs-table { }
.cell-pairs-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--muted);
  font-weight: 600;
  margin-bottom: 10px;
}
.cell-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.cell-table th {
  text-align: left;
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.32px;
  color: var(--muted);
  padding: 0 12px 8px 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.cell-table td {
  padding: 9px 12px 9px 0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  color: var(--text-secondary);
  vertical-align: middle;
}
.cell-table tr:last-child td { border-bottom: none; }

