Contents of file frontend/css/hive.css:

1 | /* ─────────────────────────────────────────────────────────────
2 |    IBM Hive — hive.css
3 |    Dark theme. Accent palette is blue → purple only.
4 |    ───────────────────────────────────────────────────────────── */
5 | *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
6 | 
7 | :root {
8 |   /* Brand accents — blue → purple, nothing else */
9 |   --accent-blue:     #4d7bff;
10 |   --accent-blue-dark:#2f5bef;
11 |   --accent-indigo:   #6c63ff;
12 |   --accent-violet:   #8b5cf6;
13 |   --accent-purple:   #a855f7;
14 |   --accent-magenta:  #d946ef;
15 |   --accent-gradient: linear-gradient(135deg, var(--accent-blue) 0%, var(--accent-purple) 100%);
16 | 
17 |   /* Back-compat alias used by a few components below */
18 |   --ibm-blue:      var(--accent-blue);
19 |   --ibm-blue-dark: var(--accent-blue-dark);
20 | 
21 |   /* Surfaces — near-black background, neutral charcoal cards (AskIBM style) */
22 |   --bg:         #0a0a0c;
23 |   --nav-bg:     #000000;
24 |   --sidebar-bg: #0a0a0c;
25 |   --surface:    #18181b;
26 |   --surface-2:  #232326;
27 |   --border:     #333338;
28 |   --text:       #f2f2f4;
29 |   --muted:      #98989f;
30 | 
31 |   /* Hexagon stroke used on every person/role hex across the app */
32 |   --hex-border: rgba(255,255,255,0.9);
33 | 
34 |   /* Role / seniority spectrum (blue → magenta = junior → senior, not danger) */
35 |   --c-exec:     #d946ef;
36 |   --c-director: #a855f7;
37 |   --c-manager:  #6c63ff;
38 |   --c-you:      var(--accent-blue);
39 |   --c-peer:     #60a5fa;
40 |   --c-tech:     #a78bfa;
41 |   --c-csm:      #4338ca;
42 |   --c-sdr:      #7e22ce;
43 |   --c-partner:  #e879f9;
44 |   --c-other:    #64748b;
45 |   --c-open:     var(--surface-2);
46 | 
47 |   /* Account pipeline stage spectrum (blue → magenta = healthy → urgent) */
48 |   --stage-won:         #3b82f6;
49 |   --stage-negotiation: #6366f1;
50 |   --stage-proposal:    #8b5cf6;
51 |   --stage-risk:        #d946ef;
52 |   --stage-prospect:    #64748b;
53 | 
54 |   /* Market spectrum */
55 |   --mkt-enterprise: #4d7bff;
56 |   --mkt-strategic:  #a855f7;
57 |   --mkt-horizon:    #6c63ff;
58 |   --mkt-territory:  #d946ef;
59 | }
60 | 
61 | body {
62 |   font-family: -apple-system, "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
63 |   background: var(--bg);
64 |   color: var(--text);
65 |   min-height: 100vh;
66 |   display: flex;
67 |   flex-direction: column;
68 | }
69 | 
70 | /* ── TOP NAV ─────────────────────────────────────────────────── */
71 | .topnav {
72 |   background: var(--nav-bg);
73 |   color: #fff;
74 |   display: flex;
75 |   align-items: center;
76 |   justify-content: space-between;
77 |   padding: 0 24px;
78 |   height: 48px;
79 |   flex-shrink: 0;
80 |   border-bottom: 1px solid var(--border);
81 | }
82 | .topnav-brand {
83 |   display: flex;
84 |   align-items: center;
85 |   gap: 10px;
86 |   font-size: 15px;
87 |   font-weight: 600;
88 |   letter-spacing: 0.5px;
89 | }
90 | 
91 | .logo-img {
92 |   width: 32px;
93 |   height: 32px;
94 |   object-fit: contain;
95 |   display: block;
96 |   flex-shrink: 0;
97 | }
98 | 
99 | .topnav-user {
100 |   display: flex;
101 |   align-items: center;
102 |   gap: 8px;
103 |   font-size: 13px;
104 |   color: #c6c6d6;
105 | }
106 | .avatar {
107 |   width: 28px;
108 |   height: 31px;
109 |   clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
110 |   border: 1.5px solid var(--hex-border);
111 |   background: var(--accent-gradient);
112 |   display: flex;
113 |   align-items: center;
114 |   justify-content: center;
115 |   font-size: 11px;
116 |   font-weight: 700;
117 |   color: #fff;
118 |   cursor: pointer;
119 | }
120 | 
121 | /* ── LAYOUT ──────────────────────────────────────────────────── */
122 | .shell {
123 |   display: flex;
124 |   flex: 1;
125 |   overflow: hidden;
126 |   min-height: 0;
127 | }
128 | 
129 | /* ── SIDEBAR ─────────────────────────────────────────────────── */
130 | .sidebar {
131 |   width: 200px;
132 |   background: var(--sidebar-bg);
133 |   display: flex;
134 |   flex-direction: column;
