155 |   transition: background 0.15s, color 0.15s;
156 | }
157 | .nav-item:hover { background: var(--surface-2); color: #fff; }
158 | .nav-item.active { background: var(--surface-2); color: var(--accent-blue); border-left-color: var(--accent-blue); }
159 | .nav-icon { font-size: 16px; width: 18px; text-align: center; }
160 | .sidebar-divider { height: 1px; background: var(--border); margin: 4px 0; }
161 | 
162 | /* ── MAIN ────────────────────────────────────────────────────── */
163 | .main { flex: 1; overflow-y: auto; display: flex; flex-direction: column; }
164 | 
165 | .view { display: none; flex-direction: column; flex: 1; }
166 | .view.active { display: flex; }
167 | 
168 | .page-header {
169 |   padding: 24px 28px 16px;
170 |   border-bottom: 1px solid var(--border);
171 |   background: var(--surface);
172 |   flex-shrink: 0;
173 | }
174 | .page-title  { font-size: 20px; font-weight: 600; }
175 | .page-sub    { font-size: 13px; color: var(--muted); margin-top: 2px; }
176 | 
177 | /* ── TAB BAR ─────────────────────────────────────────────────── */
178 | .tab-bar {
179 |   display: flex;
180 |   padding: 0 28px;
181 |   background: var(--surface);
182 |   border-bottom: 1px solid var(--border);
183 |   flex-shrink: 0;
184 | }
185 | .tab {
186 |   padding: 10px 18px;
187 |   font-size: 13px;
188 |   cursor: pointer;
189 |   color: var(--muted);
190 |   border-bottom: 2px solid transparent;
191 |   white-space: nowrap;
192 | }
193 | .tab:hover { color: var(--text); }
194 | .tab.active { color: var(--accent-blue); border-bottom-color: var(--accent-blue); font-weight: 500; }
195 | 
196 | /* ── CONTENT AREA ────────────────────────────────────────────── */
197 | .content { padding: 24px 28px; overflow-y: auto; flex: 1; }
198 | 
199 | /* ── STAT CARDS ──────────────────────────────────────────────── */
200 | .stat-row { display: flex; gap: 12px; margin-bottom: 24px; flex-wrap: wrap; }
201 | .stat-card {
202 |   background: var(--surface-2);
203 |   border: 1px solid var(--border);
204 |   border-radius: 8px;
205 |   padding: 14px 18px;
206 |   flex: 1;
207 |   min-width: 120px;
208 | }
209 | .stat-num   { font-size: 26px; font-weight: 700; color: var(--accent-blue); }
210 | .stat-label { font-size: 12px; color: var(--muted); margin-top: 2px; }
211 | 
212 | /* ── TOOLBAR ─────────────────────────────────────────────────── */
213 | .toolbar { display: flex; align-items: center; gap: 10px; margin-bottom: 20px; flex-wrap: wrap; }
214 | .search-box {
215 |   flex: 1;
216 |   min-width: 160px;
217 |   max-width: 280px;
218 |   padding: 7px 12px;
219 |   border: 1px solid var(--border);
220 |   border-radius: 4px;
221 |   font-size: 13px;
222 |   background: var(--surface-2);
223 |   color: var(--text);
224 | }
225 | .search-box::placeholder { color: #6b6b85; }
226 | .search-box:focus { outline: none; border-color: var(--accent-blue); }
227 | .sort-select {
228 |   padding: 7px 10px;
229 |   border: 1px solid var(--border);
230 |   border-radius: 4px;
231 |   font-size: 13px;
232 |   background: var(--surface-2);
233 |   color: var(--text);
234 | }
235 | .sort-select:focus { outline: none; border-color: var(--accent-blue); }
236 | 
237 | /* ── ROLE LEGEND ─────────────────────────────────────────────── */
238 | .role-legend { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 20px; }
239 | .rl-item { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--muted); }
240 | .rl-dot {
241 |   width: 12px;
242 |   height: 12px;
243 |   clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
244 | }
245 | 
246 | /* ── HEX CELLS ───────────────────────────────────────────────── */
247 | .hive-container {
248 |   display: flex;
249 |   flex-direction: column;
250 |   align-items: flex-start;
251 |   padding: 8px 0 32px;
252 | }
253 | .hex-row {
254 |   display: flex;
255 |   gap: 4px;
256 |   margin-bottom: -18px;
257 | }
258 | .hex-row:nth-child(even) { margin-left: 42px; }
