319 | }
320 | .hex.open .hex-name { color: var(--muted); text-shadow: none; }
321 | 
322 | /* ── ORG TREE ────────────────────────────────────────────────── */
323 | .org-tree { display: flex; flex-direction: column; overflow-x: auto; padding-bottom: 16px; }
324 | .org-level { display: flex; justify-content: center; gap: 16px; padding: 12px 0; }
