1 | /**
2 |  * app.js — boot, navigation, and view orchestration
3 |  */
4 | import { getPeople }      from './api.js';
5 | import { renderSeller }   from './views/seller.js';
6 | import { renderNetwork }  from './views/network.js';
7 | import { renderAccounts } from './views/accounts.js';
8 | 
9 | // ── Boot: populate current user in nav ────────────────────────
10 | async function boot() {
11 |   try {
12 |     const people = await getPeople();
13 |     const me = people.find(p => p.is_current_user);
14 |     if (me) {
15 |       document.getElementById('currentUserName').textContent = me.first_name + ' ' + me.last_name;
16 |       document.getElementById('currentUserAvatar').textContent = me.initials;
17 |     }
18 |   } catch (e) {
19 |     console.warn('Could not load user from API:', e.message);
20 |   }
21 | }
22 | 
23 | // ── View registry ─────────────────────────────────────────────
24 | const VIEW_RENDERERS = {
25 |   seller:   renderSeller,
26 |   network:  renderNetwork,
27 |   accounts: renderAccounts,
28 | };
29 | 
30 | const rendered = new Set();
31 | 
32 | async function activateView(viewName) {
33 |   // Update sidebar
34 |   document.querySelectorAll('.nav-item').forEach(n => {
35 |     n.classList.toggle('active', n.dataset.view === viewName);
36 |   });
37 | 
38 |   // Show the right view container
39 |   document.querySelectorAll('.main > .view').forEach(v => {
40 |     v.classList.toggle('active', v.id === `view-${viewName}`);
41 |   });
42 | 
43 |   // Render the view if not already rendered
44 |   const container = document.getElementById(`view-${viewName}`);
45 |   if (!container) return;
46 | 
47 |   if (!rendered.has(viewName)) {
48 |     rendered.add(viewName);
49 |     try {
50 |       await VIEW_RENDERERS[viewName]?.(container);
51 |     } catch (err) {
52 |       container.innerHTML = `
53 |         <div class="page-header">
54 |           <div class="page-title">Error</div>
55 |           <div class="page-sub">Could not load view: ${err.message}</div>
56 |         </div>
57 |         <div class="content" style="color:var(--muted);font-size:13px">
58 |           Make sure the server is running (<code>npm start</code>) and the database is seeded (<code>npm run seed</code>).
59 |         </div>
60 |       `;
61 |     }
62 |   }
63 | }
64 | 
65 | // ── Sidebar nav clicks ────────────────────────────────────────
66 | document.querySelectorAll('.nav-item').forEach(item => {
67 |   item.addEventListener('click', () => activateView(item.dataset.view));
68 | });
69 | 
70 | // ── Init ──────────────────────────────────────────────────────
71 | boot();
72 | activateView('seller');
