4 | import { getAccounts } from '../api.js';
5 | import { openAccount } from '../panel.js';
6 | 
7 | const STAGE_COLORS = {
8 |   'Closed Won':  'var(--stage-won)',
9 |   'Negotiation': 'var(--stage-negotiation)',
10 |   'Proposal':    'var(--stage-proposal)',
11 |   'At Risk':     'var(--stage-risk)',
12 |   'Prospect':    'var(--stage-prospect)',
13 | };
14 | 
15 | const STAGES = ['Closed Won', 'Negotiation', 'Proposal', 'At Risk', 'Prospect'];
16 | 
17 | export async function renderAccounts(container) {
18 |   container.innerHTML = `
19 |     <div class="page-header">
20 |       <div class="page-title">Account Hive</div>
21 |       <div class="page-sub">All your accounts in one comb — color coded by pipeline stage</div>
22 |     </div>
23 |     <div class="content">
24 |       <div id="acct-stats" class="stat-row"></div>
25 |       <div class="accounts-toolbar">
26 |         <button class="acct-filter active" data-stage="">All</button>
27 |         ${STAGES.map(s => `<button class="acct-filter" data-stage="${s}">${s}</button>`).join('')}
28 |         <div class="acct-legend">
29 |           ${Object.entries(STAGE_COLORS).map(([stage, color]) => `
30 |             <div class="legend-item">
31 |               <div class="legend-dot" style="background:${color}"></div>${stage}
32 |             </div>
33 |           `).join('')}
34 |         </div>
35 |       </div>
36 |       <div id="acct-hive" class="hive-container" style="flex-direction:column;align-items:flex-start">
37 |         <div class="loading">Loading…</div>
38 |       </div>
39 |     </div>
40 |   `;
41 | 
42 |   const accounts = await getAccounts();
43 |   renderStats(accounts);
44 | 
45 |   let activeStage = '';
46 | 
47 |   function redraw() {
48 |     renderHive(accounts, activeStage);
49 |   }
50 | 
51 |   container.querySelectorAll('.acct-filter').forEach(btn => {
52 |     btn.addEventListener('click', () => {
53 |       container.querySelectorAll('.acct-filter').forEach(b => b.classList.remove('active'));
54 |       btn.classList.add('active');
55 |       activeStage = btn.dataset.stage;
56 |       redraw();
57 |     });
58 |   });
59 | 
60 |   redraw();
61 | }
62 | 
63 | function renderStats(accounts) {
64 |   const el = document.getElementById('acct-stats');
65 |   if (!el) return;
66 | 
67 |   const total     = accounts.length;
68 |   const closedWon = accounts.filter(a => a.stage === 'Closed Won').reduce((s,a) => s + (a.value_usd||0), 0);
69 |   const pipeline  = accounts.filter(a => ['Negotiation','Proposal'].includes(a.stage)).reduce((s,a) => s + (a.value_usd||0), 0);
70 |   const atRisk    = accounts.filter(a => a.stage === 'At Risk').reduce((s,a) => s + (a.value_usd||0), 0);
71 | 
72 |   el.innerHTML = `
73 |     <div class="stat-card"><div class="stat-num">${total}</div><div class="stat-label">Accounts</div></div>
74 |     <div class="stat-card"><div class="stat-num" style="color:var(--stage-won)">${fmt(closedWon)}</div><div class="stat-label">Closed Won</div></div>
75 |     <div class="stat-card"><div class="stat-num" style="color:var(--accent-blue)">${fmt(pipeline)}</div><div class="stat-label">Active Pipeline</div></div>
76 |     <div class="stat-card"><div class="stat-num" style="color:var(--stage-risk)">${fmt(atRisk)}</div><div class="stat-label">At Risk</div></div>
77 |   `;
78 | }
79 | 
80 | function renderHive(accounts, activeStage) {
81 |   const hive = document.getElementById('acct-hive');
82 |   if (!hive) return;
83 | 
84 |   // Chunk accounts into rows of 4–5 (offset every other)
85 |   const ROW_SIZE = 4;
86 |   const rows = [];
87 |   for (let i = 0; i < accounts.length; i += ROW_SIZE) {
88 |     rows.push(accounts.slice(i, i + ROW_SIZE));
89 |   }
90 | 
91 |   hive.innerHTML = rows.map((row, ri) => `
92 |     <div class="hex-row acct-row" style="${ri % 2 === 1 ? 'margin-left:44px' : ''}">
93 |       ${row.map(a => {
94 |         const color   = STAGE_COLORS[a.stage] || 'var(--stage-prospect)';
95 |         const dimmed  = activeStage && a.stage !== activeStage;
