191 | // ── Helper: single org card ────────────────────────────────────
192 | function orgCard(person, variant) {
193 |   const color = person.is_current_user ? 'var(--c-you)' : ROLE_COLORS[person.role_type] || 'var(--c-other)';
194 |   const badge = {
195 |     you:       `<div class="org-badge" style="background:rgba(77,123,255,0.16);color:var(--c-you)">You</div>`,
196 |     highlight: `<div class="org-badge">Your Manager</div>`,
197 |     peer:      `<div class="org-badge">Peer</div>`,
198 |     '':        `<div class="org-badge">${capitalize(person.role_type)}</div>`,
199 |   }[variant] ?? `<div class="org-badge">${capitalize(person.role_type)}</div>`;
200 | 
201 |   return `
202 |     <div class="org-card ${variant}" data-person-id="${person.id}">
203 |       <div class="org-avatar" style="background:${color}">${person.initials}</div>
204 |       <div class="org-info">
205 |         <div class="org-name">${person.first_name} ${person.last_name}</div>
206 |         <div class="org-role">${person.role}</div>
207 |         ${badge}
208 |       </div>
209 |     </div>
210 |   `;
211 | }
212 | 
213 | function capitalize(s) {
214 |   return s ? s.charAt(0).toUpperCase() + s.slice(1) : '';
215 | }
