/* ─────────────────────────────────────────────────────────────
   IBM Hive — hive.css
   IBM Carbon / w3 dark theme.
   ───────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* IBM Carbon blue palette */
  --ibm-blue-10:  #edf5ff;
  --ibm-blue-40:  #78a9ff;
  --ibm-blue-50:  #4589ff;
  --ibm-blue-60:  #0f62fe;
  --ibm-blue-70:  #0043ce;

  /* IBM Purple palette */
  --ibm-purple-40: #be95ff;
  --ibm-purple-50: #a56eff;
  --ibm-purple-60: #8a3ffc;

  /* Accent aliases */
  --accent-blue:     var(--ibm-blue-50);
  --accent-blue-dark:var(--ibm-blue-60);
  --accent-indigo:   #6c63ff;
  --accent-violet:   #8b5cf6;
  --accent-purple:   var(--ibm-purple-50);
  --accent-magenta:  #d946ef;
  --accent-gradient: linear-gradient(135deg, var(--ibm-blue-60) 0%, var(--ibm-purple-60) 100%);

  /* Back-compat aliases */
  --ibm-blue:      var(--ibm-blue-50);
  --ibm-blue-dark: var(--ibm-blue-60);

  /* IBM Carbon Gray 100 surfaces (w3 dark) */
  --bg:         #161616;
  --nav-bg:     #161616;
  --sidebar-bg: #1c1c1c;
  --surface:    #262626;
  --surface-2:  #393939;
  --border:     #525252;
  --border-subtle: #393939;
  --text:       #f4f4f4;
  --text-secondary: #c6c6c6;
  --muted:      #8d8d8d;

  /* Hex border */
  --hex-border: rgba(255,255,255,0.85);

  /* Role / seniority color spectrum */
  --c-exec:     #d946ef;
  --c-director: #a855f7;
  --c-manager:  #6c63ff;
  --c-you:      var(--ibm-blue-50);
  --c-peer:     #60a5fa;
  --c-tech:     #a78bfa;
  --c-csm:      #4338ca;
  --c-sdr:      #7e22ce;
  --c-partner:  #e879f9;
  --c-other:    #525252;
  --c-open:     var(--surface-2);

  /* Pipeline stage spectrum */
  --stage-won:         #0f62fe;
  --stage-negotiation: #6c63ff;
  --stage-proposal:    #8a3ffc;
  --stage-risk:        #d946ef;
  --stage-prospect:    #525252;

  /* Market spectrum */
  --mkt-enterprise: #0f62fe;
  --mkt-strategic:  #a855f7;
  --mkt-horizon:    #6c63ff;
  --mkt-territory:  #d946ef;
}

body {
  font-family: "IBM Plex Sans", -apple-system, "Segoe UI", system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  font-size: 14px;
  line-height: 1.5;
}

/* ── TOP NAV (IBM w3 style) ───────────────────────────────────── */
.topnav {
  background: #000000;
  color: #fff;
  display: flex;
  align-items: center;
  padding: 0;
  height: 48px;
  flex-shrink: 0;
  border-bottom: 1px solid #393939;
  gap: 0;
}

.topnav-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.16px;
  padding: 0 16px;
  height: 100%;
  border-right: 1px solid #393939;
  color: #fff;
  flex-shrink: 0;
}

.logo-img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  display: block;
  flex-shrink: 0;
}

/* Nav link strip (mimic w3 Home / People / News / Apps tabs) */
.topnav-links {
  display: flex;
  align-items: center;
  height: 100%;
  flex: 1;
}

.topnav-link {
  display: flex;
  align-items: center;
  height: 100%;
  padding: 0 16px;
  font-size: 14px;
  color: #c6c6c6;
  cursor: pointer;
  border-bottom: 2px solid transparent;
  white-space: nowrap;
  transition: color 0.1s;
  letter-spacing: 0.16px;
}
.topnav-link:hover { color: #fff; }
.topnav-link.active { color: #fff; border-bottom-color: var(--ibm-blue-50); }

/* Search bar in top nav */
.topnav-search {
  display: flex;
  align-items: center;
  gap: 6px;
  background: #262626;
  border: none;
  border-left: 1px solid #393939;
  height: 100%;
  padding: 0 14px;
  flex: 0 1 280px;
}
.topnav-search input {
  background: transparent;
  border: none;
  outline: none;
  color: #c6c6c6;
  font-size: 14px;
  font-family: inherit;
  width: 100%;
}
.topnav-search input::placeholder { color: #6f6f6f; }
.topnav-search svg { flex-shrink: 0; }

.topnav-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 16px;
  height: 100%;
  font-size: 13px;
  color: #c6c6c6;
  border-left: 1px solid #393939;
  flex-shrink: 0;
}

/* Hex-shaped avatar (all profile images are hex / hive shaped) */
.avatar {
  width: 28px;
  height: 32px;
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
  background: var(--accent-gradient);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: #fff;
  cursor: pointer;
  flex-shrink: 0;
}

/* ── LAYOUT ──────────────────────────────────────────────────── */
.shell {
  display: flex;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

/* ── SIDEBAR ─────────────────────────────────────────────────── */
.sidebar {
  width: 200px;
  background: var(--sidebar-bg);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  border-right: 1px solid var(--border-subtle);
}
.sidebar-section { padding: 8px 0; }
.sidebar-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
  padding: 8px 16px 4px;
  font-weight: 600;
}
.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  cursor: pointer;
  font-size: 14px;
  color: var(--text-secondary);
  border-left: 3px solid transparent;
  transition: background 0.1s, color 0.1s;
  letter-spacing: 0.16px;
}
.nav-item:hover { background: var(--surface-2); color: var(--text); }
.nav-item.active {
  background: var(--surface);
  color: #fff;
  border-left-color: var(--ibm-blue-50);
}
.nav-icon { font-size: 15px; width: 18px; text-align: center; flex-shrink: 0; }
.sidebar-divider { height: 1px; background: var(--border-subtle); margin: 4px 0; }

/* ── MAIN ────────────────────────────────────────────────────── */
.main { flex: 1; overflow-y: auto; display: flex; flex-direction: column; }

.view { display: none; flex-direction: column; flex: 1; }
.view.active { display: flex; }

/* ── PAGE HEADER ─────────────────────────────────────────────── */
.page-header {
  padding: 20px 24px 16px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--sidebar-bg);
  flex-shrink: 0;
}
.page-title  {
  font-size: 20px;
  font-weight: 400;
  letter-spacing: 0;
  color: var(--text);
}
.page-sub    { font-size: 13px; color: var(--muted); margin-top: 3px; }

/* ── TAB BAR (IBM Carbon Tab style) ──────────────────────────── */
.tab-bar {
  display: flex;
  padding: 0;
  background: var(--sidebar-bg);
  border-bottom: 1px solid var(--border-subtle);
  flex-shrink: 0;
}
.tab {
  padding: 12px 20px;
  font-size: 14px;
  cursor: pointer;
  color: var(--muted);
  border-bottom: 2px solid transparent;
  white-space: nowrap;
  letter-spacing: 0.16px;
  transition: color 0.1s, border-color 0.1s;
}
.tab:hover { color: var(--text); }
.tab.active {
  color: var(--text);
  border-bottom-color: var(--ibm-blue-50);
  font-weight: 500;
}

