+  });
+});
+
+// Tabs
+document.querySelectorAll('.tab').forEach(tab => {
+  tab.addEventListener('click', () => {
+    tab.closest('.tab-bar').querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
+    tab.classList.add('active');
+    document.getElementById('view-seller').querySelectorAll(':scope > .content > .view').forEach(v => v.classList.remove('active'));
+    document.getElementById('tab-' + tab.dataset.tab).classList.add('active');
+  });
+});
+
+// Detail panel — people
+function openPanel(key) {
+  const p = PEOPLE[key]; if (!p) return;
+  document.getElementById('dpAvatar').textContent = p.initials;
+  document.getElementById('dpAvatar').style.background = p.color;
+  document.getElementById('dpName').textContent = p.name;
+  document.getElementById('dpRole').textContent = p.role;
+  const mkt = document.getElementById('dpMarket');
+  mkt.textContent = p.market + ' Market';
+  mkt.style.background = ''; mkt.style.color = '';
+  document.getElementById('dpEmail').textContent = p.email;
+  document.getElementById('dpEmail').href = 'mailto:' + p.email;
+  document.getElementById('dpSlack').textContent = p.slack;
+  document.getElementById('dpLocation').textContent = p.location;
+  document.getElementById('dpMet').textContent = p.met;
+  document.getElementById('dpNotes').textContent = p.notes;
