+  document.getElementById('panelOverlay').classList.add('open');
+}
+
+// Detail panel — accounts
+function openAcctPanel(key) {
+  const a = ACCOUNTS[key]; if (!a) return;
+  const colors = {'Closed Won':'#198038','Negotiation':'#0f62fe','Proposal':'#8a3ffc','At Risk':'#da1e28','Prospect':'#8d8d8d'};
+  const col = colors[a.stage] || '#8d8d8d';
+  document.getElementById('dpAvatar').textContent = a.name.slice(0,2).toUpperCase();
+  document.getElementById('dpAvatar').style.background = col;
+  document.getElementById('dpName').textContent = a.name;
+  document.getElementById('dpRole').textContent = a.industry;
+  const mkt = document.getElementById('dpMarket');
+  mkt.textContent = a.stage;
+  mkt.style.background = col + '22'; mkt.style.color = col;
+  document.getElementById('dpEmail').textContent = '—'; document.getElementById('dpEmail').href = '#';
+  document.getElementById('dpSlack').textContent = '—';
+  document.getElementById('dpLocation').textContent = a.value;
+  document.getElementById('dpMet').textContent = a.stage;
+  document.getElementById('dpNotes').textContent = a.notes;
+  document.getElementById('dpTags').innerHTML = `<span class="dp-tag">${a.stage}</span><span class="dp-tag">${a.industry}</span>`;
+  document.getElementById('panelOverlay').classList.add('open');
+}
+
+document.getElementById('dpClose').addEventListener('click', () => document.getElementById('panelOverlay').classList.remove('open'));
+document.getElementById('panelOverlay').addEventListener('click', e => { if (e.target === document.getElementById('panelOverlay')) document.getElementById('panelOverlay').classList.remove('open'); });
+
+document.querySelectorAll('[data-person]').forEach(el => el.addEventListener('click', e => { e.stopPropagation(); openPanel(el.dataset.person); }));
+document.querySelectorAll('[data-acct]').forEach(el => el.addEventListener('click', e => { e.stopPropagation(); openAcctPanel(el.dataset.acct); }));
