+    const f = btn.textContent.trim();
+    document.querySelectorAll('.acct-hex').forEach(hex => {
+      const match = f === 'All' || hex.querySelector('.acct-stage').textContent === f;
+      hex.style.opacity = match ? '1' : '0.2';
+      hex.style.pointerEvents = match ? 'auto' : 'none';
+    });
+  });
+});
+</script>
+</body>
+</html>

