  align-items: center;
  gap: 8px;
}
.exec-badge {
  font-size: 11px;
  padding: 2px 10px;
  border-radius: 10px;
  color: #fff;
  font-weight: 500;
}

/* ── DETAIL PANEL ────────────────────────────────────────────── */
.panel-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.35);
  z-index: 100;
  display: none;
  align-items: flex-start;
  justify-content: flex-end;
}
.panel-overlay.open { display: flex; }

.detail-panel {
  background: var(--surface);
  width: 340px;
  height: 100%;
  overflow-y: auto;
  box-shadow: -4px 0 20px rgba(0,0,0,0.12);
  display: flex;
  flex-direction: column;
}
.dp-header {
  padding: 20px 20px 16px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.dp-avatar {
  width: 52px; height: 52px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 18px; font-weight: 700;
  color: #fff; flex-shrink: 0;
}
.dp-name   { font-size: 16px; font-weight: 600; }
.dp-role   { font-size: 12px; color: var(--muted); margin-top: 2px; }
.dp-market {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: 10px;
  background: var(--honey-light);
  color: #8a4600;
  display: inline-block;
  margin-top: 6px;
  font-weight: 500;
}
.dp-close {
  margin-left: auto;
  font-size: 18px;
  cursor: pointer;
  color: var(--muted);
  padding: 2px 6px;
  border-radius: 4px;
  line-height: 1;
}
.dp-close:hover { background: var(--bg); color: var(--text); }

.dp-body { padding: 16px 20px; flex: 1; display: flex; flex-direction: column; gap: 16px; }
.dp-section { display: flex; flex-direction: column; gap: 6px; }
.dp-section-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--muted);
  font-weight: 600;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--border);
}
.dp-row { display: flex; align-items: flex-start; gap: 8px; font-size: 13px; }
.dp-label { color: var(--muted); min-width: 80px; font-size: 12px; flex-shrink: 0; }
.dp-value { color: var(--text); font-weight: 500; }
.dp-link  { color: var(--ibm-blue); text-decoration: none; font-size: 13px; }
.dp-link:hover { text-decoration: underline; }

.dp-note-item {
  font-size: 12px;
  color: var(--text);
  line-height: 1.6;
  background: var(--bg);
  border-radius: 6px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  margin-bottom: 6px;
}
.dp-note-date { font-size: 10px; color: var(--muted); margin-top: 3px; }

.dp-tag-row { display: flex; gap: 6px; flex-wrap: wrap; }
.dp-tag {
  font-size: 11px;
  padding: 2px 10px;
  border-radius: 10px;
  background: #e0e0e0;
  color: var(--muted);
}

/* ── LOADING STATE ───────────────────────────────────────────── */
