.search-box:focus { outline: none; border-color: var(--ibm-blue); }
.sort-select {
  padding: 7px 10px;
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 13px;
  background: var(--surface);
  color: var(--text);
}
.sort-select:focus { outline: none; border-color: var(--ibm-blue); }

