/**
 * app.js — boot, navigation, and view orchestration
 */
import { getPeople }      from './api.js';
import { renderSeller }   from './views/seller.js';
import { renderNetwork }  from './views/network.js';
import { renderAccounts } from './views/accounts.js';
import { renderExec }     from './views/exec.js';

// ── Boot: populate current user in nav ────────────────────────
async function boot() {
  try {
    const people = await getPeople();
    const me = people.find(p => p.is_current_user);
    if (me) {
      document.getElementById('currentUserName').textContent = me.first_name + ' ' + me.last_name;
      document.getElementById('currentUserAvatar').textContent = me.initials;
    }
  } catch (e) {
    console.warn('Could not load user from API:', e.message);
  }
}

// ── View registry ─────────────────────────────────────────────
const VIEW_RENDERERS = {
  seller:   renderSeller,
  network:  renderNetwork,
  accounts: renderAccounts,
  exec:     renderExec,
};

const rendered = new Set();

async function activateView(viewName) {
  // Update sidebar
  document.querySelectorAll('.nav-item').forEach(n => {
    n.classList.toggle('active', n.dataset.view === viewName);
  });

  // Show the right view container
  document.querySelectorAll('.main > .view').forEach(v => {
    v.classList.toggle('active', v.id === `view-${viewName}`);
  });

  // Render the view if not already rendered
  const container = document.getElementById(`view-${viewName}`);
  if (!container) return;

  if (!rendered.has(viewName)) {
    rendered.add(viewName);
    try {
      await VIEW_RENDERERS[viewName]?.(container);
    } catch (err) {
      container.innerHTML = `
        <div class="page-header">
          <div class="page-title">Error</div>
          <div class="page-sub">Could not load view: ${err.message}</div>
        </div>
        <div class="content" style="color:var(--muted);font-size:13px">
          Make sure the server is running (<code>npm start</code>) and the database is seeded (<code>npm run seed</code>).
        </div>
      `;
    }
  }
}

// ── Sidebar nav clicks ────────────────────────────────────────
document.querySelectorAll('.nav-item').forEach(item => {
  item.addEventListener('click', () => activateView(item.dataset.view));
});

// ── Init ──────────────────────────────────────────────────────
boot();
activateView('seller');

/**
 * accounts.js — Account Hive view
 */
import { getAccounts } from '../api.js';
import { openAccount } from '../panel.js';

const STAGE_COLORS = {
  'Closed Won':  '#198038',
  'Negotiation': '#0f62fe',
  'Proposal':    '#8a3ffc',
  'At Risk':     '#da1e28',
  'Prospect':    '#8d8d8d',
};

const STAGES = ['Closed Won', 'Negotiation', 'Proposal', 'At Risk', 'Prospect'];

export async function renderAccounts(container) {
  container.innerHTML = `
    <div class="page-header">
      <div class="page-title">Account Hive</div>
      <div class="page-sub">All your accounts in one comb — color coded by pipeline stage</div>
    </div>
    <div class="content">
      <div id="acct-stats" class="stat-row"></div>
      <div class="accounts-toolbar">
        <button class="acct-filter active" data-stage="">All</button>
        ${STAGES.map(s => `<button class="acct-filter" data-stage="${s}">${s}</button>`).join('')}
        <div class="acct-legend">
          ${Object.entries(STAGE_COLORS).map(([stage, color]) => `
            <div class="legend-item">
              <div class="legend-dot" style="background:${color}"></div>${stage}
            </div>
          `).join('')}
        </div>
      </div>
      <div id="acct-hive" class="hive-container" style="flex-direction:column;align-items:flex-start">
        <div class="loading">Loading…</div>
      </div>
    </div>
  `;

  const accounts = await getAccounts();
  renderStats(accounts);

  let activeStage = '';

  function redraw() {
    renderHive(accounts, activeStage);
  }

  container.querySelectorAll('.acct-filter').forEach(btn => {
    btn.addEventListener('click', () => {
      container.querySelectorAll('.acct-filter').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      activeStage = btn.dataset.stage;
      redraw();
    });
  });

  redraw();
}

function renderStats(accounts) {
  const el = document.getElementById('acct-stats');
  if (!el) return;

  const total     = accounts.length;
  const closedWon = accounts.filter(a => a.stage === 'Closed Won').reduce((s,a) => s + (a.value_usd||0), 0);
  const pipeline  = accounts.filter(a => ['Negotiation','Proposal'].includes(a.stage)).reduce((s,a) => s + (a.value_usd||0), 0);
  const atRisk    = accounts.filter(a => a.stage === 'At Risk').reduce((s,a) => s + (a.value_usd||0), 0);

  el.innerHTML = `
    <div class="stat-card"><div class="stat-num">${total}</div><div class="stat-label">Accounts</div></div>
    <div class="stat-card"><div class="stat-num" style="color:#198038">${fmt(closedWon)}</div><div class="stat-label">Closed Won</div></div>
    <div class="stat-card"><div class="stat-num" style="color:var(--ibm-blue)">${fmt(pipeline)}</div><div class="stat-label">Active Pipeline</div></div>
    <div class="stat-card"><div class="stat-num" style="color:#da1e28">${fmt(atRisk)}</div><div class="stat-label">At Risk</div></div>
  `;
}

function renderHive(accounts, activeStage) {
  const hive = document.getElementById('acct-hive');
  if (!hive) return;

  // Chunk accounts into rows of 4–5 (offset every other)
  const ROW_SIZE = 4;
  const rows = [];
  for (let i = 0; i < accounts.length; i += ROW_SIZE) {
    rows.push(accounts.slice(i, i + ROW_SIZE));
  }

  hive.innerHTML = rows.map((row, ri) => `
    <div class="hex-row acct-row" style="${ri % 2 === 1 ? 'margin-left:44px' : ''}">
      ${row.map(a => {
        const color   = STAGE_COLORS[a.stage] || '#8d8d8d';
        const dimmed  = activeStage && a.stage !== activeStage;
        const valStr  = a.value_usd ? '$' + (a.value_usd / 1000).toFixed(0) + 'K' : '—';
        return `
          <div class="acct-hex" data-acct-id="${a.id}"
               style="background:${color};opacity:${dimmed ? 0.2 : 1};pointer-events:${dimmed ? 'none' : 'auto'}">
            <div class="acct-name">${a.short_name || a.name}</div>
            <div class="acct-val">${valStr}</div>
            <div class="acct-stage">${a.stage}</div>
          </div>
        `;
      }).join('')}
    </div>
  `).join('');

  hive.querySelectorAll('[data-acct-id]').forEach(el => {
    el.addEventListener('click', () => openAccount(el.dataset.acctId));
  });
}

function fmt(n) {
  if (n >= 1_000_000) return '$' + (n / 1_000_000).toFixed(1) + 'M';
  if (n >= 1_000)     return '$' + (n / 1_000).toFixed(0) + 'K';
  return '$' + n;
}

/**
 * seller.js — Management Hierarchy + My Cell views
 */
import { getPeople, getPerson } from '../api.js';
import { openPerson } from '../panel.js';

const ROLE_COLORS = {
  exec:     '#da1e28',
  director: '#8a3ffc',
  manager:  '#f1a21b',
  ae:       '#009d9a',
  tse:      '#8a3ffc',
  csm:      '#005d5d',
  sdr:      '#6929c4',
  partner:  '#da1e28',
  other:    '#8d8d8d',
};

export async function renderSeller(container) {
  container.innerHTML = `
    <div class="page-header">
      <div class="page-title">My Hive View</div>
      <div class="page-sub">Your cell, your team, and where you fit in the larger comb</div>
    </div>
    <div class="tab-bar">
      <div class="tab active" data-tab="hier">Management Hierarchy</div>
      <div class="tab" data-tab="cell">My Cell</div>
    </div>
    <div class="content">
      <div id="seller-tab-hier" class="seller-tab active"></div>
      <div id="seller-tab-cell" class="seller-tab" style="display:none"></div>
    </div>
  `;

  // Tab switching
  container.querySelectorAll('.tab').forEach(tab => {
    tab.addEventListener('click', () => {
      container.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      container.querySelectorAll('.seller-tab').forEach(t => t.style.display = 'none');
      document.getElementById(`seller-tab-${tab.dataset.tab}`).style.display = 'block';
    });
  });

  // Load data
  const [me, allEnterprise] = await Promise.all([
    getPeople({ role_type: 'ae' }).then(p => p.find(x => x.is_current_user) || p[0]),
    getPeople({ market: 'Enterprise' }),
  ]);

  await Promise.all([
    renderHierarchy(me, allEnterprise),
    renderCell(me, allEnterprise),
  ]);
}

async function renderHierarchy(me, people) {
  const container = document.getElementById('seller-tab-hier');

  // Build levels: chain up from current user to root
  const byId = {};
  people.forEach(p => { byId[p.id] = p; });

  const chain = [me];
  let cur = me;
  while (cur.manager_id && byId[cur.manager_id]) {
    cur = byId[cur.manager_id];
    chain.unshift(cur);
  }

  // Direct peers (same manager)
  const peers = people.filter(p =>
    p.manager_id === me.manager_id && !p.is_current_user
  );

  const legend = `
    <div class="role-legend">
      <div class="rl-item"><div class="rl-dot" style="background:#da1e28"></div>VP / Exec</div>
      <div class="rl-item"><div class="rl-dot" style="background:#8a3ffc"></div>Director</div>
      <div class="rl-item"><div class="rl-dot" style="background:var(--honey)"></div>Manager</div>
      <div class="rl-item"><div class="rl-dot" style="background:var(--ibm-blue)"></div>You</div>
      <div class="rl-item"><div class="rl-dot" style="background:#009d9a"></div>Peer</div>
    </div>
  `;

  // Render chain (above current user)
  const chainHtml = chain.slice(0, -1).map(p => `
    <div class="org-level">
      ${orgCard(p, '')}
    </div>
    <div class="org-connector"><div class="org-connector-line"></div></div>
  `).join('');

  // Render my manager (last in chain before me)
  const manager = chain.length > 1 ? chain[chain.length - 2] : null;

  // Peer row including "you"
  const peerRow = `
    <div class="org-level" style="gap:12px">
      ${peers.slice(0, 2).map(p => orgCard(p, 'peer')).join('')}
      ${orgCard(me, 'you')}
      ${peers.slice(2).map(p => orgCard(p, 'peer')).join('')}
    </div>
  `;

  container.innerHTML = legend + `
    <div class="org-tree">
      ${chainHtml}
      <div class="org-level">${orgCard(chain[chain.length - (chain.length > 1 ? 2 : 1)], 'highlight')}</div>
      <div class="org-connector"><div class="org-connector-line"></div></div>
      ${peerRow}
    </div>
  `;

  // Wire clicks
  container.querySelectorAll('[data-person-id]').forEach(el => {
    el.addEventListener('click', () => openPerson(el.dataset.personId));
  });
}

async function renderCell(me, people) {
  const container = document.getElementById('seller-tab-cell');

  const cellMembers = people.filter(p =>
    p.manager_id === me.manager_id || p.id === me.manager_id
  );

  const legend = `
    <div class="role-legend">
      <div class="rl-item"><div class="rl-dot" style="background:var(--honey)"></div>Manager</div>
      <div class="rl-item"><div class="rl-dot" style="background:var(--ibm-blue)"></div>You</div>
      <div class="rl-item"><div class="rl-dot" style="background:#009d9a"></div>Peer AE</div>
      <div class="rl-item"><div class="rl-dot" style="background:#8a3ffc"></div>Technical</div>
    </div>
  `;

  // Build rows: manager on top, then grid of peers
  const manager = people.find(p => p.id === me.manager_id);
  const others  = cellMembers.filter(p => p.id !== me.manager_id);
  const withMe  = [me, ...others];

  // Chunk into rows of 3
  const rows = [];
  if (manager) rows.push([manager]);
  for (let i = 0; i < withMe.length; i += 3) {
    rows.push(withMe.slice(i, i + 3));
  }

  const hexRows = rows.map(row => `
    <div class="hex-row">
      ${row.map(p => `
        <div class="hex-wrap" data-person-id="${p.id}">
          <div class="hex" style="background:${p.is_current_user ? 'var(--ibm-blue)' : ROLE_COLORS[p.role_type] || '#8d8d8d'}">
            <div class="hex-name">${p.first_name} ${p.last_name.charAt(0)}.</div>
            <div class="hex-role">${p.role_type.toUpperCase()}</div>
          </div>
        </div>
      `).join('')}
    </div>
  `).join('');

  container.innerHTML = legend + `<div class="hive-container">${hexRows}</div>`;

  container.querySelectorAll('[data-person-id]').forEach(el => {
    el.addEventListener('click', () => openPerson(el.dataset.personId));
  });
}

// ── Helper: single org card ────────────────────────────────────
function orgCard(person, variant) {
  const color = person.is_current_user ? 'var(--ibm-blue)' : ROLE_COLORS[person.role_type] || '#8d8d8d';
  const badge = {
    you:       `<div class="org-badge" style="background:#d0e2ff;color:var(--ibm-blue)">You</div>`,
    highlight: `<div class="org-badge">Your Manager</div>`,
    peer:      `<div class="org-badge">Peer</div>`,
    '':        `<div class="org-badge">${capitalize(person.role_type)}</div>`,
  }[variant] ?? `<div class="org-badge">${capitalize(person.role_type)}</div>`;

  return `
    <div class="org-card ${variant}" data-person-id="${person.id}">
      <div class="org-avatar" style="background:${color}">${person.initials}</div>
      <div class="org-info">
        <div class="org-name">${person.first_name} ${person.last_name}</div>
        <div class="org-role">${person.role}</div>
        ${badge}
      </div>
    </div>
  `;
}

function capitalize(s) {
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : '';
}

/**
 * exec.js — Exec Hive View (full org by market)
 */
import { getPeople, getMarkets } from '../api.js';
import { openPerson } from '../panel.js';

export async function renderExec(container) {
  container.innerHTML = `
    <div class="page-header">
      <div class="page-title">Exec Hive View</div>
      <div class="page-sub">Full organization — every bee in the hive, broken by market segment</div>
    </div>
    <div class="content">
      <div id="exec-stats" class="stat-row"></div>
      <div class="toolbar">
        <input class="search-box" id="execSearch" type="text" placeholder="Search any bee in the hive…"/>
        <select class="sort-select" id="execMarketFilter">
          <option value="">All Markets</option>
        </select>
      </div>
      <div id="exec-body"><div class="loading">Loading…</div></div>
    </div>
  `;

  const [markets, allPeople] = await Promise.all([
    getMarkets(),
    getPeople(),
  ]);

  // Populate market filter
  const sel = document.getElementById('execMarketFilter');
  markets.forEach(m => {
    const opt = document.createElement('option');
    opt.value = m.name;
    opt.textContent = m.name;
    sel.appendChild(opt);
  });

  renderStats(markets, allPeople);

  let searchTerm   = '';
  let marketFilter = '';

  function redraw() {
    renderBody(markets, allPeople, searchTerm, marketFilter);
  }

  document.getElementById('execSearch')?.addEventListener('input', e => {
    searchTerm = e.target.value.toLowerCase();
    redraw();
  });
  sel?.addEventListener('change', e => {
    marketFilter = e.target.value;
    redraw();
  });

  redraw();
}

function renderStats(markets, people) {
  const el = document.getElementById('exec-stats');
  if (!el) return;
  el.innerHTML = `
    <div class="stat-card"><div class="stat-num">${people.length}</div><div class="stat-label">Total People</div></div>
    ${markets.map(m => `
      <div class="stat-card">
        <div class="stat-num" style="color:${m.color}">${m.people_count}</div>
        <div class="stat-label">${m.name}</div>
      </div>
    `).join('')}
  `;
}

function renderBody(markets, allPeople, search, marketFilter) {
  const body = document.getElementById('exec-body');
  if (!body) return;

  const matchPeople = allPeople.filter(p => {
    const name = (p.first_name + ' ' + p.last_name).toLowerCase();
    const matchSearch = !search || name.includes(search) || p.role.toLowerCase().includes(search);
    const matchMarket = !marketFilter || p.market === marketFilter;
    return matchSearch && matchMarket;
  });

  const byMarket = {};
  markets.forEach(m => { byMarket[m.name] = { market: m, people: [] }; });
  matchPeople.forEach(p => {
    if (p.market && byMarket[p.market]) byMarket[p.market].people.push(p);
  });

  body.innerHTML = Object.values(byMarket)
    .filter(g => (marketFilter ? g.market.name === marketFilter : true) && g.people.length > 0)
    .map(g => renderMarketSection(g.market, g.people))
    .join('');

  body.querySelectorAll('[data-person-id]').forEach(el => {
    el.addEventListener('click', () => openPerson(el.dataset.personId));
  });
}

function renderMarketSection(market, people) {
  // Chunk into honeycomb rows of 5
  const ROW_SIZE = 5;
  const rows = [];
  for (let i = 0; i < people.length; i += ROW_SIZE) {
    rows.push(people.slice(i, i + ROW_SIZE));
  }

  const hexRows = rows.map((row, ri) => `
    <div class="hex-row" style="${ri % 2 === 1 ? 'margin-left:42px' : ''}">
      ${row.map(p => `
        <div class="hex-wrap" data-person-id="${p.id}">
          <div class="hex" style="background:${p.is_current_user ? 'var(--ibm-blue)' : p.color}">
            <div class="hex-name">${p.first_name} ${p.last_name.charAt(0)}.</div>
            <div class="hex-role">${p.role_type.toUpperCase()}</div>
          </div>
        </div>
      `).join('')}
    </div>
  `).join('');

  return `
    <div class="exec-section">
      <div class="exec-title">
        <svg width="14" height="16" viewBox="0 0 14 16">
          <polygon points="7,0.5 13.5,4 13.5,12 7,15.5 0.5,12 0.5,4" fill="${market.color}"/>
        </svg>
        ${market.name} Market
        <span class="exec-badge" style="background:${market.color};${market.name==='Territory'?'color:#161616':''}">${people.length} people</span>
      </div>
      <div class="hive-container" style="flex-direction:column;align-items:flex-start">
        ${hexRows}
      </div>
    </div>
  `;
}

/**
 * network.js — My Network view
 */
import { getNetwork } from '../api.js';
import { openPerson } from '../panel.js';

const TAG_LABELS = {
  close_ally:  'Close Ally',
  partner:     'Partner',
  cross_brand: 'Cross-brand',
  client:      'Client',
  peer:        'Peer',
};

const TAG_CLASSES = {
  close_ally:  'tag-close',
  partner:     'tag-partner',
  cross_brand: 'tag-cross',
  client:      'tag-client',
  peer:        'tag-peer',
};

export async function renderNetwork(container) {
  container.innerHTML = `
    <div class="page-header">
      <div class="page-title">My Network</div>
      <div class="page-sub">Personal connections within IBM — relationships, context, open notes</div>
    </div>
    <div class="content">
      <div id="network-stats" class="stat-row"></div>
      <div class="toolbar">
        <input class="search-box" id="networkSearch" type="text" placeholder="Search connections…"/>
        <select class="sort-select" id="networkFilter">
          <option value="">All Relationships</option>
          <option value="close_ally">Close Ally</option>
          <option value="partner">Partner</option>
          <option value="cross_brand">Cross-brand</option>
          <option value="client">Client</option>
          <option value="peer">Peer</option>
        </select>
      </div>
      <div id="network-grid" class="network-grid"><div class="loading">Loading…</div></div>
    </div>
  `;

  const connections = await getNetwork();
  renderStats(connections);

  let filtered = connections;

  function redraw() {
    const search = document.getElementById('networkSearch')?.value.toLowerCase() || '';
    const filter = document.getElementById('networkFilter')?.value || '';
    filtered = connections.filter(c => {
      const name = (c.first_name + ' ' + c.last_name).toLowerCase();
      const matchSearch = !search || name.includes(search) || c.role.toLowerCase().includes(search);
      const matchFilter = !filter || c.relationship === filter;
      return matchSearch && matchFilter;
    });
    renderCards(filtered);
  }

  document.getElementById('networkSearch')?.addEventListener('input', redraw);
  document.getElementById('networkFilter')?.addEventListener('change', redraw);

  redraw();
}

function renderStats(connections) {
  const total     = connections.length;
  const allies    = connections.filter(c => c.relationship === 'close_ally').length;
  const crossBrand= connections.filter(c => c.relationship === 'cross_brand').length;
  const followup  = connections.filter(c => c.needs_followup).length;

  document.getElementById('network-stats').innerHTML = `
    <div class="stat-card"><div class="stat-num">${total}</div><div class="stat-label">Connections</div></div>
    <div class="stat-card"><div class="stat-num">${allies}</div><div class="stat-label">Close Allies</div></div>
    <div class="stat-card"><div class="stat-num">${crossBrand}</div><div class="stat-label">Cross-Brand</div></div>
    <div class="stat-card"><div class="stat-num" style="color:#da1e28">${followup}</div><div class="stat-label">Need Follow-up</div></div>
  `;
}

function renderCards(connections) {
  const grid = document.getElementById('network-grid');
  if (!grid) return;

  if (!connections.length) {
    grid.innerHTML = '<div class="loading">No connections match.</div>';
    return;
  }

  grid.innerHTML = connections.map(c => `
    <div class="network-card" data-person-id="${c.person_id}">
      <div class="nc-top">
        <div class="nc-avatar" style="background:${c.color}">${c.initials}</div>
        <div>
          <div class="nc-name">${c.first_name} ${c.last_name}</div>
          <div class="nc-role">${c.role}</div>
        </div>
      </div>
      <span class="nc-tag ${TAG_CLASSES[c.relationship] || ''}">${TAG_LABELS[c.relationship] || c.relationship}</span>
      ${c.needs_followup ? '<div class="nc-followup">⚠ Follow-up needed</div>' : ''}
      ${c.notes ? `<div class="nc-note">${c.notes}</div>` : ''}
    </div>
  `).join('');

  grid.querySelectorAll('[data-person-id]').forEach(el => {
    el.addEventListener('click', () => openPerson(el.dataset.personId));
  });
}

