/* ─────────────────────────────────────────────────────────────
   IBM Hive — hive.css
   Dark theme. Accent palette is blue → purple only.
   ───────────────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* Brand accents — blue → purple, nothing else */
  --accent-blue:     #4d7bff;
  --accent-blue-dark:#2f5bef;
  --accent-indigo:   #6c63ff;
  --accent-violet:   #8b5cf6;
  --accent-purple:   #a855f7;
  --accent-magenta:  #d946ef;
  --accent-gradient: linear-gradient(135deg, var(--accent-blue) 0%, var(--accent-purple) 100%);

  /* Back-compat alias used by a few components below */
  --ibm-blue:      var(--accent-blue);
  --ibm-blue-dark: var(--accent-blue-dark);

  /* Surfaces — near-black background, neutral charcoal cards (AskIBM style) */
  --bg:         #0a0a0c;
  --nav-bg:     #000000;
  --sidebar-bg: #0a0a0c;
  --surface:    #18181b;
  --surface-2:  #232326;
  --border:     #333338;
  --text:       #f2f2f4;
  --muted:      #98989f;

  /* Hexagon stroke used on every person/role hex across the app */
  --hex-border: rgba(255,255,255,0.9);

  /* Role / seniority spectrum (blue → magenta = junior → senior, not danger) */
  --c-exec:     #d946ef;
  --c-director: #a855f7;
  --c-manager:  #6c63ff;
  --c-you:      var(--accent-blue);
  --c-peer:     #60a5fa;
  --c-tech:     #a78bfa;
  --c-csm:      #4338ca;
  --c-sdr:      #7e22ce;
  --c-partner:  #e879f9;
  --c-other:    #64748b;
  --c-open:     var(--surface-2);

  /* Account pipeline stage spectrum (blue → magenta = healthy → urgent) */
  --stage-won:         #3b82f6;
  --stage-negotiation: #6366f1;
  --stage-proposal:    #8b5cf6;
  --stage-risk:        #d946ef;
  --stage-prospect:    #64748b;

  /* Market spectrum */
  --mkt-enterprise: #4d7bff;
  --mkt-strategic:  #a855f7;
  --mkt-horizon:    #6c63ff;
  --mkt-territory:  #d946ef;
}

body {
  font-family: -apple-system, "IBM Plex Sans", "Segoe UI", system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ── TOP NAV ─────────────────────────────────────────────────── */
.topnav {
  background: var(--nav-bg);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 48px;
  flex-shrink: 0;
  border-bottom: 1px solid var(--border);
}
.topnav-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.5px;
}

/* Logo placeholder — drop your own image at public/img/logo.png.
   Until then this renders as a blue→purple gradient swatch. */
.logo-slot {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: var(--accent-gradient);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  flex-shrink: 0;
}
.logo-img { width: 100%; height: 100%; object-fit: cover; display: block; }

.topnav-user {
  display: flex;
