  /* Role / seniority spectrum (blue → magenta = junior → senior, not danger) */
  --c-exec:     #d946ef;
  --c-director: #a855f7;
  --c-manager:  #6c63ff;
  --c-you:      var(--accent-blue);
  --c-peer:     #60a5fa;
